test('buildSelectionQuote preserves multiline answer text as an editable quote', () => {
  const selected = 'First line\n\n<script>alert("x")</script>';
  const expected = '> First line\n> \n> <script>alert("x")</script>\n\n';
  assert.equal(buildSelectionQuote(selected), expected);
  assert.equal(buildSelectionQuoteFx(selected), expected, 'Firefox quote builder should match Chrome');
  assert.equal(buildSelectionComposerDraft('A detail', 'Why?'), '> A detail\n\nWhy?');
  assert.equal(buildSelectionComposerDraftFx('A detail', 'Why?'), '> A detail\n\nWhy?', 'Firefox draft builder should match Chrome');
  assert.equal(buildSelectionComposerDraft('', 'draft'), 'draft');
  assert.equal(buildSelectionComposerDraft('A detail', '> A detail\n\nWhy?'), '> A detail\n\nWhy?');
  assert.equal(buildSelectionComposerDraft('A detail', ' '), '> A detail\n\n ');
});

test('selectionRangeRect prefers a non-empty bounding box and unions client rects otherwise', () => {
  const bounding = { top: 10, left: 20, bottom: 40, right: 80, width: 60, height: 30 };
  assert.deepEqual(selectionRangeRect({
    getBoundingClientRect: () => bounding,
    getClientRects: () => [],
  }), bounding);
  assert.deepEqual(selectionRangeRectFx({
    getBoundingClientRect: () => bounding,
    getClientRects: () => [],
  }), bounding, 'Firefox range rect helper should match Chrome');
  assert.deepEqual(selectionRangeRect({
    getBoundingClientRect: () => ({ top: 0, left: 0, bottom: 0, right: 0, width: 0, height: 0 }),
    getClientRects: () => [
      { top: 8, left: 12, bottom: 24, right: 40, width: 28, height: 16 },
      { top: 20, left: 10, bottom: 36, right: 48, width: 38, height: 16 },
    ],
  }), { top: 8, left: 10, bottom: 36, right: 48, width: 38, height: 28 });
  assert.equal(selectionRangeIsVisible({ top: 10, left: 10, bottom: 40, right: 80 }, { width: 100, height: 80 }), true);
  assert.equal(selectionRangeIsVisible({ top: 90, left: 10, bottom: 120, right: 80 }, { width: 100, height: 80 }), false);
  assert.equal(selectionRangeIsVisibleFx({ top: 10, left: 10, bottom: 40, right: 80 }, { width: 100, height: 80 }), true);
});

test('selectionIsQuoteable requires one non-empty assistant answer element', () => {
  const answer = {};
  const otherAnswer = {};
  const valid = { startTextElement: answer, endTextElement: answer, text: 'A detail' };
  assert.equal(selectionIsQuoteable(valid), true);
  assert.equal(selectionIsQuoteable({ ...valid, endTextElement: otherAnswer }), false);
  assert.equal(selectionIsQuoteable({ ...valid, text: ' \n ' }), false);
  assert.equal(selectionIsQuoteableFx(valid), true, 'Firefox eligibility should match Chrome');
  assert.equal(selectionIsQuoteableFx({ ...valid, endTextElement: otherAnswer }), false);
});

test('message body normalization is identical in the agent and the content probe', () => {
  const pipeline = (source, header) => {
    const start = source.indexOf(header);
    assert.notEqual(start, -1, `${header} not found`);
    const end = source.indexOf('normalize(\'NFKC\')', start);
    assert.notEqual(end, -1, `${header} has no NFKC normalization`);
    return source.slice(start + header.length, end)
      .split('\n')
      .map(line => line.trim())
      .filter(line => line && !line.startsWith('//'))
      .join('\n');
  };
  const agentSource = fs.readFileSync(new URL('../src/chrome/src/agent/agent.js', import.meta.url), 'utf8');
  const contentSource = fs.readFileSync(new URL('../src/chrome/src/content/content.js', import.meta.url), 'utf8');
  const firefoxContent = fs.readFileSync(new URL('../src/firefox/src/content/content.js', import.meta.url), 'utf8');
  const agentPipeline = pipeline(agentSource, '_workflowMessageBody(value) {');
  assert.equal(
    pipeline(contentSource, 'const normalizedMessageBody = (value) => {'),
    agentPipeline,
    'the content probe and the agent must normalize message bodies the same way',
  );
  assert.equal(
    pipeline(firefoxContent, 'const normalizedMessageBody = (value) => {'),
    agentPipeline,
    'the Firefox content probe must normalize message bodies the same way',
  );
});

