    assert.match(selectionActionSource, /const takenNames = new Set\(pending\.map\(att => att\?\.name\)\)/);
    assert.match(selectionActionSource, /for \(let suffix = 2; takenNames\.has\(name\); suffix \+= 1\) name = `selected-text-\$\{suffix\}\.txt`/);
