test('ATIF export: rejects unsupported or malformed WebBrain exports', () => {
  assert.throws(
    () => webbrainTraceToAtif({ schema: 'other/1', run: {}, events: [] }),
    /Expected schema "webbrain-trace\/1"/,
  );
  assert.throws(
    () => webbrainTraceToAtif({ schema: 'webbrain-trace/1', run: {}, events: 'nope' }),
    /events must be an array/,
  );
  assert.throws(
    () => webbrainTraceToAtif({ schema: 'webbrain-trace/1', run: {}, events: [] }),
    /run\.runId must be a non-empty string/,
  );
  assert.throws(
    () => webbrainTraceToAtif({ schema: 'webbrain-trace/1', run: { runId: 7 }, events: [] }),
    /run\.runId must be a non-empty string/,
  );
  assert.throws(
    () => webbrainTraceToAtif({
      schema: 'webbrain-trace/1',
      run: { runId: 'expected' },
      events: [{ runId: 'foreign', kind: 'tool', data: {} }],
    }),
    /event runId "foreign" does not match/,
  );
  assert.throws(
    () => webbrainTraceToAtif({ schema: 'webbrain-trace/1', session: {}, runs: [] }),
    /session\.sessionId must be a non-empty string/,
  );
  assert.throws(
    () => webbrainTraceToAtif({
      schema: 'webbrain-trace/1', session: { sessionId: 'empty' }, runs: [],
    }),
    /runs must be a non-empty array/,
  );
});

test('ATIF export: CLI writes a sibling .atif.json file', () => {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'webbrain-atif-'));
  try {
    const sourcePath = path.join(tempDir, 'trace.json');
    fs.writeFileSync(sourcePath, JSON.stringify({
      schema: 'webbrain-trace/1',
      exportedByWebBrainVersion: '23.4.0',
      run: { runId: 'cli-run', userMessage: 'Hello' },
      events: [],
    }));
    const result = spawnSync(
      process.execPath,
      [path.join(ROOT, 'scripts/trace-to-atif.mjs'), sourcePath],
      { encoding: 'utf8' },
    );
    assert.equal(result.status, 0, result.stderr);
    assert.match(result.stderr, /trace\.atif\.json/);
    const output = JSON.parse(
      fs.readFileSync(path.join(tempDir, 'trace.atif.json'), 'utf8'),
    );
    assert.equal(output.schema_version, 'ATIF-v1.7');
    assert.equal(output.session_id, 'cli-run');

    const bundlePath = path.join(tempDir, 'bundle.json');
    fs.writeFileSync(bundlePath, JSON.stringify({
      schema: 'webbrain-trace/1',
      session: { sessionId: 'cli-session' },
      runs: [
        { run: { runId: 'cli-run-a', userMessage: 'First' }, events: [] },
        { run: { runId: 'cli-run-b', userMessage: 'Second' }, events: [] },
      ],
    }));
    const bundleResult = spawnSync(
      process.execPath,
      [path.join(ROOT, 'scripts/trace-to-atif.mjs'), bundlePath],
      { encoding: 'utf8' },
    );
    assert.equal(bundleResult.status, 0, bundleResult.stderr);
    const bundleOutput = JSON.parse(
      fs.readFileSync(path.join(tempDir, 'bundle.atif.json'), 'utf8'),
    );
    assert.equal(bundleOutput.session_id, 'cli-session');
    assert.deepEqual(bundleOutput.steps.map(step => step.message), ['First', 'Second']);
  } finally {
    fs.rmSync(tempDir, { recursive: true, force: true });
  }
});

test('trace export: renders the full tool chain from trace events, in order', () => {
  const { markdown, turnCount, toolCount } = tracesToMarkdown(TRACE_RUNS);
  assert.equal(turnCount, 1);
  assert.equal(toolCount, 4);
  assert.match(markdown, /# WebBrain Conversation — tool chain/);
  assert.match(markdown, /## Turn 1 — Find the cheapest Sony WH-1000XM5/);
  assert.match(markdown, /\*\*Read scope:\*\*\n```\n\{"read_scope":"visible_page"\}/); // classifier is diagnostic metadata, not an assistant answer
  assert.match(markdown, /\*\*Planner:\*\*\n```json\n\{"summary"/);   // planner labelled + fenced, model's ```json language preserved
  assert.ok(!/```\n```/.test(markdown), 'planner content must not be double-fenced');
  assert.match(markdown, /Screenshot pixels and vision descriptions are omitted here/);   // honest privacy footer
  // order preserved, retries kept distinct (no aggregation)
  assert.ok(markdown.indexOf('fetch_url') < markdown.indexOf('research_url'), 'order preserved');
  assert.equal((markdown.match(/research_url/g) || []).length, 2, 'each retry emitted, not aggregated');
  // failure marker works on the RAW structured result (the #348 wrapping bug can't occur here)
  assert.match(markdown, /fetch_url[^\n]*✗[^\n]*Akamai/);
  // recorder's large-result marker rendered, not dumped
  assert.match(markdown, /recorder-truncated, 40\.0kb total/);
  assert.ok(!markdown.includes('role heading '.repeat(60)), 'huge result body must not be dumped');
  assert.match(markdown, /⚠️ error \(loop\): stopped by user/);
  assert.match(markdown, /Cheapest option: CHF 203/);
  assert.match(markdown, /Visual capture: viewport/);
});

