test('trace event model: catalog covers every kind the recorder writes', () => {
  const kinds = EVENT_MODEL_CH.EVENT_KINDS;
  for (const kind of kinds) {
    assert.equal(EVENT_MODEL_CH.isKnownKind(kind), true, `catalog entry ${kind} not recognized`);
    assert.equal(EVENT_MODEL_CH.isIgnorableKind(kind), false, `catalog entry ${kind} should not be ignorable yet`);
  }
  assert.deepEqual(EVENT_MODEL_CH.IGNORABLE_KINDS, [], 'ignorable catalog should start empty');
  for (const browser of ['chrome', 'firefox']) {
    const recorderSource = fs.readFileSync(path.join(ROOT, `src/${browser}/src/trace/recorder.js`), 'utf8');
    const used = [
      ...[...recorderSource.matchAll(/_appendEvent\(runId, '([a-z_]+)'/g)].map(m => m[1]),
      ...[...recorderSource.matchAll(/makeEvent\(runId, seq, '([a-z_]+)'/g)].map(m => m[1]),
    ];
    assert.ok(used.length >= 9, `${browser}: recorder event kinds not found (${used.length})`);
    for (const kind of used) {
      assert.ok(kinds.includes(kind), `${browser}: recorder uses uncatalogued kind '${kind}'`);
    }
  }
});

test('trace event model: makeEvent validates kinds and JSON round-trip', () => {
  const { makeEvent } = EVENT_MODEL_CH;
  const ev = makeEvent('run_x', 1, 'llm_request', { step: 0 });
  assert.equal(ev.runId, 'run_x');
  assert.equal(ev.seq, 1);
  assert.equal(ev.kind, 'llm_request');
  assert.deepEqual(ev.data, { step: 0 });
  assert.equal(ev.ignorable, undefined, 'non-ignorable kinds must not carry the flag');
  assert.equal(typeof ev.ts, 'number', 'envelope must carry a timestamp');
  assert.equal(makeEvent('run_x', 2, 'not_a_kind', {}), null, 'unknown kind must be rejected');
  const circular = {}; circular.self = circular;
  assert.equal(makeEvent('run_x', 3, 'note', circular), null, 'unserializable data must be rejected');
  assert.equal(makeEvent('run_x', 4, 'note', { big: 1n }), null, 'BigInt data must be rejected');
  assert.deepEqual(makeEvent('run_x', 5, 'note', null).data, null, 'null data must be preserved as null');
  assert.deepEqual(makeEvent('run_x', 6, 'note', undefined).data, null, 'undefined data must normalize to null');
});

test('trace event model: validateEventLog detects gaps and unknown kinds', () => {
  const { validateEventLog } = EVENT_MODEL_CH;
  assert.deepEqual(validateEventLog([]), { ok: true, firstGap: null, unknownKinds: [] }, 'empty log is valid');
  assert.equal(validateEventLog([{ seq: 1, kind: 'note' }, { seq: 2, kind: 'error' }]).ok, true, 'contiguous log is valid');
  const gap = validateEventLog([{ seq: 1, kind: 'note' }, { seq: 3, kind: 'note' }]);
  assert.equal(gap.ok, false, 'gap must invalidate the log');
  assert.equal(gap.firstGap, 2, 'first missing seq not reported');
  const unknown = validateEventLog([{ seq: 1, kind: 'mystery' }]);
  assert.equal(unknown.ok, false, 'unknown kind must invalidate the log');
  assert.deepEqual(unknown.unknownKinds, ['mystery'], 'unknown kind not listed');
  assert.equal(unknown.firstGap, null, 'unknown kinds must not count as gaps');
});

test('trace event model: mirrors are identical and browser-neutral', () => {
  const chromeSource = fs.readFileSync(path.join(ROOT, 'src/chrome/src/trace/event-model.js'), 'utf8');
  const firefoxSource = fs.readFileSync(path.join(ROOT, 'src/firefox/src/trace/event-model.js'), 'utf8');
  assert.equal(chromeSource, firefoxSource, 'Chrome/Firefox event model drifted');
  assert.deepEqual(EVENT_MODEL_FX.EVENT_KINDS, EVENT_MODEL_CH.EVENT_KINDS);
  assert.equal(EVENT_MODEL_FX.TRACE_FORMAT_VERSION, EVENT_MODEL_CH.TRACE_FORMAT_VERSION);
  assert.equal(EVENT_MODEL_CH.TRACE_FORMAT_VERSION, 1, 'first trace format version');
  assert.doesNotMatch(chromeSource, /chrome\./, 'event model must not depend on chrome APIs');
  assert.doesNotMatch(chromeSource, /indexedDB|storage\./, 'event model must not touch storage');
});

test('trace privacy: default persistence keeps metadata and content mode is explicit', () => {
  const run = {
    runId: 'privacy-run',
    userMessage: 'PRIVATE USER MESSAGE',
    finalContent: 'PRIVATE FINAL RESPONSE',
    tabUrl: 'https://private.example/account?token=PRIVATE',
    tabTitle: 'PRIVATE PAGE TITLE',
    attachments: [{ name: 'PRIVATE-FILENAME.pdf', kind: 'document' }],
    model: 'test-model',
    status: 'done',
  };
  const response = {
    step: 1,
    content: 'PRIVATE MODEL RESPONSE',
    toolCalls: [{ id: 'call-1', function: { name: 'private_tool', arguments: '{"secret":true}' } }],
    usage: { prompt_tokens: 10, completion_tokens: 4, cost: 0.12 },
    latencyMs: 120,
    model: 'response-model',
    finishReason: 'stop',
  };
  const tool = {
    step: 1,
    name: 'private_tool',
    args: { secret: true },
    result: { private: 'value' },
    latencyMs: 40,
  };
  const error = { step: 1, phase: 'loop', code: 'TRANSPORT', message: 'PRIVATE ERROR MESSAGE' };
  const note = {
    step: 1,
    note: 'llm_retry',
    extra: { attempt: 2, delayMs: 50, code: 'RATE_LIMIT', message: 'PRIVATE NOTE' },
  };

  const safeRun = TRACE_PRIVACY_CH.projectTraceRun(run);
  assert.equal(safeRun.userMessage, undefined);
  assert.equal(safeRun.finalContent, undefined);
  assert.equal(safeRun.tabUrl, undefined);
  assert.equal(safeRun.tabTitle, undefined);
  assert.equal(safeRun.attachments, undefined);
  assert.equal(safeRun.model, 'test-model');

  const safeResponse = TRACE_PRIVACY_CH.projectTraceEventData('llm_response', response);
  assert.equal(safeResponse.content, undefined);
  assert.equal(safeResponse.toolCalls, undefined);
  assert.deepEqual(safeResponse.usage, response.usage);
  assert.equal(safeResponse.latencyMs, 120);

  const safeTool = TRACE_PRIVACY_CH.projectTraceEventData('tool', tool);
  assert.equal(safeTool.args, undefined);
  assert.equal(safeTool.result, undefined);
  assert.deepEqual(safeTool, {
    step: 1,
    name: 'private_tool',
    latencyMs: 40,
    resultStatus: 'success',
  });

  const safeFailedTool = TRACE_PRIVACY_CH.projectTraceEventData('tool', {
    step: 1,
    name: 'private_tool',
    result: { success: false, code: 'RATE_LIMIT', message: 'PRIVATE FAILURE' },
    latencyMs: 40,
  });
  assert.deepEqual(safeFailedTool, {
    step: 1,
    name: 'private_tool',
    latencyMs: 40,
    resultStatus: 'error',
    resultErrorCode: 'RATE_LIMIT',
  });

  const safeError = TRACE_PRIVACY_CH.projectTraceEventData('error', error);
  assert.equal(safeError.message, undefined);
  assert.equal(safeError.code, 'TRANSPORT');

  const safeNote = TRACE_PRIVACY_CH.projectTraceEventData('note', note);
  assert.deepEqual(safeNote.extra, { attempt: 2, delayMs: 50, code: 'RATE_LIMIT' });
  const safeAdapterContext = TRACE_PRIVACY_CH.projectTraceEventData('note', {
    step: 0,
    note: 'adapter_context',
    extra: {
      adapter: 'microsoft-forms',
      revision: 1,
      workflowSchema: ADAPTER_WORKFLOW_SCHEMA,
      job: 'submit-form',
      template: 'form',
      pageText: 'PRIVATE FORM CONTENT',
    },
  });
  assert.deepEqual(safeAdapterContext, {
    step: 0,
    note: 'adapter_context',
    extra: {
      adapter: 'microsoft-forms',
      revision: 1,
      workflowSchema: ADAPTER_WORKFLOW_SCHEMA,
      job: 'submit-form',
      template: 'form',
    },
  });
  assert.deepEqual(
    TRACE_PRIVACY_FX.projectTraceEventData('note', {
      step: 0,
      note: 'adapter_context',
      extra: { ...safeAdapterContext.extra, pageText: 'PRIVATE FORM CONTENT' },
    }),
    safeAdapterContext,
    'Firefox adapter-context projection drifted',
  );
  const safeAdapterMatch = TRACE_PRIVACY_CH.projectTraceEventData('note', {
    step: 0,
    note: 'adapter_match',
    extra: {
      adapter: 'sofascore',
      revision: 1,
      notesInjected: true,
      notes: 'PRIVATE ADAPTER PROMPT CONTENT',
      tabUrl: 'https://www.sofascore.com/private',
    },
  });
  assert.deepEqual(safeAdapterMatch, {
    step: 0,
    note: 'adapter_match',
    extra: { adapter: 'sofascore', revision: 1, notesInjected: true },
  });
  assert.deepEqual(
    TRACE_PRIVACY_FX.projectTraceEventData('note', {
      ...safeAdapterMatch,
      extra: { ...safeAdapterMatch.extra, notes: 'PRIVATE ADAPTER PROMPT CONTENT' },
    }),
    safeAdapterMatch,
    'Firefox adapter-match projection drifted',
  );

  assert.deepEqual(TRACE_PRIVACY_CH.projectTraceRun(run, { includeContent: true }), run);
  assert.deepEqual(
    TRACE_PRIVACY_CH.projectTraceEventData('llm_response', response, { includeContent: true }),
    response,
  );
  assert.deepEqual(TRACE_PRIVACY_FX.projectTraceRun(run), safeRun, 'Firefox run projection drifted');
  assert.deepEqual(
    TRACE_PRIVACY_FX.projectTraceEventData('tool', tool),
    safeTool,
    'Firefox event projection drifted',
  );
});

test('trace privacy documentation distinguishes metadata-only and lossless retention', () => {
  const privacy = fs.readFileSync(path.join(ROOT, 'docs/privacy-and-data-flow.md'), 'utf8');
  const security = fs.readFileSync(path.join(ROOT, 'docs/security-model.md'), 'utf8');
  for (const [label, document] of [['privacy data flow', privacy], ['security model', security]]) {
    assert.match(document, /default (?:metadata-only )?tier[\s\S]*(?:omit|omits|omitting)[\s\S]*user[\s\S]*final assistant\s+text/i, `${label}: default run-content omission is undocumented`);
    assert.match(document, /default[\s\S]*(?:omit|omits|omitting)[\s\S]*tool arguments\/results/i, `${label}: default event-payload omission is undocumented`);
    assert.match(document, /default[\s\S]*(?:omit|omits|omitting)[\s\S]*(?:tab URLs\/titles|tab URL\/title)[\s\S]*attachment filename/i, `${label}: sensitive run metadata omission is undocumented`);
    assert.match(document, /default[\s\S]*do(?:es)? not write screenshot blobs/i, `${label}: default screenshot-byte omission is undocumented`);
    assert.match(document, /lossless[\s\S]*explicit\s+(?:user\s+)?opt-in[\s\S]*screenshot\s+bytes/i, `${label}: lossless content retention is undocumented`);
    assert.match(document, /historical[\s\S]*(?:not\s+(?:migrated|rewrite|rewritten)|do(?:es)? not rewrite)/i, `${label}: historical trace retention is undocumented`);
  }
});

test('Cloud terminal runtime envelope pairs the terminal done call with its executed result', () => {
  const messages = [
    { role: 'user', content: 'Complete the task' },
    {
      role: 'assistant',
      tool_calls: [{ id: 'call_done', function: { name: 'done', arguments: '{"outcome":"success","summary":"Complete"}' } }],
    },
    { role: 'tool', tool_call_id: 'call_done', content: '{"success":true,"done":true,"summary":"Complete"}' },
  ];
  for (const [label, runtime] of [['chrome', CLOUD_RUNTIME_OUTBOX_CH], ['firefox', CLOUD_RUNTIME_OUTBOX_FX]]) {
    const item = runtime.buildTerminalRuntimeEvent({
      runId: 'run-terminal',
      status: 'done',
      finalContent: 'Complete',
      messages,
      model: 'webbrain-cloud 1.0',
      mode: 'act',
      browserTarget: label,
      extensionVersion: '27.2.0',
    });
    assert.equal(item.event_id, 'run-terminal:1:terminal_runtime');
    assert.equal(item.event.kind, 'terminal_runtime');
    assert.equal(item.event.data.terminal_tool.name, 'done');
    assert.equal(item.event.data.terminal_tool.status, 'succeeded');
    assert.match(item.event.data.terminal_tool.result, /"done":true/);
  }
});

test('Cloud terminal runtime envelope prefers completed done_json over trailing skipped tools', () => {
  const messages = [
    { role: 'user', content: 'Return structured output' },
    {
      role: 'assistant',
      tool_calls: [
        { id: 'call_done_json', function: { name: 'done_json', arguments: '{"result":{"ok":true}}' } },
        { id: 'call_trailing', function: { name: 'click', arguments: '{"ref_id":"e2"}' } },
      ],
    },
    { role: 'tool', tool_call_id: 'call_done_json', content: '{"success":true,"done":true,"doneJson":true,"result":{"ok":true}}' },
    { role: 'tool', tool_call_id: 'call_trailing', content: '{"success":false,"skipped":true}' },
  ];
  for (const [label, runtime] of [['chrome', CLOUD_RUNTIME_OUTBOX_CH], ['firefox', CLOUD_RUNTIME_OUTBOX_FX]]) {
    const item = runtime.buildTerminalRuntimeEvent({
      runId: `run-done-json-${label}`,
      status: 'done',
      finalContent: '{"ok":true}',
      messages,
      browserTarget: label,
    });
    assert.equal(item.event.data.terminal_tool.call_id, 'call_done_json', `${label}: trailing skipped tool replaced done_json`);
    assert.equal(item.event.data.terminal_tool.name, 'done_json', `${label}: done_json was not treated as terminal`);
    assert.equal(item.event.data.terminal_tool.status, 'succeeded');
  }
});

test('Cloud terminal runtime envelope ignores blocked done attempts when later tools execute', () => {
  const messages = [
    { role: 'user', content: 'Complete the task' },
    {
      role: 'assistant',
      tool_calls: [{ id: 'call_blocked_done', function: { name: 'done', arguments: '{"outcome":"success"}' } }],
    },
    { role: 'tool', tool_call_id: 'call_blocked_done', content: '{"success":false,"blockedDone":true}' },
    {
      role: 'assistant',
      tool_calls: [{ id: 'call_recovery', function: { name: 'click', arguments: '{"ref_id":"e3"}' } }],
    },
    { role: 'tool', tool_call_id: 'call_recovery', content: '{"success":true}' },
  ];
  for (const [label, runtime] of [['chrome', CLOUD_RUNTIME_OUTBOX_CH], ['firefox', CLOUD_RUNTIME_OUTBOX_FX]]) {
    const item = runtime.buildTerminalRuntimeEvent({
      runId: `run-blocked-done-${label}`,
      status: 'error',
      finalContent: 'Stopped later',
      messages,
      browserTarget: label,
    });
    assert.equal(item.event.data.terminal_tool.call_id, 'call_recovery', `${label}: blocked done replaced later execution`);
    assert.equal(item.event.data.terminal_tool.name, 'click');
  }
});

test('Cloud terminal runtime outbox persists retryable failures and removes acknowledged events', async () => {
  const originalChrome = globalThis.chrome;
  const storage = {};
  globalThis.chrome = {
    storage: {
      local: {
        async get(keys) {
          const key = Array.isArray(keys) ? keys[0] : keys;
          return { [key]: storage[key] };
        },
        async set(values) { Object.assign(storage, values); },
      },
    },
  };
  try {
    const item = CLOUD_RUNTIME_OUTBOX_CH.buildTerminalRuntimeEvent({
      runId: 'run-retry',
      status: 'error',
      finalContent: 'Failed visibly',
      messages: [
        { role: 'user', content: 'Try it' },
        { role: 'assistant', tool_calls: [{ id: 'call_click', function: { name: 'click', arguments: '{"ref_id":"e1"}' } }] },
        { role: 'tool', tool_call_id: 'call_click', content: '{"success":false,"error":"target missing"}' },
      ],
      browserTarget: 'chrome',
    });
    assert.equal(await CLOUD_RUNTIME_OUTBOX_CH.enqueueCloudRuntimeEvent('conv-1', item), true);
    const provider = {
      config: { providerName: 'webbrain-cloud' },
      calls: 0,
      async sendRuntimeEvents() {
        this.calls++;
        return this.calls === 1
          ? { ok: false, retryable: true, status: 503 }
          : { ok: true, retryable: false, status: 202 };
      },
    };
    assert.equal(await CLOUD_RUNTIME_OUTBOX_CH.flushCloudRuntimeOutbox(provider), 0);
    assert.equal(storage[CLOUD_RUNTIME_OUTBOX_CH.CLOUD_RUNTIME_OUTBOX_STORAGE_KEY].length, 1);
    assert.equal(await CLOUD_RUNTIME_OUTBOX_CH.flushCloudRuntimeOutbox(provider), 1);
    assert.equal(storage[CLOUD_RUNTIME_OUTBOX_CH.CLOUD_RUNTIME_OUTBOX_STORAGE_KEY].length, 0);
  } finally {
    if (originalChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = originalChrome;
  }
});

test('Firefox Cloud runtime outbox uses the promise-based browser storage namespace', async () => {
  const originalBrowser = globalThis.browser;
  const originalChrome = globalThis.chrome;
  const storage = {};
  let chromeCalls = 0;
  globalThis.browser = {
    storage: {
      local: {
        async get(keys) {
          const key = Array.isArray(keys) ? keys[0] : keys;
          return { [key]: storage[key] };
        },
        async set(values) { Object.assign(storage, values); },
      },
    },
  };
  globalThis.chrome = {
    storage: {
      local: {
        get() { chromeCalls++; throw new Error('callback-only chrome namespace used'); },
        set() { chromeCalls++; throw new Error('callback-only chrome namespace used'); },
      },
    },
  };
  try {
    const item = {
      event_id: 'run-firefox-storage:1:terminal_runtime',
      event: { runId: 'run-firefox-storage', seq: 1, ts: 1, kind: 'terminal_runtime', data: {} },
    };
    assert.equal(await CLOUD_RUNTIME_OUTBOX_FX.enqueueCloudRuntimeEvent('conv-firefox', item), true);
    assert.equal(storage[CLOUD_RUNTIME_OUTBOX_FX.CLOUD_RUNTIME_OUTBOX_STORAGE_KEY].length, 1);
    assert.equal(await CLOUD_RUNTIME_OUTBOX_FX.flushCloudRuntimeOutbox({
      config: { providerName: 'webbrain-cloud' },
      async sendRuntimeEvents() { return { ok: true, retryable: false, status: 202 }; },
    }), 1);
    assert.equal(storage[CLOUD_RUNTIME_OUTBOX_FX.CLOUD_RUNTIME_OUTBOX_STORAGE_KEY].length, 0);
    assert.equal(chromeCalls, 0, 'Firefox outbox touched the callback-based chrome namespace');
  } finally {
    if (originalBrowser === undefined) delete globalThis.browser;
    else globalThis.browser = originalBrowser;
    if (originalChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = originalChrome;
  }
});

test('Cloud terminal runtime outbox never overwrites queued data after a storage read failure', async () => {
  const originalChrome = globalThis.chrome;
  let writes = 0;
  globalThis.chrome = {
    storage: {
      local: {
        async get() { throw new Error('storage unavailable'); },
        async set() { writes++; },
      },
    },
  };
  try {
    await assert.rejects(
      CLOUD_RUNTIME_OUTBOX_CH.enqueueCloudRuntimeEvent('conv-fail', {
        event_id: 'run-fail:1:terminal_runtime',
        event: { runId: 'run-fail', seq: 1, ts: 1, kind: 'terminal_runtime', data: {} },
      }),
      /storage unavailable/,
    );
    assert.equal(writes, 0);
  } finally {
    if (originalChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = originalChrome;
  }
});

test('Firefox Cloud runtime delivery uses its available fetch transport', async () => {
  const originalBrowser = globalThis.browser;
  const originalFetch = globalThis.fetch;
  let request = null;
  globalThis.browser = {
    storage: {
      local: { async get() { return {}; } },
      onChanged: { addListener() {} },
    },
  };
  globalThis.fetch = async (url, options) => {
    request = { url, options };
    return { ok: true, status: 202 };
  };
  try {
    const provider = new OpenAIProviderFx({
      providerName: 'webbrain-cloud',
      baseUrl: 'https://cloud.example/v1',
      deviceGuid: 'device-test',
      helpImproveWebBrain: true,
    });
    const result = await provider.sendRuntimeEvents('conv-firefox', [{ event_id: 'event-1', event: {} }], { timeoutMs: 500 });
    assert.deepEqual(result, { ok: true, retryable: false, status: 202 });
    assert.equal(request?.url, 'https://cloud.example/v1/improvement/runtime-events');
    assert.equal(request?.options?.method, 'POST');
    assert.equal(JSON.parse(request?.options?.body || '{}').session_id, 'conv-firefox');
  } finally {
    if (originalBrowser === undefined) delete globalThis.browser;
    else globalThis.browser = originalBrowser;
    if (originalFetch === undefined) delete globalThis.fetch;
    else globalThis.fetch = originalFetch;
  }
});

