test('/export --traces is wired in both side panels and backgrounds', () => {
  for (const [label, panelRel, bgRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js', 'src/chrome/src/background.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js', 'src/firefox/src/background.js'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    const bg = fs.readFileSync(path.join(ROOT, bgRel), 'utf8');
    assert.match(
      panel,
      /usage: '\/export \[--traces \| --config\]'[\s\S]*?value: '--traces'[\s\S]*?action: 'traces'[\s\S]*?outOfBand: true/,
      `${label}: slash metadata should advertise /export --traces`,
    );
    assert.match(
      panel,
      /function slashInvocationIsOutOfBand\(invocation\)[\s\S]*?actionOption\?\.outOfBand \?\? invocation\.command\.outOfBand/,
      `${label}: variant metadata should control busy eligibility`,
    );
    assert.match(
      panel,
      /if \(command\.value === '\/export' && action === 'traces'\) \{[\s\S]*?sendToBackground\('export_traces', \{ tabId \}\)/,
      `${label}: /export --traces should call export_traces on the background`,
    );
    assert.match(
      panel,
      /res\.reason === 'no-conversation'[\s\S]*?sp\.export_traces\.no_conversation[\s\S]*?sp\.export_traces\.none/,
      `${label}: empty export should distinguish no-conversation from no-traces`,
    );
    assert.match(
      panel,
      /sp\.export_traces\.done/,
      `${label}: success path should use the traces-specific done string`,
    );
    assert.match(bg, /case 'export_traces':/, `${label}: background should handle export_traces`);
    assert.match(
      bg,
      /case 'export_traces': \{[\s\S]*?agent\.exportTraces\(tabId\)/,
      `${label}: export_traces should call agent.exportTraces`,
    );
    assert.match(panel, /_Exported with WebBrain v\$\{webbrainVersion\}_/, `${label}: /export should include the current manifest version`);
  }
});

test('config transfer exports and restores Settings values including provider keys', () => {
  const stored = {
    wbLocale: 'tr',
    downloadDirectory: 'Work/WebBrain',
    strictSecretMode: true,
    profileEnabled: true,
    profileText: 'Use the test profile',
    capsolverApiKey: 'CAP-0123456789abcdefghij',
    captchaSolverEnabled: true,
    providers: {
      openai: { type: 'openai', apiKey: 'provider-secret', model: 'gpt-test', configured: true },
      webbrain_cloud: { type: 'openai', deviceGuid: 'must-stay-on-device' },
    },
    activeProvider: 'openai',
    visionModel: { baseUrl: 'https://vision.example/v1', apiKey: 'vision-secret', model: 'vision-test' },
    transcriptionModel: { baseUrl: 'https://audio.example/v1', apiKey: 'audio-secret', model: 'whisper-test' },
    wb_permissions: [{ capability: 'click', host: 'example.com' }],
    wb_user_memory_v1: { version: 1, records: [{ id: 'mem_1', text: 'Prefer concise answers', kind: 'preference' }] },
    cloudCostSpentUsd: 8.5,
    meteredProviderCostSpentUsd: 2.5,
    profileSyncToken: 'device-session-secret',
    webbrainDeviceGuid: 'device-guid',
  };
  const options = { exportedAt: '2026-07-16T12:00:00.000Z', webbrainVersion: '24.0.2', locale: 'tr' };

  const chromeExport = ConfigTransferCh.createConfigExport(stored, options);
  const firefoxExport = ConfigTransferFx.createConfigExport(stored, options);
  assert.deepEqual(firefoxExport, chromeExport, 'Chrome and Firefox config schemas should remain identical');
  assert.equal(chromeExport.schema, 'webbrain-config/1');
  assert.equal(chromeExport.settings.providers.openai.apiKey, 'provider-secret');
  assert.equal(chromeExport.settings.visionModel.apiKey, 'vision-secret');
  assert.equal(chromeExport.settings.transcriptionModel.apiKey, 'audio-secret');
  assert.equal(chromeExport.settings.capsolverApiKey, 'CAP-0123456789abcdefghij');
  assert.equal(chromeExport.settings.captchaSolverEnabled, true);
  assert.equal(chromeExport.settings.profileText, 'Use the test profile');
  assert.equal(chromeExport.settings.downloadDirectory, 'Work/WebBrain');
  assert.equal(chromeExport.settings.wb_user_memory_v1.records.length, 1);
  assert.equal(chromeExport.settings.providers.webbrain_cloud.deviceGuid, undefined, 'device identity must not be portable');
  assert.equal(chromeExport.settings.cloudCostSpentUsd, undefined, 'spend counters are runtime state, not config');
  assert.equal(chromeExport.settings.meteredProviderCostSpentUsd, undefined, 'metered spend counters are runtime state, not config');
  assert.equal(chromeExport.settings.profileSyncToken, undefined, 'Cloud Sync sessions must not be exported');
  assert.equal(chromeExport.settings.webbrainDeviceGuid, undefined, 'device GUID must not be exported');
  assert.match(chromeExport.warning, /plaintext provider API keys/i);

  const imported = ConfigTransferCh.parseConfigImport(JSON.stringify(chromeExport));
  assert.equal(imported.settings.providers.openai.apiKey, 'provider-secret');
  assert.equal(imported.settings.activeProvider, 'openai');
  assert.equal(imported.settings.downloadDirectory, 'Work/WebBrain');
  assert.equal(imported.settings.themeMode, 'system', 'missing Settings values should restore their product defaults');
  assert.equal(Object.keys(imported.settings).length, ConfigTransferCh.CONFIG_STORAGE_KEYS.length);

  const sparseJson = JSON.stringify({
    schema: 'webbrain-config/1',
    webbrainVersion: '24.0.2',
    settings: {
      verboseMode: true,
      providers: {
        openai: {
          type: 'openai',
          apiKey: 'provider-secret',
          configured: true,
          deviceGuid: 'must-not-import',
        },
        webbrain_cloud: {
          type: 'openai',
          baseUrl: 'https://stale-export.example/v1',
          apiKey: 'stale-export-secret',
          configured: true,
          deviceGuid: 'must-not-import',
        },
      },
      futureSetting: 'ignored',
    },
  });
  const chromePatch = ConfigTransferCh.parseConfigPatchImport(sparseJson);
  const firefoxPatch = ConfigTransferFx.parseConfigPatchImport(sparseJson);
  assert.deepEqual(firefoxPatch, chromePatch, 'Chrome and Firefox sparse config imports should remain identical');
  assert.deepEqual(Object.keys(chromePatch.settings), ['verboseMode', 'providers']);
  assert.equal(chromePatch.settings.themeMode, undefined, 'sparse import must leave omitted settings untouched');
  assert.equal(chromePatch.settings.providers.openai.deviceGuid, undefined);
  assert.deepEqual(chromePatch.ignoredKeys, ['futureSetting']);
  const currentSettings = {
    providers: {
      webbrain_cloud: {
        type: 'openai',
        baseUrl: 'https://platform.example/v1',
        apiKey: 'platform-secret',
        deviceGuid: 'platform-device',
      },
      anthropic: { type: 'anthropic', apiKey: 'existing-secret' },
    },
  };
  const mergedPatch = ConfigTransferCh.mergeConfigPatchSettings(currentSettings, chromePatch.settings);
  const firefoxMergedPatch = ConfigTransferFx.mergeConfigPatchSettings(currentSettings, firefoxPatch.settings);
  assert.deepEqual(firefoxMergedPatch, mergedPatch, 'Chrome and Firefox provider merge should remain identical');
  assert.deepEqual(
    mergedPatch.providers.webbrain_cloud,
    currentSettings.providers.webbrain_cloud,
    'sparse import must preserve the complete platform-managed WebBrain Compass provider',
  );
  assert.equal(mergedPatch.providers.anthropic.apiKey, 'existing-secret');
  assert.equal(mergedPatch.providers.openai.apiKey, 'provider-secret');
  assert.equal(currentSettings.providers.openai, undefined, 'provider merge must not mutate current storage');
  assert.equal(
    ConfigTransferCh.mergeConfigPatchSettings({}, chromePatch.settings).providers.webbrain_cloud,
    undefined,
    'a portable WebBrain Compass provider must not be introduced without platform state',
  );
});

// trace run header — session lineage allowlist
// ────────────────────────────────────────────────────────────────────────

console.log('\ntrace run header');

const RUN_HEADER_CH = await import('file://' + path.join(ROOT, 'src/chrome/src/trace/run-header.js').replace(/\\/g, '/'));
const RUN_HEADER_FX = await import('file://' + path.join(ROOT, 'src/firefox/src/trace/run-header.js').replace(/\\/g, '/'));

test('trace run header: normalizeRunHeader keeps only allowlisted lineage ids', () => {
  const { normalizeRunHeader } = RUN_HEADER_CH;
  assert.equal(normalizeRunHeader(null), null);
  assert.equal(normalizeRunHeader([]), null);
  assert.equal(normalizeRunHeader({}), null, 'empty header must be null');
  const valid = normalizeRunHeader({ parentRunId: 'run_abc', parentSessionId: 'conv_1', delegationDepth: 3 });
  assert.deepEqual(valid, { parentRunId: 'run_abc', parentSessionId: 'conv_1', delegationDepth: 3 });
  assert.equal(normalizeRunHeader({ parentRunId: 'x'.repeat(201) }), null, 'over-long id must be rejected');
  assert.deepEqual(normalizeRunHeader({ parentRunId: '  run_x  ' }), { parentRunId: 'run_x' }, 'ids should be trimmed');
  assert.equal(normalizeRunHeader({ parentRunId: 'bad\u0000id' }), null, 'control characters must be rejected');
  assert.equal(normalizeRunHeader({ delegationDepth: -1 }), null, 'negative depth must be rejected');
  assert.equal(normalizeRunHeader({ delegationDepth: 3.5 }), null, 'fractional depth must be rejected');
  assert.equal(normalizeRunHeader({ delegationDepth: 65 }), null, 'depth beyond the bound must be rejected');
  assert.deepEqual(normalizeRunHeader({ parentSessionId: 'conv_9' }), { parentSessionId: 'conv_9' }, 'session id alone must survive');
});

test('trace run header: effectiveDelegationDepth resolves root/child/explicit', () => {
  const { effectiveDelegationDepth, normalizeRunHeader } = RUN_HEADER_CH;
  assert.equal(effectiveDelegationDepth(null), 0, 'no header is a root run');
  assert.equal(effectiveDelegationDepth(normalizeRunHeader({})), 0, 'empty header is a root run');
  assert.equal(effectiveDelegationDepth(normalizeRunHeader({ parentRunId: 'run_p' })), 1, 'parent without depth is a direct child');
  assert.equal(effectiveDelegationDepth(normalizeRunHeader({ parentRunId: 'run_p', delegationDepth: 5 })), 5, 'explicit depth wins');
  assert.equal(effectiveDelegationDepth(normalizeRunHeader({ parentSessionId: 'conv_x' })), 0, 'session id without parent run is a root run');
});

test('trace run header: mirrors are identical and browser-neutral', () => {
  const chromeSource = fs.readFileSync(path.join(ROOT, 'src/chrome/src/trace/run-header.js'), 'utf8');
  const firefoxSource = fs.readFileSync(path.join(ROOT, 'src/firefox/src/trace/run-header.js'), 'utf8');
  assert.equal(chromeSource, firefoxSource, 'Chrome/Firefox run header drifted');
  assert.equal(typeof RUN_HEADER_FX.normalizeRunHeader, 'function', 'Firefox run header missing exports');
  assert.doesNotMatch(chromeSource, /chrome\./, 'run header must not depend on chrome APIs');
  assert.doesNotMatch(chromeSource, /indexedDB|storage\./, 'run header must not touch storage');
});

// trace lossless tier — opt-in full-request recording
// ────────────────────────────────────────────────────────────────────────

console.log('\ntrace lossless tier');

const RUNTIME_CONFIG_CH = await import('file://' + path.join(ROOT, 'src/chrome/src/trace/runtime-config.js').replace(/\\/g, '/'));

test('trace lossless tier: runtime-config accepts the boolean and defaults stay off', () => {
  const normalized = RUNTIME_CONFIG_CH.normalizeRuntimeTraceConfig({ lossless_trace: true });
  assert.equal(normalized.lossless_trace, true, 'lossless_trace boolean not allowlisted');
  const off = RUNTIME_CONFIG_CH.normalizeRuntimeTraceConfig({ lossless_trace: false });
  assert.equal(off.lossless_trace, false, 'lossless_trace false should survive');
  const junk = RUNTIME_CONFIG_CH.normalizeRuntimeTraceConfig({ lossless_trace: 'yes' });
  assert.equal(junk.lossless_trace, undefined, 'non-boolean lossless_trace must be rejected');
});

test('trace lossless tier: recorder branches on the tier and clamps payloads', () => {
  for (const browser of ['chrome', 'firefox']) {
    const recorderSource = fs.readFileSync(path.join(ROOT, `src/${browser}/src/trace/recorder.js`), 'utf8');
    assert.match(recorderSource, /async function losslessTraceEnabled\(\)/, `${browser}: losslessTraceEnabled missing`);
    assert.match(recorderSource, /const lossless = meta\.lossless === true \|\| await losslessTraceEnabled\(\);/, `${browser}: tier decision missing in startRun`);
    assert.match(recorderSource, /\.\.\.\(lossless \? \{ lossless: true, losslessBytes: 0, losslessBytesEncoding: 'utf8' \} : \{\}\)/, `${browser}: run record does not stamp the tier and UTF-8 accounting unit`);
    assert.match(recorderSource, /const LOSSILESS_RESULT_CAP = 200_000;/, `${browser}: lossless result cap missing`);
    assert.match(recorderSource, /const LOSSILESS_REQUEST_CAP = 500_000;/, `${browser}: lossless request cap missing`);
    assert.match(recorderSource, /_appendEvent\(runId, 'llm_request', \(state\)[\s\S]*?state\?\.lossless === true && provenanceInput/, `${browser}: request lossless branch missing`);
    assert.match(recorderSource, /const cap = state\?\.lossless === true\s*\? Math\.min\(LOSSILESS_RESULT_CAP, remainingBytes\)\s*:\s*20_000;/, `${browser}: tool-result cap does not branch on tier and remaining UTF-8 budget`);
    assert.match(recorderSource, /peekRunFlags|lossless: record\?\.lossless === true|lossless = record\?\.lossless === true/, `${browser}: SW-eviction recovery does not restore the tier`);
    assert.match(recorderSource, /async function _ensureRunState\(runId(?:, db = null)?\)/, `${browser}: recorder has no shared SW-recovery state loader`);
    assert.match(recorderSource, /function recordLLMRequest[\s\S]*?_appendEvent\(runId, 'llm_request', \(state\)[\s\S]*?state\?\.lossless === true/, `${browser}: request recovery is not serialized inside the write queue`);
    assert.match(recorderSource, /function recordToolCall[\s\S]*?_appendEvent\(runId, 'tool', \(state\)[\s\S]*?state\?\.lossless === true/, `${browser}: tool recovery is not serialized inside the write queue`);
    assert.match(recorderSource, /const _workflowTraceCaptures = new Map\(\)[\s\S]*?function recordToolCall[\s\S]*?_workflowTraceCaptures\.get\(runId\)[\s\S]*?workflowCapture\.events\.push[\s\S]*?return _appendEvent\(runId, 'tool'/, `${browser}: raw workflow inputs are not isolated to the in-memory pre-projection capture`);
    assert.match(recorderSource, /args: clampUtf8Value\(args \?\? null, 20_000\)[\s\S]*?result: clampUtf8Value\(result \?\? null, 20_000\)/, `${browser}: transient workflow inputs are not size-bounded`);
    assert.match(recorderSource, /const workflowCapture = _workflowTraceCaptures\.get\(runId\) \|\| null;[\s\S]*?_workflowTraceCaptures\.delete\(runId\);[\s\S]*?return \{ run: workflowCapture\.run, events: workflowCapture\.events \};/, `${browser}: completed runs do not release their transient workflow capture`);
    assert.match(recorderSource, /\.\.\.\(lossless \? \{ lossless: true, losslessBytes: 0, losslessBytesEncoding: 'utf8' \} : \{\}\)/, `${browser}: default run records should omit lossless accounting fields`);
    assert.match(recorderSource, /LOSSILESS_TOOLS_CAP|clampLosslessRequest|tools: \{ _truncated/, `${browser}: lossless tool schemas are not independently bounded`);
    assert.match(recorderSource, /evictOldestLosslessRuns[\s\S]*?status !== 'running'[\s\S]*?sort\(\(a, b\) => \(a\.startedAt \|\| 0\) - \(b\.startedAt \|\| 0\)\)[\s\S]*?await deleteRun\(run\.runId\)/, `${browser}: lossless runs are not evicted oldest-first`);
    assert.match(recorderSource, /_losslessTotalEstimate \+= addedBytes;[\s\S]*?if \(_losslessTotalEstimate <= LOSSILESS_TOTAL_CAP\) return;/, `${browser}: eviction scan is not gated by a cached running total`);
    assert.match(recorderSource, /async function _scanLosslessTotal\(\)[\s\S]*?objectStore\('runs'\)\.openCursor\(\)/, `${browser}: lossless total must scan every run, not a newest-N window`);
    assert.match(recorderSource, /for \(const run of runs\) \{\s*total \+= run\.losslessBytesEncoding === 'utf8'\s*\? Number\(run\.losslessBytes\) \|\| 0\s*: await _recomputeLosslessBytes\(db, run\);/, `${browser}: aggregate scans should trust UTF-8-marked totals and recompute only legacy lossless runs`);
    assert.match(recorderSource, /function _putEventWithLosslessTotal\(db, runId, event, losslessBytes\) \{[\s\S]*?tx\(db, \['events', 'runs'\]\)[\s\S]*?transaction\.oncomplete = \(\) => resolve\(totalUpdated\);[\s\S]*?eventsStore\.put\(event\);[\s\S]*?runsStore\.get\(runId\)[\s\S]*?run\.losslessBytes = losslessBytes;\s*run\.losslessBytesEncoding = 'utf8';\s*runsStore\.put\(run\);/, `${browser}: counted lossless events and their UTF-8 totals must commit atomically`);
    assert.match(recorderSource, /const nextLosslessBytes = \(state\.losslessBytes \|\| 0\) \+ bytes;\s*const totalUpdated = await _putEventWithLosslessTotal\(db, runId, ev, nextLosslessBytes\);\s*if \(totalUpdated\) \{\s*state\.losslessBytes = nextLosslessBytes;/, `${browser}: in-memory lossless totals must advance only after the atomic event/run transaction commits`);
    assert.match(recorderSource, /async function _recomputeLosslessBytes\(db, run, \{\s*refreshActiveState = true,\s*trustMarkedCurrent = true,[\s\S]*?index\('runId'\)[\s\S]*?getAll\(IDBKeyRange\.only\(run\.runId\)\)[\s\S]*?new TextEncoder\(\)\.encode\(JSON\.stringify\(event\.data\)\)\.length[\s\S]*?const runTx = tx\(db, \['runs'\]\);[\s\S]*?runStore\.get\(run\.runId\)[\s\S]*?if \(trustMarkedCurrent && current\.losslessBytesEncoding === 'utf8'\) \{[\s\S]*?bytes = Number\(current\.losslessBytes\) \|\| 0;[\s\S]*?current\.losslessBytes = bytes;/, `${browser}: aggregate scans should transactionally migrate legacy totals without overwriting a newer atomic marked total`);
    assert.match(recorderSource, /let _losslessBudgetQueue = Promise\.resolve\(\);[\s\S]*?const rescan = _losslessTotalEstimate === null;[\s\S]*?_losslessBudgetQueue\.then\(\(\) => _evictOldestLosslessRuns[\s\S]*?if \(rescan \|\| _losslessTotalEstimate === null\)[\s\S]*?await _scanLosslessTotal\(\);/, `${browser}: concurrent initial aggregate scans should serialize without awaiting another run's write queue`);
    assert.match(recorderSource, /_runState\.get\(run\.runId\)\?\.lossless === true[\s\S]*?void _queueRunWrite\(run\.runId, async \(\) => \{[\s\S]*?_recomputeLosslessBytes\(db, run, \{\s*refreshActiveState: false,\s*trustMarkedCurrent: false,[\s\S]*?state\.losslessBytes = refreshedBytes;/, `${browser}: migrated active-run byte totals should force-refresh only inside that run's serialized write queue`);
    assert.match(recorderSource, /clearAllRuns\(\) \{[\s\S]*?_losslessTotalEstimate = null;/, `${browser}: clearAllRuns does not reset the lossless total cache`);
    assert.match(recorderSource, /new TextEncoder\(\)\.encode\(JSON\.stringify\(resolvedData\)\)\.length/, `${browser}: lossless budgets should count serialized UTF-8 bytes`);
    assert.match(recorderSource, /function clampLosslessRequest\(messages, tools, maxBytes = LOSSILESS_REQUEST_CAP\)[\s\S]*?const byteLength = utf8ByteLength\(serialized\);[\s\S]*?length: byteLength,[\s\S]*?fitUtf8Prefix\(serialized, limit,/, `${browser}: lossless requests should clamp and report UTF-8 bytes`);
    assert.match(recorderSource, /import \{ clampUtf8Value, fitUtf8Prefix, utf8ByteLength \} from '\.\/utf8-budget\.js';[\s\S]*?const shortResult = clampUtf8Value\(result, cap\);/, `${browser}: tool results should use the serialized UTF-8 clamp`);
    assert.match(recorderSource, /function losslessBudgetMarker\(kind, data\)[\s\S]*?args: null,[\s\S]*?losslessBudgetOmitted: true,/, `${browser}: exhausted lossless payloads should retain content-free request and tool markers`);
    assert.match(recorderSource, /function boundedLosslessRequestMetadata\(data\)[\s\S]*?'providerClass'[\s\S]*?'providerId'[\s\S]*?'model'[\s\S]*?'phase'[\s\S]*?'messageCount'[\s\S]*?'toolsCount'[\s\S]*?'imageBlockCount'[\s\S]*?'documentBlockCount'[\s\S]*?localWikipediaRag/, `${browser}: post-cap request markers should retain only bounded content-free metadata`);
    assert.match(recorderSource, /const toolNames = Array\.isArray\(data\?\.messages\?\.toolNames\)[\s\S]*?: boundedToolNames\(data\?\.tools\);[\s\S]*?\.\.\.boundedLosslessRequestMetadata\(data\),[\s\S]*?messages: \{ _truncated: true, length, head: budgetHead, toolNames \}/, `${browser}: post-cap request markers should preserve bounded tool names and request metadata`);
    assert.match(recorderSource, /const remainingBytes = Math\.max\(0, LOSSILESS_RUN_CAP - \(state\.losslessBytes \|\| 0\)\);\s*if \(losslessBytes > remainingBytes\) \{\s*resolvedData = losslessBudgetMarker\(kind, resolvedData\);\s*losslessBudgetOmitted = true;[\s\S]*?if \(losslessBudgetOmitted\) \{\s*await promisifyReq\(tx\(db, \['events'\]\)\.objectStore\('events'\)\.put\(ev\)\);\s*return seq;/, `${browser}: a final lossless event should become an uncounted timeline marker instead of overrunning or disappearing`);
    assert.match(recorderSource, /if \(event\?\.data\?\.losslessBudgetOmitted === true\) continue;\s*try \{ bytes \+= new TextEncoder/, `${browser}: legacy byte recomputation should exclude content-free budget markers`);
    assert.match(recorderSource, /state\?\.lossless === true && state\.losslessBytesEncoding !== 'utf8'[\s\S]*?_recomputeLosslessBytes\(db, run, \{\s*refreshActiveState: false,\s*trustMarkedCurrent: false,[\s\S]*?state\.losslessBytesEncoding = 'utf8';[\s\S]*?let resolvedData = typeof data === 'function' \? data\(state\) : data;/, `${browser}: legacy active totals should force-migrate before the first payload cap guard runs`);
    assert.doesNotMatch(recorderSource, /length: 0, head: '\(per-run lossless budget reached\)'/, `${browser}: budget-reached markers lost the true payload length`);
    // Default tier must keep the content-free provenance path.
    assert.match(recorderSource, /buildPromptTraceProvenance\(/, `${browser}: default tier lost its provenance reduction`);
    const agentSource = fs.readFileSync(path.join(ROOT, `src/${browser}/src/agent/agent.js`), 'utf8');
    assert.match(agentSource, /_rememberWorkflowDraftFromCapture\(tabId, capture\)[\s\S]*?compileWorkflowFromTrace\(capture\.run, capture\.events[\s\S]*?_latestWorkflowDrafts\.set\(tabId[\s\S]*?workflowDraft: this\._latestWorkflowDrafts\.get\(tabId\) \|\| null/, `${browser}: successful raw captures are not reduced to session-scoped value-free drafts`);
    assert.match(agentSource, /const workflowCapture = await trace\.endRun\(runId, \{ status, finalContent \}\);[\s\S]*?_rememberWorkflowDraftFromCapture\(tabId, workflowCapture\)[\s\S]*?await this\._persistNow\(tabId\)/, `${browser}: workflow draft persistence is not ordered after trace completion`);
  }
});

test('trace UTF-8 budget helpers keep multibyte truncation inside byte limits', () => {
  for (const [browser, budget] of [['chrome', Utf8BudgetCh], ['firefox', Utf8BudgetFx]]) {
    assert.equal(budget.utf8ByteLength('A漢🙂'), 8, `${browser}: UTF-8 byte length should count CJK and astral characters`);
    assert.equal(budget.fitUtf8Prefix('漢🙂A', 6), '漢', `${browser}: a raw prefix should not split or overrun a multibyte character`);
    const serializeMarker = head => JSON.stringify({ _truncated: true, head });
    const markerLimit = budget.utf8ByteLength(serializeMarker('漢'));
    const head = budget.fitUtf8Prefix('漢字🙂', markerLimit, serializeMarker);
    assert.equal(head, '漢', `${browser}: marker overhead should be included in the byte boundary`);
    assert.ok(budget.utf8ByteLength(serializeMarker(head)) <= markerLimit, `${browser}: serialized marker exceeded its UTF-8 budget`);
    const escaped = '\n'.repeat(120);
    const escapedBytes = budget.utf8ByteLength(JSON.stringify(escaped));
    const clamped = budget.clampUtf8Value(escaped, 100);
    assert.equal(escapedBytes, 242, `${browser}: escaped string evidence should include JSON quotes and escapes`);
    assert.equal(clamped._truncated, true, `${browser}: escaped string bypassed the serialized byte cap`);
    assert.equal(clamped.length, escapedBytes, `${browser}: truncation marker should report serialized UTF-8 bytes`);
    assert.ok(escaped.startsWith(clamped.head), `${browser}: string truncation marker should keep a raw readable prefix`);
    assert.ok(budget.utf8ByteLength(JSON.stringify(clamped)) <= 100, `${browser}: escaped string marker exceeded its serialized UTF-8 cap`);
  }
});

