test('trace UI: exports a session bundle while preserving standalone JSON shape', () => {
  for (const [browser, runtimeName] of [['chrome', 'chrome'], ['firefox', 'browser']]) {
    const traces = fs.readFileSync(path.join(ROOT, `src/${browser}/src/ui/traces.js`), 'utf8');
    assert.match(traces, /import \{ buildTraceExportPayload \} from '\.\.\/trace\/export-contract\.js';/, `${browser}: export contract import missing`);
    assert.match(traces, /async function loadTraceExportEntry\(run\)/, `${browser}: trace entry loader missing`);
    assert.match(traces, /listRuns\(\{ limit: Number\.MAX_SAFE_INTEGER, conversationId: sessionId \}\)/, `${browser}: session export retains the default 500-run cap`);
    assert.match(traces, /for \(const candidate of \[\.\.\.sessionRuns, run\]\)/, `${browser}: selected run is not guaranteed in a session export`);
    assert.match(traces, /exportRuns\.sort\(\(left, right\) => \([\s\S]*?left\.startedAt[\s\S]*?left\.runId/, `${browser}: session runs are not ordered deterministically`);
    assert.match(traces, /for \(const exportRun of exportRuns\) entries\.push\(await loadTraceExportEntry\(exportRun\)\)/, `${browser}: session export does not load every run's events`);
    assert.match(traces, /buildTraceExportPayload\(entries, \{[\s\S]*?sessionId,[\s\S]*?exportedAt: Date\.now\(\)/, `${browser}: UI does not build the versioned export envelope`);
    assert.match(traces, /isSession\s*\?\s*`webbrain-session-\$\{safeFilenamePart\(sessionId, 'session'\)\}\.json`/, `${browser}: session export filename is not bounded`);
    assert.match(traces, new RegExp(`exportedByWebBrainVersion: ${runtimeName}\\.runtime\\.getManifest\\(\\)\\.version`), `${browser}: export version metadata changed unexpectedly`);
    assert.match(traces, /sanitizeTraceExport\(payload\)/, `${browser}: session export bypasses privacy sanitization`);
    assert.match(traces, /function traceExportConfirmation\(exportRuns\)[\s\S]*?sensitiveRunCount[\s\S]*?tr\.lossless\.warning/, `${browser}: session export does not disclose lossless sibling runs`);
    assert.match(traces, /isSession && !confirm\(traceExportConfirmation\(exportRuns\)\)/, `${browser}: session scope is not confirmed before export`);
    assert.match(traces, /const exportSessionId = typeof run\.conversationId[\s\S]*?\.trim\(\)[\s\S]*?exportButton\.title = exportSessionId[\s\S]*?tr\.conversation\.label/, `${browser}: export tooltip still claims every download is one selected run`);
    assert.match(traces, /catch \(error\) \{[\s\S]*?\[traces\] export failed:[\s\S]*?alert\(/, `${browser}: failed session reads can still produce a partial-looking download`);
  }
});

test('model output diagnostics: classifies empty completions without retaining reasoning text', () => {
  for (const [label, diagnostics] of [
    ['chrome', ModelOutputDiagnosticsCh],
    ['firefox', ModelOutputDiagnosticsFx],
  ]) {
    const limited = diagnostics.modelOutputDiagnostics({
      content: '',
      toolCalls: [],
      reasoningContent: 'private reasoning text',
      usage: {
        completion_tokens: 4096,
        completion_tokens_details: { reasoning_tokens: 4096 },
      },
      finishReason: 'length',
    }, { requestedMaxTokens: 4096, recoveryAttempt: 2 });
    assert.deepEqual(limited, {
      empty: true,
      emptyReason: 'output_limit',
      finishReason: 'length',
      contentChars: 0,
      toolCallCount: 0,
      reasoningPresent: true,
      reasoningChars: 22,
      reasoningTokens: 4096,
      outputTokens: 4096,
      requestedMaxTokens: 4096,
      recoveryAttempt: 2,
    }, `${label}: output-limit diagnostics changed`);
    assert.doesNotMatch(JSON.stringify(limited), /private reasoning text/, `${label}: reasoning text leaked into diagnostics`);
    assert.match(diagnostics.emptyOutputFailureMessage(limited), /response-token limit/i, `${label}: output-limit guidance missing`);
    assert.doesNotMatch(diagnostics.emptyOutputFailureMessage(limited), /step limit/i, `${label}: model output failures must not blame the agent step limit`);
    assert.doesNotMatch(diagnostics.emptyOutputFailureMessage(limited), /increase the response-token limit/i, `${label}: output-limit guidance must not recommend an unavailable setting`);

    assert.equal(diagnostics.modelOutputDiagnostics({
      content: '',
      toolCalls: null,
      reasoningContent: 'thought',
      usage: { completion_tokens: 12 },
    }, { requestedMaxTokens: 4096 }).emptyReason, 'reasoning_only', `${label}: reasoning-only response not classified`);
    assert.equal(diagnostics.modelOutputDiagnostics({
      content: '',
      toolCalls: [],
      responseItems: [{ type: 'reasoning', encrypted_content: 'opaque' }],
    }).emptyReason, 'reasoning_only', `${label}: encrypted reasoning item not detected without exposing it`);
    assert.equal(diagnostics.modelOutputDiagnostics({
      content: '',
      toolCalls: [],
      usage: { completion_tokens: 42 },
      responseItems: [{
        type: 'webbrain_provider_replay',
        content: [{ type: 'redacted_thinking', data: 'opaque' }],
      }],
    }, { requestedMaxTokens: 4096 }).emptyReason, 'reasoning_only', `${label}: provider replay reasoning envelope not detected`);
    assert.equal(diagnostics.modelOutputDiagnostics({
      content: '',
      toolCalls: [],
      finishReason: 'content_filter',
    }).emptyReason, 'content_filter', `${label}: filtered response not classified`);
    assert.equal(diagnostics.modelOutputDiagnostics({
      content: '',
      toolCalls: [],
      usage: { completion_tokens: 0 },
    }, { requestedMaxTokens: 4096 }).emptyReason, 'provider_empty', `${label}: unexplained empty response not classified`);
    assert.equal(diagnostics.modelOutputDiagnostics({
      content: '',
      toolCalls: [],
      raw: { choices: [{ finish_reason: 'max_tokens' }] },
    }).emptyReason, 'output_limit', `${label}: raw provider finish reason not classified`);
    assert.equal(diagnostics.modelOutputDiagnostics({
      content: 'done',
      toolCalls: [],
      reasoningContent: 'thought',
    }).emptyReason, null, `${label}: visible output must not receive an empty classification`);
    assert.equal(diagnostics.modelOutputDiagnostics({
      content: '',
      toolCalls: [{ id: 'call_1' }],
    }).empty, false, `${label}: tool output must not be empty`);
    const reasoningMessage = diagnostics.emptyOutputFailureMessage({ emptyReason: 'reasoning_only' });
    assert.match(reasoningMessage, /latest model response/i, `${label}: reasoning-only guidance should identify the observed attempt`);
    assert.doesNotMatch(reasoningMessage, /twice/i, `${label}: reasoning-only guidance must not invent the first attempt's cause`);
    const filteredMessage = diagnostics.emptyOutputFailureMessage({ emptyReason: 'content_filter' });
    assert.match(filteredMessage, /latest response/i, `${label}: filter guidance should identify the observed attempt`);
    assert.doesNotMatch(filteredMessage, /both attempts/i, `${label}: filter guidance must not invent the first attempt's cause`);
  }
  assert.equal(
    fs.readFileSync(path.join(ROOT, 'src/chrome/src/agent/model-output-diagnostics.js'), 'utf8'),
    fs.readFileSync(path.join(ROOT, 'src/firefox/src/agent/model-output-diagnostics.js'), 'utf8'),
    'Chrome/Firefox output diagnostics must remain mirrored',
  );
});

test('trace export: renders privacy-safe empty-response diagnostics', () => {
  const runs = [{
    run: { runId: 'empty-output', userMessage: 'Continue', model: 'test-model', status: 'empty_output' },
    events: [{
      runId: 'empty-output',
      seq: 1,
      kind: 'llm_response',
      data: {
        step: 7,
        content: null,
        toolCalls: [],
        empty: true,
        emptyReason: 'output_limit',
        finishReason: 'length',
        contentChars: 0,
        toolCallCount: 0,
        reasoningPresent: true,
        reasoningChars: 0,
        reasoningTokens: 4096,
        outputTokens: 4096,
        requestedMaxTokens: 4096,
        recoveryAttempt: 2,
      },
    }],
  }];
  for (const [label, serialize] of [['chrome', tracesToMarkdown], ['firefox', tracesToMarkdownFx]]) {
    const { markdown } = serialize(runs);
    assert.match(markdown, /Empty model response: reason=output_limit · finish=length · output=4096 tokens · reasoning=4096 tokens · limit=4096 tokens · attempt=2 · 0 visible chars · 0 tool calls/, `${label}: empty-response metadata remains hidden`);
    const legacy = serialize([{
      run: { runId: 'legacy-empty', userMessage: 'Continue', status: 'empty_output' },
      events: [{ runId: 'legacy-empty', seq: 1, kind: 'llm_response', data: { content: null, toolCalls: [] } }],
    }]).markdown;
    assert.match(legacy, /Empty model response: reason=unknown/, `${label}: old empty events should stay visible without an invented cause`);
    assert.doesNotMatch(legacy, /reason=provider_empty/, `${label}: legacy events cannot prove a provider-empty cause`);
  }
});

test('agent trace error classification: _traceErrorCodeFor maps failures to stable codes', () => {
  for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
    const agent = new AgentClass({});
    assert.equal(agent._traceErrorCodeFor({ status: 401, message: 'bad key' }), 'INVALID_CREDENTIAL', `${label}: 401 must classify as credential`);
    assert.equal(agent._traceErrorCodeFor({ status: 403, message: 'forbidden' }), 'INVALID_CREDENTIAL', `${label}: 403 must classify as credential`);
    assert.equal(agent._traceErrorCodeFor({ status: 429, message: 'rate limited' }), 'RATE_LIMIT', `${label}: 429 must classify as rate limit`);
    assert.equal(agent._traceErrorCodeFor({ message: 'You have hit your quota' }), 'QUOTA', `${label}: quota wording must remain distinct from rate limiting`);
    assert.equal(agent._traceErrorCodeFor({ message: 'context window exceeded' }), 'CONTEXT_WINDOW_EXCEEDED', `${label}: context wording must classify as overflow`);
    assert.equal(agent._traceErrorCodeFor({ message: 'empty response' }), 'EMPTY_RESPONSE', `${label}: empty wording must classify as empty`);
    assert.equal(agent._traceErrorCodeFor({ message: 'connection reset' }), 'TRANSPORT', `${label}: transport failures must classify as transport`);
    assert.equal(agent._traceErrorCodeFor({ message: 'network error — could not reach the server' }), 'TRANSPORT', `${label}: provider reachability wording must not look like empty output`);
    assert.equal(agent._traceErrorCodeFor({ code: 'WB_COST_ALLOWANCE' }), 'COST_LIMIT', `${label}: cost allowance must classify as cost limit`);
    assert.equal(agent._traceErrorCodeFor({ message: 'Subscribe for more usage: https://webbrain.one/' }), 'COST_LIMIT', `${label}: cloud subscribe prompt must classify as cost limit`);
    assert.deepEqual(agent._traceStepEndForResult({ content: '', toolCalls: [] }), { ok: false, code: 'EMPTY_RESPONSE' }, `${label}: empty model output must close as a failed step`);
    assert.deepEqual(agent._traceStepEndForResult({ content: 'done', toolCalls: [] }), { ok: true }, `${label}: text output must close as a successful step`);
    assert.deepEqual(agent._traceStepEndForResult({ content: '', toolCalls: [{ id: 'call_1' }] }, { retried: true }), { ok: true, retried: true }, `${label}: retried tool output must close as successful`);
    assert.deepEqual(agent._traceTurnEndPayload('error', 'TRANSPORT'), { status: 'error', reason: 'error', code: 'TRANSPORT' }, `${label}: failed turn must carry reason and code`);
    assert.deepEqual(agent._traceTurnEndPayload('done'), { status: 'done', reason: 'done' }, `${label}: successful turn must not invent a failure code`);
  }
});

test('trace recorder: turn/step boundary helpers and structured error codes are wired', () => {
  for (const browser of ['chrome', 'firefox']) {
    const recorderSource = fs.readFileSync(path.join(ROOT, `src/${browser}/src/trace/recorder.js`), 'utf8');
    assert.match(recorderSource, /export function recordTurnStart\(runId, step, payload = \{\}\)/, `${browser}: recordTurnStart missing`);
    assert.match(recorderSource, /export function recordTurnEnd\(runId, step, payload = \{\}\)/, `${browser}: recordTurnEnd missing`);
    assert.match(recorderSource, /export function recordStepStart\(runId, step, payload = \{\}\)/, `${browser}: recordStepStart missing`);
    assert.match(recorderSource, /export function recordStepEnd\(runId, step, payload = \{\}\)/, `${browser}: recordStepEnd missing`);
    assert.match(recorderSource, /recordError\(runId, step, phase, message, code\)/, `${browser}: recordError does not accept a structured code`);
    assert.match(recorderSource, /data\.code = normalizeErrorCode\(code\)/, `${browser}: recordError does not normalize the code`);
    assert.match(recorderSource, /import \{ normalizeErrorCode \} from '\.\/error-codes\.js';/, `${browser}: recorder does not import error-codes`);
    assert.match(recorderSource, /const _runWriteQueues = new Map\(\)/, `${browser}: per-run event serialization queue missing`);
    assert.match(recorderSource, /async function _flushRunWrites\(runId\) \{\s*let pending = _runWriteQueues\.get\(runId\);\s*while \(pending\) \{[\s\S]*?const next = _runWriteQueues\.get\(runId\);\s*if \(!next \|\| next === pending\) return;\s*pending = next;[\s\S]*?export async function endRun[\s\S]*?await _flushRunWrites\(runId\);[\s\S]*?return _queueRunWrite\(runId, async \(\) => \{[\s\S]*?const runTx = tx\(db, \['runs'\]\);\s*const runStore = runTx\.objectStore\('runs'\);\s*const existing = await promisifyReq\(runStore\.get\(runId\)\);[\s\S]*?runStore\.put\(existing\)/, `${browser}: run finalization must drain nested refreshes, share the per-run queue, and transactionally patch the latest byte-accounting record`);
    const endRunBody = recorderSource.slice(recorderSource.indexOf('export async function endRun'), recorderSource.indexOf('/**\n * Repair trace records'));
    assert.doesNotMatch(endRunBody, /_runWriteQueues\.delete\(runId\)/, `${browser}: finalization must let the queue owner release itself after later queued migrations settle`);
    assert.match(recorderSource, /export function recordLLMRetry\([\s\S]*?_retryCount\(db, runId, step\)[\s\S]*?normalizeErrorCode\(code\)/, `${browser}: retry attempts are not derived from the durable event log`);
    assert.match(recorderSource, /reasoningPresent[\s\S]*?reasoningTokens[\s\S]*?requestedMaxTokens/, `${browser}: privacy-safe model output diagnostics are not persisted`);
  }
});

test('agent trace instrumentation: turn/step boundaries, retries-before-wait, and codes in both builds', () => {
  for (const browser of ['chrome', 'firefox']) {
    const agentSource = fs.readFileSync(path.join(ROOT, `src/${browser}/src/agent/agent.js`), 'utf8');
    const startTraceStart = agentSource.indexOf('async _startTraceRun(');
    const endTraceStart = agentSource.indexOf('async _endTraceRun(', startTraceStart);
    const nonStreamingStart = agentSource.indexOf('async _processMessageInner(');
    const streamingStart = agentSource.indexOf('async _processMessageStreamInner(');
    assert.ok(startTraceStart >= 0 && endTraceStart > startTraceStart, `${browser}: trace lifecycle helpers missing`);
    assert.ok(nonStreamingStart >= 0 && streamingStart > nonStreamingStart, `${browser}: message loop boundaries missing`);
    const startTraceBody = agentSource.slice(startTraceStart, endTraceStart);
    const nonStreamingBody = agentSource.slice(nonStreamingStart, streamingStart);
    const streamingBody = agentSource.slice(streamingStart);
    assert.match(startTraceBody, /recordTurnStart\(runId, 0, \{ mode \}\)/, `${browser}: every started trace must receive turn_start, including planner exits`);
    assert.match(nonStreamingBody, /recordStepStart\(runId, steps, \{\}\)/, `${browser}: non-streaming step_start missing`);
    assert.match(streamingBody, /recordStepStart\(runId, steps, \{\}\)/, `${browser}: streaming step_start missing`);
    assert.match(agentSource, /modelOutputDiagnostics\(result,[\s\S]*?requestedMaxTokens: chatOpts\.maxTokens/, `${browser}: non-streaming responses omit output diagnostics`);
    assert.match(streamingBody, /recordLLMResponse\(runId, steps,[\s\S]*?\.\.\.outputDiagnostics/, `${browser}: streaming responses omit output diagnostics`);
    assert.match(streamingBody, /finishReason = String\(/, `${browser}: streaming terminal reason is discarded`);
    assert.doesNotMatch(agentSource, /raise the step limit in settings/, `${browser}: empty response guidance still blames the unrelated agent step limit`);
    assert.match(nonStreamingBody, /_traceStepEndForResult\(result\)/, `${browser}: non-streaming output is not validated before step_end`);
    assert.match(streamingBody, /const closeTraceStep = \(payload\) => \{[\s\S]*?traceStepClosed = true/, `${browser}: streaming step_end is not single-shot`);
    const streamedClose = streamingBody.indexOf('closeTraceStep(this._traceStepEndForResult');
    const streamedToolBatch = streamingBody.indexOf('await this._executeToolBatch(');
    assert.ok(streamedClose >= 0 && streamedClose < streamedToolBatch, `${browser}: streaming LLM step stays open through terminal tool exits`);
    assert.match(nonStreamingBody, /await trace\.recordLLMRetry\(runId, steps, \{ delayMs: 2000,[\s\S]*?await new Promise\(r => setTimeout\(r, 2000\)\)/, `${browser}: retry record is not durable before backoff`);
    assert.match(nonStreamingBody, /await trace\.recordTurnEnd\([\s\S]*?await this\._endTraceRun/, `${browser}: non-streaming turn_end is not flushed before run close`);
    assert.match(streamingBody, /await trace\.recordTurnEnd\([\s\S]*?await this\._endTraceRun/, `${browser}: streaming turn_end is not flushed before run close`);
    const finishStart = streamingBody.indexOf('const finish = (response, status = _traceStatus) => {');
    const finishEnd = streamingBody.indexOf('\n    };', finishStart);
    assert.doesNotMatch(streamingBody.slice(finishStart, finishEnd), /recordTurnEnd/, `${browser}: streaming finish can emit duplicate turn_end events`);
  }
});

