test('no-progress scroll warns on the second same-target miss and stops on the third', () => {
  const origin = {
    origin: 'last_interaction',
    originElement: {
      tag: 'p',
      role: '',
      text: 'The last visible paragraph',
      rect: { x: 368, y: 123, w: 594, h: 78 },
    },
  };
  for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
    const agent = new AgentClass({});
    const tab = label === 'chrome' ? 81 : 82;
    assert.equal(agent._checkNoProgressScroll(tab, 'scroll', { direction: 'down', amount: 300 }, { moved: false, ...origin }).kind, 'none', `${label}: first miss`);
    const warning = agent._checkNoProgressScroll(tab, 'scroll', { direction: 'down', amount: 500 }, { moved: false, ...origin });
    assert.equal(warning.kind, 'nudge', `${label}: second miss should warn despite a changed amount`);
    assert.match(warning.warning, /Do not repeat this scroll direction/i);
    const stopped = agent._checkNoProgressScroll(tab, 'scroll', { direction: 'down', amount: 700 }, { moved: false, ...origin });
    assert.equal(stopped.kind, 'stop', `${label}: third miss should stop`);
    assert.match(stopped.message, /same scroll direction on the same target three times/i);
  }
});

test('no-progress scroll is pane-, direction-, tab-, and run-scoped', () => {
  for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
    const agent = new AgentClass({});
    const tab = 83;
    const dead = { moved: false };
    assert.equal(agent._checkNoProgressScroll(tab, 'scroll', { direction: 'down', ref_id: 'ref_pane_a' }, dead).kind, 'none');
    assert.equal(agent._checkNoProgressScroll(tab, 'read_page', {}, { success: true }).kind, 'none');
    assert.equal(agent._checkNoProgressScroll(tab, 'scroll', { direction: 'down', ref_id: 'ref_pane_a' }, dead).kind, 'nudge', `${label}: an interleaved read must not evade the warning`);
    assert.equal(agent._checkNoProgressScroll(tab, 'scroll', { direction: 'up', ref_id: 'ref_pane_a' }, dead).kind, 'none', `${label}: opposite direction is a new recovery path`);
    assert.equal(agent._checkNoProgressScroll(tab, 'scroll', { direction: 'down', ref_id: 'ref_pane_b' }, dead).kind, 'none', `${label}: another pane is isolated`);
    assert.equal(agent._checkNoProgressScroll(tab + 1, 'scroll', { direction: 'down', ref_id: 'ref_pane_b' }, dead).kind, 'none', `${label}: tabs are isolated`);
    assert.equal(agent._checkNoProgressScroll(tab, 'scroll', { direction: 'down', ref_id: 'ref_pane_b' }, { moved: true }).kind, 'none');
    assert.equal(agent.noProgressScrolls.has(tab), false, `${label}: movement should reset the streak`);
    assert.equal(agent._checkNoProgressScroll(tab, 'scroll', { direction: 'down', ref_id: 'ref_reused' }, dead).kind, 'none');
    assert.equal(agent._checkNoProgressScroll(tab, 'click_ax', { ref_id: 'ref_link' }, { success: true, pageUrlChanged: true }).kind, 'none');
    assert.equal(agent.noProgressScrolls.has(tab), false, `${label}: document navigation should reset the streak`);
    assert.equal(agent._checkNoProgressScroll(tab, 'scroll', { direction: 'down', ref_id: 'ref_reused' }, dead).kind, 'none', `${label}: a reused ref on the new page starts fresh`);
    agent._checkNoProgressScroll(tab, 'scroll', { direction: 'down', ref_id: 'ref_pane_a' }, dead);
    agent._clearLoopState(tab);
    assert.equal(agent.noProgressScrolls.has(tab), false, `${label}: run cleanup should reset the streak`);
  }
});

test('no-progress scroll enforcement is wired into both agent loops', () => {
  for (const [browserName, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
    const source = fs.readFileSync(path.join(ROOT, `src/${browserName}/src/agent/agent.js`), 'utf8');
    assert.match(source, /const scrollCheck = this\._checkNoProgressScroll\(tabId, fnName, fnArgs, toolResult\)/, `${browserName}: evaluate each result`);
    assert.match(source, /scrollCheck\.kind === 'stop'/, `${browserName}: stop result must win`);
    assert.match(source, /scrollCheck\.kind === 'nudge'/, `${browserName}: warning must reach the model`);
    // Assert the cleanup behaviorally rather than by grepping agent.js: the
    // detector state lives in loop-detector.js, so a source match would only
    // prove where the line is written, not that run cleanup reaches it.
    const agent = new AgentClass({});
    const tab = `${browserName}-dead-scroll`;
    assert.equal(agent._checkNoProgressScroll(tab, 'scroll', { direction: 'down' }, { moved: false }).kind, 'none');
    assert.equal(agent.noProgressScrolls.has(tab), true, `${browserName}: streak must be tracked`);
    agent._clearRunLoopState(tab);
    assert.equal(agent.noProgressScrolls.has(tab), false, `${browserName}: run cleanup must clear state`);
  }
});

test('delivery checkpoints escalate at eight and reset only after meaningful progress or cleanup', () => {
  for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
    const agent = new AgentClass({});
    const tab = label === 'chrome' ? 87 : 88;
    const enforced = { enforceTerminal: true };
    assert.equal(agent._checkDeliveryObservationStreak(tab, 'read_page', {}, { success: true }, enforced).kind, 'none');
    assert.equal(agent._checkDeliveryObservationStreak(tab, 'scroll', {}, { success: true }, enforced).kind, 'none');
    assert.equal(agent._checkDeliveryObservationStreak(tab, 'get_accessibility_tree', {}, { success: true }, enforced).kind, 'none');
    const firstCheckpoint = agent._checkDeliveryObservationStreak(tab, 'wait_for_stable', {}, { success: true }, enforced);
    assert.equal(firstCheckpoint.kind, 'nudge', `${label}: fourth observation should warn`);
    assert.match(firstCheckpoint.warning, /deliver useful partial results/i);
    assert.doesNotMatch(firstCheckpoint.warning, /outcome:/i, `${label}: checkpoint must stay valid for Ask and compact done schemas`);

    assert.equal(agent._checkDeliveryObservationStreak(tab, 'scratchpad_write', {}, { success: true }, enforced).kind, 'none');
    assert.equal(agent.deliveryObservationStreaks.get(tab), 4, `${label}: meta calls must not erase the delivery obligation`);
    assert.equal(agent._checkDeliveryObservationStreak(tab, 'click_ax', {}, { success: false, error: 'missed' }, { ...enforced, consequential: true }).kind, 'none');
    assert.equal(agent.deliveryObservationStreaks.get(tab), 4, `${label}: failed actions must not erase the delivery obligation`);
    for (let i = 0; i < 3; i++) {
      assert.equal(agent._checkDeliveryObservationStreak(tab, 'research_url', {}, { success: true }, enforced).kind, 'none');
    }
    const forcedDelivery = agent._checkDeliveryObservationStreak(tab, 'fetch_url', { method: 'GET' }, { success: true }, enforced);
    assert.equal(forcedDelivery.kind, 'deliver', `${label}: eighth observation should force terminal delivery`);
    assert.equal(forcedDelivery.count, 8, `${label}: escalation count mismatch`);
    assert.match(forcedDelivery.warning, /call done exactly once/i, `${label}: terminal instruction missing`);
    assert.match(forcedDelivery.warning, /partial or failed/i, `${label}: recovery outcomes must exclude success`);

    const discoveryTab = `${tab}-discovery`;
    for (let i = 0; i < 4; i++) {
      agent._checkDeliveryObservationStreak(discoveryTab, 'get_accessibility_tree', {}, { success: true }, enforced);
    }
    const discovery = agent._checkDeliveryObservationStreak(
      discoveryTab,
      'get_accessibility_tree',
      {},
      { success: true },
      { ...enforced, discoveredActionableTargets: true },
    );
    assert.equal(discovery.kind, 'none', `${label}: newly discovered action targets should count as progress`);
    assert.equal(agent.deliveryObservationStreaks.has(discoveryTab), false, `${label}: first target discovery should reset the observation streak`);
    let repeatedDiscovery = null;
    for (let page = 2; page <= 9; page++) {
      repeatedDiscovery = agent._checkDeliveryObservationStreak(
        discoveryTab,
        'get_accessibility_tree',
        { page },
        { success: true },
        { ...enforced, discoveredActionableTargets: true },
      );
    }
    assert.equal(repeatedDiscovery.kind, 'deliver', `${label}: repeated target discovery should remain bounded`);
    assert.equal(repeatedDiscovery.count, 8, `${label}: repeated target discovery should reach forced delivery`);
    agent._checkDeliveryObservationStreak(
      discoveryTab,
      'click_ax',
      { ref: 'ref_follow' },
      { success: true },
      { ...enforced, consequential: true },
    );
    assert.equal(agent.deliveryObservationStreaks.has(discoveryTab), false, `${label}: consequential action should rearm the discovery reset`);
    assert.equal(agent.deliveryActionableDiscoveryResets.has(discoveryTab), false, `${label}: consequential action should restore the one-shot discovery reset`);
    const discoveryAfterAction = agent._checkDeliveryObservationStreak(
      discoveryTab,
      'get_accessibility_tree',
      { page: 10 },
      { success: true },
      { ...enforced, discoveredActionableTargets: true },
    );
    assert.equal(discoveryAfterAction.kind, 'none', `${label}: discovery after consequential progress should reset again`);
    assert.equal(agent.deliveryObservationStreaks.has(discoveryTab), false, `${label}: rearmed discovery should restart from zero`);

    const requiredReadTab = `${tab}-required-read`;
    for (let page = 1; page <= 12; page++) {
      const requiredRead = agent._checkDeliveryObservationStreak(
        requiredReadTab,
        'get_accessibility_tree',
        { filter: 'all', ref_id: 'ref_trusted_main', page },
        { success: true, page, hasMore: page < 12 },
        { ...enforced, requiredReadProgress: true },
      );
      assert.equal(requiredRead.kind, 'none', `${label}: trusted completeness page ${page} triggered forced delivery`);
    }
    assert.equal(agent.deliveryObservationStreaks.has(requiredReadTab), false, `${label}: trusted completeness progress retained an observation streak`);

    const wrongScopeTab = `${tab}-wrong-scope`;
    let wrongScopeResult = null;
    for (let page = 1; page <= 8; page++) {
      wrongScopeResult = agent._checkDeliveryObservationStreak(
        wrongScopeTab,
        'get_accessibility_tree',
        { filter: 'all', ref_id: `ref_untrusted_${page}`, page: 1 },
        { success: true },
        enforced,
      );
    }
    assert.equal(wrongScopeResult?.kind, 'deliver', `${label}: non-progressing arbitrary subtrees bypassed forced delivery`);

    assert.equal(agent._checkDeliveryObservationStreak(tab, 'click_ax', {}, { success: true, verified: true }, { ...enforced, consequential: true }).kind, 'none');
    assert.equal(agent.deliveryObservationStreaks.has(tab), false, `${label}: verified consequential progress should reset the streak`);

    const verificationTab = `${tab}-verification`;
    agent._beginCompletionInvariant(verificationTab);
    for (let i = 0; i < 4; i++) {
      agent._checkDeliveryObservationStreak(verificationTab, 'read_page', {}, { success: true }, enforced);
    }
    const unverifiedAction = { success: true, dispatched: true, verified: false };
    const beforeAction = agent.completionInvariants.get(verificationTab);
    const afterAction = agent._recordCompletionToolResult(verificationTab, 'upload_file', {}, unverifiedAction);
    assert.equal(agent._deliveryCheckpointVerifiedPendingAction(beforeAction, afterAction), false, `${label}: an action is not its own verification`);
    agent._checkDeliveryObservationStreak(
      verificationTab,
      'upload_file',
      {},
      unverifiedAction,
      { ...enforced, consequential: true },
    );
    assert.equal(agent.deliveryObservationStreaks.get(verificationTab), 4, `${label}: an unverified action must preserve the prior observation streak`);
    const beforeVerification = agent.completionInvariants.get(verificationTab);
    const afterVerification = agent._recordCompletionToolResult(
      verificationTab,
      'get_accessibility_tree',
      {},
      { success: true },
    );
    const verifiedPendingAction = agent._deliveryCheckpointVerifiedPendingAction(beforeVerification, afterVerification);
    assert.equal(verifiedPendingAction, true, `${label}: successful follow-up observation must verify the pending action`);
    assert.equal(agent._checkDeliveryObservationStreak(
      verificationTab,
      'get_accessibility_tree',
      {},
      { success: true },
      { ...enforced, verifiedPendingAction },
    ).kind, 'none');
    assert.equal(agent.deliveryObservationStreaks.has(verificationTab), false, `${label}: action-verifying observation should reset instead of incrementing the streak`);
    agent._clearCompletionInvariant(verificationTab);

    agent._checkDeliveryObservationStreak(tab, 'read_page', {}, { success: true }, enforced);
    agent._checkDeliveryObservationStreak(tab, 'read_page', {}, { success: true }, enforced);
    agent._checkDeliveryObservationStreak(tab, 'progress_update', {}, { success: true, updated: [{ id: 'row-1', status: 'processed' }] }, enforced);
    assert.equal(agent.deliveryObservationStreaks.has(tab), false, `${label}: a changed progress row should reset the streak`);

    for (let i = 0; i < 3; i++) {
      assert.equal(agent._checkDeliveryObservationStreak(tab, 'research_url', {}, { success: true }, enforced).kind, 'none');
    }
    assert.equal(agent._checkDeliveryObservationStreak(tab, 'fetch_url', { method: 'POST' }, { success: true }, { ...enforced, consequential: true }).kind, 'none', `${label}: mutating fetches must not trigger a delivery checkpoint`);
    assert.equal(agent.deliveryObservationStreaks.has(tab), false, `${label}: a successful consequential fetch should reset the observation streak`);

    const unenforcedTab = `${tab}-unenforced`;
    for (let i = 1; i <= 8; i++) {
      const result = agent._checkDeliveryObservationStreak(unenforcedTab, 'research_url', {}, { success: true });
      if (i === 4 || i === 8) assert.equal(result.kind, 'nudge', `${label}: an explicitly unenforced checkpoint ${i} should stay advisory`);
      else assert.equal(result.kind, 'none');
    }
    agent._clearLoopState(tab);
    assert.equal(agent.deliveryObservationStreaks.has(tab), false, `${label}: run cleanup should reset the streak`);
  }
});

test('delivery checkpoint enforcement is wired into both agent loops', () => {
  for (const browserName of ['chrome', 'firefox']) {
    const source = fs.readFileSync(path.join(ROOT, `src/${browserName}/src/agent/agent.js`), 'utf8');
    assert.match(source, /const deliveryCheck = this\._checkDeliveryObservationStreak\([\s\S]{0,180}?toolResult,[\s\S]{0,800}?requiredReadProgress,[\s\S]{0,300}?enforceTerminal: runOptions\?\.cloudRun !== true[\s\S]{0,120}?!this\._isWebBrainCloudProvider\(provider\)[\s\S]{0,120}?allowedToolNames\.has\('done'\)/, `${browserName}: every eligible interactive mode with done must preserve required-read progress and enforce the second checkpoint`);
    assert.doesNotMatch(source, /enforceTerminal:[\s\S]{0,160}?_isActionMode/, `${browserName}: Ask research must not be excluded from terminal delivery`);
    assert.match(source, /deliveryCheck\.kind === 'nudge'/, `${browserName}: warning must reach the model`);
    assert.match(source, /deliveryCheck\.kind === 'deliver'[\s\S]{0,900}?action: 'deliver'/, `${browserName}: second checkpoint must leave the browser loop`);
    assert.match(source, /batchResult\.action === 'deliver'[\s\S]{0,300}?_recoverDeliveryCheckpointTurn/, `${browserName}: caller must enter done-only recovery`);
    assert.match(source, /discoveredActionableTargets:\s*Number\(progressObserved\?\.addedPending \|\| 0\) > 0/, `${browserName}: newly observed progress rows must reset delivery drift`);
    assert.match(source, /this\.deliveryObservationStreaks\.delete\(tabId\)/, `${browserName}: run cleanup must clear state`);
  }
});

test('active WebBrain Compass provider keeps delivery checkpoints advisory', async () => {
  for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
    for (const mode of ['ask', 'act']) {
      const agent = new AgentClass({ getVisionProvider: async () => null });
      const tabId = `${label}-${mode}-webbrain-cloud-delivery`;
      const messages = [];
      const updates = [];
      const executed = [];
      agent.conversationModes.set(tabId, mode);
      agent._ensureGateSetting = async () => {};
      agent._skipPermissionGate = true;
      agent._currentUrl = async () => 'https://example.com/research';
      agent._rememberMastodonObservation = async () => null;
      agent._recordProgressObservation = async () => null;
      agent._autoRecordProgressAction = () => null;
      agent._persist = () => {};
      agent.executeTool = async (_tabId, name, args) => {
        executed.push(args.url);
        return { success: true, content: `Evidence from ${args.url}` };
      };
      const toolCalls = Array.from({ length: 9 }, (_, index) => ({
        id: `${mode}_cloud_research_${index + 1}`,
        function: {
          name: 'research_url',
          arguments: JSON.stringify({ url: `https://example.com/cloud-source-${index + 1}` }),
        },
      }));

      const result = await agent._executeToolBatch(
        tabId,
        toolCalls,
        messages,
        (type, data) => updates.push({ type, data }),
        {
          supportsVision: false,
          config: { providerName: 'webbrain-cloud' },
        },
        null,
        new Set(['research_url', 'done']),
        8,
      );

      assert.equal(result.action, 'continue', `${label}/${mode}: active WebBrain Compass was forced into terminal delivery`);
      assert.equal(executed.length, 9, `${label}/${mode}: active WebBrain Compass stopped after the eighth observation`);
      const eighthResult = messages.find(message => message.tool_call_id === `${mode}_cloud_research_8`);
      assert.match(eighthResult?.content || '', /DELIVERY CHECKPOINT/, `${label}/${mode}: advisory checkpoint was removed`);
      assert.doesNotMatch(eighthResult?.content || '', /DELIVERY REQUIRED/, `${label}/${mode}: advisory checkpoint became terminal`);
      assert.equal(
        updates.some(update => /Observation limit reached/i.test(update.data?.message || '')),
        false,
        `${label}/${mode}: active WebBrain Compass displayed terminal observation-limit recovery`,
      );
    }
  }
});

