test('no-progress scroll stop synthesizes results for the rest of a tool batch', async () => {
  for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
    const agent = new AgentClass({ getVisionProvider: async () => null });
    const tabId = label === 'chrome' ? 85 : 86;
    const messages = [];
    const executed = [];
    agent._ensureGateSetting = async () => {};
    agent._skipPermissionGate = true;
    agent._rememberMastodonObservation = async () => null;
    agent._recordProgressObservation = async () => null;
    agent._autoRecordProgressAction = () => null;
    agent._persist = () => {};
    agent.executeTool = async (_tabId, name, args) => {
      executed.push(args.amount);
      return {
        success: true,
        moved: false,
        origin: 'last_interaction',
        originElement: {
          tag: 'p', role: '', text: 'Last visible paragraph',
          rect: { x: 100, y: 200, w: 300, h: 40 },
        },
      };
    };
    const toolCalls = [300, 400, 500, 600].map((amount, index) => ({
      id: `scroll_${index}`,
      function: { name: 'scroll', arguments: JSON.stringify({ direction: 'down', amount }) },
    }));

    const result = await agent._executeToolBatch(
      tabId,
      toolCalls,
      messages,
      () => {},
      { supportsVision: false },
      null,
      new Set(['scroll']),
      1,
    );

    assert.equal(result.action, 'recover', `${label}: the third dead scroll should stop and request terminal recovery`);
    assert.deepEqual(executed, [300, 400, 500], `${label}: later calls must not execute after stop`);
    const toolMessages = messages.filter(message => message.role === 'tool');
    assert.equal(toolMessages.length, toolCalls.length, `${label}: every tool call must receive a result`);
    const skipped = toolMessages.find(message => message.tool_call_id === 'scroll_3');
    assert.ok(skipped, `${label}: remaining tool call needs a synthetic result`);
    assert.deepEqual(JSON.parse(skipped.content), {
      success: false,
      skipped: true,
      error: 'skipped: run stopped by loop detector',
    });
  }
});

test('loop-stop recovery surfaces a checkpointed draft in chat without claiming it was sent', async () => {
  for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
    const agent = new AgentClass({});
    const messages = [
      { role: 'system', content: 'ordinary agent prompt' },
      { role: 'user', content: 'Draft and send Gary a thank-you email.' },
      agent._buildScratchpadMessage('[pending draft]\nTo: Gary\nSubject: Thank you\nBody: Hi Gary,\n\nThank you for your help.\n\nBest,\nBarack'),
      { role: 'assistant', content: 'Trying the editor.', tool_calls: [] },
    ];
    const updates = [];
    let request = null;
    agent._persist = () => {};
    agent._chatWithCostAllowance = async (_provider, sentMessages, options) => {
      request = { sentMessages, options };
      return {
        content: 'Subject: Thank you\n\nHi Gary,\n\nThank you for your help.\n\nBest,\nBarack',
        toolCalls: [],
      };
    };

    const recovery = await agent._recoverLoopStoppedTurn(
      910,
      messages,
      (type, data) => updates.push({ type, data }),
      { model: 'test-model' },
      {},
      null,
      4,
      'Stuck in a loop. Stopped.',
    );

    assert.equal(recovery.status, 'loop_stopped', `${label}: recovered loop should retain a stopped status`);
    assert.match(recovery.content, /chat-only; do not assume it was saved, submitted, or sent/i, `${label}: unsent warning missing`);
    assert.match(recovery.content, /Hi Gary,[\s\S]*Thank you for your help/, `${label}: recovered draft missing`);
    assert.equal(request?.options?.tools, undefined, `${label}: recovery call must not expose tools`);
    assert.match(request?.sentMessages?.[0]?.content || '', /tool-free chat response/, `${label}: recovery system prompt missing`);
    assert.match(JSON.stringify(request?.sentMessages || []), /\[pending draft\]/, `${label}: checkpointed draft did not reach recovery`);
    assert.equal(updates.some(update => update.type === 'text' && update.data?.content === recovery.content), true, `${label}: recovered draft was not rendered`);
    assert.equal(updates.some(update => update.type === 'error'), true, `${label}: stopped run must remain visibly failed`);
    assert.equal(messages.at(-1)?.content, recovery.content, `${label}: recovered draft was not persisted in conversation`);
  }
});

test('delivery recovery exposes only done and persists a partial terminal result', async () => {
  for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
    const agent = new AgentClass({});
    agent.responseLanguagePolicies.set(913, {
      framing_locale: 'en',
      deliverable_locales: ['en'],
      preserve_source_text: false,
    });
    const messages = [
      { role: 'system', content: 'ordinary agent prompt' },
      { role: 'user', content: 'Find remote jobs and give me the links.' },
      { role: 'tool', tool_call_id: 'read_1', content: JSON.stringify({ titles: ['Engineer', 'Designer'] }) },
    ];
    const updates = [];
    let request = null;
    agent._persist = () => {};
    agent._chatWithCostAllowance = async (_provider, sentMessages, options) => {
      request = { sentMessages, options };
      return {
        content: '',
        toolCalls: [{
          id: `forced_done_${label}`,
          function: {
            name: 'done',
            arguments: JSON.stringify({
              summary: 'Partial results: Engineer and Designer roles were found. The remaining pages were not checked.',
              outcome: 'partial',
            }),
          },
        }],
      };
    };

    const recovery = await agent._recoverDeliveryCheckpointTurn(
      913,
      messages,
      (type, data) => updates.push({ type, data }),
      { model: 'test-model' },
      {},
      null,
      8,
      'fallback should not be used',
    );

    assert.equal(recovery.status, 'partial', `${label}: useful forced delivery should be partial`);
    assert.match(recovery.content, /Engineer and Designer/, `${label}: gathered evidence missing from final`);
    assert.equal(request?.options?.tools?.length, 1, `${label}: recovery must expose exactly one tool`);
    assert.equal(request?.options?.tools?.[0]?.function?.name, 'done', `${label}: recovery exposed a non-done tool`);
    assert.deepEqual(request?.options?.tools?.[0]?.function?.parameters?.properties?.outcome?.enum, ['partial', 'failed'], `${label}: forced done must forbid success`);
    assert.deepEqual(request?.options?.toolChoice, { type: 'function', function: { name: 'done' } }, `${label}: done should be explicitly requested`);
    assert.match(request?.sentMessages?.[0]?.content || '', /Call the done tool exactly once/i, `${label}: forced terminal system prompt missing`);
    assert.match(request?.sentMessages?.[0]?.content || '', /Use English \(en\) for explanatory framing/i, `${label}: recovery prompt lost English framing`);
    assert.match(request?.sentMessages?.[0]?.content || '', /authored deliverables in English \(en\)/i, `${label}: recovery prompt lost the deliverable language`);
    assert.match(request?.options?.tools?.[0]?.function?.description || '', /authored deliverables in English \(en\)/i, `${label}: forced done schema lost language guidance`);
    assert.equal(updates.some(update => update.type === 'tool_call' && update.data?.name === 'done'), true, `${label}: forced done call was not surfaced`);
    assert.equal(updates.some(update => update.type === 'run_status' && update.data?.status === 'partial'), true, `${label}: partial run status missing`);
    const persistedResult = JSON.parse(messages.at(-1)?.content || '{}');
    assert.equal(messages.at(-1)?.role, 'tool', `${label}: forced done tool result was not persisted structurally`);
    assert.equal(persistedResult.done, true, `${label}: persisted forced done result missing`);
    assert.equal(persistedResult.outcome, 'partial', `${label}: persisted forced done outcome mismatch`);
  }
});

test('step-limit recovery keeps Cloud observation checkpoints advisory but forces a done-only handoff', async () => {
  for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
    const agent = new AgentClass({});
    const tabId = label === 'chrome' ? 920 : 921;
    const messages = [
      { role: 'system', content: 'ordinary agent prompt' },
      { role: 'user', content: 'Collect every result and report what remains.' },
      { role: 'tool', tool_call_id: 'read_1', content: JSON.stringify({ result: 'One verified item' }) },
    ];
    const updates = [];
    let request = null;
    agent._persist = () => {};
    agent._chatWithCostAllowance = async (_provider, sentMessages, options) => {
      request = { sentMessages, options };
      return {
        content: '',
        toolCalls: [{
          id: `step_limit_done_${label}`,
          function: {
            name: 'done',
            arguments: JSON.stringify({
              summary: 'One item was verified. Remaining results could not be checked before the step limit.',
              outcome: 'partial',
            }),
          },
        }],
      };
    };

    assert.equal(agent._stepLimitRecoveryEligible({ supportsTools: true, config: { providerName: 'webbrain-cloud' } }), true, `${label}: selected WebBrain Cloud provider should receive terminal handoff`);
    assert.equal(agent._stepLimitRecoveryEligible({ supportsTools: true }, { cloudRun: true }), false, `${label}: structured Cloud API run must keep its done_json contract`);
    assert.equal(agent._stepLimitRecoveryEligible({ supportsTools: true }, { scheduledRun: true, independentRun: true }), false, `${label}: unattended scheduled runs must keep their deterministic max-step verdict`);
    assert.equal(agent._stepLimitRecoveryEligible({ supportsTools: false }), false, `${label}: tool-free provider cannot produce a structured done call`);

    const recovery = await agent._recoverDeliveryCheckpointTurn(
      tabId,
      messages,
      (type, data) => updates.push({ type, data }),
      { model: 'test-model', supportsTools: true, config: { providerName: 'webbrain-cloud' } },
      {},
      null,
      130,
      'fallback should not be used',
      {},
      null,
      null,
      { phase: 'step_limit_recovery' },
    );

    assert.equal(recovery.status, 'partial', `${label}: step-limit handoff should preserve the done outcome`);
    assert.match(recovery.content, /One item was verified/i);
    assert.equal(request?.options?.tools?.length, 1, `${label}: step-limit recovery exposed more than done`);
    assert.equal(request?.options?.tools?.[0]?.function?.name, 'done');
    assert.deepEqual(request?.options?.tools?.[0]?.function?.parameters?.properties?.outcome?.enum, ['partial', 'failed']);
    assert.deepEqual(request?.options?.toolChoice, { type: 'function', function: { name: 'done' } });
    assert.match(request?.sentMessages?.[0]?.content || '', /maximum agent steps/i);
    assert.doesNotMatch(request?.sentMessages?.[0]?.content || '', /two delivery checkpoints|observation limit/i);
    assert.match(request?.options?.tools?.[0]?.function?.description || '', /maximum agent steps/i);
    const persistedResult = JSON.parse(messages.at(-1)?.content || '{}');
    assert.equal(persistedResult.done, true);
    assert.equal(persistedResult.stepLimitRecovery, true, `${label}: trace/conversation result needs an explicit step-limit marker`);
    assert.equal(updates.some(update => update.type === 'run_status' && update.data?.status === 'partial'), true);

    const invalidMessages = [{ role: 'system', content: 'ordinary agent prompt' }];
    const invalidUpdates = [];
    agent._chatWithCostAllowance = async () => ({ content: 'I will keep browsing.', toolCalls: [] });
    const fallback = '[Step limit reached after 130 steps without completing the task.]';
    const invalidRecovery = await agent._recoverDeliveryCheckpointTurn(
      tabId + 10,
      invalidMessages,
      (type, data) => invalidUpdates.push({ type, data }),
      { model: 'test-model', supportsTools: true, config: { providerName: 'webbrain-cloud' } },
      {},
      null,
      130,
      fallback,
      {},
      null,
      null,
      { phase: 'step_limit_recovery' },
    );
    assert.equal(invalidRecovery.content, fallback, `${label}: invalid recovery did not use the deterministic fallback`);
    assert.equal(invalidRecovery.status, 'delivery_recovery_failed', `${label}: invalid recovery was not visibly failed`);
    assert.equal(invalidMessages.at(-1)?.content, fallback, `${label}: deterministic fallback was not persisted`);
    assert.equal(invalidUpdates.some(update => update.type === 'error' && update.data?.message === fallback), true, `${label}: deterministic blocker was not shown`);
  }
});

test('active response-language policy reaches the normal system prompt without breaking translation jobs', () => {
  for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
    const tabId = 916;
    const agent = new AgentClass({ getActive: () => ({ promptTier: 'full' }) });
    agent.conversationModes.set(tabId, 'act');
    agent.conversations.set(tabId, [{ role: 'system', content: 'stale prompt' }]);
    const translation = {
      framing_locale: 'en',
      deliverable_locales: ['es'],
      preserve_source_text: false,
    };
    agent._setResponseLanguagePolicy(tabId, translation, 'en');
    const systemPrompt = agent.conversations.get(tabId)?.[0]?.content || '';
    assert.match(systemPrompt, /Use English \(en\) for explanatory framing/i, `${label}: normal system prompt lost framing language`);
    assert.match(systemPrompt, /authored deliverables in Spanish \(es\)/i, `${label}: normal system prompt overrode the translation target`);

    agent._setResponseLanguagePolicy(tabId, null, 'tr');
    const fallbackPrompt = agent.conversations.get(tabId)?.[0]?.content || '';
    assert.match(fallbackPrompt, /Match the language of the latest genuine user request/i, `${label}: planner bypass stopped deriving framing from the user request`);
    assert.match(fallbackPrompt, /if that request explicitly specifies a response language, use it/i, `${label}: Ask-mode fallback ignored an explicit Respond-in instruction in the user request`);
    assert.match(fallbackPrompt, /if unclear, use Turkish \(tr\)/i, `${label}: UI locale was not retained as a soft fallback`);
    assert.doesNotMatch(fallbackPrompt, /Respond in Turkish \(tr\)/i, `${label}: Ask-mode fallback became a hard UI-locale requirement`);
    assert.doesNotMatch(fallbackPrompt, /authored deliverable itself in/i, `${label}: planner fallback became a blanket Turkish deliverable constraint`);
  }
});

