test('sidepanels wire highlighting and heading rendering into fenced Markdown', () => {
  for (const [label, panelRel, cssRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js', 'src/chrome/styles/sidepanel.css'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js', 'src/firefox/styles/sidepanel.css'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    const css = fs.readFileSync(path.join(ROOT, cssRel), 'utf8');
    assert.match(panel, /import \{ codeFenceLanguage, highlightCode, renderMarkdownHeadings, renderMarkdownTables \} from '\.\/markdown-render\.js';/, `${label}: renderer helpers should be imported`);
    assert.match(panel, /const lang = codeFenceLanguage\(info\);/, `${label}: fenced code should tolerate metadata after its language token`);
    assert.match(panel, /const highlighted = enhance \? highlightCode\(block\.code, block\.lang\) : escapeHtml\(block\.code\);/, `${label}: completed fenced code should be highlighted by its language while live code stays lightweight`);
    assert.match(panel, /text = renderMarkdownTables\(text\);\s*text = renderMarkdownHeadings\(text\);/, `${label}: pipe tables must render before headings swallow the following newline`);
    assert.match(css, /\.message-content table \{[\s\S]*?border-collapse: collapse;/, `${label}: rendered tables should have readable borders`);
    assert.match(css, /\.syntax-keyword[\s\S]*?var\(--syntax-keyword\)/, `${label}: token colors should be styled`);
    assert.match(css, /\.syntax-variable \{ color: var\(--syntax-variable\); \}/, `${label}: variables should use their dedicated theme color`);
    assert.match(css, /\.message-content h3 \{ font-size: 14px; \}/, `${label}: level-three headings should be visually distinct`);
  }
});

test('sidepanel composers leave IME Enter for the composition commit', () => {
  for (const [label, panelRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js'],
  ]) {
    const source = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    const handlerStart = source.indexOf("inputEl.addEventListener('keydown', (e) => {");
    const bodyStart = source.indexOf('{', handlerStart) + 1;
    const nextListener = source.indexOf("inputEl.addEventListener('input', handleInput);", bodyStart);
    const handlerEnd = source.lastIndexOf('\n});', nextListener);
    assert.notEqual(handlerStart, -1, `${label}: composer keydown handler missing`);
    assert.notEqual(nextListener, -1, `${label}: composer input listener missing`);
    assert.notEqual(handlerEnd, -1, `${label}: composer keydown handler boundary missing`);

    const handlerBody = source.slice(bodyStart, handlerEnd);
    const runHandler = (event) => {
      let sends = 0;
      Function(
        'e',
        'handleSlashCommandKeydown',
        'editLastQueuedComposerMessageForCurrentTab',
        'navigateComposerHistory',
        'sendMessage',
        handlerBody,
      )(
        event,
        () => false,
        () => false,
        () => false,
        () => { sends += 1; },
      );
      return { sends, defaultPrevented: event.defaultPrevented === true };
    };
    for (const composingEnter of [
      { key: 'Enter', shiftKey: false, isComposing: true, keyCode: 13 },
      { key: 'Enter', shiftKey: false, isComposing: false, keyCode: 229 },
    ]) {
      composingEnter.defaultPrevented = false;
      composingEnter.preventDefault = function preventDefault() { this.defaultPrevented = true; };
      assert.deepEqual(
        runHandler(composingEnter),
        { sends: 0, defaultPrevented: false },
        `${label}: IME Enter must commit composition without sending`,
      );
    }

    const composingArrow = {
      key: 'ArrowUp',
      shiftKey: false,
      isComposing: true,
      keyCode: 38,
      defaultPrevented: false,
      preventDefault() { this.defaultPrevented = true; },
    };
    assert.deepEqual(
      runHandler(composingArrow),
      { sends: 0, defaultPrevented: false },
      `${label}: IME navigation keys must remain native`,
    );

    const shiftEnter = {
      key: 'Enter',
      shiftKey: true,
      isComposing: false,
      keyCode: 13,
      defaultPrevented: false,
      preventDefault() { this.defaultPrevented = true; },
    };
    assert.deepEqual(
      runHandler(shiftEnter),
      { sends: 0, defaultPrevented: false },
      `${label}: Shift+Enter must remain a multiline newline`,
    );

    const normalEnter = {
      key: 'Enter',
      shiftKey: false,
      isComposing: false,
      defaultPrevented: false,
      preventDefault() { this.defaultPrevented = true; },
    };
    assert.deepEqual(
      runHandler(normalEnter),
      { sends: 1, defaultPrevented: true },
      `${label}: ordinary Enter should retain send behavior`,
    );
  }
});

test('sidepanels hide empty assistant placeholders until output renders', () => {
  for (const [label, panelRel, cssRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js', 'src/chrome/styles/sidepanel.css'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js', 'src/firefox/styles/sidepanel.css'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    const css = fs.readFileSync(path.join(ROOT, cssRel), 'utf8');

    assert.match(
      panel,
      /const ASSISTANT_RENDERABLE_ELEMENT_SELECTOR =[\s\S]*?img, svg, canvas, video, audio, iframe, input, textarea, select, button, hr, progress[\s\S]*?function progressContentNodeIsVisible\(node\)[\s\S]*?node\.matches\?\.\(PROGRESS_CONTENT_SELECTOR\)[\s\S]*?node\.matches\('\.tool-call'\)[\s\S]*?return verboseMode;[\s\S]*?return verboseMode \|\| compactProgressVisible;[\s\S]*?function nodeHasAssistantRenderableContent\(node\)[\s\S]*?function assistantMessageHasRenderableContent\(msgEl\)/,
      `${label}: assistant visibility should recognize text and non-text output`,
    );
    assert.doesNotMatch(panel, /visibleContent = contentEl\.cloneNode\(true\)/, `${label}: streamed visibility checks should not clone whole message trees`);
    assert.match(
      panel,
      /function syncAssistantMessageElementVisibility\(msgEl\) \{[\s\S]*?classList\?\.toggle\([\s\S]*?'assistant-awaiting-content'[\s\S]*?!assistantMessageHasRenderableContent\(msgEl\)[\s\S]*?function syncAssistantMessageVisibility\(\) \{[\s\S]*?syncAssistantMessageElementVisibility\(msgEl\)/,
      `${label}: assistant visibility should follow rendered content`,
    );
    assert.match(
      panel,
      /function syncAssistantMessageVisibilityForMutations\(mutations\)[\s\S]*?affectedMessages\.forEach\(syncAssistantMessageElementVisibility\)[\s\S]*?const persistObserver = new MutationObserver\(\(mutations\) => \{\s*syncAssistantMessageVisibilityForMutations\(mutations\);\s*schedulePersist\(\);\s*\}\);/,
      `${label}: streamed mutations should reevaluate only their affected assistant messages`,
    );
    assert.match(
      panel,
      /if \(role === 'assistant' && !assistantMessageHasRenderableContent\(msgEl\)\) \{[\s\S]*?classList\.add\('assistant-awaiting-content'\);/,
      `${label}: an empty assistant node should be hidden before it is appended`,
    );
    assert.match(
      css,
      /\.message\.assistant\.assistant-awaiting-content \{\s*display: none;\s*\}/,
      `${label}: empty assistant shells should not occupy chat space`,
    );
  }
});

// ────────────────────────────────────────────────────────────────────────
// validateFetchUrl — the agent's network gate
// ────────────────────────────────────────────────────────────────────────

console.log('\nfetch URL validator');

// Helper: shorthand expectation.
function expectReject(url, opts) {
  const r = validateFetchUrl(url, opts);
  assert.equal(r.ok, false, `${url} (allowLocal=${!!opts?.allowLocalNetwork}) should reject — got ${JSON.stringify(r)}`);
}
function expectAccept(url, opts) {
  const r = validateFetchUrl(url, opts);
  assert.equal(r.ok, true, `${url} (allowLocal=${!!opts?.allowLocalNetwork}) should accept — got ${JSON.stringify(r)}`);
}

test('rejects non-http schemes (javascript:, data:, file:, ftp:)', () => {
  expectReject('javascript:alert(1)');
  expectReject('data:text/plain,foo');
  expectReject('file:///etc/passwd');
  expectReject('ftp://example.com/');
});

test('rejects cloud metadata hostnames regardless of allowLocal', () => {
  for (const allowLocal of [false, true]) {
    expectReject('http://metadata.google.internal/', { allowLocalNetwork: allowLocal });
    expectReject('http://metadata.aws.internal/', { allowLocalNetwork: allowLocal });
    expectReject('http://metadata.azure.com/', { allowLocalNetwork: allowLocal });
  }
});

test('rejects *.internal and *.local regardless of allowLocal', () => {
  for (const allowLocal of [false, true]) {
    expectReject('http://corp-jenkins.internal/', { allowLocalNetwork: allowLocal });
    expectReject('http://router.local/', { allowLocalNetwork: allowLocal });
  }
});

test('rejects 169.254.169.254 (cloud metadata IP) regardless of allowLocal', () => {
  for (const allowLocal of [false, true]) {
    expectReject('http://169.254.169.254/latest/meta-data/', { allowLocalNetwork: allowLocal });
  }
});

test('rejects CGNAT 100.64/10 regardless of allowLocal', () => {
  expectReject('http://100.64.0.1/');
  expectReject('http://100.127.255.255/');
  expectAccept('http://100.128.0.1/'); // outside CGNAT
});

test('rejects multicast/reserved (≥224) and 0/8', () => {
  expectReject('http://224.0.0.1/');
  expectReject('http://255.255.255.255/');
  expectReject('http://0.0.0.0/');
});

test('localhost / loopback / RFC1918 — relaxable via allowLocalNetwork', () => {
  // Default = blocked.
  expectReject('http://localhost:8080/');
  expectReject('http://127.0.0.1/');
  expectReject('http://10.1.2.3/');
  expectReject('http://172.16.0.1/');
  expectReject('http://172.31.255.255/');
  expectReject('http://192.168.1.1/');
  // 172.32 is outside RFC1918 — accepted.
  expectAccept('http://172.32.0.1/');
  // With the toggle on — accepted.
  expectAccept('http://localhost:8080/', { allowLocalNetwork: true });
  expectAccept('http://127.0.0.1/', { allowLocalNetwork: true });
  expectAccept('http://10.1.2.3/', { allowLocalNetwork: true });
  expectAccept('http://192.168.1.1/', { allowLocalNetwork: true });
  expectAccept('http://172.20.0.1/', { allowLocalNetwork: true });
});

test('IPv6 — link-local always blocked, loopback/unique-local relaxable', () => {
  // Always-blocked: link-local fe80::/10 and unspecified ::
  expectReject('http://[fe80::1]/');
  expectReject('http://[fe80::1]/', { allowLocalNetwork: true });
  expectReject('http://[::]/');
  expectReject('http://[::]/', { allowLocalNetwork: true });
  // Relaxable: ::1 and fc00::/7
  expectReject('http://[::1]/');
  expectAccept('http://[::1]/', { allowLocalNetwork: true });
  expectReject('http://[fc00::1]/');
  expectAccept('http://[fc00::1]/', { allowLocalNetwork: true });
  expectReject('http://[fd12:3456::1]/');
  expectAccept('http://[fd12:3456::1]/', { allowLocalNetwork: true });
  // Public IPv6 always allowed.
  expectAccept('http://[2001:db8::1]/');
});

test('IPv4-mapped IPv6 (::ffff:V4) is decoded and re-validated', () => {
  // The URL parser normalizes ::ffff:127.0.0.1 → ::ffff:7f00:1, so the
  // validator must handle the hex form too.
  expectReject('http://[::ffff:127.0.0.1]/');
  expectAccept('http://[::ffff:127.0.0.1]/', { allowLocalNetwork: true });
  expectReject('http://[::ffff:10.0.0.1]/');
  expectAccept('http://[::ffff:10.0.0.1]/', { allowLocalNetwork: true });
  expectReject('http://[::ffff:169.254.169.254]/'); // metadata even when toggled
  expectReject('http://[::ffff:169.254.169.254]/', { allowLocalNetwork: true });
  expectAccept('http://[::ffff:8.8.8.8]/'); // public v4 mapped
});

test('public hosts always accepted', () => {
  expectAccept('https://example.com/');
  expectAccept('https://api.github.com/repos/');
  expectAccept('http://example.com/');
});

test('invalid URL strings are rejected', () => {
  expectReject('not a url');
  expectReject('://no-scheme');
  expectReject('http://');
});

test('Firefox standard protected domains are matched exactly', () => {
  assert.equal(firefoxRestrictedDomainForUrl('https://addons.mozilla.org/en-US/developers/'), 'addons.mozilla.org');
  assert.equal(firefoxRestrictedDomainForUrl('https://accounts.firefox.com/signin'), 'accounts.firefox.com');
  assert.equal(firefoxRestrictedDomainForUrl('https://addons.mozilla.org.evil.example/'), null);
  assert.equal(firefoxRestrictedDomainForUrl('https://example.com/'), null);
  assert.equal(firefoxRestrictedDomainForUrl('not a url'), null);
});

test('Firefox protected-domain failures are definitive and screenshot-aware', () => {
  const result = firefoxRestrictedDomainFailure('https://addons.mozilla.org/en-US/developers/');
  assert.equal(result.success, false);
  assert.equal(result.errorCode, 'firefox_restricted_domain');
  assert.equal(result.nonRetryable, true);
  assert.equal(result.nonRetryableScope, 'firefox-host-access:addons.mozilla.org');
  assert.equal(result.recoveryTool, 'screenshot');
  assert.match(result.error, /Opening the same URL in another tab.*will not grant access/s);

  const permission = firefoxHostPermissionFailure(
    'https://enterprise.example/dashboard',
    'Missing host permission for the tab',
  );
  assert.equal(permission.errorCode, 'firefox_host_access_denied');
  assert.equal(permission.nonRetryableScope, 'firefox-host-access:enterprise.example');
  assert.equal(firefoxHostPermissionFailure('https://example.com/', 'tab closed'), null);
});

test('Firefox network readers reject protected domains before network or tab work', async () => {
  const previousFetch = globalThis.fetch;
  let fetchCalls = 0;
  globalThis.fetch = async () => {
    fetchCalls++;
    throw new Error('fetch should not run');
  };
  try {
    for (const result of [
      await fetchUrlFx('https://addons.mozilla.org/en-US/developers/'),
      await readPageSourceFx('https://addons.mozilla.org/en-US/developers/'),
      await researchUrlFx('https://addons.mozilla.org/en-US/developers/'),
    ]) {
      assert.equal(result.errorCode, 'firefox_restricted_domain');
      assert.equal(result.nonRetryable, true);
    }
    assert.equal(fetchCalls, 0);
  } finally {
    globalThis.fetch = previousFetch;
  }
});

test('research_url rejects blocked redirect targets before returning hidden-tab content', async () => {
  const previousChrome = globalThis.chrome;
  const previousBrowser = globalThis.browser;
  const previousSetTimeout = globalThis.setTimeout;
  const nativeSetTimeout = previousSetTimeout;
  // Keep the production navigation timeout real, but skip the intentional
  // 800 ms SPA hydration pause in this deterministic unit test.
  globalThis.setTimeout = (fn, ms, ...args) => nativeSetTimeout(fn, ms === 800 ? 0 : ms, ...args);

  const blockedUrl = 'http://169.254.169.254/latest/meta-data/';
  const publicUrl = 'https://public.example/redirect';
  try {
    for (const [label, researchUrl, apiName] of [
      ['chrome', researchUrlCh, 'chrome'],
      ['firefox', researchUrlFx, 'browser'],
    ]) {
      for (const blockedPhase of ['loaded-tab', 'page-result']) {
        let executeCalls = 0;
        let removeCalls = 0;
        const updateListeners = new Set();
        const tabs = {
          async create() {
            return { id: 77, url: publicUrl };
          },
          async get() {
            return { id: 77, url: blockedPhase === 'loaded-tab' ? blockedUrl : publicUrl };
          },
          async remove() {
            removeCalls++;
          },
          onUpdated: {
            addListener(fn) {
              updateListeners.add(fn);
              nativeSetTimeout(() => fn(77, { status: 'complete' }), 0);
            },
            removeListener(fn) {
              updateListeners.delete(fn);
            },
          },
        };
        const pageResult = {
          title: 'redirected page',
          url: blockedPhase === 'page-result' ? blockedUrl : publicUrl,
          text: 'must not be returned',
          originalLength: 20,
          links: [],
        };
        if (apiName === 'chrome') {
          globalThis.chrome = {
            tabs,
            scripting: {
              async executeScript() {
                executeCalls++;
                return [{ result: pageResult }];
              },
            },
          };
        } else {
          globalThis.browser = {
            tabs: {
              ...tabs,
              async executeScript() {
                executeCalls++;
                return [pageResult];
              },
            },
          };
        }

        const result = await researchUrl(publicUrl, { timeout: 1000 });
        assert.equal(result.success, false, `${label}/${blockedPhase}: blocked redirect must fail`);
        assert.match(result.error || '', /Redirect to blocked URL/i, `${label}/${blockedPhase}: missing redirect error`);
        assert.equal(result.finalUrl, blockedUrl, `${label}/${blockedPhase}: final URL should be reported`);
        assert.equal(executeCalls, blockedPhase === 'loaded-tab' ? 0 : 1, `${label}/${blockedPhase}: extraction timing mismatch`);
        assert.equal(removeCalls, 1, `${label}/${blockedPhase}: hidden tab should always be closed`);
      }
    }
  } finally {
    globalThis.setTimeout = previousSetTimeout;
    if (previousChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = previousChrome;
    if (previousBrowser === undefined) delete globalThis.browser;
    else globalThis.browser = previousBrowser;
  }
});

test('firefox port validator agrees with chrome on a sample of cases', () => {
  // Sanity check that the two ports stay in sync. Pick one case from each
  // category — full coverage runs against the chrome copy above.
  const samples = [
    ['javascript:alert(1)', false, false],
    ['http://169.254.169.254/', false, false],
    ['http://localhost/', false, false],
    ['http://localhost/', true, true],
    ['http://[fe80::1]/', true, false],
    ['https://example.com/', false, true],
  ];
  for (const [url, allowLocal, expectOk] of samples) {
    const opts = { allowLocalNetwork: allowLocal };
    const cr = validateFetchUrl(url, opts);
    const fr = validateFetchUrlFx(url, opts);
    assert.equal(cr.ok, fr.ok, `chrome/firefox disagree on ${url} (allowLocal=${allowLocal})`);
    assert.equal(cr.ok, expectOk, `wrong result for ${url} (allowLocal=${allowLocal})`);
  }
});

test('fetchUrl reports HTTP 4xx/5xx as unsuccessful while preserving response text', async () => {
  const previousFetch = globalThis.fetch;
  try {
    for (const [label, fetchUrl] of [['chrome', fetchUrlCh], ['firefox', fetchUrlFx]]) {
      globalThis.fetch = async (rawUrl) => ({
        status: 422,
        url: String(rawUrl),
        headers: new Headers({ 'content-type': 'text/html; charset=utf-8' }),
        text: async () => '<html><title>Oh no &middot; GitHub</title><body>What&#8253; Your browser did something unexpected.</body></html>',
      });

      const result = await fetchUrl('https://github.com/users/follow?target=alice', { method: 'POST' });
      assert.equal(result.success, false, `${label}: expected HTTP 422 to be unsuccessful`);
      assert.equal(result.status, 422, `${label}: expected status to be preserved`);
      assert.equal(result.error, 'Fetch returned HTTP 422', `${label}: expected HTTP error message`);
      assert.match(result.text, /Your browser did something unexpected/, `${label}: expected body text to be preserved`);
      assert.equal(Object.hasOwn(result, 'contentLength'), false, `${label}: absent Content-Length should remain absent`);
    }
  } finally {
    if (previousFetch === undefined) {
      delete globalThis.fetch;
    } else {
      globalThis.fetch = previousFetch;
    }
  }
});

test('fetchUrl provides bounded pagination, literal search, and safe range metadata', async () => {
  const previousFetch = globalThis.fetch;
  const source = [
    'first line',
    'x'.repeat(8000),
    'TargetHelper first occurrence',
    'middle',
    'targethelper second occurrence',
    'last line',
  ].join('\n');
  const makeResponse = (body, contentType, extraHeaders = {}) => ({
    status: 206,
    url: 'https://example.com/source.js',
    headers: new Headers({
      'content-type': contentType,
      'content-length': String(body.length),
      'content-range': `bytes 0-${Math.max(0, body.length - 1)}/${body.length}`,
      'accept-ranges': 'bytes',
      ...extraHeaders,
    }),
    text: async () => body,
  });
  try {
    for (const [label, fetchUrl, AgentClass] of [
      ['chrome', fetchUrlCh, AgentCh],
      ['firefox', fetchUrlFx, AgentFx],
    ]) {
      globalThis.fetch = async () => makeResponse(source, 'text/plain; charset=utf-8');

      const first = await fetchUrl('https://example.com/source.js');
      assert.equal(first.success, true, `${label}: first window failed`);
      assert.equal(first.offset, 0, `${label}: first offset`);
      assert.equal(first.maxChars, 7000, `${label}: default maxChars`);
      assert.equal(first.maxChars, first.text.length, `${label}: delivered maxChars drifted`);
      assert.equal(first.nextOffset, first.text.length, `${label}: nextOffset drifted`);
      assert.equal(first.hasMore, true, `${label}: missing continuation`);
      assert.equal(first.originalLength, source.length, `${label}: originalLength`);
      assert.equal(first.contentRange, `bytes 0-${source.length - 1}/${source.length}`, `${label}: contentRange`);
      assert.equal(first.contentLength, source.length, `${label}: contentLength`);
      assert.equal(first.acceptRanges, 'bytes', `${label}: acceptRanges`);
      assert.ok(JSON.stringify(first).length <= 8000, `${label}: first result exceeded agent cap`);
      const firstModelVisible = JSON.parse(AgentClass.prototype._limitToolResult(first));
      assert.equal(firstModelVisible.text, first.text, `${label}: generic limiter changed fetch text`);
      assert.equal(firstModelVisible.nextOffset, first.nextOffset, `${label}: generic limiter changed continuation`);

      const second = await fetchUrl('https://example.com/source.js', {
        offset: first.nextOffset,
        maxChars: 1000,
      });
      assert.equal(second.offset, first.nextOffset, `${label}: second offset`);
      assert.equal(second.text, source.slice(first.nextOffset, first.nextOffset + second.maxChars), `${label}: second window`);

      const minimum = await fetchUrl('https://example.com/source.js', { maxChars: 0 });
      assert.equal(minimum.maxChars, 1000, `${label}: explicit maxChars below the minimum must clamp to 1000`);
      const maximum = await fetchUrl('https://example.com/source.js', { maxChars: 99999 });
      assert.equal(maximum.maxChars, 7000, `${label}: maxChars above the maximum must clamp to 7000`);
      const pastEnd = await fetchUrl('https://example.com/source.js', { offset: source.length + 500 });
      assert.equal(pastEnd.offset, source.length, `${label}: offset past EOF must clamp to originalLength`);
      assert.equal(pastEnd.maxChars, 0, `${label}: offset past EOF must return an empty window`);
      assert.equal(pastEnd.text, '', `${label}: offset past EOF text`);
      assert.equal(pastEnd.nextOffset, null, `${label}: offset past EOF continuation`);
      assert.equal(pastEnd.hasMore, false, `${label}: offset past EOF hasMore`);

      const found = await fetchUrl('https://example.com/source.js', { find: 'TARGETHELPER' });
      assert.equal(found.find, 'TARGETHELPER', `${label}: find echo`);
      assert.equal(found.matchCount, 2, `${label}: case-insensitive match count`);
      assert.deepEqual(found.matches.map(match => match.offset), [
        source.indexOf('TargetHelper'),
        source.indexOf('targethelper'),
      ], `${label}: match offsets`);
      assert.deepEqual(found.matches.map(match => match.line), [3, 5], `${label}: match lines`);
      assert.equal(found.nextOffset, null, `${label}: search should cover full response`);
      assert.equal(found.hasMore, false, `${label}: search continuation should be closed`);

      const missing = await fetchUrl('https://example.com/source.js', { find: 'not-present' });
      assert.equal(missing.matchCount, 0, `${label}: no-match count`);
      assert.deepEqual(missing.matches, [], `${label}: no-match list`);

      const repeatedBody = Array.from({ length: 25 }, (_, i) => `line ${i} needle`).join('\n');
      globalThis.fetch = async () => makeResponse(repeatedBody, 'text/plain');
      const boundedMatches = await fetchUrl('https://example.com/repeated.txt', { find: 'needle' });
      assert.equal(boundedMatches.matchCount, 20, `${label}: find match limit`);
      assert.equal(boundedMatches.matches.length, 20, `${label}: bounded match list`);
      assert.equal(boundedMatches.matchesTruncated, true, `${label}: extra matches should be disclosed`);

      const jsonBody = JSON.stringify({ pad: 'z'.repeat(8000), target: 'NeedleValue' });
      globalThis.fetch = async () => makeResponse(jsonBody, 'application/json');
      const jsonPage = await fetchUrl('https://example.com/data.json', { offset: 1000, maxChars: 1000 });
      assert.equal(typeof jsonPage.json, 'string', `${label}: paged JSON field missing`);
      assert.equal(jsonPage.offset, 1000, `${label}: JSON offset`);
      assert.ok(JSON.stringify(jsonPage).length <= 8000, `${label}: JSON result exceeded agent cap`);
      const jsonFind = await fetchUrl('https://example.com/data.json', { find: 'needlevalue' });
      assert.equal(jsonFind.matchCount, 1, `${label}: JSON find`);

      const htmlBody = '<html><title>Example</title><body><p>Alpha</p><p>ScopedHelper here</p></body></html>';
      globalThis.fetch = async () => makeResponse(htmlBody, 'text/html; charset=utf-8');
      const htmlFind = await fetchUrl('https://example.com/page', { find: 'scopedhelper' });
      assert.equal(htmlFind.matchCount, 1, `${label}: HTML find`);
      assert.equal(htmlFind.title, 'Example', `${label}: HTML title`);

      const escapeHeavy = '"\\\\\\n'.repeat(4000);
      globalThis.fetch = async () => makeResponse(escapeHeavy, 'text/plain');
      const constrained = await fetchUrl('https://example.com/escaped.txt', { maxChars: 7000 });
      assert.ok(JSON.stringify(constrained).length <= 8000, `${label}: escaped result exceeded agent cap`);
      assert.equal(constrained.nextOffset, constrained.offset + constrained.text.length, `${label}: constrained continuation drifted`);
      const constrainedModelVisible = JSON.parse(AgentClass.prototype._limitToolResult(constrained));
      assert.equal(constrainedModelVisible.text, constrained.text, `${label}: generic limiter changed constrained text`);
      assert.equal(constrainedModelVisible.nextOffset, constrained.nextOffset, `${label}: model-visible continuation drifted`);
    }
  } finally {
    if (previousFetch === undefined) {
      delete globalThis.fetch;
    } else {
      globalThis.fetch = previousFetch;
    }
  }
});

test('fetchUrl reuses captured same-origin API replay body and safe headers', async () => {
  const previousFetch = globalThis.fetch;
  const previousReplay = globalThis.__webbrainApiRequestReplay;
  try {
    for (const [label, fetchUrl] of [['chrome', fetchUrlCh], ['firefox', fetchUrlFx]]) {
      let seen = null;
      globalThis.__webbrainApiRequestReplay = new Map([[
        'api_42_req_1',
        {
          tabId: 42,
          url: 'https://github.com/users/follow?target=alice',
          method: 'POST',
          headers: {
            accept: 'text/html',
            'content-type': 'application/x-www-form-urlencoded',
            'x-csrf-token': 'opaque-token',
          },
          body: 'authenticity_token=opaque-token',
        },
      ]]);
      globalThis.fetch = async (rawUrl, init = {}) => {
        seen = { url: String(rawUrl), init };
        return new Response('ok', { status: 200, headers: { 'content-type': 'text/plain' } });
      };

      const result = await fetchUrl(
        'https://github.com/users/follow?target=bob',
        { replayRequestId: 'api_42_req_1' },
        { tabId: 42 },
      );

      assert.equal(result.success, true, `${label}: replayed fetch should succeed`);
      assert.equal(seen.init.method, 'POST', `${label}: replay should reuse captured method`);
      assert.equal(seen.init.body, 'authenticity_token=opaque-token', `${label}: replay should reuse captured body`);
      assert.equal(seen.init.headers['content-type'], 'application/x-www-form-urlencoded', `${label}: replay should reuse content-type`);
      assert.equal(seen.init.headers['x-csrf-token'], 'opaque-token', `${label}: replay should reuse safe CSRF header internally`);

      const blocked = await fetchUrl(
        'https://evil.example/users/follow?target=bob',
        { replayRequestId: 'api_42_req_1' },
        { tabId: 42 },
      );
      assert.equal(blocked.success, false, `${label}: replay must not cross origins`);
      assert.match(blocked.error, /scoped to https:\/\/github\.com/, `${label}: expected same-origin replay error`);
    }
  } finally {
    if (previousFetch === undefined) {
      delete globalThis.fetch;
    } else {
      globalThis.fetch = previousFetch;
    }
    if (previousReplay === undefined) {
      delete globalThis.__webbrainApiRequestReplay;
    } else {
      globalThis.__webbrainApiRequestReplay = previousReplay;
    }
  }
});

test('fetchUrl runs captured same-origin API replay in the active page context', async () => {
  const previousFetch = globalThis.fetch;
  const previousReplay = globalThis.__webbrainApiRequestReplay;
  const previousChrome = globalThis.chrome;
  const previousBrowser = globalThis.browser;
  try {
    let backgroundFetches = 0;
    globalThis.fetch = async () => {
      backgroundFetches++;
      throw new Error('background fetch should not run for same-origin replay');
    };
    globalThis.__webbrainApiRequestReplay = new Map([[
      'api_42_req_1',
      {
        tabId: 42,
        url: 'https://github.com/users/follow?target=alice',
        method: 'POST',
        headers: {
          accept: 'text/html',
          'content-type': 'application/x-www-form-urlencoded',
          'x-csrf-token': 'opaque-token',
        },
        body: 'authenticity_token=opaque-token',
      },
    ]]);

    let chromeSeen = null;
    globalThis.chrome = {
      tabs: {
        get: async () => ({ url: 'https://github.com/anomalyco/opencode/stargazers?page=37' }),
      },
      scripting: {
        executeScript: async (opts) => {
          chromeSeen = opts;
          return [{
            result: {
              ok: true,
              status: 200,
              url: 'https://github.com/users/follow?target=bob',
              contentType: 'text/plain',
              text: 'x'.repeat(1500),
            },
          }];
        },
      },
    };

    const chromeResult = await fetchUrlCh(
      'https://github.com/users/follow?target=bob',
      { replayRequestId: 'api_42_req_1', maxChars: 1000 },
      { tabId: 42 },
    );
    assert.equal(chromeResult.success, true, 'chrome: page-context replay should succeed');
    assert.equal(chromeResult.status, 200, 'chrome: status should be preserved');
    assert.equal(chromeResult.replayContext, 'page', 'chrome: result should identify page replay');
    assert.equal(chromeResult.text.length, 1000, 'chrome: page replay should honor maxChars');
    assert.equal(chromeResult.nextOffset, 1000, 'chrome: page replay should expose aligned continuation');
    assert.equal(chromeResult.hasMore, true, 'chrome: page replay should disclose remaining text');
    assert.equal(chromeSeen.world, 'ISOLATED', 'chrome: replay should run in the isolated world so the page cannot monkey-patch fetch/URL/Response');
    assert.equal(chromeSeen.args[1].method, 'POST', 'chrome: replay should reuse captured method');
    assert.equal(chromeSeen.args[1].body, 'authenticity_token=opaque-token', 'chrome: replay should reuse captured body');
    assert.equal(chromeSeen.args[1].headers['x-csrf-token'], 'opaque-token', 'chrome: replay should keep safe CSRF header internally');

    let firefoxSeen = null;
    globalThis.browser = {
      tabs: {
        get: async () => ({ url: 'https://github.com/anomalyco/opencode/stargazers?page=37' }),
        executeScript: async (tabId, opts) => {
          firefoxSeen = { tabId, opts };
          return [{
            ok: true,
            status: 200,
            url: 'https://github.com/users/follow?target=bob',
            contentType: 'application/json',
            text: JSON.stringify({ pad: 'z'.repeat(2000), target: 'NeedleValue' }),
          }];
        },
      },
    };

    const firefoxResult = await fetchUrlFx(
      'https://github.com/users/follow?target=bob',
      { replayRequestId: 'api_42_req_1', find: 'needlevalue' },
      { tabId: 42 },
    );
    assert.equal(firefoxResult.success, true, 'firefox: page-context replay should succeed');
    assert.equal(firefoxResult.replayContext, 'page', 'firefox: result should identify page replay');
    assert.equal(firefoxResult.matchCount, 1, 'firefox: page replay should honor literal find');
    assert.equal(firefoxResult.matches[0].line >= 1, true, 'firefox: replay find should include line metadata');
    assert.equal(Object.hasOwn(firefoxResult, 'json'), false, 'firefox: find should return matches instead of the full JSON window');
    assert.equal(firefoxSeen.tabId, 42, 'firefox: replay should run in the active tab');
    assert.match(firefoxSeen.opts.code, /fetch\(targetUrl\.href/, 'firefox: replay script should fetch from the tab context');

    assert.equal(backgroundFetches, 0, 'same-origin replay should not fall back to background fetch');
  } finally {
    if (previousFetch === undefined) delete globalThis.fetch;
    else globalThis.fetch = previousFetch;
    if (previousReplay === undefined) delete globalThis.__webbrainApiRequestReplay;
    else globalThis.__webbrainApiRequestReplay = previousReplay;
    if (previousChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = previousChrome;
    if (previousBrowser === undefined) delete globalThis.browser;
    else globalThis.browser = previousBrowser;
  }
});

