test('coupon-domain generator bounds its fixed source set and fails closed on empty indexes', async () => {
  const requested = [];
  const domains = await collectCouponFollowDomains({
    concurrency: 3,
    fetchImpl: async (url) => {
      requested.push(url);
      const index = new URL(url).pathname.split('/').at(-2);
      return new Response(`<a href="/site/shop-${index}.example.com">merchant</a>`, {
        headers: { 'content-type': 'text/html' },
      });
    },
  });
  assert.equal(requested.length, 27);
  assert.equal(new Set(requested).size, 27);
  assert.ok(domains.includes('shop-a.example.com'));

  await assert.rejects(
    collectCouponFollowDomains({
      fetchImpl: async () => new Response('<html><body>No merchant links</body></html>', {
        headers: { 'content-type': 'text/html' },
      }),
    }),
    /contained no merchant domains/,
  );
});

test('coupon-domain provenance preserves per-source history and canonical output', () => {
  const firstEvidence = new Map([
    ['couponfollow', new Set(['alpha.com', 'shared.com'])],
    ['couponswift', new Set(['beta.com', 'shared.com'])],
    ['vetted', new Set(['amazon.com'])],
  ]);
  const first = buildCouponDomainProvenance(firstEvidence, { asOf: '2026-08-10' });
  assert.deepEqual(activeDomainsFromManifest(first), ['alpha.com', 'amazon.com', 'beta.com', 'shared.com']);
  assert.equal(first.domains['shared.com'].couponfollow.firstSeen, '2026-08-10');
  assert.equal(first.domains['shared.com'].couponswift.active, true);
  assert.equal(validateCouponDomainProvenance(first), first);
  assert.equal(renderCouponDomainProvenance(first), `${JSON.stringify(first, null, 2)}\n`);

  const nextEvidence = new Map([
    ['couponfollow', new Set(['shared.com'])],
    ['couponswift', new Set(['beta.com', 'shared.com'])],
    ['vetted', new Set(['amazon.com'])],
  ]);
  const next = buildCouponDomainProvenance(nextEvidence, {
    previousManifest: first,
    asOf: '2026-08-17',
  });
  assert.equal(next.domains['alpha.com'].couponfollow.active, false);
  assert.equal(next.domains['alpha.com'].couponfollow.lastSeen, '2026-08-10');
  assert.equal(next.domains['shared.com'].couponfollow.firstSeen, '2026-08-10');
  assert.equal(next.domains['shared.com'].couponfollow.lastSeen, '2026-08-17');
  assert.deepEqual(activeDomainsFromManifest(next), ['amazon.com', 'beta.com', 'shared.com']);
});

test('coupon-domain snapshot churn fails closed unless explicitly overridden', () => {
  const previous = Array.from({ length: 200 }, (_, index) => `old-${index}.example.com`);
  const next = Array.from({ length: 200 }, (_, index) => `new-${index}.example.com`);
  assert.throws(
    () => assertCouponDomainChurn(previous, next),
    /churn exceeded 100: 200 added, 200 removed/,
  );
  const override = assertCouponDomainChurn(previous, next, { allowLargeChurn: true });
  assert.equal(override.added.length, 200);
  assert.equal(override.removed.length, 200);
});

test('coupon-domain source-count anomalies fail before generation', () => {
  const makeDomains = (prefix, count) => new Set(
    Array.from({ length: count }, (_, index) => `${prefix}-${index}.example.com`),
  );
  const valid = new Map([
    ['couponfollow', makeDomains('couponfollow', 3_000)],
    ['couponswift', makeDomains('couponswift', 40)],
    ['vetted', makeDomains('vetted', 75)],
  ]);
  assert.doesNotThrow(() => assertCouponDomainEvidence(valid));

  const tooSmall = new Map(valid);
  tooSmall.set('couponswift', makeDomains('couponswift', 39));
  assert.throws(
    () => assertCouponDomainEvidence(tooSmall),
    /couponswift yielded 39 domains; expected 40-100/,
  );

  const previousManifest = {
    sources: {
      couponfollow: { domainCount: 3_000 },
      couponswift: { domainCount: 50 },
      vetted: { domainCount: 75 },
    },
  };
  const largeChange = new Map(valid);
  largeChange.set('couponfollow', makeDomains('couponfollow', 3_701));
  assert.throws(
    () => assertCouponDomainEvidence(largeChange, { previousManifest }),
    /couponfollow count changed from 3000 to 3701; limit is 600/,
  );
  assert.doesNotThrow(() => assertCouponDomainEvidence(largeChange, {
    previousManifest,
    allowLargeChurn: true,
  }));
});

