test('compact Act exposes a self-targeting upload workflow without a general selector tool', () => {
  for (const [label, getTools, prompt] of [
    ['chrome', getToolsForModeCh, SYSTEM_PROMPT_ACT_COMPACT_CH],
    ['firefox', getToolsForModeFx, SYSTEM_PROMPT_ACT_COMPACT_FX],
  ]) {
    const askNames = getTools('ask').map(tool => tool.function.name);
    const compactTools = getTools('act', { tier: 'compact' });
    const compactNames = compactTools.map(tool => tool.function.name);
    const upload = compactTools.find(tool => tool.function.name === 'upload_file');
    const fullUpload = getTools('act').find(tool => tool.function.name === 'upload_file');

    assert.ok(upload, `[${label}] compact Act must expose upload_file`);
    assert.equal(askNames.includes('upload_file'), false, `[${label}] Ask must remain read-only`);
    for (const unavailable of [
      'download_files',
      'download_resource_from_page',
      'list_downloads',
      'read_downloaded_file',
    ]) {
      assert.equal(compactNames.includes(unavailable), false, `[${label}] compact Act exposed ${unavailable}`);
    }
    assert.match(upload.function.description, /two-step Compact workflow/i);
    assert.match(upload.function.description, /read-only/i);
    assert.match(upload.function.description, /targetId choices/i);
    assert.match(upload.function.description, /Never invent or modify a targetId/i);
    assert.match(upload.function.description, /one guarded click/i);
    assert.doesNotMatch(upload.function.description, /download_files|list_downloads|downloadId/i);
    assert.doesNotMatch(upload.function.description, /get_interactive_elements|CSS selector/i);
    assert.ok(upload.function.parameters.properties.attachmentId, `[${label}] compact upload must accept attachmentId`);
    assert.ok(upload.function.parameters.properties.targetId, `[${label}] compact upload must accept its own targetId`);
    assert.ok(fullUpload.function.parameters.properties.downloadId, `[${label}] full upload must retain downloadId`);
    assert.ok(fullUpload.function.parameters.properties.selector, `[${label}] full upload must retain selector`);
    assert.equal(fullUpload.function.parameters.properties.targetId, undefined, `[${label}] full upload must not gain compact targetId`);

    // Compact can reach only the file the user attached to this run: it has no
    // download tools to produce a downloadId, and no way to learn a local path
    // that the model did not invent.
    for (const hidden of ['selector', 'downloadId', 'filePath']) {
      assert.equal(
        upload.function.parameters.properties[hidden],
        undefined,
        `[${label}] compact upload must hide ${hidden}`,
      );
    }
    assert.deepEqual(
      Object.keys(upload.function.parameters.properties).sort(),
      ['attachmentId', 'targetId'],
      `[${label}] compact upload must expose exactly attachmentId + targetId`,
    );
    assert.equal(
      compactNames.includes('get_interactive_elements'),
      false,
      `[${label}] compact upload discovery must not expose the general selector tool`,
    );

    // Assert on the prompt's own upload_file bullet rather than on character
    // distances, so rewording the neighbouring bullets cannot break these.
    const uploadLine = prompt.split('\n').find(line => line.startsWith('- upload_file('));
    assert.ok(uploadLine, `[${label}] compact prompt must document upload_file`);
    assert.match(uploadLine, /Two steps/i);
    assert.match(uploadLine, /targetId/i);
    assert.match(uploadLine, /Never guess a targetId/i);
    assert.match(uploadLine, /one guarded initializer click/i);
    assert.doesNotMatch(uploadLine, /selector|get_interactive_elements/i);
    assert.equal(
      prompt.split('\n').some(line => line.startsWith('- get_interactive_elements')),
      false,
      `[${label}] compact prompt must not advertise the removed general selector tool`,
    );
    assert.doesNotMatch(prompt, /download_files|list_downloads|downloadId/i);

    if (label === 'firefox') {
      assert.match(upload.function.description, /user-controlled picker/i);
      assert.deepEqual(upload.function.parameters.required, []);
    } else {
      assert.deepEqual(upload.function.parameters.required, ['attachmentId']);
    }
  }
});

test('upload targeting is tier-scoped: compact self-discovers while mid/full keep selectors', () => {
  for (const [label, getTools] of [['chrome', getToolsForModeCh], ['firefox', getToolsForModeFx]]) {
    const compact = getTools('act', { tier: 'compact' });
    const compactNames = new Set(compact.map(tool => tool.function.name));
    assert.equal(compactNames.has('upload_file'), true, `[${label}] compact must keep upload_file`);
    assert.equal(compactNames.has('get_interactive_elements'), false, `[${label}] compact must avoid the overlapping inspection tool`);

    for (const tier of ['mid', 'full']) {
      const tools = getTools('act', { tier });
      const names = new Set(tools.map(tool => tool.function.name));
      const upload = tools.find(tool => tool.function.name === 'upload_file');
      assert.equal(names.has('upload_file'), true, `[${label}] act/${tier} must keep upload_file`);
      assert.equal(names.has('get_interactive_elements'), true, `[${label}] act/${tier} must keep selector recovery`);
      assert.ok(upload.function.parameters.properties.selector, `[${label}] act/${tier} lost selector`);
      assert.equal(upload.function.parameters.properties.targetId, undefined, `[${label}] act/${tier} gained compact targetId`);
      assert.deepEqual(upload.function.parameters.required, ['selector'], `[${label}] act/${tier} selector contract changed`);
    }
  }
});

test('Compact upload discovery uses a hidden file-input-only page action', async () => {
  for (const [label, AgentClass, getTools, untrustedTools] of [
    ['chrome', AgentCh, getToolsForModeCh, UNTRUSTED_CONTENT_TOOLS_CH],
    ['firefox', AgentFx, getToolsForModeFx, UNTRUSTED_CONTENT_TOOLS],
  ]) {
    const agent = Object.create(AgentClass.prototype);
    let invocation = null;
    agent.executeTool = async (tabId, name, args) => {
      invocation = { tabId, name, args };
      return [
        { tag: 'input', type: 'file', selector: '#avatar' },
        { tag: 'button', type: 'button', selector: '#submit' },
      ];
    };

    const inventory = await agent._readCompactUploadFileInputs(42);
    assert.deepEqual(invocation, {
      tabId: 42,
      name: 'get_file_input_targets',
      args: {},
    }, `[${label}] Compact discovery must call the narrow internal action`);
    assert.equal(inventory.ok, true);
    assert.deepEqual(inventory.fileInputs, [{ tag: 'input', type: 'file', selector: '#avatar' }]);
    assert.deepEqual(inventory.usable, [{ tag: 'input', type: 'file', selector: '#avatar' }]);
    assert.equal(untrustedTools.has('get_file_input_targets'), true);
    assert.equal(
      agent._toolResultTrustName('upload_file', { discoveryOnly: true }),
      'get_file_input_targets',
      `[${label}] page-derived discovery labels must use the untrusted boundary`,
    );
    assert.equal(
      agent._toolResultTrustName('upload_file', { success: true }),
      'upload_file',
      `[${label}] ordinary Mid/Full upload results must retain their existing trust classification`,
    );

    for (const [mode, tiers] of [['ask', ['full']], ['act', ['compact', 'mid', 'full']], ['dev', ['compact', 'mid', 'full']]]) {
      for (const tier of tiers) {
        const names = getTools(mode, { tier }).map(tool => tool.function.name);
        assert.equal(
          names.includes('get_file_input_targets'),
          false,
          `[${label}] ${mode}/${tier} must not expose the internal discovery action`,
        );
      }
    }
  }
});

test('Compact upload target helpers stay byte-identical across Chrome and Firefox', () => {
  const startMarker = '  // COMPACT_UPLOAD_TARGET_HELPERS_START';
  const endMarker = '  // COMPACT_UPLOAD_TARGET_HELPERS_END';
  const helperBlock = (browser) => {
    const source = fs.readFileSync(path.join(ROOT, `src/${browser}/src/agent/agent.js`), 'utf8');
    const start = source.indexOf(startMarker);
    const end = source.indexOf(endMarker, start + startMarker.length);
    assert.ok(start >= 0 && end > start, `${browser}: Compact upload helper parity markers are missing or reversed`);
    assert.equal(
      source.indexOf(startMarker, start + startMarker.length),
      -1,
      `${browser}: Compact upload helper start marker must be unique`,
    );
    assert.equal(
      source.indexOf(endMarker, end + endMarker.length),
      -1,
      `${browser}: Compact upload helper end marker must be unique`,
    );
    return source.slice(start, end + endMarker.length);
  };

  assert.equal(
    helperBlock('chrome'),
    helperBlock('firefox'),
    'Chrome and Firefox Compact upload target helpers must remain byte-identical',
  );
});

test('getToolsForMode: mode/tier redesign exposes the intended normal and Dev tools', () => {
  for (const [label, getTools] of [
    ['chrome', getToolsForModeCh],
    ['firefox', getToolsForModeFx],
  ]) {
    const ask = getTools('ask').map(t => t.function.name);
    const compact = getTools('act', { tier: 'compact' }).map(t => t.function.name);
    const mid = getTools('act', { tier: 'mid' }).map(t => t.function.name);
    const full = getTools('act').map(t => t.function.name);
    const devCompact = getTools('dev', { tier: 'compact' }).map(t => t.function.name);
    const devMid = getTools('dev', { tier: 'mid' }).map(t => t.function.name);
    const devFull = getTools('dev').map(t => t.function.name);

    assert.deepEqual(devCompact, [], `[${label}] Dev Compact should be blocked at tool-schema level`);
    for (const name of ['get_accessibility_tree', 'read_page', 'scroll', 'extract_data', 'get_selection', 'done', 'fetch_url']) {
      assert.equal(ask.includes(name), true, `[${label}] ask should expose ${name}`);
      assert.equal(compact.includes(name), true, `[${label}] compact act should expose ${name}`);
      assert.equal(mid.includes(name), true, `[${label}] mid act should expose ${name}`);
      assert.equal(full.includes(name), true, `[${label}] full act should expose ${name}`);
    }
    assert.equal(ask.includes('clarify'), false, `[${label}] default Ask should not expose research consent`);
    const researchAsk = getTools('ask', { researchEscalationEnabled: true }).map(t => t.function.name);
    assert.equal(researchAsk.includes('clarify'), true, `[${label}] opted-in Ask should expose research consent`);
    assert.equal(researchAsk.includes('delegate_research'), true, `[${label}] opted-in Ask should expose research delegation`);
    assert.equal(compact.includes('clarify'), true, `[${label}] compact act should expose clarify`);
    assert.equal(mid.includes('clarify'), true, `[${label}] mid act should expose clarify`);
    assert.equal(full.includes('clarify'), true, `[${label}] full act should expose clarify`);

    for (const name of ['click_ax', 'set_checked', 'type_ax', 'set_field', 'click', 'type_text', 'press_keys', 'navigate', 'wait_for_element', 'scratchpad_write', 'progress_update', 'progress_read']) {
      assert.equal(ask.includes(name), false, `[${label}] ask should not expose action tool ${name}`);
      assert.equal(compact.includes(name), true, `[${label}] compact act should expose ${name}`);
      assert.equal(mid.includes(name), true, `[${label}] mid act should expose ${name}`);
      assert.equal(full.includes(name), true, `[${label}] full act should expose ${name}`);
    }

    for (const name of ['new_tab', 'list_tabs', 'activate_tab']) {
      for (const [surface, names] of Object.entries({ ask, compact, mid, full, devCompact, devMid, devFull })) {
        assert.equal(names.includes(name), false, `[${label}] ${surface} must not expose removed tab tool ${name}`);
      }
    }
    const researchOptions = { researchEscalationEnabled: true };
    assert.equal(getTools('act', { tier: 'compact', ...researchOptions }).length, 25, `[${label}] Compact should expose 25 tools after tab-tool removal`);
    assert.equal(getTools('act', { tier: 'mid', ...researchOptions }).length, 44, `[${label}] Mid should expose 44 tools after tab-tool removal`);
    assert.equal(getTools('act', researchOptions).length, label === 'chrome' ? 50 : 49, `[${label}] Full tool count should drop by three`);
    assert.equal(compact.includes('research_url'), false, `[${label}] Compact must not gain research_url as a tab-tool replacement`);

    assert.equal(ask.includes('download_resource_from_page'), false, `[${label}] ask must not expose download_resource_from_page`);
    assert.equal(compact.includes('download_resource_from_page'), false, `[${label}] compact act must not expose download_resource_from_page`);
    assert.equal(mid.includes('download_resource_from_page'), true, `[${label}] mid act should expose download_resource_from_page`);
    assert.equal(full.includes('download_resource_from_page'), true, `[${label}] full act should expose download_resource_from_page`);

    for (const name of ['hover', 'drag_drop']) {
      assert.equal(ask.includes(name), false, `[${label}] ask should not expose ${name}`);
      assert.equal(compact.includes(name), false, `[${label}] compact act should not expose ${name}`);
      assert.equal(mid.includes(name), false, `[${label}] mid act should not expose ${name}`);
      assert.equal(full.includes(name), true, `[${label}] full act should expose ${name}`);
      assert.equal(devMid.includes(name), false, `[${label}] dev mid should not add ${name}`);
      assert.equal(devFull.includes(name), true, `[${label}] dev full should keep full-act ${name}`);
    }
    for (const name of ['get_shadow_dom', 'get_frames']) {
      assert.equal(ask.includes(name), false, `[${label}] ask should not expose ${name}`);
      assert.equal(compact.includes(name), false, `[${label}] compact act should not expose ${name}`);
      assert.equal(mid.includes(name), false, `[${label}] mid act should not expose ${name}`);
      assert.equal(full.includes(name), true, `[${label}] full act should expose ${name}`);
      assert.equal(devMid.includes(name), true, `[${label}] dev mid should add ${name}`);
      assert.equal(devFull.includes(name), true, `[${label}] dev full should keep full-act ${name}`);
    }

    assert.equal(ask.includes('read_page_source'), false, `[${label}] ask must not expose read_page_source`);
    assert.equal(ask.includes('inspect_element_styles'), false, `[${label}] ask must not expose inspect_element_styles`);
    assert.equal(full.includes('read_page_source'), false, `[${label}] full act must not expose read_page_source`);
    assert.equal(full.includes('inspect_element_styles'), false, `[${label}] full act must not expose inspect_element_styles`);
    assert.equal(mid.includes('read_page_source'), false, `[${label}] mid act must not expose read_page_source`);
    assert.equal(mid.includes('inspect_element_styles'), false, `[${label}] mid act must not expose inspect_element_styles`);
    assert.equal(devMid.includes('read_page_source'), true, `[${label}] dev mid should expose read_page_source`);
    assert.equal(devMid.includes('inspect_element_styles'), true, `[${label}] dev mid should expose inspect_element_styles`);
    assert.equal(devFull.includes('read_page_source'), true, `[${label}] dev full should expose read_page_source`);
    assert.equal(devFull.includes('inspect_element_styles'), true, `[${label}] dev full should expose inspect_element_styles`);
    assert.equal(ask.includes('execute_js'), false, `[${label}] ask must not expose execute_js`);
    assert.equal(compact.includes('execute_js'), false, `[${label}] compact act must not expose execute_js`);
    assert.equal(mid.includes('execute_js'), false, `[${label}] mid act must not expose execute_js`);
    assert.equal(full.includes('execute_js'), false, `[${label}] full act must not expose execute_js`);
    assert.equal(devMid.includes('execute_js'), true, `[${label}] dev mid should expose execute_js`);
    assert.equal(devFull.includes('execute_js'), true, `[${label}] dev full should expose execute_js`);

    assert.equal(mid.includes('upload_file'), true, `[${label}] mid act should expose upload_file`);
    assert.equal(full.includes('upload_file'), true, `[${label}] full act should expose upload_file`);
    if (label === 'chrome') {
      assert.equal(full.includes('shadow_dom_query'), true, '[chrome] full act should expose shadow_dom_query');
      assert.equal(mid.includes('shadow_dom_query'), false, '[chrome] mid act should not expose shadow_dom_query');
      assert.equal(devMid.includes('shadow_dom_query'), true, '[chrome] dev mid should add shadow_dom_query');
      assert.equal(devFull.includes('shadow_dom_query'), true, '[chrome] dev full should keep shadow_dom_query');
    } else {
      assert.equal(full.includes('shadow_dom_query'), false, '[firefox] shadow_dom_query is Chrome-only');
      assert.equal(mid.includes('shadow_dom_query'), false, '[firefox] shadow_dom_query is Chrome-only');
      assert.equal(devMid.includes('shadow_dom_query'), false, '[firefox] Dev must not invent Chrome-only shadow_dom_query');
      assert.equal(devFull.includes('shadow_dom_query'), false, '[firefox] Dev must not invent Chrome-only shadow_dom_query');
    }
  }
});

test('browser tab tools are absent from catalogs, runtime handlers, and prompts', () => {
  for (const [label, prompts, plannerPrompt, askPrompt, actPrompts] of [
    ['chrome', [SYSTEM_PROMPT_ASK_CH, SYSTEM_PROMPT_ACT_CH, SYSTEM_PROMPT_ACT_MID_CH, SYSTEM_PROMPT_ACT_COMPACT_CH], PLANNER_SYSTEM_PROMPT, SYSTEM_PROMPT_ASK_CH, [SYSTEM_PROMPT_ACT_CH, SYSTEM_PROMPT_ACT_MID_CH, SYSTEM_PROMPT_ACT_COMPACT_CH]],
    ['firefox', [SYSTEM_PROMPT_ASK_FX, SYSTEM_PROMPT_ACT_FX, SYSTEM_PROMPT_ACT_MID_FX, SYSTEM_PROMPT_ACT_COMPACT_FX], PLANNER_SYSTEM_PROMPT_FX, SYSTEM_PROMPT_ASK_FX, [SYSTEM_PROMPT_ACT_FX, SYSTEM_PROMPT_ACT_MID_FX, SYSTEM_PROMPT_ACT_COMPACT_FX]],
  ]) {
    const agentSource = fs.readFileSync(path.join(ROOT, `src/${label}/src/agent/agent.js`), 'utf8');
    const permissionSource = fs.readFileSync(path.join(ROOT, `src/${label}/src/agent/permission-gate.js`), 'utf8');
    const classify = label === 'chrome' ? capabilityForCh : capabilityFor;
    const AgentClass = label === 'chrome' ? AgentCh : AgentFx;
    const mutationTools = label === 'chrome' ? MUTATION_TOOLS_CH : MUTATION_TOOLS_FX;
    for (const name of ['new_tab', 'list_tabs', 'activate_tab']) {
      assert.doesNotMatch(agentSource, new RegExp(`\\b${name}\\b`), `[${label}] runtime retained ${name}`);
      assert.doesNotMatch(permissionSource, new RegExp(`\\b${name}\\b`), `[${label}] permission gate retained ${name}`);
      assert.doesNotMatch(plannerPrompt, new RegExp(`\\b${name}\\b`), `[${label}] planner advertises ${name}`);
      assert.equal(classify(name, {}), null, `[${label}] removed tool ${name} retained a permission classification`);
      assert.equal(AgentClass.STATE_CHANGE_TOOLS.has(name), false, `[${label}] removed tool ${name} retained a state-change classification`);
      assert.equal(mutationTools.has(name), false, `[${label}] removed tool ${name} retained a mutation classification`);
      for (const prompt of prompts) {
        assert.doesNotMatch(prompt, new RegExp(`\\b${name}\\b`), `[${label}] system prompt advertises ${name}`);
      }
    }
    for (const prompt of prompts) {
      assert.match(prompt, /cannot create, enumerate, activate, or retarget browser tabs/i, `[${label}] tab limitation missing`);
      assert.match(prompt, /explicitly asks for a separate tab/i, `[${label}] separate-tab requests have no stated handling`);
    }

    // Act and Dev can reach another URL through the run tab, so they promise
    // current-tab navigation rather than silently retargeting.
    for (const prompt of actPrompts) {
      assert.match(prompt, /explicitly asks for a separate tab[\s\S]*instead of silently navigating/i, `[${label}] separate-tab requests could be silently retargeted`);
      assert.match(prompt, /offer current-tab navigation/i, `[${label}] action prompt should offer the current-tab fallback`);
    }

    // Ask is read-only and has no navigate, so the same offer would be a promise
    // the mode cannot keep.
    assert.doesNotMatch(askPrompt, /offer current-tab navigation/i, `[${label}] ask prompt offers navigation it cannot perform`);
    assert.doesNotMatch(askPrompt, /navigating the current run tab/i, `[${label}] ask prompt points at navigation it cannot perform`);
    assert.match(askPrompt, /Ask mode cannot navigate the current one either/i, `[${label}] ask prompt should state that navigation is unavailable too`);
    assert.match(askPrompt, /offer to read that URL here, or to switch to Act mode/i, `[${label}] ask prompt should offer a read-only fallback and the Act handoff`);
    const askTools = new Set((label === 'chrome' ? getToolsForModeCh : getToolsForModeFx)('ask').map(t => t.function?.name));
    assert.equal(askTools.has('navigate'), false, `[${label}] ask exposing navigate would make the read-only wording wrong`);
    assert.equal(askTools.has('fetch_url'), true, `[${label}] ask needs a URL-reading tool for the fallback it offers`);
  }
});

test('schedule_task tool schema advertises supported modes and fixed-interval semantics', () => {
  for (const [label, getTools] of [
    ['chrome', getToolsForModeCh],
    ['firefox', getToolsForModeFx],
  ]) {
    const scheduleTask = getTools('act').find(t => t.function.name === 'schedule_task');
    const modeSchema = scheduleTask?.function.parameters.properties.mode;

    assert.ok(modeSchema, `[${label}] schedule_task must expose a mode schema`);
    assert.deepEqual(modeSchema.enum, ['ask', 'act', 'dev'], `[${label}] schedule_task mode enum must match validator modes`);
    assert.match(scheduleTask.function.description, /fixed-minute-interval/i, `[${label}] schedule_task should name fixed-interval recurrence`);
    assert.match(scheduleTask.function.description, /Calendar\/cron recurrence.*not supported/i, `[${label}] schedule_task should disclose calendar limitation`);
    assert.match(scheduleTask.function.description, /do not approximate/i, `[${label}] schedule_task should forbid calendar approximations`);
    assert.match(
      scheduleTask.function.parameters.properties.schedule.properties.interval_minutes.description,
      /Never convert monthly recurrence/i,
      `[${label}] recurring schema should forbid monthly interval conversion`,
    );
  }
});

test('fetch_url schema documents semantic text controls and model-visible bounds', () => {
  for (const [label, getTools] of [
    ['chrome', getToolsForModeCh],
    ['firefox', getToolsForModeFx],
  ]) {
    const fetchUrl = getTools('act').find(t => t.function.name === 'fetch_url');
    const properties = fetchUrl?.function.parameters.properties || {};
    assert.ok(fetchUrl, `[${label}] fetch_url tool missing`);
    assert.equal(properties.offset?.type, 'number', `[${label}] offset schema missing`);
    assert.match(properties.offset?.description || '', /Default 0.*nextOffset/i, `[${label}] offset continuation guidance missing`);
    assert.equal(properties.maxChars?.type, 'number', `[${label}] maxChars schema missing`);
    assert.match(properties.maxChars?.description || '', /Default 7000.*1000\.\.7000/i, `[${label}] maxChars bounds missing`);
    assert.equal(properties.find?.type, 'string', `[${label}] find schema missing`);
    assert.match(properties.find?.description || '', /case-insensitive literal search.*line and character offsets/i, `[${label}] literal find behavior missing`);
    assert.match(fetchUrl.function.description, /bounded text\/JSON window[\s\S]*offset: nextOffset[\s\S]*do not guess HTTP Range/i, `[${label}] fetch_url large-source guidance missing`);
    assert.match(fetchUrl.function.description, /originalLength[\s\S]*nextOffset[\s\S]*hasMore/, `[${label}] continuation metadata missing`);
  }
});

