test('Content-Disposition filenames use a bounded parser and fail closed on malformed quotes', () => {
  for (const [label, parseFilename] of [
    ['chrome', filenameFromContentDispositionCh],
    ['firefox', filenameFromContentDispositionFx],
  ]) {
    assert.equal(parseFilename("attachment; filename*=UTF-8''Video%20Name.mp4"), 'Video Name.mp4', `${label}: RFC 5987 filename failed`);
    assert.equal(parseFilename("attachment; filename=plain.mp4; filename*=UTF-8''preferred%20name.mp4"), 'preferred name.mp4', `${label}: filename* should take precedence`);
    assert.equal(parseFilename('attachment; filename=ordinary.mp4'), 'ordinary.mp4', `${label}: ordinary filename failed`);
    assert.equal(parseFilename('attachment; filename="part;two.mp4"'), 'part;two.mp4', `${label}: quoted semicolon failed`);
    assert.equal(parseFilename(String.raw`attachment; filename="say\"hi.mp4"`), 'say"hi.mp4', `${label}: escaped quote failed`);
    assert.equal(parseFilename(String.raw`attachment; filename="..\\folder\\clip.mp4"`), 'clip.mp4', `${label}: escaped backslash/path sanitization failed`);
    assert.equal(parseFilename('attachment; filename="unsafe\u0000\u0007name.mp4"'), 'unsafename.mp4', `${label}: control characters were not removed`);
    assert.equal(parseFilename('attachment; filename="unterminated.mp4'), undefined, `${label}: unterminated quote should fail closed`);

    const hostile = `attachment; filename="${'\\!'.repeat(1024)}`;
    const started = performance.now();
    assert.equal(parseFilename(hostile), undefined, `${label}: adversarial malformed quote should use a safe fallback`);
    assert.ok(performance.now() - started < 250, `${label}: adversarial filename parsing took too long`);
  }
});

test('executeHttpSkillTool stages oversized skill downloads locally after a validated credentialless fetch', async () => {
  const originalFetch = globalThis.fetch;
  const originalChrome = globalThis.chrome;
  const originalBrowser = globalThis.browser;
  try {
    for (const [label, prefix, executeTool, normalizeSkills, buildRegistry] of [
      ['chrome', 'src/chrome', executeHttpSkillToolCh, normalizeCustomSkillsCh, buildSkillToolRegistryCh],
      ['firefox', 'src/firefox', executeHttpSkillToolFx, normalizeCustomSkillsFx, buildSkillToolRegistryFx],
    ]) {
      const skills = normalizeSkills([packagedFreeSkillzRecord(prefix)]);
      const tool = buildRegistry(skills).get('download_public_media');
      assert.ok(tool, `${label}: download_public_media manifest tool missing`);

      const providerCalls = [];
      const downloadCalls = [];
      const stagedMessages = [];
      const tooLargeBytes = (25 * 1024 * 1024) + 1;
      let fileFetchCount = 0;
      const jsonResponse = (status, body) => ({
        ok: status >= 200 && status < 300,
        status,
        text: async () => JSON.stringify(body),
      });
      const oversizedResponse = (url) => ({
        ok: true,
        status: 200,
        url,
        headers: {
          get(name) {
            const key = String(name || '').toLowerCase();
            if (key === 'content-type') return 'video/mp4';
            if (key === 'content-length') return String(tooLargeBytes);
            if (key === 'content-disposition') return "attachment; filename*=UTF-8''Video%20by%20yaseminserpil.mp4";
            return null;
          },
        },
        arrayBuffer: async () => {
          throw new Error(`${label}: oversized response should not be buffered`);
        },
        body: { cancel: async () => {} },
      });
      const stagedResponse = (url) => ({
        ok: true,
        status: 200,
        url,
        headers: {
          get(name) {
            const key = String(name || '').toLowerCase();
            if (key === 'content-type') return 'video/mp4';
            if (key === 'content-length') return String(tooLargeBytes);
            if (key === 'content-disposition') return "attachment; filename*=UTF-8''Video%20by%20yaseminserpil.mp4";
            return null;
          },
        },
        blob: async () => new Blob([new Uint8Array([1, 2, 3])], { type: 'video/mp4' }),
      });
      globalThis.fetch = async (url, opts = {}) => {
        providerCalls.push({ url, opts });
        if (url === 'https://freeskillz.xyz/v1/media/jobs' && opts.method === 'POST') {
          return jsonResponse(200, { job_id: 'job_oversized' });
        }
        if (url === 'https://freeskillz.xyz/v1/media/jobs/job_oversized' && opts.method === 'GET') {
          return jsonResponse(200, { status: 'complete' });
        }
        if (url === 'https://freeskillz.xyz/v1/media/jobs/job_oversized/file' && opts.method === 'GET') {
          fileFetchCount += 1;
          return fileFetchCount === 1 ? oversizedResponse(url) : stagedResponse(url);
        }
        if (url === 'https://freeskillz.xyz/v1/media/jobs/job_oversized' && opts.method === 'DELETE') {
          return jsonResponse(204, {});
        }
        throw new Error(`unexpected provider call: ${opts.method || 'GET'} ${url}`);
      };

      if (label === 'chrome') {
        delete globalThis.browser;
        globalThis.chrome = {
          runtime: {
            lastError: null,
            sendMessage(message, cb) {
              stagedMessages.push(message);
              if (message.type === 'skill-download-prepare') {
                cb({
                  success: true,
                  status: 200,
                  finalUrl: message.url,
                  localUrl: 'blob:chrome-extension://webbrain/staged-large-video',
                  releaseToken: 'stage-token-1',
                  bytesReceived: tooLargeBytes,
                  contentType: 'video/mp4',
                  contentDisposition: "attachment; filename*=UTF-8''Video%20by%20yaseminserpil.mp4",
                });
                return;
              }
              cb({ success: true, released: true });
            },
          },
          offscreen: {
            async hasDocument() { return true; },
            async createDocument() {},
          },
          downloads: {
            download(opts, cb) {
              downloadCalls.push(opts);
              cb(7801);
            },
            search(_query, cb) {
              cb([{
                id: 7801,
                filename: '/Users/x/Downloads/large.mp4',
                state: 'complete',
                bytesReceived: tooLargeBytes,
                totalBytes: tooLargeBytes,
                url: downloadCalls[0].url,
                finalUrl: downloadCalls[0].url,
              }]);
            },
          },
        };
      } else {
        delete globalThis.chrome;
        globalThis.browser = {
          downloads: {
            async download(opts) {
              downloadCalls.push(opts);
              return 8801;
            },
            async search() {
              return [{
                id: 8801,
                filename: '/Users/x/Downloads/large.mp4',
                state: 'complete',
                bytesReceived: tooLargeBytes,
                totalBytes: tooLargeBytes,
                url: downloadCalls[0].url,
                finalUrl: downloadCalls[0].url,
              }];
            },
          },
        };
      }

      const result = await executeTool(tool, { url: 'https://www.instagram.com/reel/abc/' });
      assert.equal(result.success, true, `${label}: oversized file should use validated local staging`);
      assert.equal(result.status, 200, `${label}: oversized file status missing`);
      assert.equal(result.bytesExpected, tooLargeBytes, `${label}: oversized file length should be reported`);
      assert.equal(result.stagedDownload, true, `${label}: oversized file should identify the staged path`);
      assert.equal(result.contentType, 'video/mp4', `${label}: staged download should preserve the response MIME type`);
      assert.equal(result.suggestedFilename, 'Video by yaseminserpil.mp4', `${label}: staged download should preserve the response filename`);
      assert.equal(result.directDownload, undefined, `${label}: remote direct-download path must stay disabled`);
      assert.equal(result.finalUrl, 'https://freeskillz.xyz/v1/media/jobs/job_oversized/file', `${label}: oversized file URL should be reported`);
      assert.equal(result.cleanup?.success, true, `${label}: provider job should be cleaned up after oversized file`);
      assert.equal(downloadCalls.length, 1, `${label}: browser download should start for oversized file`);
      assert.match(downloadCalls[0].url, /^blob:/, `${label}: browser download should receive only a local blob URL`);
      assert.equal(downloadCalls[0].filename, 'Video by yaseminserpil.mp4', `${label}: browser download should receive the server-provided MP4 filename`);
      assert.deepEqual(
        providerCalls.map(call => `${call.opts.method || 'GET'} ${call.url}`),
        label === 'chrome' ? [
          'POST https://freeskillz.xyz/v1/media/jobs',
          'GET https://freeskillz.xyz/v1/media/jobs/job_oversized',
          'GET https://freeskillz.xyz/v1/media/jobs/job_oversized/file',
          'DELETE https://freeskillz.xyz/v1/media/jobs/job_oversized',
        ] : [
          'POST https://freeskillz.xyz/v1/media/jobs',
          'GET https://freeskillz.xyz/v1/media/jobs/job_oversized',
          'GET https://freeskillz.xyz/v1/media/jobs/job_oversized/file',
          'GET https://freeskillz.xyz/v1/media/jobs/job_oversized/file',
          'DELETE https://freeskillz.xyz/v1/media/jobs/job_oversized',
        ],
        `${label}: oversized file lifecycle mismatch`,
      );
      assert.equal(providerCalls[2].opts.credentials, 'omit', `${label}: oversized file fetch should omit cookies`);
      if (label === 'chrome') {
        assert.equal(stagedMessages[0]?.type, 'skill-download-prepare', 'chrome: large file should be staged in the offscreen document');
        assert.equal(stagedMessages[0]?.expectedUrl, 'https://freeskillz.xyz/v1/media/jobs/job_oversized/file', 'chrome: staging should carry the validated expected URL');
        assert.equal(stagedMessages.at(-1)?.type, 'skill-download-release', 'chrome: staged blob should be released after completion');
      } else {
        assert.equal(providerCalls[3].opts.credentials, 'omit', 'firefox: actual staged fetch should omit cookies');
        assert.equal(providerCalls[3].opts.redirect, 'manual', 'firefox: actual staged fetch should reject redirects');
      }
    }
  } finally {
    if (originalFetch === undefined) delete globalThis.fetch;
    else globalThis.fetch = originalFetch;
    if (originalChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = originalChrome;
    if (originalBrowser === undefined) delete globalThis.browser;
    else globalThis.browser = originalBrowser;
  }
});

test('chrome offscreen staging owns the credentialless fetch and local file lifecycle', () => {
  const source = fs.readFileSync(path.join(ROOT, 'src/chrome/src/offscreen/skill-download.js'), 'utf8');
  const html = fs.readFileSync(path.join(ROOT, 'src/chrome/src/offscreen/offscreen.html'), 'utf8');
  const ensure = fs.readFileSync(path.join(ROOT, 'src/chrome/src/offscreen/ensure.js'), 'utf8');

  assert.match(html, /<script src="skill-download\.js"><\/script>/, 'offscreen page should load the staging handler');
  assert.match(source, /credentials:\s*'omit'/, 'staged remote fetch must omit credentials');
  assert.match(source, /redirect:\s*'manual'/, 'staged remote fetch must reject redirects');
  assert.match(source, /navigator\.storage\.getDirectory\(\)/, 'large downloads should stream through extension-local storage');
  assert.match(source, /new Blob\(\[file\], \{ type: contentType \}\)/, 'staged OPFS files should preserve the response MIME type');
  assert.match(source, /content-disposition/, 'staged downloads should preserve the response filename header');
  assert.match(source, /URL\.createObjectURL\(typedBlob\)/, 'browser download should receive a typed local blob URL');
  assert.match(source, /URL\.revokeObjectURL/, 'local blob URLs should be released after download');
  assert.match(source, /cleanupStaleStages/, 'stale staged files should be removed after an interrupted offscreen lifetime');
  assert.match(ensure, /'BLOBS'/, 'offscreen document should declare its blob URL purpose');
});

test('Emergency Box downloads are hosted off the visible extension page', () => {
  const chromeHtml = fs.readFileSync(path.join(ROOT, 'src/chrome/src/offscreen/offscreen.html'), 'utf8');
  const chromeHost = fs.readFileSync(path.join(ROOT, 'src/chrome/src/offscreen/emergency-download-host.js'), 'utf8');
  const chromeBackground = fs.readFileSync(path.join(ROOT, 'src/chrome/src/background.js'), 'utf8');
  const firefoxBackground = fs.readFileSync(path.join(ROOT, 'src/firefox/src/background.js'), 'utf8');
  const chromeBox = fs.readFileSync(path.join(ROOT, 'src/chrome/src/ui/emergency-box.js'), 'utf8');
  const firefoxBox = fs.readFileSync(path.join(ROOT, 'src/firefox/src/ui/emergency-box.js'), 'utf8');
  assert.match(chromeHtml, /<script type="module" src="emergency-download-host\.js"><\/script>/,
    'chrome: offscreen page should load the Emergency download host');
  assert.match(chromeHost, /createEmergencyDownloadController/,
    'chrome: offscreen host should own Emergency downloads');
  assert.match(chromeBackground, /target: 'offscreen-emergency-download'/,
    'chrome: background should forward Emergency downloads to the offscreen host');
  assert.match(firefoxBackground, /createEmergencyDownloadController/,
    'firefox: the persistent background page should own Emergency downloads');
  for (const [label, source] of [['chrome', chromeBox], ['firefox', firefoxBox]]) {
    assert.doesNotMatch(source, /downloadAndInstallEmergencyCorpus/,
      `${label}: Emergency Box page still runs the text-pack fetch`);
    assert.doesNotMatch(source, /downloadEmergencyResource\(/,
      `${label}: Emergency Box page still runs PDF fetches`);
    assert.match(source, /sendEmergencyDownloadCommand\('start_corpus'\)/,
      `${label}: Emergency Box page does not start the text pack through the background host`);
  }
});

test('executeHttpSkillTool does not require HEAD support for skill downloads', async () => {
  const originalFetch = globalThis.fetch;
  const originalChrome = globalThis.chrome;
  const originalBrowser = globalThis.browser;
  try {
    for (const [label, prefix, executeTool, normalizeSkills, buildRegistry] of [
      ['chrome', 'src/chrome', executeHttpSkillToolCh, normalizeCustomSkillsCh, buildSkillToolRegistryCh],
      ['firefox', 'src/firefox', executeHttpSkillToolFx, normalizeCustomSkillsFx, buildSkillToolRegistryFx],
    ]) {
      const skills = normalizeSkills([packagedFreeSkillzRecord(prefix)]);
      const tool = buildRegistry(skills).get('download_public_media');
      assert.ok(tool, `${label}: download_public_media manifest tool missing`);

      const providerCalls = [];
      const downloadCalls = [];
      const jsonResponse = (status, body) => ({
        ok: status >= 200 && status < 300,
        status,
        text: async () => JSON.stringify(body),
      });
      globalThis.fetch = async (url, opts = {}) => {
        providerCalls.push({ url, opts });
        if (url === 'https://freeskillz.xyz/v1/media/jobs' && opts.method === 'POST') {
          return jsonResponse(200, { job_id: 'job_head_unsupported' });
        }
        if (url === 'https://freeskillz.xyz/v1/media/jobs/job_head_unsupported' && opts.method === 'GET') {
          return jsonResponse(200, { status: 'complete' });
        }
        if (url === 'https://freeskillz.xyz/v1/media/jobs/job_head_unsupported/file' && opts.method === 'GET') {
          return binaryResponse(200, 'head-unsupported-media', 'video/mp4', url);
        }
        if (url === 'https://freeskillz.xyz/v1/media/jobs/job_head_unsupported' && opts.method === 'DELETE') {
          return jsonResponse(204, {});
        }
        throw new Error(`unexpected provider call: ${opts.method || 'GET'} ${url}`);
      };

      if (label === 'chrome') {
        delete globalThis.browser;
        globalThis.chrome = {
          runtime: { lastError: null },
          downloads: {
            download(opts, cb) {
              downloadCalls.push(opts);
              cb(7701);
            },
            search(_query, cb) {
              cb([{
                id: 7701,
                filename: '/Users/x/Downloads/head-unsupported.mp4',
                state: 'complete',
                bytesReceived: 11,
                totalBytes: 11,
                url: 'data:video/mp4;base64,aGVhZC11bnN1cHBvcnRlZC1tZWRpYQ==',
                finalUrl: 'data:video/mp4;base64,aGVhZC11bnN1cHBvcnRlZC1tZWRpYQ==',
              }]);
            },
          },
        };
      } else {
        delete globalThis.chrome;
        globalThis.browser = {
          downloads: {
            async download(opts) {
              downloadCalls.push(opts);
              return 8701;
            },
            async search() {
              return [{
                id: 8701,
                filename: '/Users/x/Downloads/head-unsupported.mp4',
                state: 'complete',
                bytesReceived: 11,
                totalBytes: 11,
                url: 'data:video/mp4;base64,aGVhZC11bnN1cHBvcnRlZC1tZWRpYQ==',
                finalUrl: 'data:video/mp4;base64,aGVhZC11bnN1cHBvcnRlZC1tZWRpYQ==',
              }];
            },
          },
        };
      }

      const result = await executeTool(tool, { url: 'https://www.instagram.com/reel/abc/' });
      assert.equal(result.success, true, `${label}: file download should not require HEAD support`);
      assert.equal(result.downloadId, label === 'chrome' ? 7701 : 8701, `${label}: download id missing`);
      assert.equal(result.cleanup?.success, true, `${label}: provider job should be cleaned up after file download`);
      assert.equal(downloadCalls.length, 1, `${label}: browser download should run once after cookie-free file fetch`);
      assert.match(downloadCalls[0].url, /^data:video\/mp4;base64,/, `${label}: browser download should use fetched data URL`);
      assert.equal(providerCalls.some(call => call.opts.method === 'HEAD'), false, `${label}: skill download should not require HEAD support`);
      assert.deepEqual(
        providerCalls.map(call => `${call.opts.method || 'GET'} ${call.url}`),
        [
          'POST https://freeskillz.xyz/v1/media/jobs',
          'GET https://freeskillz.xyz/v1/media/jobs/job_head_unsupported',
          'GET https://freeskillz.xyz/v1/media/jobs/job_head_unsupported/file',
          'DELETE https://freeskillz.xyz/v1/media/jobs/job_head_unsupported',
        ],
        `${label}: no-HEAD file download lifecycle mismatch`,
      );
    }
  } finally {
    if (originalFetch === undefined) delete globalThis.fetch;
    else globalThis.fetch = originalFetch;
    if (originalChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = originalChrome;
    if (originalBrowser === undefined) delete globalThis.browser;
    else globalThis.browser = originalBrowser;
  }
});

test('executeHttpSkillTool cleans up provider jobs on pre-download failures', async () => {
  const originalFetch = globalThis.fetch;
  const originalChrome = globalThis.chrome;
  const originalBrowser = globalThis.browser;
  try {
    const scenarios = [
      {
        name: 'poll failure',
        jobId: 'job_poll_failure',
        statusResponse: () => ({ status: 500, body: { error: 'poll failed' } }),
        assertResult(result, label) {
          assert.equal(result.status, 500, `${label}: poll failure status missing`);
          assert.match(result.error, /poll failed/i, `${label}: poll failure error missing`);
        },
      },
      {
        name: 'terminal failure',
        jobId: 'job_failed',
        statusResponse: () => ({ status: 200, body: { status: 'failed', error: 'encoding failed' } }),
        assertResult(result, label) {
          assert.equal(result.jobStatus, 'failed', `${label}: terminal job status missing`);
          assert.match(result.error, /encoding failed|failed/i, `${label}: terminal failure error missing`);
          assert.equal(result.executionContext, 'remote_service', `${label}: terminal failure should identify the remote execution context`);
          assert.equal(result.browserLoginAffectsRequest, false, `${label}: browser login must not be presented as affecting the provider request`);
          assert.match(result.retryGuidance || '', /Signing into this browser[\s\S]*will not change/i, `${label}: terminal failure should reject logged-in browser retries`);
        },
      },
      {
        name: 'timeout',
        jobId: 'job_timeout',
        beforeRun(tool) {
          tool.job.timeoutMs = 5;
          tool.job.pollIntervalMs = 1;
        },
        statusResponse: () => ({ status: 200, body: { status: 'running' } }),
        assertResult(result, label) {
          assert.match(result.error, /timed out/i, `${label}: timeout error missing`);
        },
      },
    ];

    for (const scenario of scenarios) {
      for (const [label, prefix, executeTool, normalizeSkills, buildRegistry] of [
        ['chrome', 'src/chrome', executeHttpSkillToolCh, normalizeCustomSkillsCh, buildSkillToolRegistryCh],
        ['firefox', 'src/firefox', executeHttpSkillToolFx, normalizeCustomSkillsFx, buildSkillToolRegistryFx],
      ]) {
        const skills = normalizeSkills([packagedFreeSkillzRecord(prefix)]);
        const tool = buildRegistry(skills).get('download_public_media');
        assert.ok(tool, `${label}: download_public_media manifest tool missing`);
        scenario.beforeRun?.(tool);

        const providerCalls = [];
        const downloadCalls = [];
        const jsonResponse = (status, body) => ({
          ok: status >= 200 && status < 300,
          status,
          text: async () => JSON.stringify(body),
        });
        globalThis.fetch = async (url, opts = {}) => {
          providerCalls.push({ url, opts });
          if (url === 'https://freeskillz.xyz/v1/media/jobs' && opts.method === 'POST') {
            return jsonResponse(200, { job_id: scenario.jobId });
          }
          if (url === `https://freeskillz.xyz/v1/media/jobs/${scenario.jobId}` && opts.method === 'GET') {
            const { status, body } = scenario.statusResponse();
            return jsonResponse(status, body);
          }
          if (url === `https://freeskillz.xyz/v1/media/jobs/${scenario.jobId}` && opts.method === 'DELETE') {
            return jsonResponse(204, {});
          }
          throw new Error(`unexpected provider call: ${opts.method || 'GET'} ${url}`);
        };

        if (label === 'chrome') {
          delete globalThis.browser;
          globalThis.chrome = {
            runtime: { lastError: null },
            downloads: {
              download(opts, cb) {
                downloadCalls.push(opts);
                cb(7501);
              },
            },
          };
        } else {
          delete globalThis.chrome;
          globalThis.browser = {
            downloads: {
              async download(opts) {
                downloadCalls.push(opts);
                return 8501;
              },
            },
          };
        }

        const result = await executeTool(tool, { url: 'https://www.instagram.com/reel/abc/' });
        assert.equal(result.success, false, `${label} ${scenario.name}: pre-download failure should fail`);
        assert.equal(result.jobId, scenario.jobId, `${label} ${scenario.name}: job id missing`);
        assert.equal(result.cleanup?.success, true, `${label} ${scenario.name}: provider cleanup should run`);
        assert.equal(downloadCalls.length, 0, `${label} ${scenario.name}: browser download should not start`);
        assert.equal(providerCalls[0].opts.method, 'POST', `${label} ${scenario.name}: create job should be first`);
        const lastProviderCall = providerCalls.at(-1);
        assert.equal(lastProviderCall.url, `https://freeskillz.xyz/v1/media/jobs/${scenario.jobId}`, `${label} ${scenario.name}: cleanup URL should be last`);
        assert.equal(lastProviderCall.opts.method, 'DELETE', `${label} ${scenario.name}: cleanup method should be DELETE`);
        assert.equal(
          providerCalls.some(call => call.url.endsWith('/file')),
          false,
          `${label} ${scenario.name}: file endpoint should not be requested`,
        );
        scenario.assertResult(result, `${label} ${scenario.name}`);
      }
    }
  } finally {
    if (originalFetch === undefined) delete globalThis.fetch;
    else globalThis.fetch = originalFetch;
    if (originalChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = originalChrome;
    if (originalBrowser === undefined) delete globalThis.browser;
    else globalThis.browser = originalBrowser;
  }
});

test('executeHttpSkillTool rejects blocked skill endpoints before fetching', async () => {
  for (const [label, executeTool] of [
    ['chrome', executeHttpSkillToolCh],
    ['firefox', executeHttpSkillToolFx],
  ]) {
    let calls = 0;
    const originalFetch = globalThis.fetch;
    globalThis.fetch = async () => {
      calls += 1;
      throw new Error(`${label}: blocked skill endpoint should not be fetched`);
    };
    try {
      const loopback = await executeTool({
        name: 'read_internal',
        skillName: 'Example',
        endpoint: 'https://127.0.0.1:8443/skill',
        method: 'GET',
      });
      assert.equal(loopback.success, false, `${label}: loopback endpoint should fail`);
      assert.match(loopback.error, /endpoint is blocked/i, `${label}: loopback endpoint error missing`);
      assert.match(loopback.error, /loopback/i, `${label}: loopback reason missing`);
      assert.equal(loopback.finalUrl, 'https://127.0.0.1:8443/skill', `${label}: loopback final URL missing`);

      const localTld = await executeTool({
        name: 'read_internal',
        skillName: 'Example',
        endpoint: 'https://router.local/skill',
        method: 'POST',
      });
      assert.equal(localTld.success, false, `${label}: .local endpoint should fail`);
      assert.match(localTld.error, /endpoint is blocked/i, `${label}: .local endpoint error missing`);
      assert.match(localTld.error, /router\.local/i, `${label}: .local reason missing`);
      assert.equal(localTld.finalUrl, 'https://router.local/skill', `${label}: .local final URL missing`);
      assert.equal(calls, 0, `${label}: blocked endpoints should not reach fetch`);
    } finally {
      globalThis.fetch = originalFetch;
    }
  }
});

test('executeHttpSkillTool rejects cross-origin redirects before replaying body', async () => {
  for (const [label, executeTool] of [
    ['chrome', executeHttpSkillToolCh],
    ['firefox', executeHttpSkillToolFx],
  ]) {
    const calls = [];
    const originalFetch = globalThis.fetch;
    globalThis.fetch = async (url, opts) => {
      calls.push({ url, opts });
      assert.equal(url, 'https://example.com/skill', `${label}: cross-origin redirect target should not be fetched`);
      return {
        ok: false,
        status: 307,
        url: 'https://example.com/skill',
        headers: {
          get(name) {
            return String(name).toLowerCase() === 'location' ? 'https://collector.example/skill' : null;
          },
        },
        text: async () => {
          throw new Error(`${label}: cross-origin redirect body should not be read`);
        },
      };
    };
    try {
      const result = await executeTool({
        name: 'read_external',
        skillName: 'Example',
        endpoint: 'https://example.com/skill',
        method: 'POST',
        parameters: { type: 'object', properties: { activeTabUrl: { type: 'string' }, query: { type: 'string' } } },
      }, { activeTabUrl: 'https://sensitive.example/path', query: 'private' });
      assert.equal(result.success, false, `${label}: cross-origin redirect should fail`);
      assert.match(result.error, /redirects are not allowed/i, `${label}: redirect error missing`);
      assert.equal(result.finalUrl, 'https://example.com/skill', `${label}: redirect should not expose/follow target URL`);
      assert.equal(calls.length, 1, `${label}: cross-origin redirect target should not be requested`);
      assert.equal(calls[0].opts.method, 'POST', `${label}: setup should exercise body-preserving redirects`);
      assert.match(calls[0].opts.body, /sensitive\.example/, `${label}: setup should include sensitive request body`);
    } finally {
      globalThis.fetch = originalFetch;
    }
  }
});

