test('Emergency Box streams PDFs to resumable local storage and rejects non-PDF responses', async () => {
  function memoryAdapters(initial = new Uint8Array()) {
    const records = new Map();
    let committed = initial.slice();
    return {
      records,
      store: {
        async get(id) { return records.get(id); },
        async put(record) { records.set(record.id, { ...record }); return record; },
        async delete(id) { records.delete(id); },
      },
      storage: {
        async open() { return new Blob([committed], { type: 'application/pdf' }); },
        async size() { return committed.byteLength; },
        async createWriter() {
          let working = committed.slice();
          return {
            async write(position, bytes) {
              const needed = position + bytes.byteLength;
              if (working.byteLength < needed) {
                const expanded = new Uint8Array(needed);
                expanded.set(working);
                working = expanded;
              }
              working.set(bytes, position);
            },
            async truncate(size) { working = working.slice(0, size); },
            async close() { committed = working; },
            async abort() {},
          };
        },
        async delete() { committed = new Uint8Array(); },
      },
      bytes() { return new TextDecoder().decode(committed); },
    };
  }
  const encoder = new TextEncoder();
  const rangedResponse = (body, start, end, total) => new Response(body, {
    status: 206,
    headers: { 'content-range': `bytes ${start}-${end}/${total}` },
  });

  for (const [label, runtime] of [['chrome', EmergencyBoxCh], ['firefox', EmergencyBoxFx]]) {
    const adapters = memoryAdapters();
    const pdf = '%PDF-1.7\nEmergency Box fixture';
    const resource = {
      id: 'fixture-pdf', title: 'Fixture', category: 'health', publisher: 'Fixture Publisher',
      url: 'https://example.test/fixture.pdf', sourceUrl: 'https://example.test/source',
    };
    const ready = await runtime.downloadEmergencyResource(resource, {
      ...adapters,
      fetchImpl: async () => new Response(pdf, { status: 200, headers: { 'content-type': 'application/pdf' } }),
    });
    assert.equal(ready.status, 'ready', `${label}: valid PDF did not become readable`);
    assert.equal(adapters.bytes(), pdf, `${label}: streamed PDF bytes were not preserved`);
    assert.equal(ready.bytesReceived, encoder.encode(pdf).byteLength, `${label}: installed byte count is wrong`);

    const invalid = memoryAdapters();
    await assert.rejects(
      runtime.downloadEmergencyResource({ ...resource, id: 'fixture-html' }, {
        ...invalid,
        fetchImpl: async () => new Response('<html>blocked</html>', { status: 200, headers: { 'content-type': 'text/html' } }),
      }),
      /not a valid PDF/i,
      `${label}: HTML error page was accepted as an emergency PDF`,
    );
    assert.equal(invalid.records.get('fixture-html')?.status, 'error', `${label}: invalid PDF failure was not actionable`);
    assert.equal(invalid.bytes(), '', `${label}: invalid PDF bytes were retained`);

    const partialPdf = '%PDF-resumable-';
    const tail = 'complete';
    const partialBytes = encoder.encode(partialPdf).byteLength;
    const completeBytes = partialBytes + encoder.encode(tail).byteLength;
    const ifRangeValidator = '"fixture-v1"';
    const resumableRecord = id => ({
      id, storageKey: id, url: resource.url, ifRangeValidator,
    });

    const unvalidated = memoryAdapters(encoder.encode(partialPdf));
    const unvalidatedHeaders = [];
    const replacementPdf = '%PDF-restarted-complete';
    const replacementBytes = encoder.encode(replacementPdf).byteLength;
    await runtime.downloadEmergencyResource({ ...resource, id: 'fixture-unvalidated' }, {
      ...unvalidated,
      fetchImpl: async (_url, options) => {
        unvalidatedHeaders.push(options.headers);
        return new Response(replacementPdf, { status: 200, headers: { etag: '"fixture-v2"' } });
      },
    });
    assert.deepEqual(unvalidatedHeaders, [undefined],
      `${label}: an unvalidated partial was resumed without If-Range`);
    assert.equal(unvalidated.bytes(), replacementPdf,
      `${label}: an unvalidated partial was not replaced by the full response`);

    const changedUrl = memoryAdapters(encoder.encode(partialPdf));
    changedUrl.records.set('fixture-changed-url', {
      ...resumableRecord('fixture-changed-url'),
      url: 'https://old.example.test/fixture.pdf',
    });
    const changedUrlHeaders = [];
    await runtime.downloadEmergencyResource({ ...resource, id: 'fixture-changed-url' }, {
      ...changedUrl,
      fetchImpl: async (_url, options) => {
        changedUrlHeaders.push(options.headers);
        return new Response(replacementPdf, { status: 200 });
      },
    });
    assert.deepEqual(changedUrlHeaders, [undefined],
      `${label}: a validator from another PDF URL authorized a range request`);
    assert.equal(changedUrl.bytes(), replacementPdf,
      `${label}: bytes from another PDF URL were retained`);

    const resumed = memoryAdapters(encoder.encode(partialPdf));
    resumed.records.set('fixture-resume', resumableRecord('fixture-resume'));
    const resumeHeaders = [];
    const resumedReady = await runtime.downloadEmergencyResource({ ...resource, id: 'fixture-resume' }, {
      ...resumed,
      fetchImpl: async (_url, options) => {
        resumeHeaders.push(options.headers);
        return rangedResponse(tail, partialBytes, completeBytes - 1, completeBytes);
      },
    });
    assert.deepEqual(resumeHeaders, [{ Range: `bytes=${partialBytes}-`, 'If-Range': ifRangeValidator }],
      `${label}: valid PDF resume did not bind its byte range to the original representation`);
    assert.equal(resumed.bytes(), partialPdf + tail, `${label}: valid PDF range was not appended at its declared offset`);
    assert.equal(resumedReady.status, 'ready', `${label}: valid PDF range did not become ready`);

    const failedReplacement = memoryAdapters(encoder.encode(partialPdf));
    failedReplacement.records.set('fixture-failed-replacement', resumableRecord('fixture-failed-replacement'));
    let failedReplacementCancelled = false;
    await assert.rejects(
      runtime.downloadEmergencyResource({ ...resource, id: 'fixture-failed-replacement' }, {
        ...failedReplacement,
        storage: {
          ...failedReplacement.storage,
          async createWriter() { return {
            async write() {},
            async truncate() { throw new Error('fixture truncate failed'); },
            async close() {},
            async abort() {},
          }; },
        },
        fetchImpl: async () => ({
          ok: true,
          status: 200,
          headers: { get(name) { return name.toLowerCase() === 'etag' ? '"fixture-v2"' : null; } },
          body: { async cancel() { failedReplacementCancelled = true; } },
        }),
      }),
      /truncate failed/i,
      `${label}: a failed full replacement did not surface its truncate error`,
    );
    assert.equal(failedReplacement.records.get('fixture-failed-replacement')?.ifRangeValidator, ifRangeValidator,
      `${label}: a failed full replacement bound stale bytes to the new validator`);
    assert.equal(failedReplacement.bytes(), partialPdf,
      `${label}: a failed full replacement changed the durable partial`);
    assert.equal(failedReplacementCancelled, true,
      `${label}: a failed full replacement kept downloading after its storage error`);

    const restarted = memoryAdapters(encoder.encode(partialPdf));
    restarted.records.set('fixture-restart', resumableRecord('fixture-restart'));
    const restartRanges = [];
    const restartedReady = await runtime.downloadEmergencyResource({ ...resource, id: 'fixture-restart' }, {
      ...restarted,
      fetchImpl: async (_url, options) => {
        restartRanges.push(options.headers?.Range || null);
        if (restartRanges.length === 1) {
          return new Response(tail, {
            status: 206,
            headers: {
              'content-range': `bytes ${partialBytes}-${completeBytes - 1}/${completeBytes}`,
              etag: 'W/"fixture-v2"',
            },
          });
        }
        return new Response(replacementPdf, { status: 200 });
      },
    });
    assert.deepEqual(restartRanges, [`bytes=${partialBytes}-`, null],
      `${label}: a PDF range with a changed validator was not retried without Range`);
    assert.equal(restarted.bytes(), replacementPdf, `${label}: a changed PDF version was appended to stale bytes`);
    assert.equal(restartedReady.status, 'ready', `${label}: full PDF retry did not become ready`);

    const rejectedRetry = memoryAdapters(encoder.encode(partialPdf));
    rejectedRetry.records.set('fixture-rejected-retry', resumableRecord('fixture-rejected-retry'));
    let rejectedRequests = 0;
    await assert.rejects(
      runtime.downloadEmergencyResource({ ...resource, id: 'fixture-rejected-retry' }, {
        ...rejectedRetry,
        fetchImpl: async () => {
          rejectedRequests += 1;
          if (rejectedRequests === 1) {
            return rangedResponse(replacementPdf, 0, replacementBytes - 1, replacementBytes);
          }
          return rangedResponse('misaligned', 1, 10, replacementBytes);
        },
      }),
      /Content-Range/i,
      `${label}: a second mismatched PDF range was accepted`,
    );
    assert.equal(rejectedRequests, 2, `${label}: mismatched PDF range retried more than once`);
    assert.equal(rejectedRetry.bytes(), partialPdf, `${label}: rejected PDF ranges changed the durable partial`);
    assert.equal(rejectedRetry.records.get('fixture-rejected-retry')?.status, 'error',
      `${label}: rejected PDF range did not leave an actionable error`);

    const shortRange = memoryAdapters(encoder.encode(partialPdf));
    shortRange.records.set('fixture-short-range', resumableRecord('fixture-short-range'));
    await assert.rejects(
      runtime.downloadEmergencyResource({ ...resource, id: 'fixture-short-range' }, {
        ...shortRange,
        fetchImpl: async () => rangedResponse('short', partialBytes, completeBytes - 1, completeBytes),
      }),
      /size.*Content-Range/i,
      `${label}: a truncated PDF range was marked ready`,
    );
    assert.equal(shortRange.records.get('fixture-short-range')?.status, 'error',
      `${label}: truncated PDF range did not leave an actionable error`);
    assert.equal(shortRange.bytes(), partialPdf,
      `${label}: truncated PDF range changed the durable partial`);

    const exhaustedRange = memoryAdapters(encoder.encode(partialPdf));
    exhaustedRange.records.set('fixture-exhausted-range', resumableRecord('fixture-exhausted-range'));
    const exhaustedRanges = [];
    await runtime.downloadEmergencyResource({ ...resource, id: 'fixture-exhausted-range' }, {
      ...exhaustedRange,
      fetchImpl: async (_url, options) => {
        exhaustedRanges.push(options.headers?.Range || null);
        if (exhaustedRanges.length === 1) {
          return new Response(null, {
            status: 416,
            headers: { 'content-range': `bytes */${partialBytes}` },
          });
        }
        return new Response(replacementPdf, { status: 200 });
      },
    });
    assert.deepEqual(exhaustedRanges, [`bytes=${partialBytes}-`, null],
      `${label}: exhausted PDF range did not retry as a full download`);
    assert.equal(exhaustedRange.bytes(), replacementPdf,
      `${label}: exhausted PDF range did not recover with the full response`);

    const unexpectedStatus = memoryAdapters(encoder.encode(partialPdf));
    unexpectedStatus.records.set('fixture-unexpected-status', resumableRecord('fixture-unexpected-status'));
    await assert.rejects(
      runtime.downloadEmergencyResource({ ...resource, id: 'fixture-unexpected-status' }, {
        ...unexpectedStatus,
        fetchImpl: async () => new Response(null, { status: 204 }),
      }),
      /unexpected HTTP 204/i,
      `${label}: an empty successful response was accepted as a PDF`,
    );
    assert.equal(unexpectedStatus.bytes(), partialPdf,
      `${label}: an unexpected successful status erased the durable partial`);

    const overlongRange = memoryAdapters(encoder.encode(partialPdf));
    overlongRange.records.set('fixture-overlong-range', resumableRecord('fixture-overlong-range'));
    let rangeReaderCancelled = false;
    const overlongChunks = [encoder.encode('XXXX'), encoder.encode('far-too-long-tail')];
    let overlongChunkIndex = 0;
    await assert.rejects(
      runtime.downloadEmergencyResource({ ...resource, id: 'fixture-overlong-range' }, {
        ...overlongRange,
        fetchImpl: async () => ({
          ok: true,
          status: 206,
          headers: { get(name) {
            return name.toLowerCase() === 'content-range'
              ? `bytes ${partialBytes}-${completeBytes - 1}/${completeBytes}`
              : null;
          } },
          body: { getReader() { return {
            async read() {
              if (overlongChunkIndex >= overlongChunks.length) return { done: true };
              return { done: false, value: overlongChunks[overlongChunkIndex++] };
            },
            async cancel() { rangeReaderCancelled = true; },
          }; } },
        }),
      }),
      /exceeded.*Content-Range/i,
      `${label}: an overlong PDF range was accepted`,
    );
    assert.equal(rangeReaderCancelled, true, `${label}: an overlong PDF response kept streaming`);
    assert.equal(overlongRange.bytes(), partialPdf,
      `${label}: an overlong PDF range changed the durable partial`);
  }
});

test('Emergency Box verifies replacement PDFs before removing stale source bytes', async () => {
  const encoder = new TextEncoder();
  for (const [label, runtime] of [['chrome', EmergencyBoxCh], ['firefox', EmergencyBoxFx]]) {
    const records = new Map([['replacement-pdf', {
      id: 'replacement-pdf', title: 'Replacement PDF', status: 'error',
      storageKey: 'old-source', url: 'https://old.example.test/file.pdf',
    }]]);
    const files = new Map([['old-source', encoder.encode('%PDF-old-partial')]]);
    const deleted = [];
    const storage = {
      async size(key) { return files.get(key)?.byteLength || 0; },
      async open(key) { return new Blob([files.get(key) || new Uint8Array()], { type: 'application/pdf' }); },
      async createWriter(key) {
        let working = (files.get(key) || new Uint8Array()).slice();
        return {
          async write(position, bytes) {
            const needed = position + bytes.byteLength;
            if (working.byteLength < needed) {
              const expanded = new Uint8Array(needed);
              expanded.set(working);
              working = expanded;
            }
            working.set(bytes, position);
          },
          async truncate(size) { working = working.slice(0, size); },
          async close() { files.set(key, working); },
          async abort() {},
        };
      },
      async delete(key) {
        deleted.push({ key, replacementVerified: new TextDecoder().decode(files.get('new-source') || new Uint8Array()).startsWith('%PDF-') });
        files.delete(key);
      },
    };
    const store = {
      async get(id) { return records.get(id); },
      async put(record) { records.set(record.id, { ...record }); return record; },
    };
    const resource = {
      id: 'replacement-pdf', title: 'Replacement PDF', storageKey: 'new-source',
      url: 'https://new.example.test/file.pdf', sourceUrl: 'https://new.example.test/source',
    };
    const ready = await runtime.downloadEmergencyResource(resource, {
      store,
      storage,
      fetchImpl: async () => new Response('%PDF-new-complete', { status: 200 }),
    });
    assert.equal(ready.status, 'ready', `${label}: verified replacement PDF did not become ready`);
    assert.equal(files.has('old-source'), false, `${label}: stale source bytes survived a verified replacement`);
    assert.deepEqual(deleted, [{ key: 'old-source', replacementVerified: true }],
      `${label}: stale source bytes were removed before the replacement verified`);

    records.set('replacement-pdf', {
      id: 'replacement-pdf', title: 'Replacement PDF', status: 'error',
      storageKey: 'old-source', url: 'https://old.example.test/file.pdf',
    });
    files.set('old-source', encoder.encode('%PDF-old-partial'));
    await assert.rejects(
      runtime.downloadEmergencyResource(resource, {
        store,
        storage,
        fetchImpl: async () => new Response('<html>blocked</html>', { status: 200 }),
      }),
      /not a valid PDF/i,
      `${label}: invalid replacement response was accepted`,
    );
    assert.equal(files.has('old-source'), true,
      `${label}: stale source bytes were removed after a failed replacement`);
  }
});

test('Emergency Box commits partial PDF bytes before recording a paused download', async () => {
  for (const [label, runtime] of [['chrome', EmergencyBoxCh], ['firefox', EmergencyBoxFx]]) {
    let committed = new Uint8Array();
    const records = new Map();
    const controller = new AbortController();
    const chunks = [new TextEncoder().encode('%PDF-partial'), new TextEncoder().encode('-ignored')];
    const storage = {
      async size() { return committed.byteLength; },
      async createWriter() {
        let working = committed.slice();
        return {
          async write(position, bytes) {
            const expanded = new Uint8Array(position + bytes.byteLength);
            expanded.set(working);
            expanded.set(bytes, position);
            working = expanded;
          },
          async truncate(size) { working = working.slice(0, size); },
          async close() { committed = working; },
          async abort() {},
        };
      },
    };
    let readIndex = 0;
    const result = await runtime.downloadEmergencyResource({
      id: 'paused-pdf', title: 'Paused PDF', url: 'https://example.test/paused.pdf',
    }, {
      signal: controller.signal,
      storage,
      store: {
        async get(id) { return records.get(id); },
        async put(record) { records.set(record.id, { ...record }); return record; },
      },
      fetchImpl: async () => ({
        ok: true,
        status: 200,
        headers: { get() { return null; } },
        body: { getReader() { return { async read() {
          if (readIndex === 1) controller.abort();
          if (readIndex >= chunks.length) return { done: true };
          return { done: false, value: chunks[readIndex++] };
        } }; } },
      }),
    });

    assert.equal(result.status, 'paused', `${label}: aborted PDF did not become paused`);
    assert.equal(result.bytesReceived, chunks[0].byteLength, `${label}: paused byte count was rolled back`);
    assert.equal(committed.byteLength, chunks[0].byteLength, `${label}: partial PDF transaction was not committed`);
  }
});

test('Emergency Box serializes competing PDF writers and reuses the verified winner', async () => {
  for (const [label, runtime] of [['chrome', EmergencyBoxCh], ['firefox', EmergencyBoxFx]]) {
    const records = new Map();
    let committed = new Uint8Array();
    let writerCount = 0;
    let fetchCount = 0;
    let firstReadStarted;
    let allowFirstFinish;
    const firstReadStartedPromise = new Promise(resolve => { firstReadStarted = resolve; });
    const allowFirstFinishPromise = new Promise(resolve => { allowFirstFinish = resolve; });
    const lockQueues = new Map();
    const lockManager = {
      async request(name, options, task) {
        assert.equal(options.mode, 'exclusive', `${label}: PDF writer lock is not exclusive`);
        const previous = lockQueues.get(name) || Promise.resolve();
        let release;
        const held = new Promise(resolve => { release = resolve; });
        lockQueues.set(name, previous.then(() => held));
        await previous;
        try {
          return await task();
        } finally {
          release();
        }
      },
    };
    const store = {
      async get(id) { return records.get(id); },
      async put(record) { records.set(record.id, { ...record }); return record; },
    };
    const storage = {
      async size() { return committed.byteLength; },
      async open() { return new Blob([committed], { type: 'application/pdf' }); },
      async createWriter() {
        writerCount += 1;
        let working = committed.slice();
        return {
          async write(position, bytes) {
            const expanded = new Uint8Array(Math.max(working.byteLength, position + bytes.byteLength));
            expanded.set(working);
            expanded.set(bytes, position);
            working = expanded;
          },
          async truncate(size) { working = working.slice(0, size); },
          async close() { committed = working; },
          async abort() {},
        };
      },
      async delete() { committed = new Uint8Array(); },
    };
    const pdfBytes = new TextEncoder().encode('%PDF-exclusive-writer');
    let readCount = 0;
    const fetchImpl = async () => {
      fetchCount += 1;
      if (fetchCount > 1) throw new Error('A verified PDF was downloaded twice.');
      return {
        ok: true,
        status: 200,
        headers: { get() { return null; } },
        body: { getReader() { return { async read() {
          if (readCount === 0) {
            readCount += 1;
            firstReadStarted();
            return { done: false, value: pdfBytes };
          }
          await allowFirstFinishPromise;
          return { done: true };
        } }; } },
      };
    };
    const resource = { id: 'exclusive-pdf', title: 'Exclusive PDF', url: 'https://example.test/exclusive.pdf' };
    const first = runtime.downloadEmergencyResource(resource, { store, storage, fetchImpl, lockManager });
    await firstReadStartedPromise;
    const second = runtime.downloadEmergencyResource(resource, { store, storage, fetchImpl, lockManager });
    await Promise.resolve();
    assert.equal(writerCount, 1, `${label}: a competing download opened a second writer`);
    assert.equal(fetchCount, 1, `${label}: a competing download fetched while the writer lock was held`);
    allowFirstFinish();
    const [firstResult, secondResult] = await Promise.all([first, second]);
    assert.equal(firstResult.status, 'ready', `${label}: the lock owner did not finish`);
    assert.equal(secondResult.status, 'ready', `${label}: the waiting download did not reuse the verified PDF`);
    assert.equal(writerCount, 1, `${label}: the verified winner was opened for writing again`);
    assert.equal(fetchCount, 1, `${label}: the verified winner was downloaded again`);
  }
});

test('Emergency PDF ignores stale search and page operations', async () => {
  for (const browser of ['chrome', 'firefox']) {
    const readerSource = fs.readFileSync(path.join(ROOT, `src/${browser}/src/ui/emergency-pdf.js`), 'utf8');
    assert.match(
      readerSource,
      /textSearch\.apply\(result, isCurrent => renderPage\(result\.page, isCurrent\)\)/,
      `${browser}: PDF search navigation does not carry latest-query ownership`,
    );
    assert.match(readerSource,
      /async function renderPage\(targetPageNumber = pageNumber, isCurrent = \(\) => true\)[\s\S]*?sequence !== renderSequence \|\| !isCurrent\(\)[\s\S]*?sequence !== renderSequence \|\| !isCurrent\(\)/,
      `${browser}: PDF rendering can commit after its search loses ownership`);
    assert.match(readerSource,
      /const renderCanvas = document\.createElement\('canvas'\)[\s\S]*?page\.render\(\{ canvasContext: context[\s\S]*?if \(sequence !== renderSequence \|\| !isCurrent\(\)\) return false;[\s\S]*?drawImage\(renderCanvas, 0, 0\)/,
      `${browser}: pending PDF renders can mutate the visible canvas before ownership is confirmed`);
    assert.match(readerSource,
      /function requestPage\(value\) \{\s*cancelPendingResize\(\);\s*textSearch\.cancel\(\);\s*return goToPage\(value\);\s*\}/,
      `${browser}: manual PDF navigation does not supersede a pending text search`);
    assert.match(readerSource,
      /function rerenderRequestedPage\(\) \{\s*cancelPendingResize\(\);\s*return goToPage\(requestedPageNumber\);\s*\}[\s\S]*?resizeTimer = setTimeout\(rerenderRequestedPage, 120\)/,
      `${browser}: PDF view changes can silently revert a pending page request`);
    assert.match(readerSource,
      /if \(result\.error\) \{[\s\S]*?textSearch\.apply\(result, isCurrent => renderPage\(pageNumber, isCurrent\)\)[\s\S]*?throw result\.error/,
      `${browser}: PDF extraction errors do not restore the committed page after cancelling a render`);
    const { createEmergencyPdfTextSearch } = await import(pathToFileURL(path.join(
      ROOT, `src/${browser}/src/ui/emergency-pdf-search.js`,
    )).href);
    const search = createEmergencyPdfTextSearch();
    let releaseOlder;
    const olderPage = new Promise(resolve => { releaseOlder = resolve; });
    const older = search.find('older result', {
      pageNumber: 1,
      numPages: 3,
      pageText: async page => page === 2 ? await olderPage : '',
    });
    const latest = await search.find('latest result', {
      pageNumber: 1,
      numPages: 3,
      pageText: async page => page === 3 ? 'latest result' : '',
    });
    assert.equal(latest.page, 3, `${browser}: latest PDF query did not find its page`);
    assert.equal(search.isCurrent(latest), true, `${browser}: latest PDF query was treated as stale`);

    releaseOlder('older result');
    const stale = await older;
    assert.equal(stale.page, 0, `${browser}: older PDF query remained actionable`);
    assert.equal(search.isCurrent(stale), false, `${browser}: older PDF query could replace the latest result`);

    let rejectOlder;
    const olderFailure = search.find('older failure', {
      pageNumber: 1,
      numPages: 2,
      pageText: async () => await new Promise((_resolve, reject) => { rejectOlder = reject; }),
    });
    const replacement = await search.find('replacement', {
      pageNumber: 1,
      numPages: 2,
      pageText: async () => 'replacement',
    });
    rejectOlder(new Error('stale extraction failure'));
    const staleFailure = await olderFailure;
    assert.equal(search.isCurrent(replacement), true, `${browser}: replacement PDF query lost ownership`);
    assert.equal(search.isCurrent(staleFailure), false, `${browser}: older PDF error could replace current status`);

    const currentFailure = await search.find('current failure', {
      pageNumber: 1,
      numPages: 2,
      pageText: async () => { throw new Error('current extraction failure'); },
    });
    assert.match(currentFailure.error?.message || '', /current extraction failure/,
      `${browser}: current PDF extraction error was swallowed`);
    assert.equal(search.isCurrent(currentFailure), true, `${browser}: current PDF error lost ownership`);

    const navigationResult = await search.find('navigation result', {
      pageNumber: 1,
      numPages: 2,
      pageText: async () => 'navigation result',
    });
    let releaseNavigation;
    const navigationGate = new Promise(resolve => { releaseNavigation = resolve; });
    let staleNavigationCommitted = false;
    const oldNavigation = search.apply(navigationResult, async isCurrent => {
      await navigationGate;
      if (isCurrent()) staleNavigationCommitted = true;
      throw new Error('stale navigation failure');
    });
    const currentResult = await search.find('current result', {
      pageNumber: 1,
      numPages: 2,
      pageText: async () => 'current result',
    });
    releaseNavigation();
    assert.equal(await oldNavigation, false, `${browser}: stale PDF navigation remained actionable`);
    assert.equal(staleNavigationCommitted, false, `${browser}: stale PDF navigation committed UI state`);
    assert.equal(search.isCurrent(currentResult), true, `${browser}: current query lost navigation ownership`);
    assert.equal(await search.apply(currentResult, async () => false), false,
      `${browser}: cancelled PDF render was reported as applied`);

    let releaseCancelledSearch;
    const cancelledSearch = search.find('cancelled by navigation', {
      pageNumber: 1,
      numPages: 2,
      pageText: async () => await new Promise(resolve => { releaseCancelledSearch = resolve; }),
    });
    search.cancel();
    releaseCancelledSearch('cancelled by navigation');
    const cancelledResult = await cancelledSearch;
    assert.equal(search.isCurrent(cancelledResult), false,
      `${browser}: manual navigation did not invalidate the pending PDF search`);

    const runtimeStart = readerSource.indexOf('function updatePageControls()');
    const runtimeEnd = readerSource.indexOf('\n\nasync function initialize(', runtimeStart);
    assert.notEqual(runtimeStart, -1, `${browser}: PDF page controls are missing`);
    assert.notEqual(runtimeEnd, -1, `${browser}: PDF page runtime boundary is missing`);
    const createPageRuntime = Function('state', `
      const elements = state.elements;
      const document = state.document;
      const textSearch = state.textSearch;
      const t = key => key;
      let pdf = state.pdf;
      let pageNumber = 1;
      let requestedPageNumber = 1;
      let scale = 1;
      let fitWidth = false;
      let renderTask = null;
      let renderSequence = 0;
      let pageRequestSequence = 0;
      let resizeTimer = null;
      const textCache = new Map();
      function setStatus(message, kind = '') {
        state.status = { message, kind };
      }
      ${readerSource.slice(runtimeStart, runtimeEnd)}
      return {
        requestPage,
        rerenderRequestedPage,
        findText,
        snapshot() { return { pageNumber, requestedPageNumber, renderSequence, pageRequestSequence }; },
      };
    `);
    const renderTasks = [];
    const visibleCanvas = {
      width: 111,
      height: 222,
      hidden: false,
      marker: 'page 1',
      style: {},
      getContext() {
        return { drawImage: source => { this.marker = source.marker; } };
      },
      setAttribute() {},
    };
    const elements = {
      'page-number': { value: '1' },
      'page-count': { textContent: '2' },
      'previous-page': { disabled: true },
      'next-page': { disabled: false },
      'document-stage': { clientWidth: 800, scrollTo() {} },
      'reader-message': { hidden: true },
      'pdf-canvas': visibleCanvas,
    };
    const runtimeTextSearch = createEmergencyPdfTextSearch();
    const pageRuntimeState = {
      searchCancellations: 0,
      elements,
      textSearch: {
        find: (...args) => runtimeTextSearch.find(...args),
        apply: (...args) => runtimeTextSearch.apply(...args),
        isCurrent: (...args) => runtimeTextSearch.isCurrent(...args),
        cancel() {
          pageRuntimeState.searchCancellations += 1;
          runtimeTextSearch.cancel();
        },
      },
      document: {
        createElement(tagName) {
          assert.equal(tagName, 'canvas', `${browser}: PDF renderer created an unexpected element`);
          const canvas = {
            width: 0,
            height: 0,
            marker: '',
            getContext() { return { canvas }; },
          };
          return canvas;
        },
      },
      pdf: {
        numPages: 3,
        async getPage(number) {
          return {
            getViewport: ({ scale: viewportScale }) => ({ width: 100 * viewportScale, height: 200 * viewportScale }),
            async getTextContent() {
              return { items: [{ str: number === 2 ? 'search needle' : '' }] };
            },
            render({ canvasContext }) {
              let release;
              let fail;
              const promise = new Promise((resolve, reject) => {
                release = () => {
                  canvasContext.canvas.marker = `page ${number}`;
                  resolve();
                };
                fail = reject;
              });
              const task = {
                cancelled: false,
                cancel() { this.cancelled = true; },
                promise,
                release,
                fail,
              };
              renderTasks.push(task);
              return task;
            },
          };
        },
      },
    };
    const pageRuntime = createPageRuntime(pageRuntimeState);
    const forward = pageRuntime.requestPage(2);
    await new Promise(resolve => setImmediate(resolve));
    assert.equal(renderTasks.length, 1, `${browser}: deferred next-page render did not start`);
    assert.equal(visibleCanvas.marker, 'page 1', `${browser}: pending render changed visible PDF pixels`);
    assert.equal(visibleCanvas.width, 111, `${browser}: pending render resized the visible PDF canvas`);

    const resized = pageRuntime.rerenderRequestedPage();
    await new Promise(resolve => setImmediate(resolve));
    assert.equal(renderTasks.length, 2, `${browser}: requested-page resize render did not start`);
    assert.equal(renderTasks[0].cancelled, true, `${browser}: resize did not cancel the superseded page render`);
    renderTasks[0].release();
    assert.equal(await forward, false, `${browser}: pre-resize page render still committed`);
    assert.equal(pageRuntime.snapshot().requestedPageNumber, 2,
      `${browser}: pre-resize render reset the current requested page`);
    assert.equal(visibleCanvas.marker, 'page 1', `${browser}: pre-resize render changed visible PDF pixels`);
    renderTasks[1].release();
    assert.equal(await resized, true, `${browser}: resize did not finish the pending page request`);
    assert.equal(pageRuntime.snapshot().pageNumber, 2,
      `${browser}: resize silently reverted the pending page request`);
    assert.equal(visibleCanvas.marker, 'page 2', `${browser}: resized page request did not commit its pixels`);

    const reset = pageRuntime.requestPage(1);
    await new Promise(resolve => setImmediate(resolve));
    renderTasks[2].release();
    assert.equal(await reset, true, `${browser}: PDF runtime could not reset the committed page`);

    const nextThenPrevious = pageRuntime.requestPage(2);
    await new Promise(resolve => setImmediate(resolve));
    const back = pageRuntime.requestPage(1);
    await new Promise(resolve => setImmediate(resolve));
    assert.equal(renderTasks.length, 5, `${browser}: committed-page restoration render did not start`);
    assert.equal(renderTasks[3].cancelled, true,
      `${browser}: returning to the current page did not cancel stale rendering`);
    assert.equal(visibleCanvas.marker, 'page 1', `${browser}: restoration changed pixels before render completion`);
    renderTasks[4].release();
    assert.equal(await back, true, `${browser}: returning to the committed page was not accepted`);
    renderTasks[3].release();
    assert.equal(await nextThenPrevious, false, `${browser}: superseded next-page render still committed`);
    assert.equal(pageRuntime.snapshot().pageNumber, 1,
      `${browser}: quick next-then-previous navigation ended on the stale page`);
    assert.equal(pageRuntime.snapshot().requestedPageNumber, 1,
      `${browser}: requested PDF page reverted to the stale render`);
    assert.equal(visibleCanvas.marker, 'page 1', `${browser}: stale render replaced the committed PDF pixels`);
    assert.equal(visibleCanvas.width, 100, `${browser}: committed-page restoration used the wrong canvas size`);
    assert.equal(pageRuntimeState.searchCancellations, 4,
      `${browser}: manual PDF navigation did not cancel text-search ownership`);

    const failedSearch = pageRuntime.findText('needle');
    await new Promise(resolve => setImmediate(resolve));
    assert.equal(renderTasks.length, 6, `${browser}: search-result render did not start`);
    renderTasks[5].fail(new Error('search result render failed'));
    await assert.rejects(failedSearch, /search result render failed/,
      `${browser}: current search-result render failure was swallowed`);
    assert.equal(pageRuntime.snapshot().pageNumber, 1,
      `${browser}: failed search-result render changed the committed page`);
    assert.equal(pageRuntime.snapshot().requestedPageNumber, 1,
      `${browser}: failed search-result render left a stale requested page`);
    assert.equal(visibleCanvas.marker, 'page 1',
      `${browser}: failed search-result render changed the committed PDF pixels`);
  }
});

