test('trusted recommended actions preactivate their owning skill for one run', () => {
  for (const [label, prefix, AgentClass] of [['chrome', 'src/chrome', AgentCh], ['firefox', 'src/firefox', AgentFx]]) {
    const agent = new AgentClass({ getActive: () => ({ promptTier: 'full' }) });
    const tabId = label === 'chrome' ? 2321 : 2322;
    agent.setCustomSkills([packagedFreeSkillzRecord(prefix), packagedOtpHelperRecord(prefix)]);
    agent.conversationModes.set(tabId, 'act');
    agent._preactivateRecommendedActionSkill(tabId, { recommendedAction: { tool: 'download_public_media' } }, 'act');
    assert.deepEqual([...agent.activeSkillIds.get(tabId)], ['freeskillz-xyz'], `${label}: recommended action should activate only its owning skill`);
    assert.match(agent._buildSystemPrompt('act', tabId), /FreeSkillz\.xyz/, `${label}: preactivated skill prose missing`);
    assert.doesNotMatch(agent._buildSystemPrompt('act', tabId), /OTP \/ verification-code helper/, `${label}: unrelated skill was preactivated`);
    assert.equal(agent._activeSkillToolForName(tabId, 'download_public_media')?.name, 'download_public_media', `${label}: preactivated tool unavailable`);
    agent._resetActiveSkillsForRun(tabId);
    assert.equal(agent._activeSkillToolForName(tabId, 'download_public_media'), null, `${label}: recommended skill survived the run reset`);
    assert.equal(agent._loadSkillForRun(tabId, { skill_id: 'missing-skill' }).success, false, `${label}: unknown skill should fail closed`);
  }
});

test('Chrome execute_js and page-debugging tools are exposed only in Dev mode', () => {
  const chromePromptTexts = [
    ['ask', SYSTEM_PROMPT_ASK_CH],
    ['act:full', SYSTEM_PROMPT_ACT_CH],
    ['act:mid', SYSTEM_PROMPT_ACT_MID_CH],
    ['act:compact', SYSTEM_PROMPT_ACT_COMPACT_CH],
  ];
  for (const [label, prompt] of chromePromptTexts) {
    assert.doesNotMatch(prompt, /\bexecute_js\b/, `chrome ${label} prompt must not mention execute_js`);
  }

  const normalChromeToolSets = [
    ['ask', getToolsForModeCh('ask')],
    ['act:full', getToolsForModeCh('act')],
    ['act:mid', getToolsForModeCh('act', { tier: 'mid' })],
    ['act:compact', getToolsForModeCh('act', { tier: 'compact' })],
  ];
  const chromeDevTools = ['inject_css', 'remove_injected_css', 'patch_element', 'revert_patch', 'execute_js', 'read_console', 'inspect_network_requests', 'inspect_event_listeners', 'highlight_element'];
  for (const [label, tools] of normalChromeToolSets) {
    const names = tools.map(t => t.function?.name).filter(Boolean);
    for (const name of chromeDevTools) {
      assert.equal(names.includes(name), false, `chrome ${label} tools must not expose ${name}`);
    }
  }
  for (const [label, tools] of [
    ['dev:full', getToolsForModeCh('dev')],
    ['dev:mid', getToolsForModeCh('dev', { tier: 'mid' })],
  ]) {
    const names = tools.map(t => t.function?.name).filter(Boolean);
    for (const name of chromeDevTools) {
      assert.equal(names.includes(name), true, `chrome ${label} tools should expose ${name}`);
    }
  }
  assert.match(SYSTEM_PROMPT_DEV_APPENDIX_CH, /\bexecute_js\b/);
  assert.match(SYSTEM_PROMPT_DEV_APPENDIX_CH, /\binject_css\b/);
  assert.match(SYSTEM_PROMPT_DEV_APPENDIX_CH, /\bpatch_element\b/);
  assert.match(SYSTEM_PROMPT_DEV_APPENDIX_CH, /\binspect_network_requests\b/);
  assert.match(SYSTEM_PROMPT_DEV_APPENDIX_CH, /not available for Compact-tier providers/i);
});

