test('all locales cover English keys and preserve interpolation placeholders', async () => {
  const placeholders = (value) => [...String(value).matchAll(/\{(\w+)\}/g)]
    .map((match) => match[1])
    .sort();

  for (const [label, localeDir] of [
    ['chrome', 'src/chrome/src/ui/locales'],
    ['firefox', 'src/firefox/src/ui/locales'],
  ]) {
    const dir = path.join(ROOT, localeDir);
    const filenames = fs.readdirSync(dir).filter((name) => name.endsWith('.js')).sort();
    const english = (await import('file://' + path.join(dir, 'en.js').replace(/\\/g, '/'))).default;

    for (const filename of filenames) {
      if (filename === 'en.js') continue;
      const dict = (await import('file://' + path.join(dir, filename).replace(/\\/g, '/'))).default;
      const missing = Object.keys(english).filter((key) => !Object.hasOwn(dict, key));
      assert.deepEqual(missing, [], `${label}/${filename}: locale is missing English keys`);

      for (const [key, fallback] of Object.entries(english)) {
        assert.deepEqual(
          placeholders(dict[key]),
          placeholders(fallback),
          `${label}/${filename}: ${key} must preserve interpolation placeholders`,
        );
      }

      // Regression guard (generalized from the zh.js-only check added by PR #2949):
      // 'st.display.openai_ask_streaming.label'/'.desc' had shipped as literal runs of '?' (e.g.
      // "? Ask ????????") in many locales instead of native text. That value contains zero
      // interpolation placeholders (matching its English source), so the placeholder-parity
      // assertion above passes it trivially; this doesNotMatch catches damaged values directly.
      for (const key of ['st.display.openai_ask_streaming.label', 'st.display.openai_ask_streaming.desc']) {
        assert.doesNotMatch(
          String(dict[key]),
          /\?{4,}/,
          `${label}/${filename}: ${key} contains damaged/mojibake placeholder text`,
        );
      }
    }
   }
});

test('Apocalypse Mode translation blocks cover every canonical key with matching placeholders in all 22 locales', async () => {
  const apocalypseCopy = (await import(
    pathToFileURL(path.join(ROOT, 'src/chrome/src/ui/locales/apocalypse-copy.mjs')).href
  )).default;
  const apocalypseTranslations = (await import(
    pathToFileURL(path.join(ROOT, 'src/chrome/src/ui/locales/apocalypse-translations.mjs')).href
  )).default;
  const firefoxCopy = (await import(
    pathToFileURL(path.join(ROOT, 'src/firefox/src/ui/locales/apocalypse-copy.mjs')).href
  )).default;
  const firefoxTranslations = (await import(
    pathToFileURL(path.join(ROOT, 'src/firefox/src/ui/locales/apocalypse-translations.mjs')).href
  )).default;
  const localeCodes = ['es', 'fr', 'tr', 'zh', 'ru', 'uk', 'ar', 'ja', 'ko', 'id', 'th', 'ms', 'tl', 'pl', 'he', 'hi', 'pt', 'vi', 'bn', 'fa', 'nl', 'de'];
  const canonicalKeys = Object.keys(apocalypseCopy);
  const placeholdersIn = (value) => [...new Set(String(value).match(/\{[a-z]+\}/g) || [])].sort();

  assert.deepEqual(firefoxCopy, apocalypseCopy, 'Chrome and Firefox Apocalypse copy must stay mirrored');
  assert.deepEqual(firefoxTranslations, apocalypseTranslations,
    'Chrome and Firefox Apocalypse translations must stay mirrored');

  for (const locale of localeCodes) {
    const block = apocalypseTranslations[locale];
    assert.ok(block, `${locale}: Apocalypse Mode translation block is missing`);
    const blockKeys = Object.keys(block);
    assert.deepEqual(blockKeys.sort(), [...canonicalKeys].sort(),
      `${locale}: Apocalypse Mode key set diverged (${canonicalKeys.length} canonical, ${blockKeys.length} present)`);
    for (const key of canonicalKeys) {
      const translated = block[key];
      assert.equal(typeof translated, 'string', `${locale}: ${key} is not a string`);
      assert.ok(translated.trim(), `${locale}: ${key} is empty`);
      const dropped = placeholdersIn(apocalypseCopy[key]).filter(
        (placeholder) => !placeholdersIn(translated).includes(placeholder),
      );
      assert.deepEqual(dropped, [], `${locale}: ${key} dropped placeholder(s): ${dropped.join(', ')}`);
    }
    for (const key of ['ap.hero.consent', 'ap.vision.auto', 'ap.vision.waiting']) {
      assert.doesNotMatch(block[key], /\?{2,}/, `${locale}: ${key} contains damaged Unicode text`);
    }
  }
});

test('every permission-gate capability has an English verb and a sidepanel fallback', () => {
  for (const [label, Cap, LABEL, prefix] of [
    ['chrome', CapabilityCh, CAPABILITY_LABEL_CH, 'src/chrome'],
    ['firefox', Capability, CAPABILITY_LABEL, 'src/firefox'],
  ]) {
    for (const cap of Object.values(Cap)) {
      const labelText = LABEL[cap];
      assert.equal(typeof labelText, 'string', `${label}: ${cap} missing from CAPABILITY_LABEL`);
      assert.ok(labelText.length > 0, `${label}: ${cap} English verb must not be empty`);
    }
    // The permission prompt must fall back to CAPABILITY_LABEL (not the raw
    // key) when a locale lacks sp.perm.verb.<cap>, so a newly added capability
    // can never render its raw key on the consent prompt.
    const sidepanel = fs.readFileSync(path.join(ROOT, prefix, 'src/ui/sidepanel.js'), 'utf8');
    assert.match(sidepanel, /CAPABILITY_LABEL\[cap\] \|\| cap/, `${label}: sidepanel permission prompt must fall back to CAPABILITY_LABEL`);
  }
});

