test('sidepanel awaits onboarding completion persistence before hiding', () => {
  for (const [label, panelRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    assert.match(
      panel,
      /async function dismissOnboarding\(\) \{[\s\S]*?await (chrome|browser)\.storage\.local\.set\(\{ onboardingComplete: true \}\)\.catch\(\(\) => \{\}\);[\s\S]*?overlay\.classList\.add\('hidden'\);[\s\S]*?\}/,
      `${label}: onboarding completion should persist before the overlay is hidden`,
    );
    assert.match(
      panel,
      /changeLink\.addEventListener\('click', async \(event\) => \{[\s\S]*?await dismissOnboarding\(\);[\s\S]*?\}\);/,
      `${label}: onboarding change link should await completion persistence`,
    );
    assert.match(
      panel,
      /settingsBtn\.addEventListener\('click', async \(\) => \{[\s\S]*?if \(cloudReady\) \{[\s\S]*?await dismissOnboarding\(\);[\s\S]*?return;[\s\S]*?\}[\s\S]*?await dismissOnboarding\(\);[\s\S]*?\}\);/,
      `${label}: onboarding settings flow should await completion persistence before closing`,
    );
    assert.match(
      panel,
      /skipBtn\.addEventListener\('click', async \(\) => \{[\s\S]*?await dismissOnboarding\(\);[\s\S]*?\}\);/,
      `${label}: onboarding skip button should await completion persistence`,
    );
  }
});

test('sidepanel onboarding makes Cloud improvement use an explicit persisted choice', () => {
  for (const [label, prefix, runtime] of [
    ['chrome', 'src/chrome', 'chrome'],
    ['firefox', 'src/firefox', 'browser'],
  ]) {
    const html = fs.readFileSync(path.join(ROOT, prefix, 'src/ui/sidepanel.html'), 'utf8');
    const panel = fs.readFileSync(path.join(ROOT, prefix, 'src/ui/sidepanel.js'), 'utf8');
    const css = fs.readFileSync(path.join(ROOT, prefix, 'styles/sidepanel.css'), 'utf8');
    const background = fs.readFileSync(path.join(ROOT, prefix, 'src/background.js'), 'utf8');

    assert.match(html, /id="ob-help-improve"[\s\S]*?id="ob-help-improve-checkbox" aria-describedby="ob-help-improve-description" checked[\s\S]*?data-i18n="st\.display\.help_improve\.label"[\s\S]*?id="ob-help-improve-description"[\s\S]*?data-i18n-html="st\.display\.help_improve\.desc_html"/, `${label}: final onboarding step should expose the canonical Help Improve checkbox and disclosure`);
    assert.match(panel, /storage\.local\.get\(\['onboardingComplete', 'helpImproveWebBrain'\]\)/, `${label}: onboarding should hydrate completion and privacy state together`);
    assert.match(panel, /persistedHelpImprove = stored\.helpImproveWebBrain !== false/, `${label}: onboarding should preserve the existing default-on preference`);
    assert.match(panel, /await sendToBackground\('set_help_improve_preference', \{ enabled: requestedValue \}\);\s*persistedHelpImprove = requestedValue;\s*if \(cloudReady\) showCloudReady\(\);/, `${label}: a successful privacy retry should restore Cloud status instead of leaving the error visible`);
    assert.match(background, new RegExp(`case 'set_help_improve_preference':[\\s\\S]*?typeof msg\\.enabled !== 'boolean'[\\s\\S]*?await ${runtime}\\.storage\\.local\\.get\\('helpImproveWebBrain'\\)[\\s\\S]*?await ${runtime}\\.storage\\.local\\.set\\(\\{ helpImproveWebBrain: msg\\.enabled \\}\\);[\\s\\S]*?await providerManager\\.load\\(\\);[\\s\\S]*?await ${runtime}\\.storage\\.local\\.set\\(\\{ helpImproveWebBrain: previousEnabled \\}\\)\\.catch\\(\\(\\) => \\{\\}\\)[\\s\\S]*?return \\{ ok: true, enabled: msg\\.enabled \\};`), `${label}: a failed provider reload should roll back the stored privacy preference before the write is treated as failed`);
    assert.match(panel, /catch \(error\) \{[\s\S]*?helpImproveCheckbox\.checked = persistedHelpImprove[\s\S]*?return false;/, `${label}: failed privacy persistence should restore the last saved choice`);
    assert.match(panel, /function showCloudReady\(\) \{[\s\S]*?setHelpImproveVisible\(true\)/, `${label}: the choice should appear when WebBrain Compass is active`);
    assert.match(panel, /function showLocalChoices\(choices\) \{[\s\S]*?setHelpImproveVisible\(false\)/, `${label}: the Cloud-only choice should stay out of local-model setup`);
    assert.match(panel, /function showProviderFallback\([^)]*\) \{[\s\S]*?providerUnknown = statusKey === 'ob\.tokens\.detect_failed'[\s\S]*?setHelpImproveVisible\(providerUnknown\)[\s\S]*?skipBtn\.disabled = !providerUnknown/, `${label}: a failed provider scan should keep Skip gated and show the Cloud disclosure until the active provider is known`);
    assert.match(panel, /async function scanLocalModels\(\) \{[\s\S]*?settingsBtn\.disabled = true;\s*skipBtn\.disabled = true;/, `${label}: Skip should stay disabled until provider detection decides whether the Cloud disclosure applies`);
    for (const outcome of ['showLocalChoices', 'showCloudReady']) {
      assert.match(panel, new RegExp(`function ${outcome}\\([^)]*\\) \\{[\\s\\S]*?skipBtn\\.disabled = false;`), `${label}: ${outcome} should restore Skip after provider detection finishes`);
    }
    assert.match(panel, /if \(cloudReady\) \{[\s\S]*?if \(!await helpImproveSavePromise\.catch\(\(\) => false\)\) return;[\s\S]*?await dismissOnboarding\(\)/, `${label}: Start should not dismiss onboarding before the latest privacy choice is saved`);
    assert.match(panel, /skipBtn\.addEventListener\('click', async \(\) => \{[\s\S]*?if \(!await helpImproveSavePromise\.catch\(\(\) => false\)\) return;[\s\S]*?await dismissOnboarding\(\)/, `${label}: Skip should not dismiss onboarding before the latest privacy choice is saved`);
    assert.match(css, /\.ob-help-improve-control input \{[\s\S]*?accent-color: var\(--accent\)/, `${label}: the privacy choice should remain a recognizable native checkbox`);
    assert.match(css, /\.ob-skip:disabled \{[\s\S]*?cursor: wait;/, `${label}: disabled Skip should communicate that provider detection is still running`);
    assert.match(css, /\.onboarding \{[\s\S]*?overflow-y: auto;/, `${label}: longer localized privacy copy should remain reachable in short panels`);
  }

  const chromeHtml = fs.readFileSync(path.join(ROOT, 'src/chrome/src/ui/sidepanel.html'), 'utf8');
  const firefoxHtml = fs.readFileSync(path.join(ROOT, 'src/firefox/src/ui/sidepanel.html'), 'utf8');
  assert.doesNotMatch(chromeHtml, /class="ob-browser-pin-note"/, 'chrome: the existing real-toolbar coachmark should remain the only pin lesson');
  assert.match(firefoxHtml, /class="ob-browser-pin-note"[^>]*data-i18n="install\.firefox_pin\.body"/, 'firefox: native toolbar pin guidance should move into the sidebar onboarding');
});

test('first install opens a browser-aware panel launcher without fake toolbar controls', async () => {
  for (const [label, prefix, runtime] of [
    ['chrome', 'src/chrome', 'chrome'],
    ['firefox', 'src/firefox', 'browser'],
  ]) {
    const background = fs.readFileSync(path.join(ROOT, prefix, 'src/background.js'), 'utf8');
    const html = fs.readFileSync(path.join(ROOT, prefix, 'src/ui/install.html'), 'utf8');
    const css = fs.readFileSync(path.join(ROOT, prefix, 'src/ui/install.css'), 'utf8');
    const installJs = fs.readFileSync(path.join(ROOT, prefix, 'src/ui/install.js'), 'utf8');
    const installModule = await import(pathToFileURL(path.join(ROOT, prefix, 'src/ui/install.js')).href);

    assert.match(
      background,
      /(?:async )?function showFirstInstallGuide\(details\) \{[\s\S]*?details\?\.reason !== 'install'[\s\S]*?tabs\.create\(\{[\s\S]*?runtime\.getURL\('src\/ui\/install\.html'\)/,
      `${label}: the guide should open only for a genuine first install`,
    );
    assert.match(
      background,
      new RegExp(`${runtime}\\.runtime\\.onInstalled\\.addListener\\(async \\(details\\) => \\{\\s*(?:await )?showFirstInstallGuide\\(details\\);`),
      `${label}: onInstalled should pass install details to the guide gate`,
    );
    assert.match(html, /id="open-panel-button"/, `${label}: install guide should provide a real panel-open action`);
    assert.match(html, /id="install-intro"[^>]*aria-live="polite"/, `${label}: changing install guidance should be announced accessibly`);
    assert.match(html, /id="open-panel-button"[^>]*\sdisabled(?:\s|>)/, `${label}: install CTA should start disabled until hydration binds its click handler`);
    assert.match(
      installJs,
      /openButton\.addEventListener\('click',[\s\S]*?openButton\.disabled = false;/,
      `${label}: install CTA should become interactive only after the click handler is bound`,
    );
    assert.doesNotMatch(html, /toolbar-rehearsal|extension-menu|pin-target|class="next-step"/, `${label}: install guide must not present fake browser controls or a second pinning lesson`);
    assert.match(html, /class="feature-tabs"[^>]*role="tablist"/, `${label}: install guide should expose the showcase as an accessible tab list`);
    assert.doesNotMatch(html, /feature-caption-\w+"[^>]*class="visually-hidden"/, `${label}: showcase explanations should be visible to sighted users`);
    for (const feature of ['ask', 'act', 'model', 'apocalypse']) {
      assert.match(html, new RegExp(`data-feature="${feature}"`), `${label}: ${feature} feature tab missing`);
      assert.match(html, new RegExp(`data-feature-panel="${feature}"`), `${label}: ${feature} feature panel missing`);
      assert.match(html, new RegExp(`id="feature-caption-${feature}" class="feature-copy"`), `${label}: ${feature} showcase copy should overlay the artwork as localizable HTML`);
    }
    assert.match(html, /data-i18n="install\.showcase\.ask\.title"/, `${label}: Ask showcase headline should be localizable`);
    assert.match(html, /data-i18n="install\.showcase\.act\.title"/, `${label}: Act showcase headline should be localizable`);
    assert.match(html, /data-i18n="install\.showcase\.model\.title"/, `${label}: Model showcase headline should be localizable`);
    assert.match(html, /data-i18n="ap\.subtitle"/, `${label}: Apocalypse showcase headline should reuse the existing localized subtitle`);
    for (const asset of [
      '02-tell-the-browser.png',
      '03-ask-any-page.png',
      '04-any-llm.png',
      '08-apocalypse-mode.png',
      'fonts/bricolage-grotesque-var.woff2',
      'fonts/instrument-sans-var.woff2',
      'fonts/geist-mono-var.woff2',
    ]) {
      assert.ok(fs.existsSync(path.join(ROOT, prefix, 'src/ui/install-assets', asset)), `${label}: packaged showcase asset missing: ${asset}`);
    }
    assert.doesNotMatch(html, /06-launch-offer|07-social-proof/, `${label}: first-use showcase should not include pricing or social proof`);
    if (label === 'firefox') {
      assert.match(html, /data-build="firefox"/, 'firefox: the install page should identify its build');
      assert.match(
        installJs,
        /build === 'firefox'[\s\S]*?getElementById\('shortcut-hint'\)\?\.remove\(\)/,
        'firefox: install guidance should remove the undeclared Chromium keyboard shortcut',
      );
    }
    assert.match(css, /@media \(prefers-reduced-motion: reduce\)/, `${label}: install guide should respect reduced motion`);
    assert.match(css, /@media \(max-width: 620px\)/, `${label}: install guide should adapt to narrow windows`);
    assert.match(css, /font-family: "Bricolage Grotesque"/, `${label}: install guide should carry the explainer display typography into the product`);
    assert.match(css, /\.feature-panels \{[\s\S]*?aspect-ratio: 8 \/ 5;/, `${label}: showcase should preserve the explainer artwork without distortion`);
    assert.match(css, /\.feature-copy \{[\s\S]*?position: absolute;/, `${label}: localized showcase copy should overlay the copy-free artwork`);
    assert.match(css, /\.shortcut-hint \{[\s\S]*?font-size: 14px;[\s\S]*?font-weight: 520;/, `${label}: keyboard shortcut guidance should remain comfortably readable`);
    assert.match(css, /kbd \{[\s\S]*?padding: 3px 7px;[\s\S]*?font-size: 11px;[\s\S]*?font-weight: 650;/, `${label}: shortcut keycaps should carry clear visual emphasis`);
    assert.match(css, /\.open-panel-button:disabled/, `${label}: install CTA should visibly communicate its unavailable state`);
    assert.doesNotMatch(css, /\.open-panel-button\.is-open(?:\s|,|\{)/, `${label}: opening the panel should not look like setup completion`);
    assert.doesNotMatch(installJs, /classList\.(?:add|remove)\('is-open'\)/, `${label}: install logic should not apply the retired success-green state`);
    assert.doesNotMatch(installJs, /advanceInstallGuide|install\.pin\.title/, `${label}: opening the panel should not replace the feature showcase with pin instructions`);
    assert.match(
      installJs,
      /Promise\.resolve\(opening\)\.then\(\(\) => \{[\s\S]*?reportInstalledPanelOpened\(\{ build, tabId: installTab\?\.id \}\)[\s\S]*?\}\)\.catch/,
      `${label}: a successful panel open should preserve the showcase while completing background bookkeeping`,
    );
    assert.match(installJs, /\['ArrowLeft', 'ArrowRight', 'Home', 'End'\]/, `${label}: showcase tabs should support standard keyboard navigation`);

    assert.equal(
      await installModule.detectBrowser({ userAgent: 'Mozilla/5.0 Chrome/140.0 Safari/537.36 Edg/140.0' }),
      'edge',
      `${label}: Edge should be detected before generic Chromium`,
    );
    assert.equal(
      await installModule.detectBrowser({ userAgent: 'Mozilla/5.0 Chrome/140.0 Safari/537.36 Vivaldi/7.5' }),
      'vivaldi',
      `${label}: Vivaldi should get its own toolbar guidance`,
    );
    assert.equal(
      await installModule.detectBrowser({ userAgent: 'Mozilla/5.0 Chrome/140.0 Safari/537.36 OPR/121.0' }),
      'opera',
      `${label}: Opera should be detected before generic Chromium`,
    );
    assert.equal(
      await installModule.detectBrowser({ userAgent: 'Mozilla/5.0 Firefox/142.0' }),
      'firefox',
      `${label}: Firefox should get its native toolbar guidance`,
    );
    assert.equal(
      await installModule.detectBrowser({
        userAgent: 'Mozilla/5.0 Chrome/140.0 Safari/537.36',
        brave: { isBrave: async () => true },
      }),
      'brave',
      `${label}: Brave should use its native detection hook`,
    );
    assert.equal(
      await installModule.detectBrowser({
        userAgent: 'Mozilla/5.0',
        userAgentData: { brands: [{ brand: 'Google Chrome', version: '140' }] },
      }),
      'chrome',
      `${label}: UA Client Hints should identify Chrome`,
    );
    assert.equal(
      await installModule.detectBrowser({ userAgent: 'Mozilla/5.0 Chrome/140.0 Safari/537.36' }),
      'chromium',
      `${label}: unidentified Chromium forks should receive safe generic guidance`,
    );
    assert.equal(installModule.getBrowserGuide('firefox').openKey, 'install.open_sidebar', `${label}: Firefox should use native sidebar wording`);
    assert.equal(installModule.getBrowserGuide('firefox').failureKey, 'install.open_failed_firefox', `${label}: Firefox should receive its native recovery instructions`);
    assert.equal(installModule.getBrowserGuide('vivaldi').failureKey, 'install.open_failed_chromium', `${label}: Chromium browsers should receive shortcut and Extensions-menu recovery`);

    const classSet = new Set();
    const featureTabs = ['ask', 'act', 'model', 'apocalypse'].map((feature) => ({
      dataset: { feature },
      classList: { toggle(name, on) { if (on) classSet.add(`${feature}:${name}`); else classSet.delete(`${feature}:${name}`); } },
      setAttribute(name, value) { this[name] = value; },
      tabIndex: feature === 'ask' ? 0 : -1,
    }));
    const featurePanels = ['ask', 'act', 'model', 'apocalypse'].map((feature) => ({
      dataset: { featurePanel: feature },
      hidden: feature !== 'ask',
    }));
    const showcaseDocument = {
      querySelectorAll(selector) {
        return selector === '[data-feature]' ? featureTabs : featurePanels;
      },
    };
    assert.equal(installModule.selectInstallFeature('apocalypse', { documentLike: showcaseDocument }), true, `${label}: Apocalypse Mode should be selectable`);
    assert.equal(featureTabs[3]['aria-selected'], 'true', `${label}: selected feature tab should expose its state`);
    assert.equal(featureTabs[0].tabIndex, -1, `${label}: roving tab stop should leave the old feature`);
    assert.equal(featurePanels[3].hidden, false, `${label}: selected Apocalypse Mode artwork should become visible`);
    assert.equal(featurePanels[0].hidden, true, `${label}: previous feature artwork should be hidden`);

    const calls = [];
    const messages = [];
    if (label === 'chrome') {
      const chromeApi = {
        runtime: {
          sendMessage(message) {
            messages.push(message);
            return Promise.resolve();
          },
        },
        sidePanel: {
          setOptions(options) {
            calls.push(['setOptions', options]);
            return Promise.resolve();
          },
          open(options) {
            calls.push(['open', options]);
            return Promise.resolve();
          },
        },
      };
      await installModule.openInstalledPanel({ build: 'chromium', tabId: 42, chromeApi });
      assert.deepEqual(calls, [
        ['setOptions', { tabId: 42, path: 'src/ui/sidepanel.html', enabled: true }],
        ['open', { tabId: 42 }],
      ], 'chrome: the install-page click should enable and open the real panel in the same turn');
      await installModule.reportInstalledPanelOpened({ build: 'chromium', tabId: 42, chromeApi });
      assert.deepEqual(messages, [
        { type: 'WB_INSTALL_PANEL_OPENED', tabId: 42 },
      ], 'chrome: a successful install-page open should request background panel bookkeeping');
    } else {
      const browserApi = {
        runtime: {
          sendMessage(message) {
            messages.push(message);
            return Promise.resolve();
          },
        },
        sidebarAction: {
          open() {
            calls.push(['open']);
            return Promise.resolve();
          },
        },
      };
      await installModule.openInstalledPanel({ build: 'firefox', browserApi });
      assert.deepEqual(calls, [['open']], 'firefox: the install-page click should open the real sidebar');
      await installModule.reportInstalledPanelOpened({ build: 'firefox', tabId: 42, browserApi });
      assert.deepEqual(messages, [
        { type: 'WB_INSTALL_PANEL_OPENED', tabId: 42 },
      ], 'firefox: a successful install-page open should request background group bookkeeping');
    }
  }

  const explainerRenderer = fs.readFileSync(path.join(ROOT, 'assets/webstore-explainer-2026/render.mjs'), 'utf8');
  assert.match(explainerRenderer, /actScene\(true\), askScene\(true\), modelsScene\(true\), apocalypseScene\(\{ onboarding: true \}\)/, 'install showcase should render dedicated copy-free artwork');
  assert.match(explainerRenderer, /scene\.onboarding[\s\S]*?'install-assets'/, 'copy-free artwork should be written only to extension install assets');
  assert.match(explainerRenderer, /candidate\.onboarding \? `onboarding\/\$\{candidate\.file\}` : candidate\.file/, 'onboarding-only renders should be independently selectable without replacing Web Store screenshots');
  for (const asset of [
    '02-tell-the-browser.png',
    '03-ask-any-page.png',
    '04-any-llm.png',
    '08-apocalypse-mode.png',
  ]) {
    const storeArtwork = fs.readFileSync(path.join(ROOT, 'assets/webstore-explainer-2026', asset));
    const chromeArtwork = fs.readFileSync(path.join(ROOT, 'src/chrome/src/ui/install-assets', asset));
    const firefoxArtwork = fs.readFileSync(path.join(ROOT, 'src/firefox/src/ui/install-assets', asset));
    assert.ok(chromeArtwork.equals(firefoxArtwork), `${asset}: Chrome and Firefox should package the same copy-free artwork`);
    assert.ok(!chromeArtwork.equals(storeArtwork), `${asset}: onboarding artwork must not reuse or replace the English Web Store screenshot`);
  }

  const chromeBackground = fs.readFileSync(path.join(ROOT, 'src/chrome/src/background.js'), 'utf8');
  const firefoxBackground = fs.readFileSync(path.join(ROOT, 'src/firefox/src/background.js'), 'utf8');
  const chromePanelHtml = fs.readFileSync(path.join(ROOT, 'src/chrome/src/ui/sidepanel.html'), 'utf8');
  const chromePanelJs = fs.readFileSync(path.join(ROOT, 'src/chrome/src/ui/sidepanel.js'), 'utf8');
  const chromePanelCss = fs.readFileSync(path.join(ROOT, 'src/chrome/styles/sidepanel.css'), 'utf8');
  const firefoxPanelHtml = fs.readFileSync(path.join(ROOT, 'src/firefox/src/ui/sidepanel.html'), 'utf8');
  assert.match(
    chromeBackground,
    /storage\.local\.set\(\{ pinCoachmarkPending: true \}\)[\s\S]*?tabs\.create\(/,
    'chrome: first install should prepare the pin coachmark before opening the guide tab',
  );
  assert.match(
    chromeBackground,
    /msg\?\.type !== 'WB_INSTALL_PANEL_OPENED'[\s\S]*?senderUrl !== installGuideUrl[\s\S]*?panelTabs\.add\(tab\.id\);[\s\S]*?savePanelTabs\(\);[\s\S]*?ensureWebBrainGroup\(tab\)/,
    'chrome: verified install-page opens should join normal panel and tab-group state',
  );
  assert.match(
    firefoxBackground,
    /msg\?\.type !== 'WB_INSTALL_PANEL_OPENED'[\s\S]*?senderUrl !== installGuideUrl[\s\S]*?ensureWebBrainGroup\(tab\)/,
    'firefox: verified install-page opens should join normal tab-group state',
  );
  assert.match(chromePanelHtml, /data-i18n="install\.pin\.body"/, 'chrome: coachmark should keep its spatial side-panel pin copy');
  assert.match(chromePanelHtml, /id="pin-coachmark"[\s\S]*?aria-modal="true"[\s\S]*?aria-describedby="pin-coachmark-description"/, 'chrome: side panel should expose the first-open coachmark as a described modal dialog');
  assert.match(chromePanelHtml, /id="pin-coachmark-done"[\s\S]*?id="pin-coachmark-skip"/, 'chrome: pin coachmark should provide confirm and explicit skip actions');
  assert.doesNotMatch(firefoxPanelHtml, /id="pin-coachmark"/, 'firefox: sidebar should not point at a Chromium-only panel pin');
  assert.match(chromePanelJs, /sidePanel\?\.getLayout\?\.\(\)/, 'chrome: coachmark should read the real left/right side-panel layout when supported');
  assert.match(chromePanelJs, /await pinCoachmarkDismissed\.catch\(\(\)\s*=>\s*\{\}\);[\s\S]*?storage\.local\.get\(\['onboardingComplete', 'helpImproveWebBrain'\]\)/, 'chrome: product onboarding should wait until the pin coachmark is dismissed before loading setup and privacy state');
  assert.match(chromePanelJs, /initPinCoachmark[\s\S]*?catch\s*\{[\s\S]*?\}[\s\S]*?\}\)\(\)/, 'chrome: pin coachmark setup failures must not reject into onboarding');
  assert.match(chromePanelJs, /for \(const layer of backgroundLayers\) \{[\s\S]*?layer\.inert = true/, 'chrome: modal coachmark should make the rest of the panel inert');
  assert.match(chromePanelJs, /for \(const \[layer, wasInert\] of backgroundInertState\) \{[\s\S]*?layer\.inert = wasInert/, 'chrome: modal coachmark should restore prior inert state on dismissal');
  assert.match(chromePanelJs, /event\.key !== 'Tab'[\s\S]*?event\.shiftKey[\s\S]*?overlay\.contains\(activeElement\)/, 'chrome: modal coachmark should keep forward and reverse tab focus inside the dialog');
  assert.match(chromePanelJs, /doneButton\.addEventListener\('click', dismiss\)/, 'chrome: pin confirmation should dismiss the coachmark');
  assert.match(chromePanelJs, /skipButton\.addEventListener\('click', dismiss\)/, 'chrome: explicit skip should dismiss the coachmark');
  assert.match(chromePanelJs, /event\.key === 'Escape'[\s\S]*?stopImmediatePropagation\(\)[\s\S]*?dismiss\(\)/, 'chrome: Escape should be consumed by the modal and use the same dismissal path');
  assert.match(
    chromePanelCss,
    // The offset is divided by the zoom because the arrow points at the toolbar
    // pin, which sits outside the panel and does not move with the UI scale.
    /\.pin-coachmark-arrow\s*\{[^}]*\bright:\s*calc\(28px \/ var\(--ui-scale-zoom, 1\)\);[^}]*\bleft:\s*auto;[^}]*\btransform:\s*none;/,
    'chrome: the normal right-side panel should point the coachmark arrow at the upper-right pin',
  );
  assert.match(
    chromePanelCss,
    /:root\[data-panel-side="left"\] \.pin-coachmark-arrow\s*\{[^}]*\bleft:\s*calc\(28px \/ var\(--ui-scale-zoom, 1\)\);[^}]*\bright:\s*auto;[^}]*\btransform:\s*scaleX\(-1\);/,
    'chrome: left-side panels should mirror the coachmark arrow toward the upper-left pin',
  );

  const localeFilenames = fs.readdirSync(path.join(ROOT, 'src/chrome/src/ui/locales'))
    .filter((name) => name.endsWith('.js'))
    .sort();
  for (const filename of localeFilenames) {
    const chromeLocale = (await import(pathToFileURL(path.join(ROOT, 'src/chrome/src/ui/locales', filename)).href)).default;
    const firefoxLocale = (await import(pathToFileURL(path.join(ROOT, 'src/firefox/src/ui/locales', filename)).href)).default;
    const installKeys = Object.keys(chromeLocale).filter((key) => key.startsWith('install.'));
    assert.equal(installKeys.length, 35, `${filename}: install guide should translate every user-facing string`);
    assert.ok(chromeLocale['install.showcase.ask.title'], `${filename}: Ask showcase headline should be translated`);
    assert.ok(chromeLocale['install.showcase.apocalypse.body'], `${filename}: Apocalypse showcase body should be translated`);
    assert.ok(chromeLocale['install.pin.confirm'], `${filename}: pin coachmark should translate its confirmation action`);
    assert.ok(chromeLocale['install.pin.skip'], `${filename}: pin coachmark should translate its skip action`);
    assert.ok(chromeLocale['install.open_failed_chromium'], `${filename}: Chromium recovery guidance should be translated`);
    assert.ok(chromeLocale['install.open_failed_firefox'], `${filename}: Firefox recovery guidance should be translated`);
    assert.deepEqual(
      Object.fromEntries(installKeys.map((key) => [key, chromeLocale[key]])),
      Object.fromEntries(installKeys.map((key) => [key, firefoxLocale[key]])),
      `${filename}: install guide translations should match across browser builds`,
    );
  }

  const englishLocale = (await import(pathToFileURL(path.join(ROOT, 'src/chrome/src/ui/locales/en.js')).href)).default;
  assert.match(englishLocale['install.pin.body'], /side panel header/i, 'chrome: pin guidance should identify the pin in the side-panel header');
  assert.match(englishLocale['install.pin.body'], /browser toolbar/i, 'chrome: pin guidance should separately explain the toolbar icon that pinning adds');
  assert.match(englishLocale['install.open_failed_chromium'], /Alt\+Shift\+W[\s\S]*Extensions/i, 'chrome: failed open should offer shortcut and Extensions-menu recovery');
  assert.match(englishLocale['install.open_failed_firefox'], /Firefox Extensions/i, 'firefox: failed open should point to Firefox Extensions');
});

test('chrome /record reports mic denial as a warning, not recording failure', () => {
  const panel = fs.readFileSync(path.join(ROOT, 'src/chrome/src/ui/sidepanel.js'), 'utf8');
  const locale = fs.readFileSync(path.join(ROOT, 'src/chrome/src/ui/locales/en.js'), 'utf8');
  assert.match(panel, /start_tab_recording/, 'chrome: /record should start tab recording through background');
  assert.match(panel, /sp\.record\.mic_unavailable/, 'chrome: /record mic denial should use warning copy');
  assert.match(locale, /sp\.record\.mic_unavailable/, 'chrome: missing mic unavailable locale key');
  assert.match(locale, /Recording started with tab audio and video only/, 'chrome: mic warning should say recording started');
});

test('chrome /record --full-screen shows the recording banner unless explicitly hidden', () => {
  const panel = fs.readFileSync(path.join(ROOT, 'src/chrome/src/ui/sidepanel.js'), 'utf8');
  const firefoxPanel = fs.readFileSync(path.join(ROOT, 'src/firefox/src/ui/sidepanel.js'), 'utf8');
  const manifest = fs.readFileSync(path.join(ROOT, 'src/chrome/manifest.json'), 'utf8');
  const background = fs.readFileSync(path.join(ROOT, 'src/chrome/src/background.js'), 'utf8');
  const host = fs.readFileSync(path.join(ROOT, 'src/chrome/src/recorder/host.js'), 'utf8');
  const offscreen = fs.readFileSync(path.join(ROOT, 'src/chrome/src/offscreen/recorder.js'), 'utf8');
  const locale = fs.readFileSync(path.join(ROOT, 'src/chrome/src/ui/locales/en.js'), 'utf8');

  const slashList = panel.slice(panel.indexOf('const SLASH_COMMANDS = ['), panel.indexOf('function slashCommandIsDiscoverable'));
  assert.match(slashList, /usage: '\/record \[--stop \| --full-screen\] \[--hide-recording-indicator\] \[--transcribe\]'/, 'chrome: slash metadata should advertise /record flags');
  assert.match(slashList, /value: '--stop'[\s\S]*?action: 'stop'[\s\S]*?outOfBand: true/, 'chrome: --stop should remain available while another run is busy');
  assert.match(slashList, /value: '--full-screen'[\s\S]*?action: 'full-screen'/, 'chrome: slash metadata should advertise --full-screen');
  assert.match(slashList, /value: '--hide-recording-indicator'[\s\S]*?requires: '--full-screen'/, 'chrome: hidden indicator should require full-screen capture');
  assert.match(locale, /sp\.slash\.record_full_screen/, 'chrome: missing --full-screen description');
  assert.match(locale, /sp\.slash\.record_hide_indicator[\s\S]*?Escape[\s\S]*?twice/, 'chrome: hidden indicator help should explain double Escape');
  const startedShown = locale.match(/'sp\.record\.full_screen_started_html': '([\s\S]*?)',\n/)?.[1] || '';
  const startedHidden = locale.match(/'sp\.record\.full_screen_started_hidden_html': '([\s\S]*?)',\n/)?.[1] || '';
  assert.match(startedShown, /<strong>Stop<\/strong>[\s\S]*?recording banner/, 'chrome: the default start message should point at the banner Stop button');
  assert.match(startedShown, /<code>--hide-recording-indicator<\/code>/, 'chrome: the default start message should offer the banner opt-out');
  assert.match(startedHidden, /<code>Escape<\/code>[\s\S]*?twice/, 'chrome: the hidden start message should still explain double Escape');
  assert.doesNotMatch(startedHidden, /banner/i, 'chrome: the hidden start message must not reference a banner the user cannot see');
  assert.doesNotMatch(manifest, /"desktopCapture"/, 'chrome: full-screen recording should use getDisplayMedia without desktopCapture permission');

  const fullScreenIdx = panel.indexOf("if (command.value === '/record' && action === 'full-screen')");
  const stopIdx = panel.indexOf("if (command.value === '/record' && action === 'stop')");
  const recordIdx = panel.indexOf("if (command.value === '/record' && action === 'tab')");
  assert.ok(stopIdx >= 0 && fullScreenIdx >= 0 && recordIdx >= 0 && stopIdx < fullScreenIdx && fullScreenIdx < recordIdx, 'chrome: stop and full-screen routes must run before tab recording');
  const stopBody = panel.slice(stopIdx, fullScreenIdx);
  const fullScreenBody = panel.slice(fullScreenIdx, recordIdx);
  const helperStart = panel.indexOf('async function startFullScreenRecording');
  assert.notEqual(helperStart, -1, 'chrome: startFullScreenRecording helper should exist');
  const helperEnd = panel.indexOf('async function sendMessage', helperStart);
  assert.notEqual(helperEnd, -1, 'chrome: sendMessage should follow the full-screen recording helper');
  const helperBody = panel.slice(helperStart, helperEnd);
  assert.match(fullScreenBody, /startFullScreenRecording\(tabId/, 'chrome: parser should route /record --full-screen through helper');
  assert.match(stopBody, /stopRecording\(\{ showAlert: false \}\)[\s\S]*?sp\.record\.error/, 'chrome: /record --stop should reuse the visible Stop path and report errors in chat');
  assert.match(helperBody, /prepare_recording_host/, 'chrome: full-screen route should prepare offscreen before recording');
  assert.match(fullScreenBody, /showBanner:\s*!optionValues\.has\('--hide-recording-indicator'\)/, 'chrome: full-screen route should hide the banner only when explicitly requested');
  assert.match(helperBody, /start_display_recording[\s\S]*?showBanner:\s*recordOptions\.showBanner !== false/, 'chrome: full-screen route should show the recording banner by default');
  assert.match(helperBody, /recordOptions\.showBanner === false\s*\?\s*'sp\.record\.full_screen_started_hidden_html'\s*:\s*'sp\.record\.full_screen_started_html'/, 'chrome: the start message should match whether the banner is actually shown');
  assert.doesNotMatch(helperBody, /streamId/, 'chrome: sidepanel must not ferry a desktopCapture stream id to the recorder');
  assert.match(panel, /function shouldShowRecordingBanner\(state\)[\s\S]*?state\?\.showBanner !== false/, 'chrome: banner visibility should be state-driven');
  assert.match(panel, /async function stopRecording\(options = \{\}\)[\s\S]*?sendToBackground\('stop_tab_recording'\)[\s\S]*?return res;/, 'chrome: button and slash Stop should share one stopping helper');
  assert.match(panel, /const banner = document\.getElementById\('recording-banner'\);[\s\S]*?banner\.parentNode\.insertBefore\(el, banner\.nextSibling\);/, 'chrome: post-recording status should stay beside the independent recording bar');
  assert.match(panel, /optionValues\.has\('--transcribe'\)/, 'chrome: recording slash commands should support transcript opt-in');

  assert.match(background, /prepare_recording_host[\s\S]*?start_display_recording/, 'chrome: background should keep recorder routes for slash commands');
  assert.match(host, /export async function startDisplayRecording\(options = \{\}/, 'chrome: recorder host should expose display recording for slash command routing');
  assert.match(host, /function scheduleRecordingSafetyWatchdog[\s\S]*?chrome\.alarms\?\.create/, 'chrome: hidden recordings should have a background-owned safety cap');
  assert.match(offscreen, /navigator\.mediaDevices\.getDisplayMedia\(\{[\s\S]*?audio: audio !== false,[\s\S]*?video: true,[\s\S]*?\}\)/, 'chrome: offscreen recorder should open the screen/window picker through getDisplayMedia');
  assert.match(offscreen, /function pickRecorderMimeType\(\{ hasVideo, hasAudio, requestedMime \}\)[\s\S]*?'video\/webm;codecs=vp9,opus'[\s\S]*?'video\/webm;codecs=vp9'[\s\S]*?'audio\/webm;codecs=opus'/, 'chrome: recorder should choose MIME after it knows whether the final stream has audio');
  assert.match(offscreen, /const hasAudioSources = capturedAudioTracks\.length > 0 \|\| !!micStream;[\s\S]*?if \(hasAudioSources\) \{[\s\S]*?mixDest = audioContext\.createMediaStreamDestination\(\);[\s\S]*?if \(mixDest\) \{[\s\S]*?mixDest\.stream\.getAudioTracks\(\)/, 'chrome: display video-only recordings should not add an empty WebAudio track');
  assert.match(offscreen, /if \(finalHasAudio\) \{[\s\S]*?recorderOptions\.audioBitsPerSecond = 192_000;[\s\S]*?\}[\s\S]*?if \(finalHasVideo\) \{[\s\S]*?recorderOptions\.videoBitsPerSecond = 2_500_000;/, 'chrome: recorder bitrate hints should match the actual final stream tracks');
  assert.doesNotMatch(offscreen, /chrome\.desktopCapture/, 'chrome: offscreen recorder cannot use extension APIs beyond chrome.runtime');
  assert.match(offscreen, /addEventListener\('ended', \(\) => \{[\s\S]*?if \(!s \|\| s\.stopping \|\| s\.captureEndedCleanupStarted\) return;[\s\S]*?s\.captureEndedCleanupStarted = true;[\s\S]*?finalizeCaptureEnded\(s\)\.catch/, 'chrome: capture-ended cleanup should ignore intentional stop and start-failure teardown');
  assert.match(offscreen, /async function finalizeCaptureEnded\(s\) \{[\s\S]*?s\.stopping = true;[\s\S]*?await waitForRecorderStop\(s\);[\s\S]*?notifyCaptureEnded\(s\);[\s\S]*?await releaseSession\(s\);[\s\S]*?\}/, 'chrome: capture-ended finalize should wait for final recorder data before notifying background');
  assert.match(offscreen, /function waitForRecorderStop\(s\) \{[\s\S]*?if \(s\.stopPromise\) return s\.stopPromise;[\s\S]*?s\.stopPromise = new Promise/, 'chrome: recorder stop waits should share one in-progress stop promise');
  assert.match(offscreen, /let dataEventCount = 0;[\s\S]*?recorder\.ondataavailable = \(e\) => \{[\s\S]*?dataEventCount \+= 1;[\s\S]*?get dataEventCount\(\) \{ return dataEventCount; \}/, 'chrome: recorder should track dataavailable events for finalization');
  assert.match(offscreen, /const onFinalDataAvailable = \(e\) => \{[\s\S]*?finalDataSettled = true;[\s\S]*?maybeFinish\(\);[\s\S]*?\};[\s\S]*?s\.recorder\.addEventListener\('dataavailable', onFinalDataAvailable\)/, 'chrome: recorder stop must wait for final dataavailable before resolving');
  assert.match(offscreen, /timed out waiting for MediaRecorder final data[\s\S]*?\}, 2000\);/, 'chrome: final data fallback should stay short enough for visible stop UI');
  assert.doesNotMatch(offscreen, /s\.recorder\.state === 'inactive'\) (?:return Promise\.resolve|finish\(\))/, 'chrome: inactive recorder state alone must not skip waiting for queued stop/dataavailable events');
  assert.match(offscreen, /try \{[\s\S]*?recorder\.start\(2000\);[\s\S]*?\} catch \(e\) \{[\s\S]*?activeSession\.stopping = true;[\s\S]*?activeSession\.captureEndedCleanupStarted = true;[\s\S]*?await releaseSession\(activeSession\);[\s\S]*?if \(session === activeSession\) session = null;/, 'chrome: recorder startup failure must release capture resources without treating the cleanup as an unexpected capture end');
  assert.match(offscreen, /function notifyCaptureEnded\(s\) \{[\s\S]*?target: 'background'[\s\S]*?action: 'recording_capture_ended'[\s\S]*?tabId: s\.tabId/, 'chrome: capture-ended notify should ask background to persist the stopped recording');
  assert.match(background, /case 'recording_capture_ended':[\s\S]*?stopTabRecording\(\{ reason: 'capture_ended' \}\)/, 'chrome: background should finalize and save recordings when the shared stream ends');
  assert.match(offscreen, /async function releaseSession\(s\) \{[\s\S]*?s\.captureStream = null;[\s\S]*?s\.micStream = null;[\s\S]*?s\.audioContext = null;[\s\S]*?micStream\?\.getTracks/, 'chrome: releaseSession should be idempotent and stop the separately-acquired mic stream');
  assert.match(background, /case 'get_recording_state':[\s\S]*?getRecordingStateFresh\(\{[\s\S]*?beforeFinalizeRecording: loadProvidersForRecordingFinalize,[\s\S]*?\}\)/, 'chrome: get_recording_state should preload providers before finalizing transcribed stopped recordings');
  assert.match(background, /async function loadProvidersForRecordingFinalize\(\) \{[\s\S]*?providerManager\.providers\.size === 0[\s\S]*?await providerManager\.load\(\);[\s\S]*?\}/, 'chrome: recording finalize provider preload should load the provider manager only when empty');
  assert.match(host, /async function beforeRecordingFinalize\(beforeFinalizeRecording\)[\s\S]*?recordingState\?\.transcribeAfter[\s\S]*?await beforeFinalizeRecording\(\)/, 'chrome: recorder host should only preload providers before finalize when transcription was requested');
  assert.match(host, /async function runTranscription[\s\S]*?providerManagerRef\.providers\?\.size === 0[\s\S]*?await providerManagerRef\.load\(\)/, 'chrome: transcription should also lazy-load providers as a fallback');

  const firefoxSlashList = firefoxPanel.slice(firefoxPanel.indexOf('const SLASH_COMMANDS = ['), firefoxPanel.indexOf('function slashCommandIsDiscoverable'));
  assert.match(firefoxSlashList, /value: '\/record'[\s\S]*?unsupported: true/, 'firefox: canonical /record syntax should be recognized as unsupported');
  assert.match(firefoxPanel, /function slashCommandIsDiscoverable\(command\) \{[\s\S]*?command\?\.unsupported !== true/, 'firefox: unsupported recording should stay out of autocomplete and help');
  assert.match(firefoxPanel, /showComposerToast\(t\('sp\.slash\.unsupported'/, 'firefox: unsupported recording should show a local error');
});

test('canonical slash parser handles flags, values, casing, termination, and hard-cutover errors', () => {
  const chrome = loadSlashCommandRuntime('src/chrome/src/ui/sidepanel.js');
  const firefox = loadSlashCommandRuntime('src/firefox/src/ui/sidepanel.js');

  for (const text of [
    '/record --full-screen --transcribe',
    '/record --full-screen --hide-recording-indicator --transcribe',
    '/ReCoRd --TRANSCRIBE --FULL-SCREEN',
  ]) {
    const invocation = chrome.parseSlashInvocation(text);
    assert.equal(invocation.action, 'full-screen', `${text}: should select full-screen recording`);
    assert.equal(invocation.optionValues.has('--full-screen'), true, `${text}: full-screen flag missing`);
    assert.equal(invocation.optionValues.has('--transcribe'), true, `${text}: transcribe flag missing`);
  }
  const hiddenIndicator = chrome.parseSlashInvocation('/record --hide-recording-indicator --full-screen');
  assert.equal(hiddenIndicator.action, 'full-screen', 'hidden indicator should allow flags in either order');
  assert.equal(hiddenIndicator.optionValues.has('--hide-recording-indicator'), true, 'hidden indicator flag missing');
  const stopRecording = chrome.parseSlashInvocation('/ReCoRd --STOP');
  assert.equal(stopRecording.action, 'stop', '/record --stop should select the stop action case-insensitively');
  assert.equal(stopRecording.optionValues.has('--stop'), true, '/record --stop flag missing');
  assert.equal(chrome.slashInvocationIsOutOfBand(stopRecording), true, '/record --stop should remain available while busy');

  const scheduleList = chrome.parseSlashInvocation('  /SCHEDULE   --LIST  ');
  assert.equal(scheduleList.action, 'list');
  assert.equal(chrome.slashInvocationIsOutOfBand(scheduleList), true);
  for (const [label, runtime] of [['chrome', chrome], ['firefox', firefox]]) {
    const foreground = runtime.parseSlashInvocation('/FoReGrOuNd finish the checkout');
    assert.equal(foreground.action, 'enable', `${label}: /foreground should select the compatibility action`);
    assert.equal(foreground.payload, 'finish the checkout', `${label}: /foreground should preserve the task payload`);
    assert.equal(foreground.command.acceptsPayload, true, `${label}: /foreground should accept an inline prompt`);
  }
  for (const command of chrome.SLASH_COMMANDS.filter((item) => !item.unsupported)) {
    const invocation = chrome.parseSlashInvocation(`${command.value} --help`);
    assert.equal(invocation.action, 'help', `${command.value} --help should route to command help`);
    assert.equal(chrome.slashInvocationIsOutOfBand(invocation), true, `${command.value} --help should be available while busy`);
    const detail = chrome.buildSlashCommandDetailHtml(command);
    assert.ok(detail.includes(command.usage), `${command.value} help should include its usage`);
    assert.ok(detail.includes(command.descriptionKey), `${command.value} help should include its /help description`);
  }
  assert.equal(chrome.parseSlashInvocation('/schedule write report --list').payload, 'write report --list', 'flags should stop at the first positional argument');
  assert.equal(chrome.parseSlashInvocation('/schedule -- --list tomorrow').payload, '--list tomorrow', 'explicit -- should terminate option parsing');
  assert.equal(chrome.parseSlashInvocation('/scratchpad --append -- --clear literally').payload, '--clear literally', 'value flags should support explicit -- termination');
  assert.equal(chrome.parseSlashInvocation('/scratchpad --append note --clear').payload, 'note --clear', 'option parsing should stop after a value begins');

  for (const text of [
    '/record --unknown',
    '/record --transcribe --transcribe',
    '/record --hide-recording-indicator',
    '/record --stop --full-screen',
    '/record --transcribe --stop',
    '/record --stop --hide-recording-indicator --full-screen',
    '/scratchpad --append',
    '/memory --forget',
    '/scratchpad --append --clear',
    '/schedule --help extra',
    '/schedule --help --list',
    '/schedule --list --help',
    '/screenshot trailing text',
  ]) {
    assert.equal(chrome.parseSlashInvocation(text).error, 'invalid-usage', `${text}: should be rejected locally`);
  }

  const retired = [
    '/list-schedules',
    '/record-full-screen',
    '/full-page-screenshot',
    '/export-with-traces',
    '/show-scratchpad',
    '/edit-scratchpad note',
    '/clear-scratchpad',
    '/show-memory',
    '/remember note',
    '/forget-memory id',
    '/check-progress',
  ];
  for (const text of retired) {
    assert.equal(chrome.parseSlashInvocation(text).error, 'unknown-command', `${text}: retired syntax must not execute`);
  }

  const chromeHelp = chrome.buildSlashCommandHelpHtml();
  for (const command of chrome.SLASH_COMMANDS.filter((item) => !item.unsupported)) {
    assert.ok(chromeHelp.includes(command.usage), `Chrome help should include ${command.usage}`);
    for (const option of (command.options || []).filter((item) => !item.unsupported)) {
      const optionUsage = `${option.value}${option.valueLabel ? ` ${option.valueLabel}` : ''}`;
      assert.ok(chromeHelp.includes(optionUsage), `Chrome help should describe ${optionUsage}`);
      assert.ok(chromeHelp.includes(option.descriptionKey), `Chrome help should localize ${optionUsage}`);
    }
  }
  for (const text of retired) {
    assert.ok(!chromeHelp.includes(text.split(' ')[0]), `Chrome help must omit retired syntax ${text}`);
  }

  assert.equal(firefox.parseSlashInvocation('/record --full-screen --transcribe').unsupported, true, 'Firefox should reject canonical recording locally');
  assert.equal(firefox.parseSlashInvocation('/screenshot --full-page').unsupported, true, 'Firefox should reject the unsupported canonical screenshot flag locally');
  assert.equal(firefox.SLASH_COMMANDS.find((command) => command.value === '/record').unsupported, true, 'Firefox recording should be hidden from discovery');
  const firefoxHelp = firefox.buildSlashCommandHelpHtml();
  assert.doesNotMatch(firefoxHelp, /\/record/, 'Firefox help should omit unsupported recording');
  assert.doesNotMatch(firefoxHelp, /--full-page/, 'Firefox help should omit the unsupported full-page flag');
  const firefoxEnglish = fs.readFileSync(path.join(ROOT, 'src/firefox/src/ui/locales/en.js'), 'utf8');
  assert.doesNotMatch(firefoxEnglish, /Stop an active recording/, 'Firefox help shortcuts should not advertise unsupported recording');

  for (const [label, panelRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    assert.match(panel, /if \(action === 'help'\) \{[\s\S]*?addPersistentSlashMessage\(systemHtml\(buildSlashCommandDetailHtml\(command\)\)\);[\s\S]*?return '';[\s\S]*?\}/, `${label}: command help should be posted as a persistent chat response`);
    assert.match(panel, /function activateSlashCommandBaseAction\(index = slashCommandSelectedIndex\) \{[\s\S]*?match\?\.kind !== 'base-action'[\s\S]*?hideSlashCommandAutocomplete\(\);[\s\S]*?void sendMessage\(\);[\s\S]*?return true;/, `${label}: the base-action row should close autocomplete and execute the exact command`);
    assert.match(panel, /if \(match\?\.kind === 'base-action'\) \{[\s\S]*?e\.preventDefault\(\);[\s\S]*?return activateSlashCommandBaseAction\(\);/, `${label}: Enter should run the selected base-action row`);
    assert.match(panel, /if \(e\.key === 'Enter'\) \{[\s\S]*?const match = slashCommandMatches\[slashCommandSelectedIndex\];[\s\S]*?match\?\.kind === 'option'[\s\S]*?applySlashCommandCompletion\(\)/, `${label}: Enter should accept an option suggestion before submitting the parent command`);
    assert.match(panel, /if \(e\.key === 'Tab'\) \{[\s\S]*?const completionIndex =[\s\S]*?if \(!slashCommandMatches\[completionIndex\]\) return false;\s*e\.preventDefault\(\);[\s\S]*?applySlashCommandCompletion\(completionIndex\);/, `${label}: Tab should retain its default focus behavior when the Enter row is the only match`);
  }
});

test('/foreground is a run-scoped compatibility override in both local builds', () => {
  for (const [label, panelRel, backgroundRel, apiName] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js', 'src/chrome/src/background.js', 'chrome'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js', 'src/firefox/src/background.js', 'browser'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    const background = fs.readFileSync(path.join(ROOT, backgroundRel), 'utf8');

    assert.match(panel, /const foregroundForSend = retryOptions[\s\S]*?\^\\\/foreground\\b/i,
      `${label}: send flow should recognize /foreground before slash parsing`);
    assert.match(panel, /foreground: foregroundForSend,[\s\S]*?sendRunWithReconnect\('chat_start',[\s\S]*?foreground: foregroundForSend,/,
      `${label}: fresh runs and retries should carry the foreground bit`);
    assert.match(panel, /case 'max_steps_reached':[\s\S]*?showContinueButton\(\{ foreground: retryPayload\?\.foreground === true \}\)/,
      `${label}: max-step continuations should inherit foreground mode`);
    assert.match(panel, /function showContinueButton\(options = \{\}\)[\s\S]*?continueBtn\.dataset\.foreground[\s\S]*?continueAgent\(\{[\s\S]*?foreground:/,
      `${label}: persisted Continue buttons should retain foreground mode`);
    assert.match(panel, /async function continueAgent\(options = \{\}\)[\s\S]*?const foregroundForSend = options\?\.foreground === true;[\s\S]*?dataset\.retryForeground = foregroundForSend[\s\S]*?sendRunWithReconnect\('continue_start',[\s\S]*?foreground: foregroundForSend,/,
      `${label}: continuation runs should forward and retain foreground mode`);
    assert.match(panel, /async function adoptRestoredRunState\([\s\S]*?sendRunWithReconnect\('continue_start', \{[\s\S]*?foreground: runUi\.foreground === true,/,
      `${label}: remounted runs should recover foreground mode from the durable journal`);
    assert.match(panel, /async function applyActiveRunState\([\s\S]*?dataset\.retryForeground = runUi\.foreground === true/,
      `${label}: replayed max-step events should rebuild foreground continuation state`);
    assert.match(background, new RegExp(
      `async function activateForegroundCompatibilityTab\\(tabId\\)[\\s\\S]*?${apiName}\\.tabs\\.update\\(tabId, \\{ active: true \\}\\)[\\s\\S]*?${apiName}\\.windows\\.update\\(tab\\.windowId, \\{ focused: true \\}\\)`,
    ), `${label}: compatibility mode should activate the run tab and focus its window`);
    assert.match(background, /if \(msg\.foreground\) await activateForegroundCompatibilityTab\(tabId\);[\s\S]*?\.\.\.\(msg\.foreground \? \{ foreground: true \} : \{\}\)/,
      `${label}: background dispatch should scope foreground behavior to the requested run`);
    assert.match(background, /case 'continue':[\s\S]*?foreground: msg\.foreground === true,[\s\S]*?agent\.continueProcessing\([\s\S]*?\.\.\.\(msg\.foreground \? \{ foreground: true \} : \{\}\)/,
      `${label}: background continuations should persist foreground mode and configure the agent`);

    for (const [caseName, nextCaseName] of [
      ['chat', 'chat_stream'],
      ['chat_stream', 'continue'],
      ['continue', 'clear_conversation'],
    ]) {
      const start = background.indexOf(`case '${caseName}': {`);
      const end = background.indexOf(`case '${nextCaseName}': {`, start);
      const body = background.slice(start, end);
      const tryIndex = body.indexOf('try {');
      const activationIndex = body.indexOf('await activateForegroundCompatibilityTab(tabId)');
      const finallyIndex = body.lastIndexOf('finally {');
      const releaseIndex = body.lastIndexOf('releaseRunKeepalive();');
      assert.ok(start >= 0 && end > start, `${label}: ${caseName} handler should be extractable`);
      assert.ok(tryIndex >= 0 && activationIndex > tryIndex,
        `${label}: ${caseName} activation failures should enter run cleanup`);
      assert.ok(finallyIndex > activationIndex && releaseIndex > finallyIndex,
        `${label}: ${caseName} should release its keepalive after activation failures`);
    }
  }
});

test('hidden trailing run-capture suffixes wrap normal prompts without entering slash help', () => {
  for (const [label, panelRel, backgroundRel, captureRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js', 'src/chrome/src/background.js', 'src/chrome/src/run-capture.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js', 'src/firefox/src/background.js', 'src/firefox/src/run-capture.js'],
  ]) {
    const runtime = loadSlashCommandRuntime(panelRel);

    assert.deepEqual(
      runtime.parseTrailingRunCaptureDirective('Update the checkout form /record'),
      { kind: 'record', prompt: 'Update the checkout form', saveAs: null },
      `${label}: /record suffix should be stripped from a normal prompt`,
    );
    assert.deepEqual(
      runtime.parseTrailingRunCaptureDirective('Test the menu\n/screenshot --save-as "menu state.png"'),
      { kind: 'screenshot', prompt: 'Test the menu', saveAs: 'menu state.png' },
      `${label}: quoted screenshot filename should be parsed`,
    );
    assert.deepEqual(
      runtime.parseTrailingRunCaptureDirective('/act fix it /record --SAVE-AS ../demo.webm'),
      { kind: 'record', prompt: '/act fix it', saveAs: '../demo.webm' },
      `${label}: suffix parsing should preserve a leading mode command and parse flags case-insensitively`,
    );
    assert.equal(runtime.parseTrailingRunCaptureDirective('/record'), null, `${label}: standalone /record must keep its existing behavior`);
    assert.equal(runtime.parseTrailingRunCaptureDirective('/screenshot'), null, `${label}: standalone /screenshot must keep its existing behavior`);
    assert.equal(runtime.parseTrailingRunCaptureDirective('Explain /record --unknown'), null, `${label}: invalid prose-like suffixes must remain normal prompt text`);
    assert.equal(runtime.parseTrailingRunCaptureDirective('Do it /recording'), null, `${label}: longer slash words must not match /record`);
    assert.equal(runtime.parseTrailingRunCaptureDirective('Do it /record --save-as').error, 'missing-save-as', `${label}: missing recording filename should fail locally`);
    assert.equal(runtime.parseTrailingRunCaptureDirective('Do it /screenshot --save-as "unterminated.png').error, 'invalid-save-as', `${label}: unmatched filename quotes should fail locally`);

    assert.equal(runtime.buildRunRecordingFilename('../demo.webm'), 'demo.webm', `${label}: recording save-as should be basename-only`);
    assert.deepEqual(
      runtime.buildRunScreenshotFilenames('../menu state.png', new Date('2026-07-16T12:34:56Z')),
      { before: 'menu state-before.png', after: 'menu state-after.png' },
      `${label}: screenshot save-as should generate paired before/after names`,
    );
    assert.deepEqual(
      runtime.buildRunScreenshotFilenames(null, new Date('2026-07-16T12:34:56Z')),
      {
        before: 'webbrain-run-2026-07-16_12-34-56-before.png',
        after: 'webbrain-run-2026-07-16_12-34-56-after.png',
      },
      `${label}: unnamed screenshots should receive a shared timestamp`,
    );
    assert.doesNotMatch(runtime.buildSlashCommandHelpHtml(), /--save-as/, `${label}: hidden suffix flag must stay out of /help`);

    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    const sendMatch = panel.match(/async function sendMessage\(extraChatParams(?: = \{\})?\) \{[\s\S]*?\n  return accepted;\n\}/);
    assert.ok(sendMatch, `${label}: sendMessage missing`);
    const sendBody = sendMatch[0];
    const parseIdx = sendBody.indexOf('parseTrailingRunCaptureDirective(text)');
    const chatIdx = sendBody.indexOf("sendRunWithReconnect('chat_start'");
    assert.ok(parseIdx >= 0 && chatIdx > parseIdx, `${label}: capture suffix should be parsed before chat dispatch`);
    assert.match(sendBody, /runCapture: \{[\s\S]*?kind: runCaptureDirective\.kind,[\s\S]*?saveAs: runCaptureDirective\.saveAs/, `${label}: chat dispatch should transfer capture ownership to background`);
    assert.doesNotMatch(sendBody, /startTrailingRunCapture|finishTrailingRunCapture/, `${label}: side panel lifecycle must not own capture start or finalization`);

    const background = fs.readFileSync(path.join(ROOT, backgroundRel), 'utf8');
    const chatMatch = background.match(/case 'chat': \{[\s\S]*?\n    \}\n\n    case 'chat_stream':/);
    assert.ok(chatMatch, `${label}: background chat handler missing`);
    const chatBody = chatMatch[0];
    const startIdx = chatBody.indexOf('runCaptureController.start(msg.runCapture, tabId)');
    const agentIdx = chatBody.indexOf('agent.processMessage(');
    const finishIdx = chatBody.indexOf('runCaptureController.finish(runCaptureState, tabId)');
    assert.ok(startIdx >= 0 && agentIdx > startIdx, `${label}: background should start capture before the agent run`);
    assert.ok(finishIdx > agentIdx && chatBody.slice(chatBody.indexOf('} finally {')).includes('runCaptureController.finish'), `${label}: background finally should finalize capture after the agent run`);

    const capture = fs.readFileSync(path.join(ROOT, captureRel), 'utf8');
    assert.match(capture, /api\.downloads\.download\(\{[\s\S]*?filename,[\s\S]*?conflictAction: 'uniquify'/, `${label}: background-owned screenshots should save through Downloads`);
  }

  const background = fs.readFileSync(path.join(ROOT, 'src/chrome/src/background.js'), 'utf8');
  const firefoxBackground = fs.readFileSync(path.join(ROOT, 'src/firefox/src/background.js'), 'utf8');
  const capture = fs.readFileSync(path.join(ROOT, 'src/chrome/src/run-capture.js'), 'utf8');
  const host = fs.readFileSync(path.join(ROOT, 'src/chrome/src/recorder/host.js'), 'utf8');
  assert.match(capture, /startRecording\(tabId, \{[\s\S]*?filename: buildRunRecordingFilename\(directive\.saveAs\)/, 'chrome: trailing /record should pass the requested filename to the recorder');
  assert.match(firefoxBackground, /unsupportedRecordingMessage: 'Tab recording is not supported in Firefox\.'/i, 'firefox: unsupported trailing recording should fail before the run');
  assert.match(capture, /stopRecording\(\{ expectedRecordingId: state\.recordingId \}\)/, 'chrome: automatic cleanup should scope stop to the recording it started');
  assert.match(host, /recordingId:[\s\S]*?filename: normalizeRecordingFilename\(options\.filename\)/, 'chrome: recorder state should persist the custom filename and session identity');
  assert.match(host, /opts\.expectedRecordingId[\s\S]*?reason: 'different-recording'/, 'chrome: run cleanup must not stop a newer recording');
  assert.match(host, /if \(opts\.expectedRecordingId\) return \{ ok: true, alreadyStopped: true \};[\s\S]*?broadcast\('stopped'/, 'chrome: scoped cleanup after a manual stop should not overwrite the saved recording result');
  assert.match(host, /const filename = recordingState\.filename \|\| `webbrain-recording-\$\{stamp\}\.webm`;/, 'chrome: custom filename should override only the default timestamped recording name');
});

test('run screenshot capture keeps Firefox backgrounded while Chrome retains its diagnostic activation path', async () => {
  for (const [label, captureRel] of [
    ['chrome', 'src/chrome/src/run-capture.js'],
    ['firefox', 'src/firefox/src/run-capture.js'],
  ]) {
    let tab = { id: 42, windowId: 7, active: false };
    const updates = [];
    const captures = [];
    const downloads = [];
    const api = {
      tabs: {
        get: async (tabId) => ({ ...tab, id: tabId }),
        update: async (tabId, changes) => {
          updates.push({ tabId, changes });
          tab = { ...tab, ...changes, id: tabId };
          return { ...tab };
        },
        captureVisibleTab: async (windowId, options) => {
          captures.push({ windowId, options });
          return 'data:image/png;base64,capture';
        },
        captureTab: async (tabId, options) => {
          captures.push({ tabId, options });
          return 'data:image/png;base64,capture';
        },
      },
      downloads: {
        download: async (options) => {
          downloads.push(options);
          return 99;
        },
        search: async ({ id }) => [{
          id,
          filename: `/Users/test/Downloads/WebBrain/${downloads.at(-1).filename}`,
          state: 'complete',
        }],
      },
    };
    const runtime = await loadRunCaptureRuntime(captureRel);
    const result = await runtime.captureAndSaveRunScreenshot(api, 42, 'run-after.png');

    if (label === 'chrome') {
      assert.deepEqual(updates, [{ tabId: 42, changes: { active: true } }], 'chrome: diagnostic capture should retain its existing activation path');
      assert.deepEqual(captures, [{ windowId: 7, options: { format: 'png' } }], 'chrome: diagnostic capture should use the activated tab window');
    } else {
      assert.deepEqual(updates, [], 'firefox: inactive run tab should not be activated for capture');
      assert.deepEqual(captures, [{ tabId: 42, options: { format: 'png' } }], 'firefox: capture should target the run tab directly');
    }
    assert.equal(downloads[0].filename, 'run-after.png', `${label}: after screenshot should be saved under the requested filename`);
    assert.deepEqual(result, {
      filename: '/Users/test/Downloads/WebBrain/run-after.png',
      downloadId: 99,
      state: 'complete',
    });
  }
});

test('saved download results wait for completion and expose the browser-resolved absolute path', async () => {
  for (const [label, resultRel] of [
    ['chrome', 'src/chrome/src/download-result.js'],
    ['firefox', 'src/firefox/src/download-result.js'],
  ]) {
    const runtime = await loadDownloadResultRuntime(resultRel);
    let clock = 0;
    let searches = 0;
    const api = {
      downloads: {
        async search({ id }) {
          searches += 1;
          if (searches === 1) {
            return [{ id, filename: '/Users/test/Downloads/WebBrain/report.pdf', state: 'in_progress' }];
          }
          return [{ id, filename: '/Users/test/Downloads/WebBrain/report (1).pdf', state: 'complete' }];
        },
      },
    };

    const result = await runtime.resolveSavedDownload(api, 73, {
      timeoutMs: 10,
      pollMs: 0,
      now: () => clock,
      wait: async () => { clock += 1; },
    });

    assert.deepEqual(result, {
      downloadId: 73,
      filename: '/Users/test/Downloads/WebBrain/report (1).pdf',
      state: 'complete',
    }, `${label}: should return the completed browser path, including conflict renames`);
    assert.equal(searches, 2, `${label}: should not report an in-progress download as saved`);
  }
});

test('saved download results reject interrupted and timed-out saves', async () => {
  for (const [label, resultRel] of [
    ['chrome', 'src/chrome/src/download-result.js'],
    ['firefox', 'src/firefox/src/download-result.js'],
  ]) {
    const runtime = await loadDownloadResultRuntime(resultRel);
    await assert.rejects(
      runtime.resolveSavedDownload({
        downloads: {
          async search() {
            return [{ id: 74, state: 'interrupted', error: 'USER_CANCELED' }];
          },
        },
      }, 74),
      /Download #74 was interrupted: USER_CANCELED/,
      `${label}: interrupted downloads must not be reported as saved`,
    );

    let clock = 0;
    await assert.rejects(
      runtime.resolveSavedDownload({
        downloads: {
          async search() {
            return [{
              id: 75,
              filename: '/Users/test/Downloads/WebBrain/large-recording.webm',
              state: 'in_progress',
            }];
          },
        },
      }, 75, {
        timeoutMs: 1,
        pollMs: 0,
        now: () => clock,
        wait: async () => { clock += 1; },
      }),
      /Download #75 did not complete within 1ms \(last state: in_progress\)/,
      `${label}: timed-out downloads must not be reported as saved`,
    );
  }
});

test('WebBrain save surfaces report completed paths while durable download context stays id-only', async () => {
  for (const [label, prefix] of [
    ['chrome', 'src/chrome'],
    ['firefox', 'src/firefox'],
  ]) {
    const agent = fs.readFileSync(path.join(ROOT, prefix, 'src/agent/agent.js'), 'utf8');
    const capture = fs.readFileSync(path.join(ROOT, prefix, 'src/run-capture.js'), 'utf8');
    assert.match(agent, /resolveSavedDownload\([^,]+,\s*downloadId\)/, `${label}: agent saves should wait for the completed browser item`);
    assert.match(capture, /return resolveSavedDownload\(api, downloadId\)/, `${label}: run screenshots should return the completed browser path`);
    assert.match(capture, /filenames: \[state\.before\.filename, after\.filename\]/, `${label}: run result should surface resolved before/after paths`);

    // Durable auto-scratchpad must pin downloadId only — never a page-derived
    // basename or absolute path (prompt-injection / privacy).
    assert.match(agent, /_pinDownloadId\(tabId,\s*downloadId\)/, `${label}: download tools should pin via _pinDownloadId`);
    const pinNoteMatch = agent.match(
      /_pinDownloadId\(tabId,\s*downloadId\)\s*\{[\s\S]*?_autoScratchpadNote\(tabId,\s*`([^`]+)`\)/
    );
    assert.ok(pinNoteMatch, `${label}: _pinDownloadId should write an [auto] scratchpad note`);
    const pinNote = pinNoteMatch[1];
    assert.match(pinNote, /\[auto\] Downloaded file \(downloadId \$\{downloadId\}\)/, `${label}: pin note should include the downloadId handle`);
    assert.doesNotMatch(pinNote, /\$\{[^}]*filename[^}]*\}/, `${label}: pin note must not interpolate filenames`);
    assert.doesNotMatch(pinNote, /\/Users\/|\/home\/|Downloads\/|C:\\\\/i, `${label}: pin note must not embed absolute path fragments`);
  }

  const chromeAgent = fs.readFileSync(path.join(ROOT, 'src/chrome/src/agent/agent.js'), 'utf8');
  const recorder = fs.readFileSync(path.join(ROOT, 'src/chrome/src/recorder/host.js'), 'utf8');
  const downloadResult = fs.readFileSync(path.join(ROOT, 'src/chrome/src/download-result.js'), 'utf8');
  assert.doesNotMatch(chromeAgent, /saved to Downloads as/, 'chrome: screenshot messages should not claim a fixed Downloads location');
  assert.match(downloadResult, /RECORDING_DOWNLOAD_TIMEOUT_MS\s*=\s*5\s*\*\s*60\s*\*\s*1000/, 'chrome: recording saves need a longer timeout than screenshots');
  assert.match(recorder, /timeoutMs:\s*RECORDING_DOWNLOAD_TIMEOUT_MS/, 'chrome: recordings and transcripts should use the longer save timeout');
  assert.match(recorder, /broadcast\(['"]saving['"]\)/, 'chrome: should clear live-recording UI before waiting on disk');
  assert.match(recorder, /saving:\s*true/, 'chrome: disk flush should reserve recording state so a second start cannot race stopped');
  assert.match(recorder, /A recording is still being saved/, 'chrome: concurrent start during save should be rejected');
  assert.match(recorder, /stillOurSave/, 'chrome: final stopped broadcast should only clear our own save reservation');
  assert.match(recorder, /savedDownload = await resolveSavedDownload\(chrome, downloadId/, 'chrome: recordings and transcripts should wait for the completed browser item');
  assert.match(recorder, /filename: saveError \? null : savedDownload\.filename/, 'chrome: recording results should expose the resolved path');
  assert.match(recorder, /transcriptFilename: savedDownload\.filename/, 'chrome: transcript results should expose the resolved path');

  const localeFilenames = fs.readdirSync(path.join(ROOT, 'src/chrome/src/ui/locales'))
    .filter((name) => name.endsWith('.js'))
    .sort();
  const fixedDownloadsNames = /Downloads|Descargas|Téléchargements|İndirilenler|التنزيلات|Загрузки|Pobranych|להורדות|Завантаження/;
  for (const filename of localeFilenames) {
    const chromeLocale = (await import(pathToFileURL(path.join(ROOT, 'src/chrome/src/ui/locales', filename)).href)).default;
    const firefoxLocale = (await import(pathToFileURL(path.join(ROOT, 'src/firefox/src/ui/locales', filename)).href)).default;
    assert.equal(chromeLocale['sp.record.saved'], firefoxLocale['sp.record.saved'], `${filename}: save-path copy should match across browser builds`);
    assert.match(chromeLocale['sp.record.saved'], /\{filename\}/, `${filename}: save-path copy should include the resolved path`);
    assert.doesNotMatch(chromeLocale['sp.record.saved'], fixedDownloadsNames, `${filename}: save-path copy should not name a fixed Downloads folder`);
  }
});

test('background run-capture controller owns scoped recording cleanup', async () => {
  const runtime = await loadRunCaptureRuntime('src/chrome/src/run-capture.js');
  const starts = [];
  const stops = [];
  const controller = runtime.createRunCaptureController({
    api: {},
    startRecording: async (tabId, options) => {
      starts.push({ tabId, options });
      return { ok: true, state: { recordingId: 'run-recording-1', hasMic: true } };
    },
    stopRecording: async (options) => {
      stops.push(options);
      return { ok: true, filename: 'checkout.webm' };
    },
  });

  const state = await controller.start({ kind: 'record', saveAs: '../checkout.webm' }, 42);
  assert.equal(state.recordingId, 'run-recording-1');
  assert.equal(starts[0].options.filename, 'checkout.webm');

  // Finalization is invoked by background.js, not by a side-panel callback.
  const result = await controller.finish(state, 42);
  assert.deepEqual(stops, [{ expectedRecordingId: 'run-recording-1' }]);
  assert.deepEqual(result, { kind: 'record', filename: 'checkout.webm' });

  const firefoxController = runtime.createRunCaptureController({
    api: {},
    unsupportedRecordingMessage: 'Tab recording is not supported in Firefox.',
  });
  await assert.rejects(
    firefoxController.start({ kind: 'record', saveAs: null }, 42),
    new RegExp(`${runtime.RUN_CAPTURE_START_ERROR_PREFIX}Tab recording is not supported in Firefox\\.$`),
  );
});

test('slash autocomplete progressively suggests only available unused flags', () => {
  const chrome = loadSlashAutocompleteRuntime('src/chrome/src/ui/sidepanel.js');
  const firefox = loadSlashAutocompleteRuntime('src/firefox/src/ui/sidepanel.js');
  const optionMatches = (runtime, context) => context ? runtime.slashCommandOptions(context.command)
    .filter((option) => runtime.slashOptionIsAvailable(option, context.selected, context.selectedGroups))
    .filter((option) => option.value.startsWith(context.query))
    .map((option) => option.value) : [];

  const initial = chrome.getContext('/record ');
  assert.equal(initial.kind, 'option');
  assert.deepEqual(optionMatches(chrome, initial), ['--stop', '--full-screen', '--hide-recording-indicator', '--transcribe', '--help']);
  assert.deepEqual(
    chrome.getMatches(chrome.getContext('/scratchpad ')).map(({ kind, value, label, descriptionKey }) => ({ kind, value, label, descriptionKey })),
    [
      { kind: 'base-action', value: '/scratchpad', label: '↵ Enter', descriptionKey: 'sp.slash.show_scratchpad' },
      { kind: 'option', value: '--append', label: undefined, descriptionKey: 'sp.slash.edit_scratchpad' },
      { kind: 'option', value: '--clear', label: undefined, descriptionKey: 'sp.slash.clear_scratchpad' },
      { kind: 'option', value: '--help', label: undefined, descriptionKey: 'sp.slash.show_scratchpad' },
    ],
    'a complete command should expose its Enter action above flag completions',
  );

  const partial = chrome.getContext('/record --trans');
  assert.equal(partial.query, '--trans');
  assert.deepEqual(optionMatches(chrome, partial), ['--transcribe']);
  assert.equal(chrome.getMatches(partial).some((match) => match.kind === 'base-action'), false, 'typing a flag should hide the base-action row');

  const afterFullScreen = chrome.getContext('/record --full-screen ');
  assert.deepEqual([...afterFullScreen.selected], ['--full-screen']);
  assert.deepEqual(optionMatches(chrome, afterFullScreen), ['--hide-recording-indicator', '--transcribe']);
  assert.deepEqual(
    chrome.getMatches(afterFullScreen).map(({ kind, value, label, descriptionKey }) => ({ kind, value, label, descriptionKey })),
    [
      { kind: 'base-action', value: '/record', label: '↵ Enter', descriptionKey: 'sp.slash.record_full_screen' },
      { kind: 'option', value: '--hide-recording-indicator', label: undefined, descriptionKey: 'sp.slash.record_hide_indicator' },
      { kind: 'option', value: '--transcribe', label: undefined, descriptionKey: 'sp.slash.record_transcribe' },
    ],
    'a selected first flag should keep an explicit Enter action above the next flag',
  );

  const afterTranscribe = chrome.getContext('/record --transcribe ');
  assert.deepEqual(optionMatches(chrome, afterTranscribe), ['--full-screen', '--hide-recording-indicator']);
  const afterStop = chrome.getContext('/record --stop ');
  assert.deepEqual(optionMatches(chrome, afterStop), [], 'stop should exclude every recording-start flag');
  assert.deepEqual(
    chrome.getMatches(afterStop).map(({ kind, value, label, descriptionKey }) => ({ kind, value, label, descriptionKey })),
    [{ kind: 'base-action', value: '/record', label: '↵ Enter', descriptionKey: 'sp.record.stop' }],
    'the completed stop flag should keep an executable Enter action',
  );
  const beforeRequiredFullScreen = chrome.getContext('/record --hide-recording-indicator ');
  assert.deepEqual(optionMatches(chrome, beforeRequiredFullScreen), ['--full-screen', '--transcribe']);
  assert.equal(
    chrome.getMatches(beforeRequiredFullScreen).some((match) => match.kind === 'base-action'),
    false,
    'an option with an unmet dependency should not expose an invalid Enter action',
  );
  for (const [label, runtime] of [['chrome', chrome], ['firefox', firefox]]) {
    const beforeRequiredFile = runtime.getContext('/workflow --import ');
    assert.equal(
      runtime.getMatches(beforeRequiredFile).some((match) => match.kind === 'base-action'),
      false,
      `${label}: mutually required workflow flags should not expose an invalid Enter action`,
    );
  }
  const afterBothRecordOptions = chrome.getContext('/record --transcribe --full-screen ');
  assert.deepEqual(optionMatches(chrome, afterBothRecordOptions), ['--hide-recording-indicator']);
  const afterAllRecordOptions = chrome.getContext('/record --transcribe --full-screen --hide-recording-indicator ');
  assert.deepEqual(optionMatches(chrome, afterAllRecordOptions), []);
  assert.deepEqual(
    chrome.getMatches(afterAllRecordOptions).map(({ kind, value, label, descriptionKey }) => ({ kind, value, label, descriptionKey })),
    [
      { kind: 'base-action', value: '/record', label: '↵ Enter', descriptionKey: 'sp.slash.record_full_screen' },
    ],
    'the Enter action should remain available after the final flag',
  );
  assert.deepEqual(optionMatches(chrome, chrome.getContext('/scratchpad --clear ')), [], 'conflicting scratchpad actions should not be suggested');
  assert.equal(chrome.getContext('/scratchpad --append '), null, 'value-taking options should hand control back to text entry');
  assert.equal(chrome.getContext('/record positional'), null, 'positional input should close flag autocomplete');
  assert.equal(chrome.getContext('/record --full-screen --full-screen '), null, 'duplicate flags should not expose an executable Enter action');
  assert.deepEqual(optionMatches(chrome, chrome.getContext('/schedule ')), ['--list', '--help'], 'schedule should keep its real flags ahead of universal help');
  assert.deepEqual(optionMatches(chrome, chrome.getContext('/progress ')), ['--help'], 'commands without flags should still offer --help');
  const afterHelp = chrome.getContext('/schedule --help ');
  assert.deepEqual(optionMatches(chrome, afterHelp), [], '--help should finish option autocomplete');
  assert.deepEqual(
    chrome.getMatches(afterHelp).map(({ kind, value, label, descriptionKey }) => ({ kind, value, label, descriptionKey })),
    [
      { kind: 'base-action', value: '/schedule', label: '↵ Enter', descriptionKey: 'sp.slash.help' },
    ],
    'a completed --help invocation should describe the help action that Enter will run',
  );
  assert.equal(chrome.getMatches(chrome.getContext('/scratchpad --clear '))[0]?.kind, 'base-action', 'selected flags should keep an explicit Enter action in autocomplete');

  assert.equal(firefox.getContext('/record '), null, 'Firefox should not discover unsupported recording');
  assert.equal(firefox.getMatches(firefox.getContext('/scratchpad '))[0]?.kind, 'base-action', 'Firefox should mirror the base-action row');
  assert.equal(firefox.getMatches(firefox.getContext('/scratchpad --clear '))[0]?.kind, 'base-action', 'Firefox should mirror Enter after a selected flag');
  assert.equal(firefox.getMatches(firefox.getContext('/schedule --help '))[0]?.descriptionKey, 'sp.slash.help', 'Firefox should describe the completed help action accurately');
  assert.deepEqual(optionMatches(firefox, firefox.getContext('/screenshot ')), ['--help'], 'Firefox should omit unsupported flags but still offer command help');
  assert.deepEqual(optionMatches(firefox, firefox.getContext('/scratchpad --clear ')), [], 'Firefox should not suggest conflicting scratchpad actions');
});

test('chrome offscreen helper recreates an evicted document after ready cache is stale', async () => {
  const previousChrome = globalThis.chrome;
  let documentExists = false;
  const createCalls = [];
  globalThis.chrome = {
    offscreen: {
      async hasDocument() {
        return documentExists;
      },
      async createDocument(args) {
        createCalls.push(args);
        documentExists = true;
      },
    },
  };
  try {
    const ensureUrl = 'file://' + path.join(ROOT, 'src/chrome/src/offscreen/ensure.js').replace(/\\/g, '/') + `?test=${Date.now()}`;
    const { ensureOffscreen } = await import(ensureUrl);

    await ensureOffscreen();
    assert.equal(createCalls.length, 1, 'chrome: first ensure should create the offscreen document');

    documentExists = false;
    await ensureOffscreen();
    assert.equal(createCalls.length, 2, 'chrome: stale ready cache should not skip recreation after eviction');
    assert.equal(createCalls[1].url, 'src/offscreen/offscreen.html', 'chrome: recreated document should use the shared offscreen URL');
  } finally {
    if (previousChrome === undefined) {
      delete globalThis.chrome;
    } else {
      globalThis.chrome = previousChrome;
    }
  }
});

test('chrome non-idempotent fetch uses one offscreen transport and clears its timeout', async () => {
  const previousChrome = globalThis.chrome;
  const previousFetch = globalThis.fetch;
  const previousSetTimeout = globalThis.setTimeout;
  const previousClearTimeout = globalThis.clearTimeout;
  const previousWarn = console.warn;
  const timers = [];
  console.warn = () => {};
  globalThis.setTimeout = (fn, ms) => {
    const handle = { fn, ms, cleared: false };
    timers.push(handle);
    return handle;
  };
  globalThis.clearTimeout = (handle) => {
    if (handle) handle.cleared = true;
  };
  let directAttempts = 0;
  globalThis.fetch = async () => {
    directAttempts += 1;
    throw new TypeError('Failed to fetch');
  };
  globalThis.chrome = {
    offscreen: {
      async hasDocument() {
        return true;
      },
    },
    runtime: {
      connect({ name }) {
        const messageListeners = [];
        return {
          onMessage: { addListener: (fn) => messageListeners.push(fn) },
          onDisconnect: { addListener: () => {} },
          postMessage() {
            // Simulate the offscreen streaming protocol: headers first
            // (clears the caller's connection-phase timeout), then the
            // body as chunks, then done.
            queueMicrotask(() => {
              const emit = (m) => messageListeners.forEach((fn) => fn(m));
              emit({ type: 'headers', ok: true, status: 200, contentType: 'application/json' });
              emit({ type: 'chunk', text: '{"ok":true}' });
              emit({ type: 'done' });
            });
          },
          disconnect() {},
        };
      },
    },
  };
  try {
    const fetchUrl = 'file://' + path.join(ROOT, 'src/chrome/src/providers/fetch-with-fallback.js').replace(/\\/g, '/') + `?test=${Date.now()}`;
    const { fetchWithFallback } = await import(fetchUrl);
    const res = await fetchWithFallback('http://127.0.0.1:11434/api/chat', {
      method: 'POST',
      timeoutMs: 12345,
      body: '{}',
    });

    assert.equal(res.status, 200, 'chrome: fallback should synthesize the proxied response');
    assert.equal(await res.text(), '{"ok":true}', 'chrome: fallback response body should survive proxy conversion');
    assert.equal(directAttempts, 0, 'chrome: a POST must not be replayed after a direct network failure');
    assert.equal(timers.length, 1, 'chrome: the single offscreen transport should install one timeout');
    assert.equal(timers.every((timer) => timer.cleared), true, 'chrome: offscreen proxy timeout should be cleared after success');
  } finally {
    globalThis.setTimeout = previousSetTimeout;
    globalThis.clearTimeout = previousClearTimeout;
    if (previousFetch === undefined) {
      delete globalThis.fetch;
    } else {
      globalThis.fetch = previousFetch;
    }
    if (previousChrome === undefined) {
      delete globalThis.chrome;
    } else {
      globalThis.chrome = previousChrome;
    }
    console.warn = previousWarn;
  }
});

test('chrome fetch fallback chunks multipart blobs through disk-backed offscreen staging', async () => {
  const previousChrome = globalThis.chrome;
  const previousFetch = globalThis.fetch;
  const previousWarn = console.warn;
  const previousNavigatorDescriptor = Object.getOwnPropertyDescriptor(globalThis, 'navigator');
  let initialRequest = null;
  let connectListener = null;
  const sentToOffscreen = [];
  const stagedFiles = new Map();
  console.warn = () => {};

  try {
    const stagedDir = {
      async *keys() { yield* stagedFiles.keys(); },
      async removeEntry(filename) { stagedFiles.delete(filename); },
      async getFileHandle(filename, { create = false } = {}) {
        if (create && !stagedFiles.has(filename)) {
          stagedFiles.set(filename, { parts: [], closed: false });
        }
        const staged = stagedFiles.get(filename);
        if (!staged) throw new Error('staged file not found');
        return {
          async createWritable() {
            return {
              async write(chunk) { staged.parts.push(new Uint8Array(chunk)); },
              async close() { staged.closed = true; },
              async abort() {
                staged.parts = [];
                staged.closed = true;
              },
            };
          },
          async getFile() { return new Blob(staged.parts); },
        };
      },
    };
    Object.defineProperty(globalThis, 'navigator', {
      configurable: true,
      value: {
        storage: {
          async getDirectory() {
            return { async getDirectoryHandle() { return stagedDir; } };
          },
        },
      },
    });
    globalThis.fetch = async () => {
      throw new TypeError('Failed to fetch');
    };
    globalThis.chrome = {
      offscreen: {
        async hasDocument() { return true; },
      },
      runtime: {
        onMessage: { addListener() {} },
        onConnect: { addListener(fn) { connectListener = fn; } },
      },
    };
    const offscreenUrl = 'file://' + path.join(ROOT, 'src/chrome/src/offscreen/offscreen.js').replace(/\\/g, '/') + `?multipart=${Date.now()}`;
    await import(offscreenUrl);
    assert.equal(typeof connectListener, 'function');

    globalThis.fetch = async (url, options) => {
      if (!initialRequest) {
        throw new TypeError('Failed to fetch');
      }
      assert.equal(String(url), 'http://127.0.0.1:1234/v1/audio/transcriptions');
      assert.ok(options.body instanceof FormData);
      assert.equal(options.body.get('model'), 'whisper-local');
      const file = options.body.get('file');
      assert.ok(file instanceof Blob);
      assert.equal(file.name, 'probe.wav');
      assert.equal(file.type, 'audio/wav');
      const received = new Uint8Array(await file.arrayBuffer());
      assert.equal(received.byteLength, 600_000);
      assert.deepEqual([...received.subarray(0, 4)], [82, 73, 70, 70]);
      assert.equal(received[received.length - 1], 255);
      return new Response(JSON.stringify({ text: '' }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    };

    globalThis.chrome.runtime.connect = () => {
      const callerMessageListeners = [];
      const callerDisconnectListeners = [];
      const offscreenRequestListeners = [];
      const portForOffscreen = {
        name: 'offscreen-fetch-stream',
        onMessage: { addListener(fn) { offscreenRequestListeners.push(fn); } },
        postMessage(msg) {
          queueMicrotask(() => callerMessageListeners.forEach((fn) => fn(msg)));
        },
      };
      connectListener(portForOffscreen);
      return {
        onMessage: { addListener(fn) { callerMessageListeners.push(fn); } },
        onDisconnect: { addListener(fn) { callerDisconnectListeners.push(fn); } },
        postMessage(msg) {
          sentToOffscreen.push(msg);
          if (msg.url) initialRequest = msg;
          queueMicrotask(() => offscreenRequestListeners.forEach((fn) => fn(msg)));
        },
        disconnect() {
          callerDisconnectListeners.forEach((fn) => fn());
        },
      };
    };

    const fetchUrl = 'file://' + path.join(ROOT, 'src/chrome/src/providers/fetch-with-fallback.js').replace(/\\/g, '/') + `?multipart=${Date.now()}`;
    const { fetchWithFallback } = await import(fetchUrl);
    const fileBytes = new Uint8Array(600_000);
    fileBytes.set([82, 73, 70, 70]);
    fileBytes[fileBytes.length - 1] = 255;
    const form = new FormData();
    form.append('file', new Blob([fileBytes], { type: 'audio/wav' }), 'probe.wav');
    form.append('model', 'whisper-local');
    const response = await fetchWithFallback('http://127.0.0.1:1234/v1/audio/transcriptions', {
      method: 'POST',
      body: form,
      timeoutMs: 12345,
    });

    assert.equal(response.status, 200);
    assert.equal(await response.text(), '{"text":""}');
    assert.equal(initialRequest.bodyType, 'form-data-chunked');
    assert.equal(initialRequest.body, undefined);
    assert.deepEqual(initialRequest.formDataEntries.map(({ name, kind }) => ({ name, kind })), [
      { name: 'file', kind: 'blob' },
      { name: 'model', kind: 'text' },
    ]);
    assert.equal(Object.hasOwn(initialRequest.formDataEntries[0], 'value'), false);
    const chunkMessages = sentToOffscreen.filter(({ type }) => type === 'form-data-chunk');
    assert.equal(chunkMessages.length, 3, '600KB upload should be split into bounded 256KiB chunks');
    assert.equal(sentToOffscreen.at(-1)?.type, 'form-data-complete');
    assert.equal(stagedFiles.size, 0, 'offscreen staging files should be removed after request upload');
  } finally {
    if (previousChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = previousChrome;
    if (previousFetch === undefined) delete globalThis.fetch;
    else globalThis.fetch = previousFetch;
    if (previousNavigatorDescriptor) {
      Object.defineProperty(globalThis, 'navigator', previousNavigatorDescriptor);
    } else {
      delete globalThis.navigator;
    }
    console.warn = previousWarn;
  }
});

test('chrome fetch fallback resolves null-body proxy statuses without hanging', async () => {
  const previousChrome = globalThis.chrome;
  const previousFetch = globalThis.fetch;
  const previousWarn = console.warn;
  let nextStatus = 204;
  let disconnects = 0;
  console.warn = () => {};
  globalThis.fetch = async () => {
    throw new TypeError('Failed to fetch');
  };
  globalThis.chrome = {
    offscreen: {
      async hasDocument() {
        return true;
      },
    },
    runtime: {
      connect() {
        const messageListeners = [];
        return {
          onMessage: { addListener: (fn) => messageListeners.push(fn) },
          onDisconnect: { addListener: () => {} },
          postMessage() {
            queueMicrotask(() => {
              messageListeners.forEach((fn) => fn({
                type: 'headers',
                ok: nextStatus >= 200 && nextStatus < 300,
                status: nextStatus,
                contentType: 'application/json',
                hasBody: false,
              }));
            });
          },
          disconnect() {
            disconnects++;
          },
        };
      },
    },
  };
  try {
    const fetchUrl = 'file://' + path.join(ROOT, 'src/chrome/src/providers/fetch-with-fallback.js').replace(/\\/g, '/') + `?test=${Date.now()}`;
    const { fetchWithFallback } = await import(fetchUrl);
    for (const status of [204, 205, 304]) {
      nextStatus = status;
      const res = await fetchWithFallback('http://127.0.0.1:11434/api/models', { timeoutMs: 12345 });
      assert.equal(res.status, status, `chrome: proxied ${status} status should resolve`);
      assert.equal(await res.text(), '', `chrome: proxied ${status} response must have no body`);
    }
    assert.equal(disconnects, 3, 'chrome: null-body responses should close their streaming ports immediately');
  } finally {
    if (previousFetch === undefined) {
      delete globalThis.fetch;
    } else {
      globalThis.fetch = previousFetch;
    }
    if (previousChrome === undefined) {
      delete globalThis.chrome;
    } else {
      globalThis.chrome = previousChrome;
    }
    console.warn = previousWarn;
  }
});

test('chrome fetch fallback aborts an active offscreen response body', async () => {
  const previousChrome = globalThis.chrome;
  const previousFetch = globalThis.fetch;
  const previousWarn = console.warn;
  let disconnects = 0;
  console.warn = () => {};
  globalThis.fetch = async () => {
    throw new TypeError('Failed to fetch');
  };
  globalThis.chrome = {
    offscreen: {
      async hasDocument() { return true; },
    },
    runtime: {
      connect() {
        const messageListeners = [];
        return {
          onMessage: { addListener: (fn) => messageListeners.push(fn) },
          onDisconnect: { addListener() {} },
          postMessage() {
            queueMicrotask(() => {
              messageListeners.forEach((fn) => fn({
                type: 'headers',
                ok: true,
                status: 200,
                contentType: 'application/json',
                hasBody: true,
              }));
            });
          },
          disconnect() { disconnects += 1; },
        };
      },
    },
  };

  try {
    const fetchUrl = 'file://' + path.join(ROOT, 'src/chrome/src/providers/fetch-with-fallback.js').replace(/\\/g, '/') + `?abort=${Date.now()}`;
    const { fetchWithFallback } = await import(fetchUrl);
    const controller = new AbortController();
    const response = await fetchWithFallback('http://127.0.0.1:11434/api/show', {
      method: 'POST',
      body: '{}',
      timeoutMs: 12345,
      signal: controller.signal,
    });
    const body = response.text();
    controller.abort(new DOMException('metadata deadline', 'TimeoutError'));
    await assert.rejects(body, /metadata deadline/);
    assert.equal(disconnects, 1, 'aborting after headers should disconnect the offscreen streaming port');
  } finally {
    if (previousFetch === undefined) delete globalThis.fetch;
    else globalThis.fetch = previousFetch;
    if (previousChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = previousChrome;
    console.warn = previousWarn;
  }
});

