test('sidepanel escapes dynamic system-message interpolation before raw HTML insertion', () => {
  for (const [label, panelRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    const utils = fs.readFileSync(path.join(ROOT, path.dirname(panelRel), 'utils.js'), 'utf8');
    assert.match(panel, /import \{ escapeHtml \} from '\.\/utils\.js';/, `${label}: sidepanel should use the shared escapeHtml`);
    assert.match(utils, /export function escapeHtml\(s\) \{[\s\S]*?String\(s == null \? '' : s\)/, `${label}: escapeHtml should normalize nullish values`);
    assert.equal(utils.includes("replace(/[&<>\"']/g"), true, `${label}: escapeHtml should cover attribute-breaking quotes as well as HTML tags`);
    assert.match(
      panel,
      /function tSystemHtml\(key, params\) \{[\s\S]*?Object\.entries\(params \|\| \{\}\)[\s\S]*?safeParams\[name\] = escapeHtml\(value\);[\s\S]*?return t\(key, safeParams\);[\s\S]*?\}/,
      `${label}: dynamic system HTML helper missing`,
    );
    assert.match(panel, /function systemHtml\(html\) \{[\s\S]*?__systemHtml: String\(html == null \? '' : html\)/, `${label}: trusted system HTML wrapper missing`);
    assert.match(
      panel,
      /role === 'system'\) \{[\s\S]*?if \(isSystemHtml\(content\)\) textEl\.innerHTML = content\.__systemHtml;[\s\S]*?else textEl\.textContent = content \|\| '';[\s\S]*?\}/,
      `${label}: system messages should default to textContent`,
    );
    assert.doesNotMatch(
      panel,
      /addMessage\('system',\s*t\('[^']+',\s*\{/,
      `${label}: system messages inserted as raw HTML must not interpolate unescaped params directly`,
    );
    assert.doesNotMatch(
      panel,
      /addMessage\('system',\s*(?:tSystemHtml|t\('[^']*_html'|imgHtml)/,
      `${label}: trusted system HTML should be wrapped explicitly`,
    );
    const dynamicHtmlKeys = [
      'sp.scheduled.created',
      'sp.scheduled.needs_user_input',
      'sp.schedule_form.created',
      'sp.scratchpad.error',
      'sp.compact.failed',
      'sp.screenshot.error',
      'sp.vision.error',
    ];
    if (label === 'chrome') dynamicHtmlKeys.push('sp.record.error');
    for (const key of dynamicHtmlKeys) {
      assert.match(panel, new RegExp(`tSystemHtml\\('${escapeRegExpLiteral(key)}'`), `${label}: ${key} should escape dynamic params for system HTML`);
    }
  }
});

