test('chrome sidepanel Escape abort honors slash autocomplete dismissal', () => {
  const panel = fs.readFileSync(path.join(ROOT, 'src/chrome/src/ui/sidepanel.js'), 'utf8');
  assert.match(panel, /if \(e\.key === 'Escape'\) \{\s*e\.preventDefault\(\);\s*hideSlashCommandAutocomplete\(\);\s*return true;\s*\}/, 'chrome: slash autocomplete Escape should consume the key event');

  const globalHandlerStart = panel.indexOf('function handleGlobalKeydown(e)');
  const defaultPreventedGuard = panel.indexOf('if (e.defaultPrevented) return;', globalHandlerStart);
  const recordingEscapeCall = panel.indexOf('if (handleRecordingEscapeKey(e)) return;', globalHandlerStart);
  const abortCall = panel.indexOf('abortRun();', globalHandlerStart);
  assert.notEqual(globalHandlerStart, -1, 'chrome: global keydown handler missing');
  assert.notEqual(defaultPreventedGuard, -1, 'chrome: global keydown handler should honor consumed key events');
  assert.notEqual(recordingEscapeCall, -1, 'chrome: global keydown handler should route recording Escape after higher-priority Escape handlers');
  assert.notEqual(abortCall, -1, 'chrome: Escape abort shortcut missing');
  assert.equal(defaultPreventedGuard < abortCall, true, 'chrome: consumed slash-menu Escape should not reach abortRun');
  assert.equal(abortCall < recordingEscapeCall, true, 'chrome: agent-run Escape abort should take precedence over recording stop');
});

test('firefox sidepanel implements documented global keyboard shortcuts', () => {
  const panel = fs.readFileSync(path.join(ROOT, 'src/firefox/src/ui/sidepanel.js'), 'utf8');
  const locale = fs.readFileSync(path.join(ROOT, 'src/firefox/src/ui/locales/en.js'), 'utf8');

  const globalHandlerStart = panel.indexOf('async function handleGlobalKeydown(e)');
  const defaultPreventedGuard = panel.indexOf('if (e.defaultPrevented) return;', globalHandlerStart);
  const abortCall = panel.indexOf('abortRun();', globalHandlerStart);
  assert.notEqual(globalHandlerStart, -1, 'firefox: global keydown handler missing');
  assert.notEqual(defaultPreventedGuard, -1, 'firefox: global keydown handler should honor consumed key events');
  assert.notEqual(abortCall, -1, 'firefox: Escape abort shortcut missing');
  assert.equal(defaultPreventedGuard < abortCall, true, 'firefox: consumed slash-menu Escape should not reach abortRun');
  assert.match(panel, /document\.addEventListener\('keydown', handleGlobalKeydown, true\)/, 'firefox: shortcuts should run in capture phase');
  assert.match(panel, /mod && e\.key === '\/'/, 'firefox: Ctrl/Cmd+/ focus shortcut missing');
  assert.match(panel, /mod && e\.shiftKey && e\.key === 'A'/, 'firefox: Ask mode shortcut missing');
  assert.match(panel, /mod && e\.shiftKey && e\.key === 'X'/, 'firefox: Act mode shortcut missing');
  assert.match(panel, /mod && e\.shiftKey && e\.key === 'D'/, 'firefox: Dev mode shortcut missing');
  assert.match(panel, /await ensureActMode\(\)/, 'firefox: Act shortcut should call ensureActMode');
  assert.match(panel, /await ensureDevMode\(\)/, 'firefox: Dev shortcut should call ensureDevMode');
  // Review P1s: AltGr / IME / open pickers must not steal Escape or slash entry
  assert.match(panel, /e\.altKey \|\| e\.getModifierState\?\.\('AltGraph'\)/, 'firefox: AltGr/Option chords must not trigger Ctrl shortcuts');
  assert.match(panel, /if \(e\.isComposing\) return;/, 'firefox: IME Escape must not abort the active run');
  assert.match(panel, /providerPickerMenu && !providerPickerMenu\.classList\.contains\('hidden'\)/, 'firefox: open provider picker Escape must not abort');
  assert.match(panel, /languagePickerMenu && !languagePickerMenu\.classList\.contains\('hidden'\)/, 'firefox: open language picker Escape must not abort');
  const composingGuard = panel.indexOf('if (e.isComposing) return;', globalHandlerStart);
  const providerPickerGuard = panel.indexOf("providerPickerMenu && !providerPickerMenu.classList.contains('hidden')", globalHandlerStart);
  const languagePickerGuard = panel.indexOf("languagePickerMenu && !languagePickerMenu.classList.contains('hidden')", globalHandlerStart);
  assert.equal(composingGuard !== -1 && composingGuard < abortCall, true, 'firefox: IME guard must precede abortRun');
  assert.equal(providerPickerGuard !== -1 && providerPickerGuard < abortCall, true, 'firefox: provider picker guard must precede abortRun');
  assert.equal(languagePickerGuard !== -1 && languagePickerGuard < abortCall, true, 'firefox: language picker guard must precede abortRun');

  for (const shortcut of ['Ctrl/Cmd+/', 'Ctrl/Cmd+Shift+A', 'Ctrl/Cmd+Shift+X', 'Ctrl/Cmd+Shift+D', 'Escape']) {
    assert.match(locale, new RegExp(escapeRegExpLiteral(shortcut)), `firefox: /help should mention ${shortcut}`);
  }
});

test('chrome double Escape stops active recordings from sidepanel and content pages', () => {
  const panel = fs.readFileSync(path.join(ROOT, 'src/chrome/src/ui/sidepanel.js'), 'utf8');
  const content = fs.readFileSync(path.join(ROOT, 'src/chrome/src/content/content.js'), 'utf8');
  const host = fs.readFileSync(path.join(ROOT, 'src/chrome/src/recorder/host.js'), 'utf8');

  assert.match(panel, /const RECORDING_DOUBLE_ESCAPE_MS = 1400;/, 'chrome: sidepanel should define a double-Escape window');
  assert.match(panel, /function handleRecordingEscapeKey\(e\)[\s\S]*?recordingActive[\s\S]*?!e\.isTrusted[\s\S]*?recordingEscapeArmedUntil[\s\S]*?stopRecording\(\)/, 'chrome: sidepanel should arm then stop recording on trusted double Escape');
  assert.match(panel, /document\.addEventListener\('keydown', handleGlobalKeydown, true\)/, 'chrome: sidepanel Escape routing should run in capture phase');
  assert.match(host, /export const MAX_RECORDING_MS = 2 \* 60 \* 60 \* 1000/, 'chrome: recorder host should own the recording safety cap');
  assert.match(host, /function scheduleRecordingSafetyWatchdog[\s\S]*?setTimeout[\s\S]*?chrome\.alarms\?\.create/, 'chrome: recording safety cap should survive hidden sidepanel recordings');

  assert.match(content, /const RECORDING_DOUBLE_ESCAPE_MS = 1400;/, 'chrome: content script should define a double-Escape window');
  assert.match(content, /let recordingActive = false;/, 'chrome: content script should track live recording state');
  assert.match(content, /action: 'get_recording_state'[\s\S]*?setRecordingActive\(!!res\?\.state\?\.active\)/, 'chrome: content script should hydrate recording state from background');
  assert.match(content, /msg\?\.target !== 'content' \|\| msg\.action !== 'recording_state'[\s\S]*?setRecordingActive\(!!msg\.active\)/, 'chrome: content script should accept recording state broadcasts');
  assert.match(content, /if \(!recordingActive \|\| !e\.isTrusted\)[\s\S]*?return;/, 'chrome: content pages should only consume trusted Escape while recording is active');
  assert.match(content, /stop_tab_recording[\s\S]*?reason: 'double_escape'/, 'chrome: top-level content pages should send stop_tab_recording on active trusted double Escape');
});

test('chrome sidepanel shortcuts are documented in help and README', () => {
  const locale = fs.readFileSync(path.join(ROOT, 'src/chrome/src/ui/locales/en.js'), 'utf8');
  const readme = fs.readFileSync(path.join(ROOT, 'README.md'), 'utf8');

  for (const shortcut of ['Ctrl/Cmd+/', 'Ctrl/Cmd+Shift+A', 'Ctrl/Cmd+Shift+X', 'Escape']) {
    assert.match(locale, new RegExp(escapeRegExpLiteral(shortcut)), `chrome: /help should mention ${shortcut}`);
    const readmePattern = shortcut.startsWith('Ctrl/Cmd')
      ? `Ctrl.*Cmd${escapeRegExpLiteral(shortcut.slice('Ctrl/Cmd'.length))}`
      : escapeRegExpLiteral(shortcut);
    assert.match(readme, new RegExp(readmePattern), `README should mention ${shortcut}`);
  }
  assert.match(locale, /Keyboard Shortcuts/, 'chrome: /help should include a keyboard shortcut section');
  assert.match(readme, /## Keyboard Shortcuts/, 'README should include a keyboard shortcut section');
  assert.match(readme, /Stop the active run, unless it is only dismissing slash-command autocomplete/, 'README should document Escape vs slash autocomplete behavior');
});

test('sidepanel reports missing background responses without res.content crash', () => {
  for (const [label, panelRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    const reconnect = fs.readFileSync(
      path.join(ROOT, panelRel.replace('/ui/sidepanel.js', '/run-reconnect.js')),
      'utf8',
    );
    assert.match(panel, /No response from WebBrain background/, `${label}: missing background response should become a clear error`);
    assert.match(panel, /formatBackgroundSendError\(action/, `${label}: runtime disconnects should be rewritten as WebBrain errors`);
    assert.match(reconnect, /Receiving end does not exist/, `${label}: Chrome missing-receiver errors should be recognized`);
    assert.match(panel, /response == null/, `${label}: sendToBackground should reject nullish responses`);
    assert.equal((panel.match(/res\?\.content && (?:currentAssistantEl|assistantEl)/g) || []).length >= 2, true, `${label}: chat and continue should not dereference missing responses`);
    assert.doesNotMatch(panel, /res\.content && (?:currentAssistantEl|assistantEl)/, `${label}: unsafe res.content render guard returned`);
  }
});

test('sidepanel rebinds interactive controls after restoring serialized tab chat', () => {
  for (const [label, panelRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    assert.match(panel, /function rebindCopyButtons\(\)/, `${label}: copy-button rebinding helper missing`);
    assert.match(panel, /document\.querySelectorAll\('\.msg-copy-btn'\)[\s\S]*?bindMessageCopyButton\(btn\)/, `${label}: message copy buttons should be rebound`);
    assert.match(panel, /function bindMessageCopyButton\(btn\) \{[\s\S]*?addEventListener\('click'/, `${label}: message copy rebinding should attach a click listener`);
    assert.match(panel, /btn\.__wbCopyBound = true;/, `${label}: message copy binding should use an in-memory flag so restored HTML can rebind`);
    assert.match(panel, /document\.querySelectorAll\('\.code-copy-btn'\)[\s\S]*?addEventListener\('click'/, `${label}: code copy buttons should be rebound`);
    assert.match(panel, /function rebindContinueButtons\(\) \{[\s\S]*?document\.querySelectorAll\('\.continue-btn'\)[\s\S]*?addEventListener\('click', \(\) => continueAgent\(\{[\s\S]*?foreground: btn\.dataset\.foreground === 'true'/, `${label}: restored Continue buttons should be rebound with their foreground mode`);
    assert.match(panel, /function rebindClarifyCards\(\) \{[\s\S]*?document\.querySelectorAll\('\.clarify-card'\)[\s\S]*?submitClarify\(card, tabId, clarifyId/, `${label}: restored clarify cards should be rebound`);
    assert.match(panel, /function rebindScheduleComposers\(\) \{[\s\S]*?document\.querySelectorAll\('form\.schedule-composer'\)[\s\S]*?bindScheduleComposer\(form\)/, `${label}: restored schedule composers should be rebound`);
    assert.match(panel, /function rebindRestoredMessageControls\(\) \{[\s\S]*?rebindCopyButtons\(\);[\s\S]*?rebindContinueButtons\(\);[\s\S]*?rebindClarifyCards\(\);[\s\S]*?rebindScheduleComposers\(\);[\s\S]*?\}/, `${label}: restored tab chat should rebind all durable message controls`);
    assert.match(panel, /card\.dataset\.tabId = String\(tabId\);/, `${label}: clarify cards should persist their target tab for restore rebinding`);
    assert.match(panel, /b\.dataset\.value = value;[\s\S]*?submitClarify\(card, tabId, clarifyId, value, 'option'\)/, `${label}: restored permission choices need stable values, not localized labels`);

    const match = panel.match(/(?:async\s+)?function switchToTab\(newTabId\) \{[\s\S]*?consumePendingContextMenuPrompt\(\)/);
    assert.ok(match, `${label}: switchToTab body missing`);
    const body = match[0];
    const restoreIdx = body.indexOf('messagesEl.innerHTML =');
    const clearBoundIdx = body.indexOf("messagesEl.querySelectorAll('[data-bound]')");
    const rebindIdx = body.indexOf('rebindRestoredMessageControls();');
    assert.notEqual(restoreIdx, -1, `${label}: restored tab chat should write serialized HTML`);
    assert.notEqual(clearBoundIdx, -1, `${label}: restored controls should clear serialized bound markers`);
    assert.notEqual(rebindIdx, -1, `${label}: restored tab chat should rebind interactive controls`);
    assert.equal(restoreIdx < clearBoundIdx && clearBoundIdx < rebindIdx, true, `${label}: control handlers must be rebound immediately after restoring tab chat HTML`);
  }
});

test('chrome sidepanel drops stale async tab-chat restores', () => {
  const panel = fs.readFileSync(path.join(ROOT, 'src/chrome/src/ui/sidepanel.js'), 'utf8');
  assert.match(panel, /let renderedTabId = null;/, 'chrome: sidepanel should track which tab is actually rendered in the DOM');
  const match = panel.match(/async function switchToTab\(newTabId\) \{([\s\S]*?)\n\}/);
  assert.ok(match, 'chrome: switchToTab body missing');
  const body = match[1];
  const setIdx = body.indexOf('currentTabId = newTabId;');
  const loadIdx = body.indexOf('const html = await loadTabChat(newTabId);');
  const guardIdx = body.indexOf('if (switchGeneration !== tabSwitchGeneration || currentTabId !== newTabId) return;');
  const renderedSetIdx = body.indexOf('renderedTabId = newTabId;');
  const restoreIdx = body.indexOf('messagesEl.innerHTML =');
  const consumeIdx = body.indexOf('consumePendingContextMenuPrompt()');
  const flushIdx = body.indexOf('await flushRenderedTabChat();');
  const historyFlushIdx = body.indexOf('await flushChatHistorySnapshot(outgoingTabId);');
  const syncRunFlagsIdx = body.indexOf('syncCurrentTabRunFlags();');
  assert.notEqual(setIdx, -1, 'chrome: switchToTab should set the visible tab before restoring chat');
  assert.notEqual(loadIdx, -1, 'chrome: switchToTab should load persisted tab chat asynchronously');
  assert.notEqual(guardIdx, -1, 'chrome: stale async tab-chat restores should be dropped');
  assert.notEqual(renderedSetIdx, -1, 'chrome: switchToTab should mark the rendered tab only after stale async restores are dropped');
  assert.notEqual(restoreIdx, -1, 'chrome: switchToTab restore point missing');
  assert.notEqual(consumeIdx, -1, 'chrome: switchToTab context-menu consume point missing');
  assert.notEqual(flushIdx, -1, 'chrome: switchToTab should flush rendered chat before changing tabs');
  assert.notEqual(historyFlushIdx, -1, 'chrome: switchToTab should flush rendered history before changing tabs');
  assert.notEqual(syncRunFlagsIdx, -1, 'chrome: switchToTab should restore the destination tab run flags');
  assert.doesNotMatch(body, /if \(isProcessing\)[\s\S]*?pendingTabSwitch = newTabId/, 'chrome: active runs must not defer visible tab switches');
  assert.equal(flushIdx < historyFlushIdx && historyFlushIdx < setIdx, true, 'chrome: pending history snapshots should flush before currentTabId changes');
  assert.equal(setIdx < syncRunFlagsIdx, true, 'chrome: destination run flags should load after currentTabId changes');
  assert.equal(setIdx < loadIdx && loadIdx < guardIdx && guardIdx < renderedSetIdx && renderedSetIdx < restoreIdx && guardIdx < consumeIdx, true, 'chrome: stale guard must run after async chat load and before rendered-tab/DOM/context-menu work');
  assert.match(body, /if \(renderedTabId != null\) \{[\s\S]*?const outgoingTabId = renderedTabId;[\s\S]*?await flushRenderedTabChat\(\);[\s\S]*?await flushChatHistorySnapshot\(outgoingTabId\);[\s\S]*?captureInputDraftForTab\(outgoingTabId\);[\s\S]*?\}/, 'chrome: overlapping tab switches should flush chat/history and save drafts for the tab represented by the DOM');
  assert.doesNotMatch(body, /persistTabChat\(currentTabId,\s*messagesEl\.innerHTML\)|captureInputDraftForTab\(currentTabId\)/, 'chrome: overlapping tab switches must not save DOM or drafts under a pending target tab');
});

test('sidepanel queues target-tab updates and suppresses non-target updates during tab switches', () => {
  for (const [label, panelRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    assert.match(panel, /let tabSwitchTransitionId = null;/, `${label}: tab switches should track the tab currently being restored`);
    assert.match(panel, /let tabSwitchGeneration = 0;/, `${label}: overlapping tab switches should invalidate stale async work`);
    assert.match(panel, /let queuedTabSwitchMessages = \[\];/, `${label}: tab switches should keep target-tab messages that arrive mid-restore`);
    assert.match(panel, /function queueAgentUpdateDuringTabSwitch\(msg\) \{[\s\S]*?tabSwitchTransitionId == null \|\| tabId == null[\s\S]*?if \(tabId === tabSwitchTransitionId\) queuedTabSwitchMessages\.push\(msg\);[\s\S]*?return true;[\s\S]*?\}/, `${label}: target events should queue while non-target events are consumed during a transition`);
    assert.match(panel, /function drainQueuedAgentUpdatesForTab\(tabId\) \{[\s\S]*?queuedTabSwitchMessages = remaining;[\s\S]*?replay\.forEach\(\(msg\) => handleAgentUpdateMessage\(msg\)\);[\s\S]*?\}/, `${label}: queued target-tab messages should replay through the normal agent update handler`);

    const switchMatch = panel.match(/async function switchToTab\(newTabId\) \{([\s\S]*?)\n\}/);
    assert.ok(switchMatch, `${label}: switchToTab body missing`);
    const body = switchMatch[1];
    const markIdx = body.indexOf('tabSwitchTransitionId = newTabId;');
    const flushIdx = body.indexOf('await flushRenderedTabChat();');
    const historyFlushIdx = body.indexOf('await flushChatHistorySnapshot(outgoingTabId);');
    const loadIdx = body.indexOf('loadTabChat(newTabId');
    const clearTransitionIdx = body.indexOf('if (switchGeneration === tabSwitchGeneration && tabSwitchTransitionId === newTabId) tabSwitchTransitionId = null;');
    const replayIdx = body.indexOf('drainQueuedAgentUpdatesForTab(newTabId);');
    const consumeIdx = body.indexOf('consumePendingContextMenuPrompt()');
    assert.notEqual(markIdx, -1, `${label}: switchToTab should mark the target tab before any async flush can yield`);
    assert.notEqual(flushIdx, -1, `${label}: switchToTab flush point missing`);
    assert.notEqual(historyFlushIdx, -1, `${label}: switchToTab history flush point missing`);
    assert.notEqual(loadIdx, -1, `${label}: switchToTab restore load point missing`);
    assert.notEqual(body.indexOf('const switchGeneration = ++tabSwitchGeneration;'), -1, `${label}: switchToTab should invalidate older overlapping transitions`);
    assert.notEqual(body.indexOf('if (switchGeneration !== tabSwitchGeneration) return;'), -1, `${label}: stale transitions should stop after async flushes`);
    assert.notEqual(clearTransitionIdx, -1, `${label}: switchToTab should clear the transition marker after restore settles`);
    assert.notEqual(replayIdx, -1, `${label}: switchToTab should replay queued target-tab messages after restore`);
    assert.notEqual(consumeIdx, -1, `${label}: switchToTab context-menu consume point missing`);
    assert.equal(markIdx < flushIdx && flushIdx < historyFlushIdx && historyFlushIdx < loadIdx && loadIdx < clearTransitionIdx && clearTransitionIdx < replayIdx && replayIdx < consumeIdx, true, `${label}: queued target-tab updates must wait until the async restore has settled`);

    const listenerStart = panel.indexOf("if (msg.target !== 'sidepanel' || msg.action !== 'agent_update') return;");
    assert.notEqual(listenerStart, -1, `${label}: runtime message listener missing`);
    const listenerBody = panel.slice(listenerStart, panel.indexOf('\n});', listenerStart) + 4);
    const queueIdx = listenerBody.indexOf('if (queueAgentUpdateDuringTabSwitch(msg)) return;');
    const handleIdx = listenerBody.indexOf('handleAgentUpdateMessage(msg);');
    assert.notEqual(queueIdx, -1, `${label}: runtime listener should queue target-tab updates during async tab switching`);
    assert.notEqual(handleIdx, -1, `${label}: runtime listener should still pass normal updates to the shared handler`);
    assert.equal(queueIdx < handleIdx, true, `${label}: target-tab updates should be queued before scheduled-job or tab filters can drop them`);
  }
});

test('sidepanel clears shared activity while restoring an idle destination tab', () => {
  for (const [label, panelRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    const switchMatch = panel.match(/async function switchToTab\(newTabId\) \{([\s\S]*?)\n\}/);
    assert.ok(switchMatch, `${label}: switchToTab body missing`);
    const switchBody = switchMatch[1];
    const transitionIdx = switchBody.indexOf('tabSwitchTransitionId = newTabId;');
    const hideIdx = switchBody.indexOf('hideActivity();', transitionIdx);
    const firstAwaitIdx = switchBody.indexOf('await flushRenderedTabChat();');
    const replayIdx = switchBody.indexOf('drainQueuedAgentUpdatesForTab(newTabId);');
    assert.notEqual(hideIdx, -1, `${label}: tab switches should clear the outgoing activity strip`);
    assert.notEqual(firstAwaitIdx, -1, `${label}: tab-switch async restore boundary missing`);
    assert.notEqual(replayIdx, -1, `${label}: queued destination updates should still replay`);
    assert.equal(transitionIdx < hideIdx && hideIdx < firstAwaitIdx, true, `${label}: outgoing activity must clear before async tab restore can yield`);
    assert.equal(hideIdx < replayIdx, true, `${label}: queued destination updates must replay after the transient reset`);

    const restoreStart = panel.indexOf('async function restoreActiveRunState(tabId = currentTabId)');
    const restoreEnd = panel.indexOf('\nfunction conversationHasUserMessages()', restoreStart);
    assert.notEqual(restoreStart, -1, `${label}: active-run restore helper missing`);
    assert.notEqual(restoreEnd, -1, `${label}: active-run restore helper boundary missing`);
    const restoreBody = panel.slice(restoreStart, restoreEnd);
    const runningIdx = restoreBody.indexOf('if (state?.running || state?.starting) {');
    const idleIdx = restoreBody.indexOf('} else {', runningIdx);
    const runningBody = restoreBody.slice(runningIdx, idleIdx);
    const idleBody = restoreBody.slice(idleIdx);
    const clearProcessingIdx = idleBody.indexOf('setTabProcessing(numericTabId, false);');
    const idleHideIdx = idleBody.indexOf('hideActivity();');
    const syncComposerIdx = idleBody.indexOf('syncSendButtonState();');
    assert.match(runningBody, /startThinkingActivity\(\);/, `${label}: a running destination should restore its activity strip`);
    assert.notEqual(clearProcessingIdx, -1, `${label}: idle restore should clear destination processing state`);
    assert.notEqual(idleHideIdx, -1, `${label}: idle restore should hide stale activity even when terminal replay is already acknowledged`);
    assert.notEqual(syncComposerIdx, -1, `${label}: idle restore should resync composer controls`);
    assert.equal(clearProcessingIdx < idleHideIdx && idleHideIdx < syncComposerIdx, true, `${label}: idle activity and composer state should settle after processing is cleared`);

    const drainHelperStart = panel.indexOf('function drainQueuedAgentUpdatesForTab(tabId)');
    const drainHelperEnd = panel.indexOf('\nasync function settleScheduledRun', drainHelperStart);
    const drainHelperBody = panel.slice(drainHelperStart, drainHelperEnd);
    assert.match(drainHelperBody, /replay\.forEach\(\(msg\) => handleAgentUpdateMessage\(msg\)\);/, `${label}: queued destination updates should re-enter the normal renderer`);
    const updateHandlerStart = panel.indexOf('function handleAgentUpdateMessage(msg)');
    const thinkingStart = panel.indexOf("case 'thinking':", updateHandlerStart);
    const textStart = panel.indexOf("case 'text':", thinkingStart);
    const thinkingBody = panel.slice(thinkingStart, textStart);
    assert.match(thinkingBody, /showActivity\(/, `${label}: a queued thinking update should be able to show activity again after reset`);
  }
});

test('sidepanel hydrates restored history ids before fallback records', () => {
  for (const [label, panelRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    const htmlHelperMatch = panel.match(/function chatHistoryHtmlHasUserMessage\(html\) \{([\s\S]*?)\n\}/);
    assert.ok(htmlHelperMatch, `${label}: restored history user-message helper missing`);
    const htmlHelper = htmlHelperMatch[1];
    assert.ok(htmlHelper.includes("document.createElement('div')"), `${label}: restored history helper should parse restored HTML off-DOM`);
    assert.ok(htmlHelper.includes("wrapper.innerHTML = String(html || '');"), `${label}: restored history helper should inspect the restored HTML`);
    assert.ok(htmlHelper.includes("classList?.contains('message')"), `${label}: restored history helper should look for message elements`);
    assert.ok(htmlHelper.includes("classList.contains('user')"), `${label}: restored history hydration should only run for chats with user messages`);
    assert.match(panel, /async function hydrateRestoredChatHistory\(tabId, html\) \{[\s\S]*?if \(!html \|\| !chatHistoryHtmlHasUserMessage\(html\)\) return;[\s\S]*?await hydrateChatHistoryIdentity\(tabId, agentMode\);[\s\S]*?\}/, `${label}: restored chat helper should hydrate history ids before DOM restore`);
    assert.match(panel, /async function hydrateChatHistoryIdentity\(tabId, mode = agentMode, \{ allowFallback = false, refreshTabInfo = false \} = \{\}\) \{[\s\S]*?sendToBackground\('ensure_conversation_id'[\s\S]*?chatHistoryConversationIdsByTab\.set\(numericTabId, identity\.conversationId\);[\s\S]*?chatHistoryRecordIdsByTab\.set\(numericTabId, identity\.conversationId\);[\s\S]*?else if \(allowFallback && !chatHistoryRecordIdsByTab\.has\(numericTabId\)\) \{[\s\S]*?fallbackHistoryRecordId\(numericTabId\);/, `${label}: history identity helper should hydrate conversation ids before allowing fallback records`);
    assert.match(panel, /async function prepareChatHistoryForTurn\(tabId, mode\) \{\s*await hydrateChatHistoryIdentity\(tabId, mode, \{ allowFallback: true, refreshTabInfo: true \}\);\s*\}/, `${label}: send and continue preflight should use the shared history identity helper`);

    const switchMatch = panel.match(/async function switchToTab\(newTabId\) \{([\s\S]*?)\n\}/);
    assert.ok(switchMatch, `${label}: switchToTab body missing`);
    const switchBody = switchMatch[1];
    const loadIdx = switchBody.indexOf('loadTabChat(newTabId');
    const restoredHasUserIdx = switchBody.indexOf('if (html) {');
    const hydrateRestoredIdx = switchBody.indexOf('await hydrateRestoredChatHistory(newTabId, html);');
    const postHydrateGuardIdx = switchBody.indexOf('if (switchGeneration !== tabSwitchGeneration || currentTabId !== newTabId) return;', hydrateRestoredIdx);
    const restoreDomIdx = switchBody.indexOf('messagesEl.innerHTML = html;');
    assert.notEqual(loadIdx, -1, `${label}: switchToTab should load persisted tab chat`);
    assert.notEqual(restoredHasUserIdx, -1, `${label}: switchToTab should detect restored user chats before DOM insertion`);
    assert.notEqual(hydrateRestoredIdx, -1, `${label}: switchToTab should hydrate restored chat history ids`);
    assert.notEqual(postHydrateGuardIdx, -1, `${label}: switchToTab should drop stale restores after async history hydration`);
    assert.notEqual(restoreDomIdx, -1, `${label}: switchToTab should restore chat HTML`);
    assert.equal(loadIdx < restoredHasUserIdx && restoredHasUserIdx < hydrateRestoredIdx && hydrateRestoredIdx < postHydrateGuardIdx && postHydrateGuardIdx < restoreDomIdx, true, `${label}: restored chat ids must hydrate before the MutationObserver sees restored HTML`);

    const initMatch = panel.match(/async function init\(\) \{([\s\S]*?)\n  restoreLatestChatTurnPosition\(\);/);
    assert.ok(initMatch, `${label}: init restore block missing`);
    const initBody = initMatch[1];
    const initLoadIdx = initBody.indexOf('loadTabChat(restoreTabId, { waitForHandoff: true })');
    const initHydrateIdx = initBody.indexOf('await hydrateRestoredChatHistory(restoreTabId, html);');
    const initGuardIdx = initBody.indexOf('if (currentTabId === restoreTabId) {', initHydrateIdx);
    const initDomIdx = initBody.indexOf('messagesEl.innerHTML = html;', initGuardIdx);
    const initObserveIdx = initBody.indexOf('persistObserver.observe(messagesEl');
    const initRepairIdx = initBody.indexOf('await repairRestoredChatHistorySnapshot(restoreTabId);');
    assert.notEqual(initLoadIdx, -1, `${label}: init should load restored tab chat`);
    assert.notEqual(initHydrateIdx, -1, `${label}: init should hydrate restored chat history ids`);
    assert.notEqual(initGuardIdx, -1, `${label}: init should recheck the active tab after hydration`);
    assert.notEqual(initDomIdx, -1, `${label}: init should restore chat HTML after hydration`);
    assert.notEqual(initObserveIdx, -1, `${label}: init persistence observer missing`);
    assert.notEqual(initRepairIdx, -1, `${label}: init should content-repair restored durable history snapshots`);
    assert.equal(initLoadIdx < initHydrateIdx && initHydrateIdx < initGuardIdx && initGuardIdx < initDomIdx, true, `${label}: startup restore must hydrate ids before restoring HTML`);
    assert.equal(initDomIdx < initObserveIdx && initObserveIdx < initRepairIdx, true, `${label}: startup should repair history after restoring and observing the chat DOM`);

    const persistMatch = panel.match(/async function persistChatHistorySnapshot\(tabId, \{ refreshTabInfo = false \} = \{\}\) \{([\s\S]*?)\n\}/);
    assert.ok(persistMatch, `${label}: persistChatHistorySnapshot missing`);
    const persistBody = persistMatch[1];
    const hydrateIdx = persistBody.indexOf('await hydrateChatHistoryIdentity(numericTabId, agentMode, { refreshTabInfo });');
    const recordIdx = persistBody.indexOf('const recordId = chatHistoryRecordIdsByTab.get(numericTabId) || fallbackHistoryRecordId(numericTabId);');
    const saveIdx = persistBody.indexOf('await saveChatHistoryRecord({');
    assert.notEqual(hydrateIdx, -1, `${label}: history snapshots should try to hydrate conversation identity`);
    assert.notEqual(recordIdx, -1, `${label}: history snapshots should still have a local fallback`);
    assert.notEqual(saveIdx, -1, `${label}: history snapshots should save a record`);
    assert.equal(hydrateIdx < recordIdx && recordIdx < saveIdx, true, `${label}: snapshots must hydrate ids before minting a fallback record`);
  }
});

test('sidepanel deletes durable history when clearing conversations', () => {
  for (const [label, panelRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    assert.match(panel, /import \{[\s\S]*?deleteChatHistoryRecord,[\s\S]*?saveChatHistoryRecord,[\s\S]*?\} from '\.\/chat-history-store\.js';/, `${label}: sidepanel should import durable history deletion`);

    const resetMatch = panel.match(/async function resetChatHistoryStateForTab\(tabId\) \{([\s\S]*?)\n\}/);
    assert.ok(resetMatch, `${label}: resetChatHistoryStateForTab should be async`);
    const resetBody = resetMatch[1];
    const recordSetIdx = resetBody.indexOf('const recordIdsToDelete = new Set([');
    const activeRecordIdx = resetBody.indexOf('chatHistoryRecordIdsByTab.get(numericTabId)');
    const conversationRecordIdx = resetBody.indexOf('chatHistoryConversationIdsByTab.get(numericTabId)');
    const deleteIdx = resetBody.indexOf('deleteChatHistoryRecord(recordId)');
    const mapDeleteIdx = resetBody.indexOf('chatHistoryRecordIdsByTab.delete(numericTabId)');
    const hydrateMissingIdx = resetBody.indexOf('await hydrateChatHistoryIdentity(numericTabId, agentMode);');
    assert.notEqual(recordSetIdx, -1, `${label}: reset should collect durable record ids before clearing maps`);
    assert.notEqual(activeRecordIdx, -1, `${label}: reset should delete the active history record id`);
    assert.notEqual(conversationRecordIdx, -1, `${label}: reset should also delete the conversation id record`);
    assert.notEqual(hydrateMissingIdx, -1, `${label}: reset should hydrate restored ids before collecting records to delete`);
    assert.notEqual(deleteIdx, -1, `${label}: reset should delete IndexedDB history records`);
    assert.notEqual(mapDeleteIdx, -1, `${label}: reset should clear in-memory history ids`);
    assert.equal(hydrateMissingIdx < recordSetIdx && recordSetIdx < deleteIdx && activeRecordIdx < deleteIdx && conversationRecordIdx < deleteIdx && deleteIdx < mapDeleteIdx, true, `${label}: durable history must be hydrated and deleted before in-memory ids are dropped`);

    const helperStart = panel.indexOf('async function renderClearedConversationForTab(tabId, { allowCacheClearFailure = false } = {})');
    assert.notEqual(helperStart, -1, `${label}: clear helper should be async`);
    const helperBody = panel.slice(helperStart, panel.indexOf('refreshRecommendedActions();', helperStart) + 'refreshRecommendedActions();'.length);
    assert.match(helperBody, /await clearCachedTabChat\(tabId\);[\s\S]*?await resetChatHistoryStateForTab\(tabId\);[\s\S]*?if \(currentTabId !== tabId\) return;/, `${label}: clear helper should durably clear tab chat before deleting history and checking visibility`);
    assert.match(helperBody, /messagesEl\.innerHTML = '';[\s\S]*?const clearedHtml = messagesEl\.innerHTML;[\s\S]*?lastVisibleTabChatSnapshot = \{ tabId: Number\(tabId\), html: clearedHtml \};[\s\S]*?await persistTabChat\(tabId, clearedHtml, \{ allowHidden: true \}\)/, `${label}: a cleared handoff snapshot should persist an actually empty transcript so the empty state can return`);
    assert.doesNotMatch(helperBody, /addMessage\('system'/, `${label}: clearing should not turn empty-state guidance back into a message bubble`);

    const resetIdx = panel.indexOf("if (command.value === '/reset')");
    const resetSlashBody = panel.slice(resetIdx, panel.indexOf("if (command.value === '/screenshot'", resetIdx));
    assert.match(resetSlashBody, /await sendToBackground\('clear_conversation', \{ tabId \}\);[\s\S]*?await renderClearedConversationForTab\(tabId\);/, `${label}: /reset should await durable history deletion`);

    const clearStart = panel.indexOf('async function startNewConversationForTab(tabId) {');
    const clearBody = panel.slice(clearStart, panel.indexOf("\n\nclearBtn.addEventListener", clearStart));
    assert.match(clearBody, /await sendToBackground\('clear_conversation', \{ tabId, clearContextMenuPrompt: true \}\);[\s\S]*?await renderClearedConversationForTab\(tabId\);/, `${label}: shared new-conversation action should await durable prompt and history deletion`);
  }
});

test('sidepanel ignores stale async history snapshot saves', () => {
  for (const [label, panelRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    assert.match(panel, /const chatHistorySaveSeqByTab = new Map\(\);[\s\S]*?let chatHistorySaveSeq = 0;/, `${label}: history snapshots should track per-tab save sequence`);
    assert.match(panel, /function nextChatHistorySaveSeqForTab\(tabId\) \{[\s\S]*?chatHistorySaveSeq \+= 1;[\s\S]*?chatHistorySaveSeqByTab\.set\(numericTabId, chatHistorySaveSeq\);[\s\S]*?return chatHistorySaveSeq;[\s\S]*?\}/, `${label}: history snapshot sequence helper missing`);

    const persistStart = panel.indexOf('async function persistChatHistorySnapshot(tabId, { refreshTabInfo = false } = {}) {');
    assert.notEqual(persistStart, -1, `${label}: persistChatHistorySnapshot missing`);
    const persistBody = panel.slice(persistStart, panel.indexOf('\n}\n\nfunction scheduleHistoryPersist', persistStart) + 2);
    const userCheckIdx = persistBody.indexOf("if (!messages.some((message) => message.role === 'user')) return;");
    const stampIdx = persistBody.indexOf('const saveSeq = nextChatHistorySaveSeqForTab(numericTabId);');
    const hydrateIdx = persistBody.indexOf('await hydrateChatHistoryIdentity(numericTabId, agentMode, { refreshTabInfo });');
    const staleGuardIdx = persistBody.indexOf('if (chatHistorySaveSeqByTab.get(numericTabId) !== saveSeq) return;');
    const saveIdx = persistBody.indexOf('await saveChatHistoryRecord({');
    assert.notEqual(userCheckIdx, -1, `${label}: snapshots should skip conversations without user messages`);
    assert.notEqual(stampIdx, -1, `${label}: snapshots should stamp async saves`);
    assert.notEqual(hydrateIdx, -1, `${label}: snapshots should hydrate identity before saving`);
    assert.notEqual(staleGuardIdx, -1, `${label}: snapshots should skip stale async saves`);
    assert.notEqual(saveIdx, -1, `${label}: snapshots should save only after stale guard`);
    assert.equal(userCheckIdx < stampIdx && stampIdx < hydrateIdx && hydrateIdx < staleGuardIdx && staleGuardIdx < saveIdx, true, `${label}: stale snapshot guard must run before writing history`);

    const resetMatch = panel.match(/async function resetChatHistoryStateForTab\(tabId\) \{([\s\S]*?)\n\}/);
    assert.ok(resetMatch, `${label}: resetChatHistoryStateForTab missing`);
    const resetBody = resetMatch[1];
    const invalidateIdx = resetBody.indexOf('nextChatHistorySaveSeqForTab(numericTabId);');
    const hydrateMissingIdx = resetBody.indexOf('await hydrateChatHistoryIdentity(numericTabId, agentMode);');
    const recordSetIdx = resetBody.indexOf('const recordIdsToDelete = new Set([');
    const mapDeleteIdx = resetBody.indexOf('chatHistorySaveSeqByTab.delete(numericTabId);');
    assert.notEqual(invalidateIdx, -1, `${label}: reset should invalidate in-flight history saves`);
    assert.notEqual(hydrateMissingIdx, -1, `${label}: reset should hydrate restored ids after invalidating saves`);
    assert.notEqual(recordSetIdx, -1, `${label}: reset should collect record ids after invalidating saves`);
    assert.notEqual(mapDeleteIdx, -1, `${label}: reset should clear save sequence state after deleting history`);
    assert.equal(invalidateIdx < hydrateMissingIdx && hydrateMissingIdx < recordSetIdx && recordSetIdx < mapDeleteIdx, true, `${label}: clear/reset must invalidate stale saves before async deletion work`);
  }
});

test('chrome sidepanel persists tab chat to the tab captured before debounce', () => {
  const panel = fs.readFileSync(path.join(ROOT, 'src/chrome/src/ui/sidepanel.js'), 'utf8');
  const start = panel.indexOf('function schedulePersist() {');
  assert.notEqual(start, -1, 'chrome: schedulePersist missing');
  const body = panel.slice(start, panel.indexOf('\n}\n\n// Observe', start) + 2);
  const captureTabIdx = body.indexOf('const tabId = renderedTabId;');
  const captureHtmlIdx = body.indexOf('const html = messagesEl.innerHTML;');
  const timerIdx = body.indexOf('persistTimer = setTimeout(() => {');
  const persistIdx = body.indexOf('persistTabChat(tabId, html);');
  assert.notEqual(captureTabIdx, -1, 'chrome: persistence should capture the rendered tab id before the debounce delay');
  assert.notEqual(captureHtmlIdx, -1, 'chrome: persistence should capture the chat HTML before the debounce delay');
  assert.notEqual(timerIdx, -1, 'chrome: persistence debounce missing');
  assert.notEqual(persistIdx, -1, 'chrome: persistence should write the captured tab/html');
  assert.equal(captureTabIdx < timerIdx && captureHtmlIdx < timerIdx && timerIdx < persistIdx, true, 'chrome: persistence must not read mutable tab state after the debounce delay');
  assert.doesNotMatch(body, /persistTabChat\(currentTabId,\s*messagesEl\.innerHTML\)/, 'chrome: debounced persistence should not save live DOM under the later currentTabId');
});

test('sidepanel flushes run chat before queue settlement after immediate tab switches', () => {
  for (const [label, panelRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');

    if (label === 'chrome' || label === 'firefox') {
      assert.match(
        panel,
        /async function flushRenderedTabChat\(\{ allowHidden = false \} = \{\}\) \{[\s\S]*?const tabId = renderedTabId;[\s\S]*?if \(persistTimer && persistTimerTabId === tabId\) \{[\s\S]*?clearTimeout\(persistTimer\);[\s\S]*?\}[\s\S]*?const html = messagesEl\.innerHTML;[\s\S]*?await persistTabChat\(tabId, html, \{ allowHidden \}\);[\s\S]*?\}/,
        `${label}: final flush should cancel stale debounced writes and persist the rendered tab immediately`,
      );
    }

    const sendMatch = panel.match(/async function sendMessage\([^)]*\) \{[\s\S]*?finally \{([\s\S]*?)\n  \}\n  return accepted;/);
    assert.ok(sendMatch, `${label}: sendMessage finally block missing`);
    const sendFinally = sendMatch[1];
    const sendFlushIdx = sendFinally.indexOf('flushRenderedTabChat()');
    const sendDrainIdx = sendFinally.indexOf('await drainQueuedPromptsAfterRunSettles(tabId);');
    assert.notEqual(sendFlushIdx, -1, `${label}: send completion should flush the final transcript`);
    assert.notEqual(sendDrainIdx, -1, `${label}: send completion should drain queued prompts`);
    assert.equal(sendFlushIdx < sendDrainIdx, true, `${label}: send completion must flush before draining queued prompts`);

    const continueMatch = panel.match(/async function continueAgent\(options = \{\}\) \{[\s\S]*?finally \{([\s\S]*?)\n  \}\n\}/);
    assert.ok(continueMatch, `${label}: continueAgent finally block missing`);
    const continueFinally = continueMatch[1];
    const continueFlushIdx = continueFinally.indexOf('flushRenderedTabChat()');
    const continueDrainIdx = continueFinally.indexOf('await drainQueuedPromptsAfterRunSettles(tabId);');
    assert.notEqual(continueFlushIdx, -1, `${label}: Continue completion should flush the final transcript`);
    assert.notEqual(continueDrainIdx, -1, `${label}: Continue completion should drain queued prompts`);
    assert.equal(continueFlushIdx < continueDrainIdx, true, `${label}: Continue completion must flush before draining queued prompts`);

    const scheduledStart = panel.search(/(?:async\s+)?function settleScheduledRun\(event, job, tabId = currentTabId\)/);
    const scheduledEnd = panel.search(/(?:async\s+)?function handleScheduledJobEvent\(data, tabId\)/);
    assert.notEqual(scheduledStart, -1, `${label}: scheduled settlement helper missing`);
    assert.notEqual(scheduledEnd, -1, `${label}: scheduled event handler boundary missing`);
    const scheduledBody = panel.slice(scheduledStart, scheduledEnd);
    const scheduledFlushNeedle = 'await flushRenderedTabChat()';
    const scheduledDrainNeedle = 'await drainQueuedPromptsAfterRunSettles(runTabId);';
    const scheduledFlushIdx = scheduledBody.indexOf(scheduledFlushNeedle);
    const scheduledDrainIdx = scheduledBody.indexOf(scheduledDrainNeedle);
    assert.notEqual(scheduledFlushIdx, -1, `${label}: scheduled completion should flush the final transcript`);
    assert.notEqual(scheduledDrainIdx, -1, `${label}: scheduled completion should drain queued prompts`);
    assert.equal(scheduledFlushIdx < scheduledDrainIdx, true, `${label}: scheduled completion must flush before draining queued prompts`);

    const abortStart = panel.indexOf('const settleWhenInactive = async () => {');
    const abortEnd = panel.indexOf('fallbackTimer = setTimeout(settleWhenInactive, 3000);', abortStart);
    assert.notEqual(abortStart, -1, `${label}: abort safety timeout body missing`);
    assert.notEqual(abortEnd, -1, `${label}: abort safety timeout registration missing`);
    const abortBody = panel.slice(abortStart, abortEnd);
    const abortFlushIdx = abortBody.indexOf('flushRenderedTabChat()');
    const abortDrainIdx = abortBody.indexOf('await drainQueuedPromptsAfterRunSettles(tabId);');
    assert.notEqual(abortFlushIdx, -1, `${label}: abort timeout should flush the stopped transcript`);
    assert.notEqual(abortDrainIdx, -1, `${label}: abort timeout should drain queued prompts`);
    assert.equal(abortFlushIdx < abortDrainIdx, true, `${label}: abort timeout must flush before draining queued prompts`);
  }
});

test('tab-chat persistence recovers when several sub-threshold chats exceed the shared quota', async () => {
  for (const [label, persistence] of [
    ['chrome', TabChatPersistenceCh],
    ['firefox', TabChatPersistenceFx],
  ]) {
    const values = {};
    const quota = 10 * 1024 * 1024;
    const storageArea = {
      async get(query) {
        if (query == null) return { ...values };
        if (typeof query === 'string') return { [query]: values[query] };
        return { ...values };
      },
      async set(patch) {
        const next = { ...values, ...patch };
        const bytes = Object.entries(next)
          .reduce((total, [key, value]) => total + key.length + String(value).length, 0);
        if (bytes > quota) throw new Error('QUOTA_BYTES exceeded');
        Object.assign(values, patch);
      },
    };
    const warnings = [];
    const imagePayload = 'A'.repeat(6 * 1024 * 1024);
    const firstHtml = `<div class="message"><img src="data:image/png;base64,${imagePayload}"></div>`;
    const secondHtml = `<div class="message"><img src="data:image/webp;base64,${imagePayload}"></div>`;
    const firstKey = persistence.TAB_CHAT_PREFIX + '1';
    const secondKey = persistence.TAB_CHAT_PREFIX + '2';

    const first = await persistence.persistTabChatToSession(storageArea, firstKey, firstHtml, (...args) => warnings.push(args));
    assert.equal(first.ok, true, `${label}: first sub-threshold chat should persist`);
    assert.equal(first.recoveredFromQuota, false, `${label}: first write should not need recovery`);
    assert.equal(values[firstKey], firstHtml, `${label}: normal stored copy should retain its image`);

    const second = await persistence.persistTabChatToSession(storageArea, secondKey, secondHtml, (...args) => warnings.push(args));
    assert.equal(second.ok, true, `${label}: aggregate quota failure should recover`);
    assert.equal(second.recoveredFromQuota, true, `${label}: second write should retry with a bounded stored copy`);
    assert.equal(warnings.length, 0, `${label}: recovered quota writes should not warn`);
    assert.equal(values[firstKey], firstHtml, `${label}: recovery should not rewrite unrelated tab chats`);
    assert.match(values[secondKey], /data:image\/png;base64,iVBOR/, `${label}: second stored image should be compacted`);
    assert.ok(values[secondKey].length < 2048, `${label}: second compacted chat should be small`);
    assert.equal(firstHtml.includes(imagePayload), true, `${label}: caller's in-memory HTML must remain unchanged`);

    const textOnly = `<div class="message">${'recent '.repeat(20 * 1024)}</div>`;
    const bounded = persistence.compactTabChatForPersist(textOnly, 64 * 1024);
    assert.ok(bounded.length <= 64 * 1024, `${label}: text-only fallback must respect its budget`);
    assert.match(bounded, /^<div class="message system">/, `${label}: text-only fallback should remain valid message markup`);
    assert.match(bounded, /<\/div><\/div>$/, `${label}: text-only fallback should close its markup`);

    const whitespaceClosedRawText = `<div>${'visible text '.repeat(300)}<script>LEAK_SCRIPT</script ><style>LEAK_STYLE</style ></div>`;
    const whitespaceClosedFallback = persistence.compactTabChatForPersist(whitespaceClosedRawText, 1024);
    assert.doesNotMatch(whitespaceClosedFallback, /LEAK_SCRIPT|LEAK_STYLE/, `${label}: whitespace before raw-text end-tag brackets must not leak script/style text`);
    assert.match(whitespaceClosedFallback, /visible text/, `${label}: safe readable text should survive raw-text removal`);
  }
});

test('tab-chat persistence never evicts other chats when shared quota remains exhausted', async () => {
  for (const [label, persistence] of [
    ['chrome', TabChatPersistenceCh],
    ['firefox', TabChatPersistenceFx],
  ]) {
    const values = { unrelatedSessionState: 'keep' };
    const quota = 10 * 1024 * 1024;
    const storageBytes = (next) => Object.entries(next)
      .reduce((total, [storedKey, value]) => total + storedKey.length + String(value).length, 0);
    const storageArea = {
      async get(query) {
        if (query == null) return { ...values };
        if (typeof query === 'string') return { [query]: values[query] };
        return { ...values };
      },
      async set(patch) {
        const next = { ...values, ...patch };
        if (storageBytes(next) > quota) throw new Error('QUOTA_BYTES exceeded');
        Object.assign(values, patch);
      },
      async remove(keys) {
        for (const storedKey of Array.isArray(keys) ? keys : [keys]) delete values[storedKey];
      },
    };
    const oldKey = persistence.TAB_CHAT_PREFIX + 'older';
    const newKey = persistence.TAB_CHAT_PREFIX + 'current';
    const fixedBytes = storageBytes(values) + oldKey.length;
    values[oldKey] = 'x'.repeat(quota - fixedBytes - 64);
    const source = `<div class="message">${'recent text '.repeat(80 * 1024)}</div>`;
    const warnings = [];

    const result = await persistence.persistTabChatToSession(
      storageArea,
      newKey,
      source,
      (...args) => warnings.push(args),
    );

    assert.equal(result.ok, false, `${label}: saturated shared quota should report non-durable persistence`);
    assert.equal(values[oldKey]?.length > 0, true, `${label}: another tab's chat must not be evicted`);
    assert.equal(values[newKey], undefined, `${label}: failed current snapshot should not be advertised as stored`);
    assert.equal(values.unrelatedSessionState, 'keep', `${label}: non-chat session state must not be evicted`);
    assert.equal(warnings.length, 1, `${label}: failed bounded persistence should warn once`);
  }
});

test('tab-chat quota recovery removes only a provably closed tab chat', async () => {
  const originalChrome = globalThis.chrome;
  const originalBrowser = globalThis.browser;
  try {
    for (const [label, persistence, runtimeKey] of [
      ['chrome', TabChatPersistenceCh, 'chrome'],
      ['firefox', TabChatPersistenceFx, 'browser'],
    ]) {
      delete globalThis.chrome;
      delete globalThis.browser;
      globalThis[runtimeKey] = {
        tabs: {
          async get(tabId) {
            if (tabId === 41) throw new Error('No tab with id: 41');
            if (tabId === 40) throw new Error('Tabs API temporarily unavailable');
            return { id: tabId };
          },
        },
      };
      const quota = 1200 * 1024;
      const values = { unrelatedSessionState: 'keep' };
      const unknownKey = persistence.TAB_CHAT_PREFIX + '40';
      const staleKey = persistence.TAB_CHAT_PREFIX + '41';
      const openKey = persistence.TAB_CHAT_PREFIX + '42';
      const currentKey = persistence.TAB_CHAT_PREFIX + '43';
      values[unknownKey] = 'u'.repeat(750 * 1024);
      values[staleKey] = 's'.repeat(700 * 1024);
      values[openKey] = 'o'.repeat(300 * 1024);
      const storageBytes = next => Object.entries(next)
        .reduce((total, [storedKey, value]) => total + storedKey.length + String(value).length, 0);
      const storageArea = {
        async get() { return { ...values }; },
        async set(patch) {
          const next = { ...values, ...patch };
          if (storageBytes(next) > quota) throw new Error('QUOTA_BYTES exceeded');
          Object.assign(values, patch);
        },
        async remove(key) { delete values[key]; },
      };

      const result = await persistence.persistTabChatToSession(
        storageArea,
        currentKey,
        `<div>${'current '.repeat(80 * 1024)}</div>`,
      );
      assert.equal(result.ok, true, `${label}: stale closed-tab data should unblock persistence`);
      assert.deepEqual(result.evictedKeys, [staleKey], `${label}: only the closed tab should be reclaimed`);
      assert.equal(values[staleKey], undefined, `${label}: closed tab chat was retained`);
      assert.equal(values[unknownKey]?.length > 0, true, `${label}: a tab with unknown liveness was evicted`);
      assert.equal(values[openKey]?.length > 0, true, `${label}: open tab chat was evicted`);
      assert.equal(typeof values[currentKey], 'string', `${label}: current compact snapshot was not stored`);
      assert.equal(values.unrelatedSessionState, 'keep', `${label}: unrelated session state changed`);
    }
  } finally {
    if (originalChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = originalChrome;
    if (originalBrowser === undefined) delete globalThis.browser;
    else globalThis.browser = originalBrowser;
  }
});

test('tab-chat handoff coordinator orders a returning-panel read behind the outgoing snapshot', async () => {
  for (const [label, persistence] of [
    ['chrome', TabChatPersistenceCh],
    ['firefox', TabChatPersistenceFx],
  ]) {
    const values = { [`${persistence.TAB_CHAT_PREFIX}7`]: '<div>stale</div>' };
    const writes = [];
    let acknowledgeHandoff;
    let requestedHandoff = null;
    let signalHandoffRequest;
    let nextRemoveError = null;
    let nextSetError = null;
    const handoffAcknowledged = new Promise(resolve => { acknowledgeHandoff = resolve; });
    const handoffRequested = new Promise(resolve => { signalHandoffRequest = resolve; });
    const storageArea = {
      async get(key) {
        return { [key]: values[key] };
      },
      async set(patch) {
        if (nextSetError) {
          const error = nextSetError;
          nextSetError = null;
          throw error;
        }
        if (Object.hasOwn(patch, `${persistence.TAB_CHAT_PREFIX}7`)) {
          writes.push(patch[`${persistence.TAB_CHAT_PREFIX}7`]);
        }
        Object.assign(values, patch);
      },
      async remove(keys) {
        if (nextRemoveError) {
          const error = nextRemoveError;
          nextRemoveError = null;
          throw error;
        }
        for (const key of Array.isArray(keys) ? keys : [keys]) delete values[key];
      },
    };
    const coordinator = persistence.createTabChatHandoffCoordinator(storageArea, {
      requestHandoff: async (tabId, handoff) => {
        requestedHandoff = { tabId, ...handoff };
        signalHandoffRequest();
        return handoffAcknowledged;
      },
    });

    const outgoing = await coordinator.load(7, {
      waitForHandoff: true,
      claimantId: 'outgoing-panel',
    });
    assert.equal(outgoing.handoffGeneration, 1, `${label}: the first visible panel should own generation one`);

    // Model a service-worker/message delay longer than the removed settling
    // timer: the restore must remain pending until the exact outgoing
    // generation acknowledges its final lossless snapshot.
    let restoreSettled = false;
    const restore = coordinator.load(7, {
      waitForHandoff: true,
      claimantId: 'returning-panel',
    }).finally(() => { restoreSettled = true; });
    await handoffRequested;
    assert.equal(restoreSettled, false, `${label}: restore must wait for an explicit handoff acknowledgement`);
    assert.deepEqual(
      requestedHandoff,
      { tabId: 7, ownerId: 'outgoing-panel', generation: 1 },
      `${label}: the barrier should target the current owner generation`,
    );
    acknowledgeHandoff({
      ok: true,
      ownerId: requestedHandoff.ownerId,
      generation: requestedHandoff.generation,
      html: '<div>fresh</div>',
    });

    const restored = await restore;
    assert.deepEqual(writes, ['<div>fresh</div>'], `${label}: final snapshot should be the coordinated write`);
    assert.deepEqual(
      restored,
      {
        ok: true,
        found: true,
        html: '<div>fresh</div>',
        handoffOwnerId: 'returning-panel',
        handoffGeneration: 2,
      },
      `${label}: returning panel must restore the final outgoing snapshot`,
    );
    const staleWrite = await coordinator.save(7, '<div>late stale</div>', {
      ownerId: 'outgoing-panel',
      handoffGeneration: 1,
    });
    assert.equal(staleWrite.skipped, true, `${label}: a late write from the old generation must be rejected`);
    assert.equal(values[`${persistence.TAB_CHAT_PREFIX}7`], '<div>fresh</div>', `${label}: stale delivery must not overwrite the acknowledged snapshot`);

    const cleared = await coordinator.clear(7, {
      ownerId: 'returning-panel',
      handoffGeneration: 2,
    });
    assert.equal(cleared.ok, true, `${label}: the visible owner should clear its transcript`);
    assert.equal(cleared.handoffGeneration, 3, `${label}: clear should rotate the visible owner's generation`);
    assert.equal(values[`${persistence.TAB_CHAT_PREFIX}7`], undefined, `${label}: clear should remove transcript content`);
    assert.deepEqual(
      values[`${persistence.TAB_CHAT_HANDOFF_PREFIX}7`],
      { ownerId: 'returning-panel', generation: 3 },
      `${label}: clear should preserve the visible document's ownership under a fresh generation`,
    );
    const capturedAcknowledgementWrite = await coordinator.save(7, '<div>captured before clear</div>', {
      ownerId: 'returning-panel',
      handoffGeneration: 2,
    });
    assert.equal(capturedAcknowledgementWrite.skipped, true, `${label}: a pre-clear acknowledgement delivered after clear must be rejected`);
    assert.equal(values[`${persistence.TAB_CHAT_PREFIX}7`], undefined, `${label}: a delayed pre-clear acknowledgement must not restore cleared content`);
    const unversionedWrite = await coordinator.save(7, '<div>unversioned stale</div>', {
      ownerId: 'returning-panel',
    });
    assert.equal(unversionedWrite.skipped, true, `${label}: owner-tagged writes without a generation must fail closed`);
    const postClearWrite = await coordinator.save(7, '<div>new conversation</div>', {
      ownerId: 'returning-panel',
      handoffGeneration: 3,
    });
    assert.equal(postClearWrite.ok, true, `${label}: the owner should persist the new conversation under the rotated generation`);
    assert.equal(values[`${persistence.TAB_CHAT_PREFIX}7`], '<div>new conversation</div>', `${label}: the post-clear transcript should remain current`);

    values['contextMenuPrompt:8'] = { id: 'prompt-8', text: 'Summarize this' };
    values['contextMenuPromptClaim:8'] = { promptId: 'prompt-8', claimantId: 'panel-8' };
    await coordinator.save(8, '<div>conversation eight</div>');
    const combinedClear = await coordinator.clear(8, {
      additionalKeys: ['contextMenuPrompt:8', 'contextMenuPromptClaim:8'],
    });
    assert.equal(combinedClear.ok, true, `${label}: coordinator should clear additional transaction keys`);
    assert.equal(values[`${persistence.TAB_CHAT_PREFIX}8`], undefined, `${label}: combined clear retained the transcript`);
    assert.equal(values['contextMenuPrompt:8'], undefined, `${label}: combined clear retained the prompt`);
    assert.equal(values['contextMenuPromptClaim:8'], undefined, `${label}: combined clear retained the prompt lease`);

    values['contextMenuPrompt:9'] = { id: 'prompt-9', text: 'Keep this prompt' };
    values['contextMenuPromptClaim:9'] = { promptId: 'prompt-9', claimantId: 'panel-9' };
    await coordinator.save(9, '<div>conversation nine</div>');
    await assert.rejects(
      coordinator.clear(9, {
        additionalKeys: ['contextMenuPrompt:9', 'contextMenuPromptClaim:9'],
        commitAfterRemove: async () => { throw new Error('scheduler storage failed'); },
      }),
      /scheduler storage failed/,
      `${label}: a failed scheduler commit should reject the combined clear`,
    );
    assert.equal(values[`${persistence.TAB_CHAT_PREFIX}9`], '<div>conversation nine</div>', `${label}: scheduler failure should restore the transcript`);
    assert.equal(values['contextMenuPrompt:9']?.id, 'prompt-9', `${label}: scheduler failure should restore the prompt`);
    assert.equal(values['contextMenuPromptClaim:9']?.claimantId, 'panel-9', `${label}: scheduler failure should restore the prompt lease`);
    const restoredAfterRollback = await coordinator.load(9);
    assert.equal(restoredAfterRollback.html, '<div>conversation nine</div>', `${label}: scheduler rollback should restore the coordinator's lossless cache`);

    await coordinator.save(10, '<div>lossless conversation ten</div>');
    values[`${persistence.TAB_CHAT_PREFIX}10`] = '<div>compacted conversation</div>';
    nextRemoveError = new Error('transcript removal failed');
    await assert.rejects(
      coordinator.clear(10, { commitAfterRemove: async () => {} }),
      /transcript removal failed/,
      `${label}: a failed transcript removal should reject the transactional clear`,
    );
    const restoredAfterRemoveFailure = await coordinator.load(10);
    assert.equal(
      restoredAfterRemoveFailure.html,
      '<div>lossless conversation ten</div>',
      `${label}: a failed transcript removal should preserve the coordinator's lossless cache`,
    );

    await coordinator.save(11, '<div>lossless conversation eleven</div>');
    nextSetError = new Error('rollback write failed');
    await assert.rejects(
      coordinator.clear(11, {
        commitAfterRemove: async () => { throw new Error('scheduler cancellation failed'); },
      }),
      /rollback write failed/,
      `${label}: a failed durable rollback should reject the transactional clear`,
    );
    const restoredAfterRollbackFailure = await coordinator.load(11);
    assert.equal(
      restoredAfterRollbackFailure.html,
      '<div>lossless conversation eleven</div>',
      `${label}: a failed durable rollback should still restore the coordinator's lossless cache`,
    );
  }
});

test('chrome sidepanel serializes tab-chat storage writes with clears and reads', () => {
  const panel = fs.readFileSync(path.join(ROOT, 'src/chrome/src/ui/sidepanel.js'), 'utf8');
  assert.match(panel, /const tabChatOperations = new Map\(\);/, 'chrome: tab-chat operations should be queued per tab');
  assert.match(panel, /function enqueueTabChatOperation\(tabId, fn\) \{[\s\S]*?const previous = tabChatOperations\.get\(numericTabId\) \|\| Promise\.resolve\(\);[\s\S]*?tabChatOperations\.set\(numericTabId, operation\);[\s\S]*?\}/, 'chrome: tab-chat writes should be serialized behind prior operations');
  const loadStart = panel.indexOf('async function loadTabChat(tabId, { waitForHandoff = false } = {}) {');
  assert.notEqual(loadStart, -1, 'chrome: loadTabChat missing');
  const loadBody = panel.slice(loadStart, panel.indexOf('\n}\n\nfunction persistTabChat', loadStart) + 2);
  assert.match(loadBody, /const numericTabId = Number\(tabId\);[\s\S]*?if \(!Number\.isFinite\(numericTabId\)\) return null;/, 'chrome: tab-chat restore should normalize tab ids before checking the cache');
  assert.match(loadBody, /if \(!waitForHandoff && !tabChatOperations\.has\(numericTabId\) && tabChats\.has\(numericTabId\)\)/, 'chrome: coordinated handoff restores should bypass stale document-local HTML');
  assert.match(loadBody, /return await enqueueTabChatOperation\(numericTabId, async \(queuedTabId\) => \{[\s\S]*?sendToBackground\('load_tab_chat', \{[\s\S]*?waitForHandoff,[\s\S]*?\}\);/, 'chrome: tab-chat restore should read through the shared background queue');
  assert.match(loadBody, /catch \(e\) \{\s*if \(waitForHandoff\) return TAB_CHAT_LOAD_FAILED;\s*\}[\s\S]*?return null;/, 'chrome: coordinated load failures should remain distinct from successful empty restores');
  assert.match(panel, /const html = await loadTabChat\(tabId, \{ waitForHandoff: true \}\);\s*if \(html === TAB_CHAT_LOAD_FAILED\) return false;[\s\S]*?messagesEl\.innerHTML = '';/, 'chrome: a failed visibility handoff must preserve the current transcript DOM');
  assert.match(panel, /const payload = \{[\s\S]*?handoffOwnerId: tabChatHandoffOwnerId,[\s\S]*?handoffGeneration[\s\S]*?return enqueueTabChatOperation\(tabId, async \(numericTabId\) => \{[\s\S]*?sendToBackground\('persist_tab_chat', payload\);/, 'chrome: visible tab-chat persistence should carry its owner generation through the shared background queue');
  assert.match(panel, /document\.visibilityState === 'hidden' && allowHidden[\s\S]*?sendToBackground\('persist_tab_chat', payload\);/, 'chrome: hidden handoff must bypass the document-local queue and enter the shared queue immediately');
  const clearStart = panel.indexOf('function clearCachedTabChat(tabId) {');
  assert.notEqual(clearStart, -1, 'chrome: clearCachedTabChat missing');
  const clearBody = panel.slice(clearStart, panel.indexOf('\n}\n\nasync function renderClearedConversationForTab', clearStart) + 2);
  assert.match(clearBody, /tabChats\.delete\(tabId\);/, 'chrome: clearing tab chat should delete the cached HTML before queuing storage removal');
  assert.match(clearBody, /return enqueueTabChatOperation\(tabId, async \(numericTabId\) => \{/, 'chrome: clearing tab chat should be serialized through the queue');
  assert.match(clearBody, /lastVisibleTabChatSnapshot[\s\S]*?sameTabId\(lastVisibleTabChatSnapshot\.tabId, tabId\)[\s\S]*?lastVisibleTabChatSnapshot = null;[\s\S]*?return enqueueTabChatOperation/, 'chrome: clearing should invalidate the pre-clear handoff snapshot before yielding');
  assert.match(clearBody, /while \(true\)[\s\S]*?clearResult\?\.reason === 'stale-handoff'[\s\S]*?sendToBackground\('load_tab_chat'[\s\S]*?clearResult = await sendToBackground\('clear_tab_chat'[\s\S]*?clearResult\.reason !== 'stale-handoff'/, 'chrome: a stale clear should reacquire ownership and retry before rendering the cleared conversation');
  assert.match(clearBody, /return enqueueTabChatOperation\(tabId, async \(numericTabId\) => \{[\s\S]*?tabChats\.delete\(numericTabId\);[\s\S]*?handoffGeneration = tabChatHandoffGenerations\.get\(numericTabId\);[\s\S]*?sendToBackground\('load_tab_chat', \{[\s\S]*?waitForHandoff: true,[\s\S]*?sendToBackground\('clear_tab_chat', \{[\s\S]*?handoffOwnerId: tabChatHandoffOwnerId,[\s\S]*?handoffGeneration,/, 'chrome: queued clears should retain or reacquire ownership before clearing shared state');
  assert.match(clearBody, /clearResult\?\.handoffOwnerId === tabChatHandoffOwnerId[\s\S]*?tabChatHandoffGenerations\.set\(numericTabId, Number\(clearResult\.handoffGeneration\)\)/, 'chrome: the clearing panel should adopt the generation rotated by the coordinator');
  assert.doesNotMatch(clearBody, /tabChatHandoffGenerations\.delete/, 'chrome: clearing content must not discard the visible document handoff generation');
});

