test('Ollama settings use tri-state vision capability with mirrored preflight wiring', () => {
  for (const [label, prefix] of [
    ['chrome', 'src/chrome'],
    ['firefox', 'src/firefox'],
  ]) {
    const settings = fs.readFileSync(path.join(ROOT, prefix, 'src/ui/settings.js'), 'utf8');
    const manager = fs.readFileSync(path.join(ROOT, prefix, 'src/providers/manager.js'), 'utf8');
    const agent = fs.readFileSync(path.join(ROOT, prefix, 'src/agent/agent.js'), 'utf8');
    const handoff = fs.readFileSync(path.join(ROOT, prefix, 'src/ollama-handoff.js'), 'utf8');
    const ollamaFields = settings.slice(settings.indexOf('ollama: {'), settings.indexOf('lmstudio: {'));

    assert.match(ollamaFields, /OLLAMA_VISION_MODE_FIELD/, `${label}: Ollama should expose the tri-state vision field`);
    assert.doesNotMatch(ollamaFields, /key: 'supportsVision'.*checkbox/, `${label}: Ollama should no longer expose the legacy boolean checkbox`);
    assert.match(settings, /value: 'auto'[\s\S]*value: 'on'[\s\S]*value: 'off'/, `${label}: vision selector should expose auto, force-on, and off`);
    for (const key of ['vision_detected_vision', 'vision_detected_text', 'vision_pending']) {
      assert.ok(settings.includes(key), `${label}: auto detection status should include ${key}`);
    }
    assert.match(settings, /data-ollama-vision-status/, `${label}: the status should remain addressable when Auto is not initially selected`);
    assert.match(settings, /select\[data-provider="ollama"\]\[data-key="visionMode"\][\s\S]*?addEventListener\('change', refreshOllamaVisionStatus\)/,
      `${label}: changing the override should update status visibility immediately`);
    assert.match(settings, /input\[data-key="model"\][\s\S]*providerDefinitionId\(input\.dataset\.provider\) === 'ollama'[\s\S]*refreshVisionStatus\(input\.dataset\.provider\)/,
      `${label}: editing the model or endpoint should invalidate the displayed detection`);
    assert.match(settings, /Object\.entries\(changes\.providers\.newValue\)[\s\S]*?providerDefinitionId\(id\)[\s\S]*?VISION_UI_PROVIDER_IDS\.has\(definitionId\)[\s\S]*?refreshVisionStatus\(id\)/,
      `${label}: background detection storage updates should refresh source and duplicate cards on an open Settings page`);
    assert.match(manager, /visionMode: 'auto'[\s\S]*visionDetection: null/, `${label}: Ollama defaults should be auto and unresolved`);
    assert.doesNotMatch(handoff, /supportsVision:\s*true/, `${label}: launch handoff must not force vision`);
    assert.match(handoff, /visionMode:\s*'auto'/, `${label}: launch handoff should request metadata detection`);

    const firstPreflight = agent.indexOf('prepareActiveProviderCapabilities?.()');
    const firstEnrichment = agent.indexOf('this._enrichUserMessageWithCurrentPage(', firstPreflight);
    assert.ok(firstPreflight >= 0 && firstEnrichment > firstPreflight, `${label}: capability preflight must run before first-turn enrichment`);
  }
});

test('Ollama vision settings copy is translated and mirrored in every locale', async () => {
  const localeCodes = [
    'ar', 'bn', 'de', 'en', 'es', 'fa', 'fr', 'he', 'hi', 'id', 'ja', 'ko',
    'ms', 'nl', 'pl', 'pt', 'ru', 'th', 'tl', 'tr', 'uk', 'vi', 'zh',
  ];
  const keys = [
    'st.provider.field.vision_auto',
    'st.provider.field.vision_force_on',
    'st.provider.field.vision_detected_vision',
    'st.provider.field.vision_detected_text',
    'st.provider.field.vision_pending',
  ];
  const english = (await import(pathToFileURL(path.join(ROOT, 'src/chrome/src/ui/locales/en.js')).href)).default;

  for (const locale of localeCodes) {
    const chromeLocale = (await import(pathToFileURL(path.join(ROOT, `src/chrome/src/ui/locales/${locale}.js`)).href)).default;
    const firefoxLocale = (await import(pathToFileURL(path.join(ROOT, `src/firefox/src/ui/locales/${locale}.js`)).href)).default;
    for (const key of keys) {
      assert.equal(firefoxLocale[key], chromeLocale[key], `${locale}: ${key} should match across browsers`);
      assert.ok(chromeLocale[key]?.trim(), `${locale}: ${key} should not be empty`);
      if (locale !== 'en') {
        assert.notEqual(chromeLocale[key], english[key], `${locale}: ${key} should not fall back to English`);
      }
    }
  }
});

test('settings exposes compatibility controls and native Anthropic custom request bodies', () => {
  for (const [label, settingsRel, htmlRel, PM] of [
    ['chrome', 'src/chrome/src/ui/settings.js', 'src/chrome/src/ui/settings.html', ProviderManagerCh],
    ['firefox', 'src/firefox/src/ui/settings.js', 'src/firefox/src/ui/settings.html', ProviderManagerFx],
  ]) {
    const settings = fs.readFileSync(path.join(ROOT, settingsRel), 'utf8');
    const html = fs.readFileSync(path.join(ROOT, htmlRel), 'utf8');
    assert.match(
      settings,
      /id !== 'webbrain_cloud' && \['openai', 'llamacpp', 'azure_openai'\]\.includes\(config\.type\)/,
      `${label}: OpenAI compatibility controls should remain protocol-scoped`,
    );
    assert.match(
      settings,
      /\['anthropic', 'anthropic_oauth', 'vertex_anthropic'\]\.includes\(config\.type\)/,
      `${label}: native Anthropic providers should expose Custom request body JSON`,
    );
    assert.match(settings, /showCompatibilityControls \? `/, `${label}: Anthropic should not render OpenAI-only selectors`);
    for (const key of [
      'st.providers.compat.title',
      'st.providers.compat.preset',
      'st.providers.compat.reasoning',
      'st.providers.compat.system_role',
      'st.providers.compat.token_field',
      'st.providers.compat.extra_body',
      'st.providers.compat.reset',
    ]) {
      // Literal includes avoids incomplete RegExp escaping of dynamic keys.
      assert.ok(settings.includes(key), `${label}: missing ${key}`);
    }
    assert.match(settings, /data-key="compat\.reasoningEffort"/, `${label}: reasoning setting should persist under compat`);
    assert.match(settings, /data-key="extraBody" data-type="json"/, `${label}: custom body textarea should be typed as JSON`);
    assert.match(settings, /parseProviderExtraBodyJson\(input\.value\)/, `${label}: Save and Test should reject invalid JSON before updating the provider`);
    assert.match(settings, /textarea\[data-provider/, `${label}: provider save should include the JSON textarea`);
    assert.match(settings, /const providerCompatibilityJsonDrafts = new Map\(\)/, `${label}: raw compatibility JSON drafts need separate UI state`);
    assert.match(
      settings,
      /if \(input\.dataset\.type === 'json'\) \{[\s\S]*?providerCompatibilityJsonDrafts\.set\(id, input\.value\);[\s\S]*?parseProviderExtraBodyJson\(input\.value\)/,
      `${label}: invalid or partial JSON should survive provider-card re-renders`,
    );
    assert.match(settings, /providerCompatibilityJsonDrafts\.delete\(id\);[\s\S]*?Object\.assign\(providersData\[id\], config\)/, `${label}: successful saves should clear the raw JSON draft`);
    assert.match(html, /\.provider-compatibility \{/, `${label}: compatibility disclosure styling missing`);
    assert.match(html, /textarea\[aria-invalid="true"\]/, `${label}: invalid JSON needs a visible error state`);

    const defaults = new PM()._defaultConfigs();
    assert.equal(defaults.openai.model, 'gpt-5.6-terra', `${label}: Terra should be the new-install OpenAI default`);
    for (const model of ['gpt-5.6-terra', 'gpt-5.6-sol', 'gpt-5.6-luna', 'gpt-5.6']) {
      assert.ok(
        settings.includes(`'${model}'`) || settings.includes(`"${model}"`),
        `${label}: model picker missing ${model}`,
      );
    }
  }
});

