test('clarify tool auto-timeout is configurable and mirrored across browsers', () => {
  for (const [label, paths] of [
    ['chrome', {
      agent: 'src/chrome/src/agent/agent.js',
      tools: 'src/chrome/src/agent/tools.js',
      scheduler: 'src/chrome/src/agent/scheduler.js',
      bg: 'src/chrome/src/background.js',
      settings: 'src/chrome/src/ui/settings.js',
      settingsHtml: 'src/chrome/src/ui/settings.html',
      panel: 'src/chrome/src/ui/sidepanel.js',
      locale: 'src/chrome/src/ui/locales/en.js',
      idLocale: 'src/chrome/src/ui/locales/id.js',
    }],
    ['firefox', {
      agent: 'src/firefox/src/agent/agent.js',
      tools: 'src/firefox/src/agent/tools.js',
      scheduler: 'src/firefox/src/agent/scheduler.js',
      bg: 'src/firefox/src/background.js',
      settings: 'src/firefox/src/ui/settings.js',
      settingsHtml: 'src/firefox/src/ui/settings.html',
      panel: 'src/firefox/src/ui/sidepanel.js',
      locale: 'src/firefox/src/ui/locales/en.js',
      idLocale: 'src/firefox/src/ui/locales/id.js',
    }],
  ]) {
    const agent = fs.readFileSync(path.join(ROOT, paths.agent), 'utf8');
    const tools = fs.readFileSync(path.join(ROOT, paths.tools), 'utf8');
    const scheduler = fs.readFileSync(path.join(ROOT, paths.scheduler), 'utf8');
    const bg = fs.readFileSync(path.join(ROOT, paths.bg), 'utf8');
    const settings = fs.readFileSync(path.join(ROOT, paths.settings), 'utf8');
    const settingsHtml = fs.readFileSync(path.join(ROOT, paths.settingsHtml), 'utf8');
    const panel = fs.readFileSync(path.join(ROOT, paths.panel), 'utf8');
    const locale = fs.readFileSync(path.join(ROOT, paths.locale), 'utf8');
    const idLocale = fs.readFileSync(path.join(ROOT, paths.idLocale), 'utf8');

    assert.match(agent, /this\.clarifyTimeoutSec = 60/, `${label}: agent default clarify timeout should be 60s`);
    assert.match(agent, /_normalizeClarifyTimeoutSec/, `${label}: agent should normalize clarify timeout (instant / wait / off)`);
    assert.match(agent, /if \(sec > 1200\) return -1/, `${label}: stored values above 1200 should normalize to Off (-1)`);
    assert.match(agent, /_settleClarification/, `${label}: clarify responses should settle once and clear timers`);
    assert.match(agent, /noteClarifyInputActivity/, `${label}: custom-answer typing should renew a waited clarify timeout`);
    assert.match(agent, /onUpdate\('clarify_timeout_extended'/, `${label}: renewed deadlines should be published to the UI`);
    assert.match(agent, /timeoutSec === 0 \? 'auto' : 'timeout'/, `${label}: Instant should use source=auto; waited timeout uses source=timeout`);
    assert.match(agent, /source: autoSource/, `${label}: clarify_auto / settle should pass auto or timeout via autoSource`);
    assert.match(agent, /source === 'timeout'/, `${label}: waited timeout should keep the non-confirmation tool note`);
    assert.match(agent, /source === 'auto'/, `${label}: Instant auto-approve should get a non-warning tool note`);
    assert.match(agent, /intentionally configured unattended auto-approve/, `${label}: Instant note should treat auto-approve as intentional`);
    assert.match(agent, /onUpdate\('clarify_auto'/, `${label}: agent should emit clarify_auto for UI lock`);
    assert.match(agent, /timeoutSec >= 0/, `${label}: Instant (0) and positive waits should arm auto-select; Off (-1) waits forever`);
    assert.match(agent, /NOT a real user confirmation/, `${label}: timeout tool note should deny user-confirmation status`);
    assert.match(agent, /_clarificationAuthorizationBlock/, `${label}: waited timeout should arm a structural authorization guard`);
    assert.match(agent, /requiresExplicitConfirmation: !authorized/, `${label}: clarify results should expose machine-readable authorization state`);
    assert.match(agent, /authorizationSource: 'timeout'/, `${label}: blocked actions should identify the timeout authorization source`);
    // Permission / form confirm prompts reuse clarify plumbing but must not
    // arm the auto-timeout (first option would grant access).
    const permMatch = agent.match(/async _promptPermission\([\s\S]*?\n  \}/);
    assert.ok(permMatch, `${label}: _promptPermission body missing`);
    assert.doesNotMatch(permMatch[0], /timeoutSec|setTimeout/, `${label}: permission prompts must not auto-timeout`);
    const submitMatch = agent.match(/async _promptSubmitConfirmation\([\s\S]*?\n  \}/);
    assert.ok(submitMatch, `${label}: _promptSubmitConfirmation body missing`);
    assert.doesNotMatch(submitMatch[0], /timeoutSec|setTimeout/, `${label}: form-submit prompts must not auto-timeout`);

    assert.match(tools, /options\[0\] is auto-selected|options\[0\] is selected/, `${label}: clarify tool schema should document auto-select of first option`);
    assert.match(tools, /source=timeout/, `${label}: system prompts should treat timeout answers as non-confirmations`);
    assert.match(tools, /source=auto/, `${label}: system prompts should document Instant source=auto`);
    assert.match(tools, /source=timeout is not user approval|source=timeout \(waited timeout|not source=timeout waited/, `${label}: prompts should qualify real clarify answers vs waited timeouts`);

    assert.match(scheduler, /pending\.timeoutSec/, `${label}: scheduled pendingClarify should persist timeoutSec`);
    assert.match(scheduler, /pending\.deadlineTs/, `${label}: scheduled pendingClarify should persist deadlineTs`);
    assert.match(
      scheduler,
      /type === 'clarify_auto'[\s\S]*?_waitingForInput\.delete\(job\.id\)[\s\S]*?status: 'running'[\s\S]*?pendingClarify: null/,
      `${label}: scheduled clarify_auto should clear wait state and restore running`,
    );
    assert.match(
      scheduler,
      /type === 'clarify_auto'[\s\S]*?_emit\(resumed, 'updated'\)/,
      `${label}: scheduled clarify_auto must not re-emit running (would spawn a new assistant bubble)`,
    );
    assert.doesNotMatch(
      scheduler,
      /type === 'clarify_auto'[\s\S]*?_emit\(resumed, 'running'\)/,
      `${label}: scheduled clarify_auto must not emit running after timeout`,
    );
    assert.match(
      scheduler,
      /const jobScopedUpdate = type === 'clarify'\s*\|\| type === 'clarify_timeout_extended'\s*\|\| type === 'clarify_auto'/,
      `${label}: scheduled clarify deadline updates should carry scheduledJobId`,
    );
    assert.match(scheduler, /type === 'clarify_timeout_extended'[\s\S]*?pendingClarify:[\s\S]*?deadlineTs:/, `${label}: scheduled clarifies should persist renewed deadlines`);
    assert.match(
      panel,
      /isAutoClarify = source === 'timeout' \|\| source === 'auto'/,
      `${label}: sidepanel should not attach memorySource for timeout or Instant auto-selects`,
    );
    assert.match(
      bg,
      /isAutoClarify = source === 'timeout' \|\| source === 'auto'/,
      `${label}: background should not learn timeout or Instant clarify answers as user memory`,
    );

    assert.match(bg, /loadClarifyTimeout/, `${label}: background should load clarify timeout from storage`);
    assert.match(bg, /changes\.clarifyTimeoutSec/, `${label}: background should hot-reload clarify timeout`);
    assert.match(bg, /if \(sec > 1200\) return -1/, `${label}: background should treat >1200 as Off`);
    assert.match(bg, /clarifyTimeoutSemanticsV2/, `${label}: background should migrate old 0=Off semantics once`);
    assert.match(bg, /CLARIFY_TIMEOUT_OFF_SLIDER = 1205/, `${label}: Off slider sentinel should be 1205`);
    assert.match(bg, /case 'clarify_input_activity':[\s\S]*?agent\.noteClarifyInputActivity/, `${label}: background should route custom-answer activity to the agent timer`);

    assert.match(settingsHtml, /id="range-clarify-timeout"[^>]*min="0"[^>]*max="1205"[^>]*value="60"/, `${label}: settings should expose 0–1205 clarify timeout slider (1205=Off)`);
    assert.match(settings, /clarifyTimeoutSec/, `${label}: settings should persist clarifyTimeoutSec`);
    assert.match(settings, /st\.display\.clarify_timeout\.off/, `${label}: settings Off label should be i18n-backed`);
    assert.match(settings, /st\.display\.clarify_timeout\.instant/, `${label}: settings Instant label should be i18n-backed`);
    assert.match(settings, /sec === 0/, `${label}: settings should label 0 as Instant`);
    assert.match(settings, /sec > 1200/, `${label}: settings should label >1200 as Off`);
    assert.match(panel, /startClarifyCountdown/, `${label}: sidepanel should show clarify countdown`);
    assert.match(panel, /case 'clarify_auto':/, `${label}: sidepanel should handle clarify_auto`);
    assert.match(panel, /lockClarifyCardFromAuto/, `${label}: sidepanel should lock cards on auto-select`);
    assert.match(panel, /dataset\.deadlineTs/, `${label}: clarify cards should persist deadline for restore`);
    assert.match(panel, /input\.addEventListener\('input',[\s\S]*?keepClarifyAliveWhileTyping/, `${label}: custom-answer input should keep a waited clarify alive`);
    assert.match(panel, /activeDeadlineTs = Number\(card\.dataset\.deadlineTs\)/, `${label}: countdown should read renewed deadlines`);
    assert.match(panel, /startClarifyCountdown\(card, \{ tabId, clarifyId, deadlineTs, firstOption \}\)/, `${label}: rebind should restart countdown from restored metadata`);
    assert.match(locale, /st\.display\.clarify_timeout\.label/, `${label}: English locale should include clarify timeout label`);
    assert.match(locale, /st\.display\.clarify_timeout\.off/, `${label}: English locale should include Off label`);
    assert.match(locale, /st\.display\.clarify_timeout\.instant/, `${label}: English locale should include Instant label`);
    assert.match(locale, /0 = Instant/, `${label}: English locale should document Instant at 0`);
    assert.match(locale, /above 1200s/, `${label}: English locale should document Off above 1200s`);
    assert.match(locale, /sp\.clarify\.auto_timeout/, `${label}: English locale should include countdown string`);
    assert.match(idLocale, /\{seconds\} dtk/, `${label}: Indonesian countdown should use seconds unit, not bare d`);
  }
});

test('clarify custom-answer activity restarts the authoritative waited timeout', async () => {
  const originalSetTimeout = globalThis.setTimeout;
  const originalClearTimeout = globalThis.clearTimeout;
  const originalDateNow = Date.now;
  let now = 10_000;
  let nextTimerId = 1;
  const timers = new Map();
  globalThis.setTimeout = (callback, delay) => {
    const id = nextTimerId++;
    timers.set(id, { callback, delay });
    return id;
  };
  globalThis.clearTimeout = (id) => {
    timers.delete(id);
  };
  Date.now = () => now;

  try {
    for (const [index, AgentClass] of [AgentCh, AgentFx].entries()) {
      const agent = new AgentClass({});
      const tabId = 4810 + index;
      agent.clarifyTimeoutSec = 5;
      const updates = [];
      const resultPromise = agent.executeTool(
        tabId,
        'clarify',
        { question: 'Which option?', options: ['First', 'Something else'] },
        (type, data) => updates.push({ type, data }),
      );
      // executeTool performs one async preflight before reaching clarify.
      await new Promise(resolve => originalSetTimeout(resolve, 0));
      const clarify = updates.find((update) => update.type === 'clarify')?.data;
      assert.ok(clarify?.clarifyId, `${AgentClass.name}: clarify prompt was not emitted`);
      const firstTimerId = [...timers.keys()][0];
      assert.equal(timers.get(firstTimerId)?.delay, 5000, `${AgentClass.name}: initial waited timeout was not armed`);

      now += 4000;
      const renewed = agent.noteClarifyInputActivity(tabId, clarify.clarifyId);
      assert.equal(renewed?.deadlineTs, now + 5000, `${AgentClass.name}: typing did not renew the full timeout`);
      assert.equal(timers.has(firstTimerId), false, `${AgentClass.name}: original timeout remained armed while typing`);
      const renewedTimerId = [...timers.keys()][0];
      assert.equal(timers.get(renewedTimerId)?.delay, 5000, `${AgentClass.name}: renewed timeout used the wrong delay`);
      assert.equal(
        updates.at(-1)?.type,
        'clarify_timeout_extended',
        `${AgentClass.name}: renewed deadline was not emitted`,
      );

      timers.get(renewedTimerId).callback();
      timers.delete(renewedTimerId);
      const result = await resultPromise;
      assert.equal(result.source, 'timeout', `${AgentClass.name}: renewed timer did not preserve waited-timeout semantics`);
      assert.equal(agent.noteClarifyInputActivity(tabId, clarify.clarifyId), null, `${AgentClass.name}: settled clarify accepted stale typing activity`);
      now += 1000;
    }
  } finally {
    globalThis.setTimeout = originalSetTimeout;
    globalThis.clearTimeout = originalClearTimeout;
    Date.now = originalDateNow;
  }
});

test('clarify result distinguishes waited timeout from user and Instant authorization', async () => {
  for (const AgentClass of [AgentCh, AgentFx]) {
    const agent = new AgentClass({});
    const tabId = AgentClass === AgentCh ? 4801 : 4802;
    agent.clarifyTimeoutSec = 1205;

    const waitedTimeout = await agent.executeTool(
      tabId,
      'clarify',
      { question: 'Which record?', options: ['First', 'Second'] },
      (type, data) => {
        if (type === 'clarify') agent.submitClarifyResponse(tabId, data.clarifyId, 'First', 'timeout');
      },
    );
    assert.equal(waitedTimeout.source, 'timeout', `${AgentClass.name}: timeout source was lost`);
    assert.equal(waitedTimeout.authorized, false, `${AgentClass.name}: waited timeout became authorization`);
    assert.equal(waitedTimeout.requiresExplicitConfirmation, true, `${AgentClass.name}: timeout did not require an explicit answer`);
    assert.equal(agent._clarificationAuthorizationGuards.get(tabId)?.authorized, false, `${AgentClass.name}: timeout guard was not armed`);

    const userReply = await agent.executeTool(
      tabId,
      'clarify',
      { question: 'Which record?', options: ['First', 'Second'] },
      (type, data) => {
        if (type === 'clarify') agent.submitClarifyResponse(tabId, data.clarifyId, 'Second', 'user');
      },
    );
    assert.equal(userReply.authorized, true, `${AgentClass.name}: direct user reply was not authorized`);
    assert.equal(userReply.requiresExplicitConfirmation, false, `${AgentClass.name}: direct reply kept the timeout warning`);
    assert.equal(agent._clarificationAuthorizationGuards.has(tabId), false, `${AgentClass.name}: direct reply did not clear the timeout guard`);

    agent.clarifyTimeoutSec = 0;
    const instant = await agent.executeTool(
      tabId,
      'clarify',
      { question: 'Which record?', options: ['First', 'Second'] },
      () => {},
    );
    assert.equal(instant.source, 'auto', `${AgentClass.name}: Instant did not use source=auto`);
    assert.equal(instant.authorized, true, `${AgentClass.name}: configured Instant mode was not authorized`);
    assert.equal(agent._clarificationAuthorizationGuards.has(tabId), false, `${AgentClass.name}: Instant unexpectedly armed the timeout guard`);
  }
});

test('waited clarify timeout guard is persisted before clarify returns', async () => {
  for (const [index, AgentClass] of [AgentCh, AgentFx].entries()) {
    const agent = new AgentClass({});
    const tabId = 4803 + index;
    agent.clarifyTimeoutSec = 1205;
    agent.conversations.set(tabId, [{ role: 'system', content: 'system' }]);
    agent.conversationIds.set(tabId, `conv_${tabId}`);

    let releasePersist;
    let persistStarted = false;
    let persistedEntry = null;
    let clarifySettled = false;
    const persistGate = new Promise(resolve => { releasePersist = resolve; });
    agent._persistNow = async () => {
      persistStarted = true;
      persistedEntry = agent._conversationStorageEntry(tabId);
      await persistGate;
      return true;
    };

    const clarifyPromise = agent.executeTool(
      tabId,
      'clarify',
      { question: 'Which record?', options: ['First', 'Second'] },
      (type, data) => {
        if (type === 'clarify') agent.submitClarifyResponse(tabId, data.clarifyId, 'First', 'timeout');
      },
    ).then(result => {
      clarifySettled = true;
      return result;
    });

    await new Promise(resolve => setTimeout(resolve, 0));
    assert.equal(persistStarted, true, `${AgentClass.name}: timeout guard persistence did not start`);
    assert.equal(persistedEntry?.clarificationAuthorizationGuard?.authorized, false, `${AgentClass.name}: durable entry did not contain the timeout guard`);
    assert.equal(clarifySettled, false, `${AgentClass.name}: clarify returned before timeout guard persistence completed`);

    releasePersist();
    const result = await clarifyPromise;
    assert.equal(result.authorized, false, `${AgentClass.name}: persisted timeout became authorization`);
  }
});

test('waited clarify timeout guard persists across restart and ordinary user turns', async () => {
  const previousChrome = globalThis.chrome;
  const previousBrowser = globalThis.browser;
  try {
    for (const [AgentClass, apiName, tabId] of [
      [AgentCh, 'chrome', 4803],
      [AgentFx, 'browser', 4804],
    ]) {
      const first = new AgentClass({});
      first.conversations.set(tabId, [{ role: 'system', content: 'system' }]);
      first.conversationIds.set(tabId, `conv_${tabId}`);
      first._persist = () => {};
      first._persistNow = async () => true;
      await first._recordClarificationAuthorization(tabId, 'timeout');
      const storedEntry = first._conversationStorageEntry(tabId);
      assert.equal(storedEntry.clarificationAuthorizationGuard?.authorized, false, `${AgentClass.name}: persisted entry lost timeout guard`);
      assert.equal(storedEntry.clarificationAuthorizationGuard?.conversationId, `conv_${tabId}`, `${AgentClass.name}: guard was not scoped to its conversation`);

      globalThis[apiName] = {
        storage: {
          session: {
            get: async key => ({ [key]: storedEntry }),
          },
        },
      };
      const restarted = new AgentClass({});
      restarted._persist = () => {};
      await restarted._hydrate(tabId);
      assert.equal(restarted._clarificationAuthorizationGuards.get(tabId)?.authorized, false, `${AgentClass.name}: worker restart lost timeout guard`);

      restarted._prepareClarificationAuthorizationForRun(tabId, { trustedContinuation: true });
      assert.equal(restarted._clarificationAuthorizationGuards.has(tabId), true, `${AgentClass.name}: trusted continuation cleared the guard`);
      restarted._prepareClarificationAuthorizationForRun(tabId, {});
      assert.equal(restarted._clarificationAuthorizationGuards.has(tabId), true, `${AgentClass.name}: ordinary user turn cleared the unresolved guard`);

      restarted.abort(tabId);
      assert.equal(restarted._clarificationAuthorizationGuards.has(tabId), true, `${AgentClass.name}: Stop cleared the unresolved timeout guard`);
      assert.equal(restarted._checkAbort(tabId), true, `${AgentClass.name}: Stop did not still cancel the active run`);
      assert.equal(restarted._clarificationAuthorizationGuards.has(tabId), true, `${AgentClass.name}: consuming Stop also cleared the unresolved guard`);

      restarted.conversationIds.set(tabId, `different_conv_${tabId}`);
      restarted._prepareClarificationAuthorizationForRun(tabId, {});
      assert.equal(restarted._clarificationAuthorizationGuards.has(tabId), false, `${AgentClass.name}: conversation-scoped guard leaked into a replacement conversation`);
    }
  } finally {
    if (previousChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = previousChrome;
    if (previousBrowser === undefined) delete globalThis.browser;
    else globalThis.browser = previousBrowser;
  }
});

test('waited clarify timeout permits only partial or failed completion', async () => {
  for (const AgentClass of [AgentCh, AgentFx]) {
    const tabId = AgentClass === AgentCh ? 4807 : 4808;

    for (const [name, args] of [
      ['done', { summary: 'Everything completed.', outcome: 'success' }],
      ['done', { summary: 'Everything completed.' }],
      ['done_json', { result: { ok: true } }],
    ]) {
      const agent = new AgentClass({ getVisionProvider: async () => null });
      let executed = false;
      let permissionGateCalls = 0;
      agent._persist = () => {};
      agent._ensureGateSetting = async () => { permissionGateCalls += 1; };
      agent.executeTool = async () => {
        executed = true;
        return { done: true, summary: 'should not execute', outcome: 'success' };
      };
      await agent._recordClarificationAuthorization(tabId, 'timeout');

      const messages = [];
      const result = await agent._executeToolBatch(
        tabId,
        [{ id: `completion_${name}`, function: { name, arguments: JSON.stringify(args) } }],
        messages,
        () => {},
        { supportsVision: false },
        '',
        new Set([name]),
        1,
      );

      assert.deepEqual(result, { action: 'continue' }, `${AgentClass.name}: ${name} success completion did not request a fresh turn`);
      assert.equal(executed, false, `${AgentClass.name}: ${name} success completion reached executeTool`);
      assert.equal(permissionGateCalls, 0, `${AgentClass.name}: ${name} success completion passed the authorization guard`);
      const blocked = JSON.parse(messages[0].content);
      assert.equal(blocked.blockedDone, true, `${AgentClass.name}: ${name} result was not marked as blocked completion`);
      assert.equal(blocked.clarificationAuthorizationRequired, true, `${AgentClass.name}: ${name} block did not require explicit clarification`);
    }

    const completionAgent = new AgentClass({});
    completionAgent._persist = () => {};
    await completionAgent._recordClarificationAuthorization(tabId, 'timeout');
    assert.equal(
      completionAgent._clarificationAuthorizationBlock(tabId, 'done', { outcome: 'partial' }, []),
      null,
      `${AgentClass.name}: partial completion was blocked`,
    );
    assert.equal(
      completionAgent._clarificationAuthorizationBlock(tabId, 'done', { outcome: 'failed' }, []),
      null,
      `${AgentClass.name}: failed completion was blocked`,
    );
  }
});

