test('sidepanel preserves stale residual slash-command prompts without hidden runs', () => {
  for (const [label, panelRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    assert.match(
      panel,
      /function autoResizeInput\(\) \{\s*const maxHeight = 120;\s*inputEl\.style\.height = 'auto';\s*if \(!inputEl\.value\) \{\s*inputEl\.style\.height = '';\s*inputEl\.style\.overflowY = 'hidden';\s*updateSlashCommandHighlight\(\);\s*return;\s*\}\s*(?:\/\/[^\n]*\n\s*)*const contentHeight = inputEl\.scrollHeight;\s*inputEl\.style\.height = Math\.min\(contentHeight, maxHeight\) \+ 'px';\s*inputEl\.style\.overflowY = contentHeight > maxHeight \? 'auto' : 'hidden';\s*updateSlashCommandHighlight\(\);\s*\}/,
      `${label}: empty composer should reset to its rows=1 height instead of autosizing to placeholder scrollHeight`,
    );
    assert.match(panel, /const tabInputDrafts = new Map\(\);/, `${label}: sidepanel should track per-tab composer drafts`);
    assert.match(panel, /function saveInputDraftForTab\(tabId, text\) \{[\s\S]*?tabInputDrafts\.set\(numericTabId, draft\);[\s\S]*?tabInputDrafts\.delete\(numericTabId\);[\s\S]*?\}/, `${label}: tab drafts should save non-empty text and clear empty text`);
    assert.match(panel, /function restoreInputDraftForTab\(tabId\) \{[\s\S]*?inputEl\.value = draft;[\s\S]*?autoResizeInput\(\);[\s\S]*?updateSlashCommandAutocomplete\(\);[\s\S]*?\}/, `${label}: tab drafts should restore into the composer when returning to a tab`);

    const switchStart = panel.indexOf('function switchToTab(newTabId)');
    assert.notEqual(switchStart, -1, `${label}: switchToTab missing`);
    const switchBody = panel.slice(switchStart, panel.indexOf('refreshScheduledJobs({', switchStart));
    assert.match(switchBody, /const outgoingTabId = renderedTabId;[\s\S]*?captureInputDraftForTab\(outgoingTabId\);[\s\S]*?restoreInputDraftForTab\(newTabId\);/, `${label}: tab switches should capture and restore per-tab composer drafts`);

    const sendMatch = panel.match(/async function sendMessage\(extraChatParams(?: = \{\})?\) \{[\s\S]*?\n  return accepted;\n\}/);
    assert.ok(sendMatch, `${label}: sendMessage missing`);
    const sendBody = sendMatch[0];
    const modeHelperStart = panel.indexOf('function modeForMessageText(text) {');
    assert.notEqual(modeHelperStart, -1, `${label}: modeForMessageText missing`);
    const modeHelper = panel.slice(modeHelperStart, panel.indexOf('\n}', modeHelperStart) + 2);
    for (const [snippet, commandLabel] of [
      ["if (invocation?.command?.value === '/ask' || invocation?.command?.value === '/plan') return 'ask';", '/ask and /plan'],
      ["if (invocation?.command?.value === '/act') return 'act';", '/act'],
      ["if (invocation?.command?.value === '/dev') return 'dev';", '/dev'],
      ['return agentMode;', 'current mode fallback'],
    ]) {
      assert.ok(modeHelper.includes(snippet), `${label}: modeForMessageText should handle ${commandLabel}`);
    }
    const modeOverride = "const modeOverride = ['ask', 'act', 'dev'].includes(extraChatParams?.__mode) ? extraChatParams.__mode : null;";
    const modeCapture = "const modeForSend = retryOptions?.mode || modeOverride || modeForMessageText(text);";
    const apiCapture = 'const apiMutationsAllowedForSend = retryOptions';
    const modeOverrideIdx = sendBody.indexOf(modeOverride);
    const deleteModeIdx = sendBody.indexOf('delete chatExtraParams.__mode;');
    const modeCaptureIdx = sendBody.indexOf(modeCapture);
    const apiCaptureIdx = sendBody.indexOf(apiCapture);
    const parseIdx = sendBody.indexOf('text = await parseSlashCommands(text, tabId, { permissionSkipContext });');
    assert.notEqual(modeOverrideIdx, -1, `${label}: recommended-action mode override should be captured before send mode selection`);
    assert.notEqual(deleteModeIdx, -1, `${label}: internal recommended-action mode override should not leak into chat payload`);
    assert.notEqual(modeCaptureIdx, -1, `${label}: send mode should be captured from the initiating command before async slash parsing`);
    assert.notEqual(apiCaptureIdx, -1, `${label}: API override should be captured from the initiating tab before async slash parsing`);
    assert.equal(modeOverrideIdx < modeCaptureIdx && deleteModeIdx < modeCaptureIdx, true, `${label}: recommended-action mode override should be captured and stripped before selecting send mode`);
    assert.equal(modeCaptureIdx < parseIdx && apiCaptureIdx < parseIdx, true, `${label}: stale-tab residual sends should not read visible-tab options after slash parsing`);
    assert.match(
      sendBody,
      /const tabId = currentTabId;[\s\S]*?text = await parseSlashCommands\(text, tabId, \{ permissionSkipContext \}\);[\s\S]*?renderToCurrentTab = document\.visibilityState !== 'hidden'[\s\S]*?sameTabId\(currentTabId, tabId\)[\s\S]*?sameTabId\(renderedTabId, tabId\);[\s\S]*?if \(!renderToCurrentTab\) \{[\s\S]*?if \(text\) saveInputDraftForTab\(tabId, agentPrompt \? submittedText : text\);[\s\S]*?return false;[\s\S]*?\}/,
      `${label}: stale residual slash-command prompts should be preserved as drafts instead of hidden runs`,
    );
    assert.match(
      sendBody,
      /if \(!text\) \{[\s\S]*?return;[\s\S]*?\}\s*setTabProcessing\(tabId, true\);\s*setTabAbortRequested\(tabId, false\);\s*inputEl\.value = '';\s*autoResizeInput\(\);\s*syncSendButtonState\(\);\s*await prepareChatHistoryForTurn\(tabId, modeForSend\);/,
      `${label}: send should enter a busy state and clear the composer before async history hydration`,
    );
    assert.match(
      sendBody,
      /await prepareChatHistoryForTurn\(tabId, modeForSend\);\s*if \(isTabAbortRequested\(tabId\)\) \{[\s\S]*?setTabProcessing\(tabId, false\);[\s\S]*?setTabAbortRequested\(tabId, false\);[\s\S]*?syncSendButtonState\(\);[\s\S]*?return false;[\s\S]*?\}[\s\S]*?renderToCurrentTab = document\.visibilityState !== 'hidden'[\s\S]*?sameTabId\(currentTabId, tabId\)[\s\S]*?sameTabId\(renderedTabId, tabId\);/,
      `${label}: aborted sends during history hydration should stop before chat dispatch`,
    );
    const staleReturnIdx = sendBody.indexOf('if (!renderToCurrentTab) {');
    const sendIdx = sendBody.indexOf("sendRunWithReconnect('chat_start'");
    assert.notEqual(staleReturnIdx, -1, `${label}: stale-tab residual guard missing`);
    assert.notEqual(sendIdx, -1, `${label}: chat send missing`);
    assert.equal(staleReturnIdx < sendIdx, true, `${label}: stale-tab residual guard must run before chat dispatch`);
    assert.match(
      sendBody,
      /if \(renderToCurrentTab\) \{\s*setTabProcessing\(tabId, true\);\s*setTabAbortRequested\(tabId, false\);\s*syncSendButtonState\(\);[\s\S]*?addMessage\('user', agentPrompt \? submittedText : text, \{[\s\S]*?attachments: attachmentsForSend,[\s\S]*?attachmentState:[\s\S]*?\}\);[\s\S]*?currentAssistantEl = assistantEl;[\s\S]*?\}/,
      `${label}: stale-tab residual sends should not mutate or render chat UI in the currently visible tab`,
    );
    assert.doesNotMatch(
      sendBody,
      /sendRunWithReconnect\('chat_start', \{[\s\S]*?tabId: currentTabId/,
      `${label}: chat dispatch should not read currentTabId after slash parsing`,
    );
  }
});

test('sidepanel keeps retry metadata long enough for returned error updates', () => {
  for (const [label, panelRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js'],
  ]) {
    const source = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    assert.match(
      source,
      /function createActiveChatPayloadState\(retryPayload, requestId = ''\) \{[\s\S]*?requestId: String\(requestId \|\| ''\)[\s\S]*?renderedErrorMessages: new Set\(\)[\s\S]*?\}/,
      `${label}: active retry metadata should track rendered error messages`,
    );
    assert.match(
      source,
      /const retryAttachmentIdsByTab = new Map\(\);/,
      `${label}: retry attachment payloads should be indexed by tab for cleanup`,
    );
    assert.match(
      source,
      /function clearRetryAttachmentsForTab\(tabId\) \{[\s\S]*?retryAttachmentPayloads\.delete\(retryId\)[\s\S]*?retryAttachmentIdsByTab\.delete\(numericTabId\);[\s\S]*?\}/,
      `${label}: clearing a conversation should release retry attachment payloads for that tab`,
    );
    assert.match(
      source,
      /function renderClearedConversationForTab\(tabId, \{ allowCacheClearFailure = false \} = \{\}\) \{[\s\S]*?releaseRetryAttachmentsInTree\(messagesEl\);[\s\S]*?clearRetryAttachmentsForTab\(tabId\);[\s\S]*?messagesEl\.innerHTML = '';/,
      `${label}: reset should release retry attachment payloads before removing retry buttons from the DOM`,
    );
    assert.match(
      source,
      /retryAttachmentPayloads\.set\(retryId, attachments\);[\s\S]*?trackRetryAttachmentId\(renderedTabId \?\? currentTabId, retryId\);/,
      `${label}: retry attachment payload IDs should be associated with the rendered tab`,
    );
    assert.match(
      source,
      /if \(payload\.apiMutationsAllowed\) \{[\s\S]*?grantApiMutationsForTab\(currentTabId\);[\s\S]*?\}[\s\S]*?await sendMessage\(\{/,
      `${label}: restored retries that replay API mutation permission should resync the visible per-tab API state and report the grant`,
    );
    assert.match(
      source,
      /const activePayloadState = createActiveChatPayloadState\(retryPayload, requestId\);[\s\S]*?activeChatPayloadsByTab\.set\(tabId, activePayloadState\);/,
      `${label}: sendMessage should store retry metadata as an active run state`,
    );
    assert.match(
      source,
      /const returnedErrorUpdate = Array\.isArray\(res\?\.updates\)[\s\S]*?res\.updates\.find\(u => u\?\.type === 'error'\)[\s\S]*?renderAgentErrorUpdate\(returnedErrorUpdate\.data, tabId, requestId, \{[\s\S]*?submittedTurnDurable: res\.submittedTurnDurable,[\s\S]*?\}\);/,
      `${label}: returned agent error updates should render with retry metadata and durable-turn proof even if the broadcast is late`,
    );
    assert.match(
      source,
      /case 'error':[\s\S]*?renderAgentErrorUpdate\(data, currentTabId, msg\.requestId\);[\s\S]*?break;/,
      `${label}: broadcast agent errors should share the retry-aware renderer`,
    );
    assert.match(
      source,
      /function scheduleActiveChatPayloadCleanup\(tabId, state\) \{[\s\S]*?setTimeout\(\(\) => \{[\s\S]*?activeChatPayloadsByTab\.delete\(tabId\);[\s\S]*?\}, 30000\);/,
      `${label}: active retry metadata should be cleaned up after late broadcasts have had a chance to drain`,
    );
    assert.match(
      source,
      /function clearActiveChatPayloadForTab\(tabId\) \{[\s\S]*?activeChatPayloadsByTab\.delete\(tabId\);[\s\S]*?\}/,
      `${label}: non-chat runs should be able to clear stale chat retry metadata`,
    );
    assert.match(
      source,
      /else if \(event === 'running'\) \{[\s\S]*?clearActiveChatPayloadForTab\(runTabId\);[\s\S]*?setTabProcessing\(runTabId, true\);/,
      `${label}: scheduled runs should clear stale chat retry metadata before starting`,
    );
    assert.match(
      source,
      /function reattachPlanReviewActiveRun\(card\) \{[\s\S]*?clearActiveChatPayloadForTab\(tabId\);[\s\S]*?setTabProcessing\(tabId, true\);/,
      `${label}: plan review resumes should clear stale chat retry metadata before starting`,
    );
    assert.match(
      source,
      /const isScheduledClarify = !!card\.dataset\.scheduledJobId;[\s\S]*?if \(isScheduledClarify\) \{[\s\S]*?clearActiveChatPayloadForTab\(tabId\);[\s\S]*?setTabProcessing\(tabId, true\);/,
      `${label}: scheduled clarify resumes should clear stale chat retry metadata before starting`,
    );
    assert.match(
      source,
      /async function continueAgent\(options = \{\}\) \{[\s\S]*?const tabId = currentTabId;[\s\S]*?clearActiveChatPayloadForTab\(tabId\);[\s\S]*?setTabProcessing\(tabId, true\);/,
      `${label}: Continue runs should clear stale chat retry metadata before starting`,
    );
  }
});

test('sidepanel allows safe slash commands and queues normal messages while busy', () => {
  for (const [label, panelRel, localeRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js', 'src/chrome/src/ui/locales/en.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js', 'src/firefox/src/ui/locales/en.js'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    const locale = fs.readFileSync(path.join(ROOT, localeRel), 'utf8');
    const slash = loadSlashCommandRuntime(panelRel);
    for (const command of ['/help', '/progress', '/scratchpad', '/memory', '/schedule --list', '/screenshot', '/export', '/export --traces', '/verbose']) {
      assert.equal(slash.slashInvocationIsOutOfBand(slash.parseSlashInvocation(command)), true, `${label}: ${command} should be allowed while busy`);
    }
    for (const command of ['/schedule task', '/scratchpad --append note', '/scratchpad --clear', '/memory --add note', '/memory --forget id']) {
      assert.equal(slash.slashInvocationIsOutOfBand(slash.parseSlashInvocation(command)), false, `${label}: ${command} should stay gated while busy`);
    }
    if (label === 'chrome') {
      assert.equal(slash.slashInvocationIsOutOfBand(slash.parseSlashInvocation('/screenshot --full-page')), false, `${label}: full-page capture should stay gated while busy`);
      assert.equal(slash.slashInvocationIsOutOfBand(slash.parseSlashInvocation('/record --full-screen')), false, `${label}: recording should stay gated while busy`);
      assert.equal(slash.slashInvocationIsOutOfBand(slash.parseSlashInvocation('/record --stop')), true, `${label}: recording Stop should stay available while busy`);
    }
    assert.match(
      panel,
      /function syncSendButtonState\(\) \{[\s\S]*?const draft = normalizeScreenshotCommandText\(inputEl\?\.value \|\| ''\)\.trim\(\);[\s\S]*?if \(!isProcessing\) \{[\s\S]*?sendBtn\.disabled = isAttachmentReadPendingForTab\(\);[\s\S]*?return;[\s\S]*?\}[\s\S]*?if \(!draft\) \{[\s\S]*?sendBtn\.disabled = true;[\s\S]*?return;[\s\S]*?\}[\s\S]*?sendBtn\.disabled = draft\.startsWith\('\/'\) && !isOutOfBandSlashDraft\(draft\);[\s\S]*?\}/,
      `${label}: send button state should gate attachment reads while idle, permit normal queued drafts while busy, and only block unsafe slash drafts`,
    );
    assert.match(
      panel,
      /function applySlashCommandCompletion\(index = slashCommandSelectedIndex\) \{[\s\S]*?inputEl\.value = `\$\{before\}\$\{match\.value\} \$\{after\}`;[\s\S]*?autoResizeInput\(\);\s*updateSlashCommandAutocomplete\(\);\s*syncSendButtonState\(\);[\s\S]*?return true;[\s\S]*?\}/,
      `${label}: slash autocomplete completion should resync send button state`,
    );
    assert.match(
      panel,
      /text = normalizeScreenshotCommandText\(text\);[\s\S]*?if \(isProcessing\) \{[\s\S]*?if \(isOutOfBandSlashDraft\(text\)\) \{[\s\S]*?await parseSlashCommands\(text, tabId, \{ permissionSkipContext \}\);[\s\S]*?return true;[\s\S]*?\}[\s\S]*?if \(text\.startsWith\('\/'\)\) \{[\s\S]*?showBusySlashCommandNotice\(\);[\s\S]*?return false;[\s\S]*?\}[\s\S]*?return enqueueQueuedComposerMessage\(tabId, text\);[\s\S]*?\}/,
      `${label}: busy send preflight should run safe slash commands and queue normal drafts`,
    );
    assert.match(
      panel,
      /await parseSlashCommands\(text, tabId, \{ permissionSkipContext \}\);[\s\S]*?if \(currentTabId === tabId\) \{[\s\S]*?if \(!inputEl\.value\.trim\(\) \|\| inputEl\.value\.trim\(\) === text\) \{[\s\S]*?inputEl\.value = '';[\s\S]*?autoResizeInput\(\);[\s\S]*?\}[\s\S]*?syncSendButtonState\(\);[\s\S]*?\}/,
      `${label}: async busy slash completion should preserve newly typed drafts`,
    );
    assert.match(
      locale,
      /'sp\.slash\.busy_only_oob': 'Messages are queued while WebBrain is busy\. Only \/help, \/progress, \/scratchpad, \/memory, \/schedule --list, \/watch, \/dangerously-skip-permissions, \/screenshot, \/export, \/export --traces, and \/verbose can run immediately as slash commands\./,
      `${label}: busy slash notice should explain queued messages and safe slash commands`,
    );
  }
});

test('sidepanel queued composer messages expose edit and delete controls', () => {
  for (const [label, panelRel, htmlRel, cssRel, localeRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js', 'src/chrome/src/ui/sidepanel.html', 'src/chrome/styles/sidepanel.css', 'src/chrome/src/ui/locales/en.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js', 'src/firefox/src/ui/sidepanel.html', 'src/firefox/styles/sidepanel.css', 'src/firefox/src/ui/locales/en.js'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    const html = fs.readFileSync(path.join(ROOT, htmlRel), 'utf8');
    const css = fs.readFileSync(path.join(ROOT, cssRel), 'utf8');
    const locale = fs.readFileSync(path.join(ROOT, localeRel), 'utf8');

    assert.match(html, /id="queued-messages" class="queued-messages hidden" role="list"/, `${label}: queued message strip should exist above the composer`);
    assert.match(panel, /const queuedComposerMessagesByTab = new Map\(\);/, `${label}: queued composer messages should be tracked per tab`);
    assert.match(panel, /function enqueueQueuedComposerMessage\(tabId, text\) \{[\s\S]*?queue\.push\(\{[\s\S]*?text: queuedText,[\s\S]*?inputEl\.value = '';[\s\S]*?autoResizeInput\(\);[\s\S]*?syncSendButtonState\(\);[\s\S]*?return true;[\s\S]*?\}/, `${label}: busy drafts should be queued, clear the composer, and reset its height`);
    assert.match(panel, /function sameTabId\(a, b\) \{\s*return a != null && b != null && String\(a\) === String\(b\);\s*\}/, `${label}: queued-message tab checks should tolerate equivalent tab id types`);
    assert.match(panel, /function editQueuedComposerMessage\(tabId, queueId\) \{[\s\S]*?!sameTabId\(currentTabId, tabId\)[\s\S]*?removeQueuedComposerMessage\(tabId, queueId\);[\s\S]*?inputEl\.value = item\.text;[\s\S]*?inputEl\.setSelectionRange\(inputEl\.value\.length, inputEl\.value\.length\);[\s\S]*?\}/, `${label}: queued message edit should guard the tab and move text back into the composer`);
    assert.match(panel, /function editLastQueuedComposerMessageForCurrentTab\(\) \{[\s\S]*?const atStart = inputEl\.selectionStart === 0 && inputEl\.selectionEnd === 0;[\s\S]*?if \(inputEl\.value !== '' \|\| !atStart\) return false;[\s\S]*?const item = queue\[queue\.length - 1\];[\s\S]*?editQueuedComposerMessage\(currentTabId, item\.id\);[\s\S]*?return true;[\s\S]*?\}/, `${label}: ArrowUp edit should only pull the latest queued message into an exactly empty composer at the start`);
    assert.match(panel, /function deleteQueuedComposerMessage\(tabId, queueId\) \{[\s\S]*?removeQueuedComposerMessage\(tabId, queueId\);[\s\S]*?\}/, `${label}: queued message delete should remove the queued item`);
    assert.match(panel, /queued-message-edit/, `${label}: queued item should render an edit button`);
    assert.match(panel, /queued-message-delete/, `${label}: queued item should render a delete button`);
    assert.match(panel, /queuedMessagesEl\?\.addEventListener\('click', \(e\) => \{[\s\S]*?e\.target\.closest\('button\[data-queue-action\]\[data-queue-id\]'\);[\s\S]*?editQueuedComposerMessage\(currentTabId, queueId\);[\s\S]*?\}\);/, `${label}: queued edit button clicks should call the edit helper`);
    assert.match(panel, /inputEl\.addEventListener\('keydown', \(e\) => \{[\s\S]*?if \(e\.isComposing \|\| e\.keyCode === 229\) return;[\s\S]*?if \(handleSlashCommandKeydown\(e\)\) return;[\s\S]*?const isPlainArrow = !e\.altKey && !e\.ctrlKey && !e\.metaKey && !e\.shiftKey;[\s\S]*?if \(e\.key === 'ArrowUp' && editLastQueuedComposerMessageForCurrentTab\(\)\) \{[\s\S]*?e\.preventDefault\(\);[\s\S]*?return;[\s\S]*?\}[\s\S]*?if \(e\.key === 'Enter' && !e\.shiftKey\)/, `${label}: plain ArrowUp should edit queued messages before history and Enter handling`);
    const drainStart = panel.indexOf('function drainQueuedComposerMessageForCurrentTab()');
    const drainEnd = panel.indexOf('function renderClearedConversationForTab', drainStart);
    assert.notEqual(drainStart, -1, `${label}: queued composer drain helper should exist`);
    assert.notEqual(drainEnd, -1, `${label}: queued composer drain helper boundary should exist`);
    const drainBody = panel.slice(drainStart, drainEnd);
    const draftGuardIdx = drainBody.indexOf("if (inputEl.value !== '') return false;");
    const queueShiftIdx = drainBody.indexOf('const item = shiftQueuedComposerMessage(currentTabId);');
    assert.notEqual(draftGuardIdx, -1, `${label}: queued composer drain should preserve newly typed drafts`);
    assert.notEqual(queueShiftIdx, -1, `${label}: queued composer drain should shift the next queued message`);
    assert.equal(draftGuardIdx < queueShiftIdx, true, `${label}: queued composer drain must preserve drafts before removing queued messages`);
    assert.match(panel, /if \(drainQueuedComposerMessageForCurrentTab\(\)\) return;[\s\S]*?drainQueuedContextMenuPrompts\(\);/, `${label}: run settlement should drain queued composer messages before context-menu recovery prompts`);
    const helperStart = panel.indexOf('async function drainQueuedPromptsAfterRunSettles(tabId = currentTabId)');
    const helperEnd = panel.indexOf('function queueAgentUpdateDuringTabSwitch', helperStart);
    assert.notEqual(helperStart, -1, `${label}: queued drain helper should exist`);
    assert.notEqual(helperEnd, -1, `${label}: queued drain helper boundary should exist`);
    const helperBody = panel.slice(helperStart, helperEnd);
    const composerDrainIdx = helperBody.indexOf('if (drainQueuedComposerMessageForCurrentTab()) return;');
    const contextDrainIdx = helperBody.indexOf('drainQueuedContextMenuPrompts();');
    assert.notEqual(composerDrainIdx, -1, `${label}: completed-tab queued composer drain should run in the drain helper`);
    assert.notEqual(contextDrainIdx, -1, `${label}: context-menu prompt drain should run in the drain helper`);
    assert.equal(composerDrainIdx < contextDrainIdx, true, `${label}: queued composer messages for the completed tab must drain before context-menu recovery prompts`);
    assert.match(css, /\.queued-messages/, `${label}: queued message strip should be styled`);
    assert.match(css, /\.queued-message-action/, `${label}: queued message controls should be styled`);
    assert.match(locale, /'sp\.queue\.edit': 'Edit queued message'/, `${label}: queued edit label should have an English fallback`);
    assert.match(locale, /'sp\.queue\.delete': 'Delete queued message'/, `${label}: queued delete label should have an English fallback`);
  }
});

test('sidepanel composer history navigation is queue-aware and draft-safe', () => {
  for (const [label, panelRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');

    assert.match(panel, /const composerHistoryNavigationByTab = new Map\(\);/, `${label}: composer history navigation should be tracked per tab`);
    assert.match(
      panel,
      /function getComposerHistoryEntriesForCurrentTab\(\) \{[\s\S]*?sameTabId\(currentTabId, renderedTabId\)[\s\S]*?querySelectorAll\(':scope > \.message\.user'\)[\s\S]*?map\(getComposerHistoryTextFromMessage\)[\s\S]*?filter\(\(text\) => text\.trim\(\)\);[\s\S]*?\}/,
      `${label}: history recall should read only non-empty user bubbles from the rendered conversation`,
    );
    assert.match(
      panel,
      /function getComposerHistoryTextFromMessage\(messageEl\) \{[\s\S]*?dataset\.composerHistoryText[\s\S]*?if \(typeof protectedText === 'string'\) return protectedText;[\s\S]*?querySelector\('\.message-text'\)\?\.textContent[\s\S]*?dataset\.composerHistoryVerbatim !== 'true'[\s\S]*?isLegacySelectionDisplay \? '' : displayText;[\s\S]*?\}/,
      `${label}: history recall should prefer the protected model-facing payload and omit ambiguous legacy selection bubbles`,
    );
    assert.match(
      panel,
      /if \(role === 'user'\) \{[\s\S]*?const userText = String\(content \|\| ''\);[\s\S]*?const displayText = formatSelectionPromptForDisplay\(userText\);[\s\S]*?if \(displayText === userText\) \{[\s\S]*?dataset\.composerHistoryVerbatim = 'true';[\s\S]*?\} else \{[\s\S]*?dataset\.composerHistoryText = userText;[\s\S]*?\}/,
      `${label}: rendered user bubbles should persist either a verbatim marker or their protected recall payload across DOM restores`,
    );
    assert.match(
      panel,
      /function getComposerCaretRowBoundary\(\) \{[\s\S]*?inputEl\.selectionStart !== inputEl\.selectionEnd[\s\S]*?measureComposerCaretTop\(inputEl\.selectionStart, computedStyle\)[\s\S]*?measureComposerCaretTop\(0, computedStyle\)[\s\S]*?measureComposerCaretTop\(inputEl\.value\.length, computedStyle\)[\s\S]*?atFirstRow:[\s\S]*?atLastRow:[\s\S]*?\}/,
      `${label}: history recall should measure first and last rendered rows and reject active selections`,
    );

    const navigationStart = panel.indexOf('function navigateComposerHistory(direction)');
    const navigationEnd = panel.indexOf('function deleteQueuedComposerMessage', navigationStart);
    assert.notEqual(navigationStart, -1, `${label}: composer history navigation helper missing`);
    assert.notEqual(navigationEnd, -1, `${label}: composer history navigation helper boundary missing`);
    const navigation = panel.slice(navigationStart, navigationEnd);
    assert.match(navigation, /!sameTabId\(currentTabId, renderedTabId\)/, `${label}: history navigation should stay scoped to the rendered tab`);
    assert.match(navigation, /getQueuedComposerMessages\(numericTabId\)\.length[\s\S]*?return false;/, `${label}: queued messages should block sent-history navigation`);
    assert.match(navigation, /if \(direction !== -1 \|\| inputEl\.value !== ''\) return false;/, `${label}: only ArrowUp from an exactly empty composer should start history navigation`);
    assert.match(navigation, /if \(inputEl\.value !== expectedText\) \{[\s\S]*?resetComposerHistoryNavigation\(numericTabId\);[\s\S]*?return false;/, `${label}: changed recalled text should stop navigation instead of being overwritten`);
    assert.match(navigation, /if \(state\.index === 0\) return true;[\s\S]*?state\.index -= 1;/, `${label}: ArrowUp should stop at the oldest entry without wrapping`);
    assert.match(navigation, /if \(state\.index === state\.entries\.length - 1\) \{[\s\S]*?applyComposerHistoryText\(numericTabId, ''\);[\s\S]*?return true;/, `${label}: ArrowDown past the newest entry should restore the empty composer`);
    assert.match(panel, /function handleInput\(\) \{\s*resetComposerHistoryNavigation\(currentTabId\);/, `${label}: editing recalled text should reset navigation state`);
    assert.match(panel, /function applySlashCommandCompletion[\s\S]*?resetComposerHistoryNavigation\(currentTabId\);[\s\S]*?inputEl\.value =/, `${label}: slash completion should replace history navigation state explicitly`);

    const keydownStart = panel.indexOf("inputEl.addEventListener('keydown', (e) => {");
    const keydownEnd = panel.indexOf("inputEl.addEventListener('input', handleInput);", keydownStart);
    assert.notEqual(keydownStart, -1, `${label}: composer keydown handler missing`);
    assert.notEqual(keydownEnd, -1, `${label}: composer keydown handler boundary missing`);
    const keydown = panel.slice(keydownStart, keydownEnd);
    const slashIdx = keydown.indexOf('handleSlashCommandKeydown(e)');
    const queueIdx = keydown.indexOf('editLastQueuedComposerMessageForCurrentTab()');
    const historyUpIdx = keydown.indexOf('navigateComposerHistory(-1)');
    const historyDownIdx = keydown.indexOf('navigateComposerHistory(1)');
    const enterIdx = keydown.indexOf("e.key === 'Enter'");
    assert.ok(slashIdx >= 0 && slashIdx < queueIdx, `${label}: slash autocomplete should keep priority over queued and sent history`);
    assert.ok(queueIdx < historyUpIdx, `${label}: queued-message editing should keep priority over sent history`);
    assert.ok(historyUpIdx < historyDownIdx && historyDownIdx < enterIdx, `${label}: history arrows should run before Enter handling`);
    assert.match(keydown, /if \(e\.isComposing \|\| e\.keyCode === 229\) return;[\s\S]*?const isPlainArrow = !e\.altKey && !e\.ctrlKey && !e\.metaKey && !e\.shiftKey;/, `${label}: modified arrows and IME composition should retain native behavior`);
  }
});

test('sidepanel busy slash notice is updated in every locale', async () => {
  for (const [label, localeDir] of [
    ['chrome', 'src/chrome/src/ui/locales'],
    ['firefox', 'src/firefox/src/ui/locales'],
  ]) {
    for (const filename of fs.readdirSync(path.join(ROOT, localeDir)).filter((name) => name.endsWith('.js'))) {
      const locale = (await import('file://' + path.join(ROOT, localeDir, filename).replace(/\\/g, '/'))).default;
      const message = locale['sp.slash.busy_only_oob'];
      assert.equal(typeof message, 'string', `${label}/${filename}: busy slash notice key missing`);
      for (const syntax of ['/help', '/progress', '/scratchpad', '/memory', '/schedule --list', '/watch', '/dangerously-skip-permissions', '/screenshot', '/export --traces', '/verbose']) {
        assert.match(message, new RegExp(syntax.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')), `${label}/${filename}: busy notice should mention ${syntax}`);
      }
    }
  }
});

test('sidepanel continue runs use the initiating tab state', () => {
  for (const [label, panelRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    const match = panel.match(/async function continueAgent\(options = \{\}\) \{[\s\S]*?\n\}/);
    assert.ok(match, `${label}: continueAgent missing`);
    const body = match[0];
    assert.match(body, /const tabId = currentTabId;[\s\S]*?const modeForSend = \['ask', 'act', 'dev'\]\.includes\(options\?\.mode\) \? options\.mode : agentMode;[\s\S]*?sendRunWithReconnect\('continue_start', \{[\s\S]*?tabId,[\s\S]*?mode: modeForSend,/, `${label}: Continue should send with the tab and requested-or-current mode captured before awaiting`);
    assert.doesNotMatch(body, /sendRunWithReconnect\('continue_start', \{[\s\S]*?tabId: currentTabId/, `${label}: Continue should not read currentTabId inside the async send payload`);
    assert.doesNotMatch(body, /sendRunWithReconnect\('continue_start', \{[\s\S]*?mode: agentMode/, `${label}: Continue should not read agentMode inside the async send payload`);
    assert.match(body, /await prepareChatHistoryForTurn\(tabId, modeForSend\);[\s\S]*?if \(isTabAbortRequested\(tabId\)\) return false;[\s\S]*?if \(!sameTabId\(currentTabId, tabId\) \|\| !sameTabId\(renderedTabId, tabId\)\) return false;[\s\S]*?assistantEl = addMessage\('assistant', ''\);/, `${label}: Continue should hydrate history, honor aborts, and re-check the initiating tab before rendering`);
    assert.match(body, /let assistantEl = null;[\s\S]*?assistantEl = addMessage\('assistant', ''\);[\s\S]*?currentAssistantEl = assistantEl;[\s\S]*?if \(currentTabId === tabId && res\?\.content && assistantEl\) \{[\s\S]*?addMessageCopyButton\(assistantEl\);/, `${label}: Continue should render only into its captured assistant bubble for the initiating tab`);
    assert.match(body, /if \(currentTabId === tabId && assistantEl\) finalizeSteps\(assistantEl\);[\s\S]*?if \(currentAssistantEl === assistantEl\) currentAssistantEl = null;/, `${label}: Continue should finalize and clear only its captured assistant bubble`);
  }
});

test('sidepanel drains queued context-menu prompts on run completion', () => {
  for (const [label, panelRel] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    const completions = [
      ['sendMessage', /async function sendMessage\([^)]*\) \{[\s\S]*?finally \{([\s\S]*?)\n  \}\n  return accepted;/],
      ['continueAgent', /async function continueAgent\(options = \{\}\) \{[\s\S]*?finally \{([\s\S]*?)\n  \}\n\}/],
    ];
    for (const [fnName, pattern] of completions) {
      const match = panel.match(pattern);
      assert.ok(match, `${label}: ${fnName} finally block missing`);
      const finallyBody = match[1];
      const idleIdx = finallyBody.indexOf('setTabProcessing(tabId, false);');
      const helperIdx = finallyBody.indexOf('await drainQueuedPromptsAfterRunSettles(tabId);');
      assert.notEqual(idleIdx, -1, `${label}: ${fnName} should clear processing state`);
      assert.notEqual(helperIdx, -1, `${label}: ${fnName} completion should drain queued prompts via the settlement helper`);
      assert.equal(idleIdx < helperIdx, true, `${label}: ${fnName} context-menu queue must drain after processing is cleared`);
      assert.equal(finallyBody.includes('drainQueuedContextMenuPrompts();'), false, `${label}: ${fnName} should not drain directly against a potentially stale tab`);
    }
  }
});

