test('Ollama launch handoff rejects unsafe base URLs and clamps context', () => {
  for (const normalize of [normalizeOllamaLaunchHandoffCh, normalizeOllamaLaunchHandoffFx]) {
    assert.throws(
      () => normalize({ model: 'qwen3:8b', baseUrl: 'https://evil.example/v1' }),
      /loopback/
    );
    assert.throws(
      () => normalize({ model: 'qwen3:8b', baseUrl: 'http://127.0.0.1:11434/api' }),
      /\/v1/
    );
    assert.throws(
      () => normalize({ model: 'bad\nmodel', baseUrl: 'http://127.0.0.1:11434/v1' }),
      /model/
    );
    const clamped = normalize({
      model: 'qwen3:8b',
      baseUrl: 'http://127.0.0.1:11434',
      contextWindow: '9999999',
    });
    assert.equal(clamped.baseUrl, 'http://127.0.0.1:11434/v1');
    assert.equal(clamped.contextWindow, 1048576);
    // Sub-4k clamps up to the usable min (aligned with detection normalization).
    const small = normalize({
      model: 'qwen3:8b',
      baseUrl: 'http://127.0.0.1:11434/v1',
      contextWindow: '2048',
    });
    assert.equal(small.contextWindow, 4096);
  }
});

test('Ollama vision identity normalizes hosts without folding case-sensitive URL paths', () => {
  for (const [label, canonicalize, PM] of [
    ['chrome', canonicalizeOllamaBaseUrlCh, ProviderManagerCh],
    ['firefox', canonicalizeOllamaBaseUrlFx, ProviderManagerFx],
  ]) {
    assert.equal(
      canonicalize('HTTP://LOCALHOST:11434/Proxy/v1/'),
      'http://localhost:11434/Proxy/v1',
      `${label}: scheme/host and a trailing slash should be canonicalized`,
    );
    assert.notEqual(
      canonicalize('http://localhost:11434/Proxy/v1'),
      canonicalize('http://localhost:11434/proxy/v1'),
      `${label}: proxy path case must remain part of endpoint identity`,
    );

    const manager = new PM();
    const upperPath = manager._ollamaVisionIdentity({
      model: 'same-model',
      baseUrl: 'HTTP://LOCALHOST:11434/Proxy/v1/',
    });
    const normalizedHost = manager._ollamaVisionIdentity({
      model: 'SAME-MODEL',
      baseUrl: 'http://localhost:11434/Proxy/v1',
    });
    const lowerPath = manager._ollamaVisionIdentity({
      model: 'same-model',
      baseUrl: 'http://localhost:11434/proxy/v1',
    });
    assert.equal(upperPath.key, normalizedHost.key, `${label}: equivalent host spelling should share a detection`);
    assert.notEqual(upperPath.key, lowerPath.key, `${label}: case-distinct paths must not share a detection`);

    const defaults = manager._defaultConfigs();
    const provider = manager._createProvider('ollama', {
      ...defaults.ollama,
      baseUrl: lowerPath.baseUrl,
      model: lowerPath.model,
      visionDetection: {
        model: upperPath.model,
        baseUrl: upperPath.baseUrl,
        supportsVision: true,
        source: 'ollama_show',
      },
    });
    assert.equal(provider.supportsVision, false, `${label}: a detection from a case-distinct path must fail closed`);
  }
});

test('Ollama vision auto-detection is model-bound, single-flight, and overrideable', async () => {
  const originalFetch = globalThis.fetch;
  const originalChrome = globalThis.chrome;
  const originalBrowser = globalThis.browser;

  try {
    for (const [label, PM, AgentClass, runtimeKey] of [
      ['chrome', ProviderManagerCh, AgentCh, 'chrome'],
      ['firefox', ProviderManagerFx, AgentFx, 'browser'],
    ]) {
      const writes = [];
      globalThis[runtimeKey] = {
        storage: {
          local: {
            get: async () => ({}),
            set: async (patch) => { writes.push(patch); },
          },
          onChanged: { addListener() {} },
        },
        tabs: {
          get: async () => ({ url: 'https://example.test/', title: 'Example' }),
        },
      };

      let fetchCalls = 0;
      globalThis.fetch = async (url, init = {}) => {
        fetchCalls += 1;
        assert.match(String(url), /\/api\/show$/, `${label}: detection should use Ollama's native show endpoint`);
        const body = JSON.parse(init.body);
        assert.equal(Object.hasOwn(body, 'model'), true, `${label}: show request should use the current model field`);
        const capabilities = body.model === 'gemma3:4b'
          ? ['completion', 'vision']
          : ['completion'];
        return new Response(JSON.stringify({ capabilities }), {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        });
      };

      const mgr = new PM();
      const defaults = mgr._defaultConfigs();
      mgr.providers.set('ollama', mgr._createProvider('ollama', {
        ...defaults.ollama,
        model: 'qwen2.5:3b',
        configured: true,
      }));
      mgr.activeProviderId = 'ollama';

      const [first, second] = await Promise.all([
        mgr.prepareActiveProviderCapabilities(),
        mgr.prepareActiveProviderCapabilities(),
      ]);
      assert.equal(first.ok, true, `${label}: text-only metadata detection should succeed`);
      assert.equal(second.ok, true, `${label}: shared detection should succeed for all waiters`);
      assert.equal(fetchCalls, 1, `${label}: concurrent checks should share one metadata request`);
      assert.equal(mgr.getActive().supportsVision, false, `${label}: qwen2.5 without vision metadata must be text-only`);
      assert.deepEqual(mgr.getActive().config.visionDetection, {
        model: 'qwen2.5:3b',
        baseUrl: 'http://localhost:11434/v1',
        supportsVision: false,
        source: 'ollama_show',
      });
      const agent = new AgentClass(mgr);
      let screenshots = 0;
      agent._captureBudgetedAutoScreenshot = async () => {
        screenshots += 1;
        return { dataUrl: 'data:image/png;base64,AA==', width: 100, height: 100, coordAligned: true };
      };
      const textOnlyEnriched = await agent._enrichUserMessageWithCurrentPage(7, [], 'alo');
      assert.equal(typeof textOnlyEnriched.content, 'string', `${label}: text-only Ollama should keep the first Ask request textual`);
      assert.equal(screenshots, 0, `${label}: text-only Ollama should not capture an initial model-facing screenshot`);
      const prunedHistory = agent._pruneOldImages([{
        role: 'user',
        content: [{ type: 'image_url', image_url: { url: 'data:image/png;base64,AA==' } }],
      }], mgr.getActive());
      assert.equal(prunedHistory[0].content.some((block) => block?.type === 'image_url'), false,
        `${label}: historical screenshots should be removed for auto-detected text-only Ollama`);
      const rejectedAttachment = await agent._applyAttachments(
        { role: 'user', content: 'describe this' },
        [{ kind: 'image', dataUrl: 'data:image/png;base64,AA==', name: 'explicit.png' }],
        mgr.getActive(),
      );
      assert.equal(rejectedAttachment.ok, false, `${label}: an explicit image should be rejected, not silently dropped`);
      assert.match(rejectedAttachment.error, /Force on/, `${label}: Ollama rejection should explain the override`);

      await mgr.updateProvider('ollama', { model: 'gemma3:4b' });
      assert.equal(mgr.getActive().supportsVision, false, `${label}: changing models should invalidate old detection immediately`);
      const vision = await mgr.prepareActiveProviderCapabilities();
      assert.equal(vision.supportsVision, true, `${label}: explicit Ollama vision capability should be honored`);
      assert.equal(mgr.getActive().supportsVision, true, `${label}: matching vision detection should reach the provider`);
      assert.equal(fetchCalls, 2, `${label}: a new model should get its own metadata request`);
      const visionEnriched = await agent._enrichUserMessageWithCurrentPage(7, [], 'what is here?');
      assert.ok(Array.isArray(visionEnriched.content), `${label}: vision-capable Ollama should retain multimodal enrichment`);
      assert.equal(visionEnriched.content.some((block) => block?.type === 'image_url'), true, `${label}: vision-capable Ollama should receive the screenshot`);
      assert.equal(screenshots, 1, `${label}: vision-capable Ollama should capture exactly one initial screenshot`);

      await mgr.updateProvider('ollama', { visionMode: 'off' });
      assert.equal((await mgr.prepareActiveProviderCapabilities()).skipped, true, `${label}: off override should skip metadata`);
      assert.equal(mgr.getActive().supportsVision, false, `${label}: off override should win`);
      await mgr.updateProvider('ollama', { visionMode: 'on' });
      assert.equal((await mgr.prepareActiveProviderCapabilities()).skipped, true, `${label}: on override should skip metadata`);
      assert.equal(mgr.getActive().supportsVision, true, `${label}: on override should win`);
      assert.equal(fetchCalls, 2, `${label}: manual overrides should not call Ollama metadata`);
      assert.ok(writes.length >= 3, `${label}: detection and settings changes should be persisted`);
    }
  } finally {
    globalThis.fetch = originalFetch;
    if (originalChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = originalChrome;
    if (originalBrowser === undefined) delete globalThis.browser;
    else globalThis.browser = originalBrowser;
  }
});

test('Ollama vision detection fails closed and ignores stale responses', async () => {
  const originalFetch = globalThis.fetch;
  const originalChrome = globalThis.chrome;
  const originalBrowser = globalThis.browser;

  try {
    for (const [label, PM, runtimeKey] of [
      ['chrome', ProviderManagerCh, 'chrome'],
      ['firefox', ProviderManagerFx, 'browser'],
    ]) {
      globalThis[runtimeKey] = {
        storage: {
          local: { get: async () => ({}), set: async () => {} },
          onChanged: { addListener() {} },
        },
      };
      let releaseFirst;
      let fetchCalls = 0;
      globalThis.fetch = async (_url, init = {}) => {
        fetchCalls += 1;
        const model = JSON.parse(init.body).model;
        if (model === 'old-model') {
          await new Promise((resolve) => { releaseFirst = resolve; });
          return new Response(JSON.stringify({ capabilities: ['completion', 'vision'] }), { status: 200 });
        }
        if (model === 'unreachable-model') return new Response('missing', { status: 404 });
        if (model === 'malformed-model') return new Response('{not-json', { status: 200 });
        if (model === 'timeout-model') throw new DOMException('The operation was aborted', 'AbortError');
        return new Response(JSON.stringify({ capabilities: ['completion'] }), { status: 200 });
      };

      const mgr = new PM();
      const defaults = mgr._defaultConfigs();
      mgr.providers.set('ollama', mgr._createProvider('ollama', {
        ...defaults.ollama,
        model: 'old-model',
        configured: true,
      }));
      mgr.activeProviderId = 'ollama';

      const staleCheck = mgr.prepareActiveProviderCapabilities();
      await Promise.resolve();
      await mgr.updateProvider('ollama', { model: 'new-model' });
      releaseFirst();
      const stale = await staleCheck;
      assert.equal(stale.stale, true, `${label}: a late response should be marked stale`);
      assert.equal(mgr.getActive().config.visionDetection, null, `${label}: a stale response must not update the new model`);
      assert.equal(mgr.getActive().supportsVision, false, `${label}: the new model should stay fail-closed until checked`);

      await mgr.updateProvider('ollama', { model: 'unreachable-model' });
      const unavailable = await mgr.prepareActiveProviderCapabilities();
      assert.equal(unavailable.ok, false, `${label}: HTTP metadata failure should be non-authoritative`);
      assert.equal(mgr.getActive().supportsVision, false, `${label}: metadata failure should fail closed`);
      assert.equal(mgr.getActive().config.visionDetection, null, `${label}: metadata failure must not persist text-only detection`);
      await mgr.prepareActiveProviderCapabilities();
      assert.equal(fetchCalls, 3, `${label}: a failed key should be evicted so a later turn can retry`);

      await mgr.updateProvider('ollama', { model: 'malformed-model' });
      const malformed = await mgr.prepareActiveProviderCapabilities();
      assert.equal(malformed.ok, false, `${label}: malformed JSON should fail closed`);
      assert.equal(mgr.getActive().config.visionDetection, null, `${label}: malformed JSON must not persist a false result`);

      await mgr.updateProvider('ollama', { model: 'timeout-model' });
      const timedOut = await mgr.prepareActiveProviderCapabilities();
      assert.equal(timedOut.ok, false, `${label}: a metadata timeout should fail closed`);
      assert.equal(mgr.getActive().supportsVision, false, `${label}: a timed-out turn must remain text-only`);
      assert.equal(fetchCalls, 5, `${label}: distinct models and the retried failed key should each issue metadata requests`);

      const managerSource = fs.readFileSync(path.join(ROOT, `src/${label}/src/providers/manager.js`), 'utf8');
      assert.match(managerSource, /OLLAMA_VISION_METADATA_TIMEOUT_MS\s*=\s*3000/,
        `${label}: Ollama metadata should use a three-second timeout`);
      assert.match(managerSource, /timeoutMs:\s*OLLAMA_VISION_METADATA_TIMEOUT_MS/,
        `${label}: the metadata request should apply the bounded timeout`);
      assert.match(managerSource, /Promise\.race\(\[request, timeout\]\)/,
        `${label}: the three-second bound should include response JSON parsing`);
      assert.match(managerSource, /signal:\s*controller\.signal/,
        `${label}: metadata fetch should receive the timeout controller signal`);
      assert.match(managerSource, /controller\.abort\(/,
        `${label}: the outer metadata timeout should abort the losing request`);
    }
  } finally {
    globalThis.fetch = originalFetch;
    if (originalChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = originalChrome;
    if (originalBrowser === undefined) delete globalThis.browser;
    else globalThis.browser = originalBrowser;
  }
});

test('Ollama vision metadata timeout aborts stalled response bodies', async () => {
  const originalFetch = globalThis.fetch;
  const originalChrome = globalThis.chrome;
  const originalBrowser = globalThis.browser;
  const abortedModels = new Set();

  try {
    const runtime = {
      storage: {
        local: { get: async () => ({}), set: async () => {} },
        onChanged: { addListener() {} },
      },
    };
    globalThis.chrome = runtime;
    globalThis.browser = runtime;
    globalThis.fetch = async (_url, init = {}) => {
      const model = JSON.parse(init.body).model;
      let streamController;
      const stream = new ReadableStream({
        start(controller) { streamController = controller; },
      });
      init.signal.addEventListener('abort', () => {
        abortedModels.add(model);
        try { streamController.error(init.signal.reason); } catch {}
      }, { once: true });
      return new Response(stream, { status: 200, headers: { 'Content-Type': 'application/json' } });
    };

    const checks = [
      ['chrome', ProviderManagerCh, 'stalled-chrome'],
      ['firefox', ProviderManagerFx, 'stalled-firefox'],
    ].map(async ([label, PM, model]) => {
      const manager = new PM();
      const defaults = manager._defaultConfigs();
      manager.providers.set('ollama', manager._createProvider('ollama', {
        ...defaults.ollama,
        model,
        configured: true,
      }));
      manager.activeProviderId = 'ollama';
      const result = await manager.prepareActiveProviderCapabilities();
      assert.equal(result.ok, false, `${label}: a stalled body should fail closed`);
      assert.equal(manager.getActive().supportsVision, false, `${label}: a stalled body must not enable screenshots`);
    });

    await Promise.all(checks);
    assert.deepEqual(
      [...abortedModels].sort(),
      ['stalled-chrome', 'stalled-firefox'],
      'both browser paths should abort their stalled body when the metadata deadline wins',
    );
  } finally {
    globalThis.fetch = originalFetch;
    if (originalChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = originalChrome;
    if (originalBrowser === undefined) delete globalThis.browser;
    else globalThis.browser = originalBrowser;
  }
});

test('ProviderManager persists detected local context windows with safe apply policy', async () => {
  const originalFetch = globalThis.fetch;
  const originalChrome = globalThis.chrome;
  const originalBrowser = globalThis.browser;

  function makeRuntime(writes) {
    return {
      storage: {
        local: {
          async get() { return {}; },
          async set(patch) { writes.push(patch); },
        },
      },
      runtime: { id: 'test-runtime' },
    };
  }

  function jsonOk(body) {
    return new Response(JSON.stringify(body), {
      status: 200,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  function chatOk() {
    return jsonOk({ choices: [{ message: { content: 'ok' } }] });
  }

  try {
    for (const [label, PM, runtimeKey] of [
      ['chrome', ProviderManagerCh, 'chrome'],
      ['firefox', ProviderManagerFx, 'browser'],
    ]) {
      // llama.cpp: refresh default 16k from /props
      {
        const writes = [];
        globalThis[runtimeKey] = makeRuntime(writes);
        globalThis.fetch = async (url) => {
          const u = String(url);
          if (u.endsWith('/props')) return jsonOk({ default_generation_settings: { n_ctx: 8192 } });
          if (u.includes('/chat/completions')) return chatOk();
          return new Response('missing', { status: 404 });
        };
        const mgr = new PM();
        const config = { ...mgr._defaultConfigs().llamacpp, baseUrl: 'http://localhost:8080', model: 'local' };
        mgr.providers.set('llamacpp', mgr._createProvider('llamacpp', config));
        const result = await mgr.testProvider('llamacpp');
        assert.equal(result.ok, true, `${label}: llama test ok`);
        assert.equal(result.contextWindow, 8192, `${label}: llama returns detected window`);
        assert.equal(mgr.providers.get('llamacpp').config.contextWindow, 8192, `${label}: llama persists`);
        assert.ok(
          writes.some((patch) => patch.providers?.llamacpp?.contextWindow === 8192),
          `${label}: llama persistence writes detected window to storage`
        );
      }

      // Ollama /api/ps live: may shrink a manual override
      {
        const writes = [];
        globalThis[runtimeKey] = makeRuntime(writes);
        globalThis.fetch = async (url) => {
          const u = String(url);
          if (u.endsWith('/api/ps')) {
            return jsonOk({ models: [{ name: 'qwen3:8b', context_length: 8192 }] });
          }
          if (u.includes('/chat/completions')) return chatOk();
          return new Response('missing', { status: 404 });
        };
        const mgr = new PM();
        const config = {
          ...mgr._defaultConfigs().ollama,
          model: 'qwen3:8b',
          contextWindow: 65536,
        };
        mgr.providers.set('ollama', mgr._createProvider('ollama', config));
        const result = await mgr.testProvider('ollama');
        assert.equal(result.ok, true, `${label}: ollama ps test ok`);
        assert.equal(result.contextWindow, 8192, `${label}: ollama ps shrinks override`);
        assert.equal(mgr.providers.get('ollama').config.contextWindow, 8192);
        assert.ok(
          writes.some((patch) => patch.providers?.ollama?.contextWindow === 8192),
          `${label}: ollama persistence writes detected window to storage`
        );
      }

      // Ollama /api/show only: refresh default, but do not shrink manual override
      {
        globalThis[runtimeKey] = makeRuntime([]);
        globalThis.fetch = async (url, init = {}) => {
          const u = String(url);
          if (u.endsWith('/api/ps')) return jsonOk({ models: [] });
          if (u.endsWith('/api/show') && init.method === 'POST') {
            return jsonOk({ parameters: 'num_ctx 8192' });
          }
          if (u.includes('/chat/completions')) return chatOk();
          return new Response('missing', { status: 404 });
        };
        const mgr = new PM();
        const config = {
          ...mgr._defaultConfigs().ollama,
          model: 'qwen3:8b',
          contextWindow: 65536,
        };
        mgr.providers.set('ollama', mgr._createProvider('ollama', config));
        const result = await mgr.testProvider('ollama');
        assert.equal(result.ok, true, `${label}: ollama show test ok`);
        assert.equal(result.contextWindow, undefined, `${label}: show-only must not shrink override`);
        assert.equal(mgr.providers.get('ollama').config.contextWindow, 65536);

        const mgrDefault = new PM();
        const defaultConfig = {
          ...mgrDefault._defaultConfigs().ollama,
          model: 'qwen3:8b',
          contextWindow: 16384,
        };
        mgrDefault.providers.set('ollama', mgrDefault._createProvider('ollama', defaultConfig));
        const refreshed = await mgrDefault.testProvider('ollama');
        assert.equal(refreshed.contextWindow, 8192, `${label}: show-only refreshes default`);
        assert.equal(mgrDefault.providers.get('ollama').config.contextWindow, 8192);
      }

      // In-flight detection must not write stale context to a changed provider config.
      {
        const writes = [];
        globalThis[runtimeKey] = makeRuntime(writes);
        const mgr = new PM();
        const config = {
          ...mgr._defaultConfigs().ollama,
          baseUrl: 'http://localhost:11434/v1',
          model: 'qwen3:8b',
          contextWindow: 65536,
        };
        mgr.providers.set('ollama', mgr._createProvider('ollama', config));

        let releaseDetection;
        mgr._detectLocalContextWindow = async () => {
          await new Promise((resolve) => { releaseDetection = resolve; });
          return { contextWindow: 8192, shrinkOverride: true };
        };

        const pending = mgr._attachDetectedContextWindow('ollama', mgr.providers.get('ollama'), { ok: true });
        await Promise.resolve();
        await mgr.updateProvider('ollama', { model: 'llama3:8b' });
        releaseDetection();

        const result = await pending;
        assert.equal(result.contextWindow, undefined, `${label}: stale attach detection is not returned`);
        assert.equal(mgr.providers.get('ollama').config.model, 'llama3:8b');
        assert.equal(mgr.providers.get('ollama').config.contextWindow, 65536);
        assert.equal(
          writes.some((patch) =>
            patch.providers?.ollama?.model === 'llama3:8b' &&
            patch.providers?.ollama?.contextWindow === 8192
          ),
          false,
          `${label}: stale attach detection is not written after model changes`
        );
      }

      // Preferred model missing from /api/ps must not borrow another running model
      {
        globalThis[runtimeKey] = makeRuntime([]);
        globalThis.fetch = async (url, init = {}) => {
          const u = String(url);
          if (u.endsWith('/api/ps')) {
            return jsonOk({ models: [{ name: 'other:latest', context_length: 32768 }] });
          }
          if (u.endsWith('/api/show') && init.method === 'POST') {
            return jsonOk({ parameters: 'num_ctx 8192' });
          }
          if (u.includes('/chat/completions')) return chatOk();
          return new Response('missing', { status: 404 });
        };
        const mgr = new PM();
        const config = {
          ...mgr._defaultConfigs().ollama,
          model: 'qwen3:8b',
          contextWindow: 16384,
        };
        mgr.providers.set('ollama', mgr._createProvider('ollama', config));
        const result = await mgr.testProvider('ollama');
        assert.equal(result.contextWindow, 8192, `${label}: falls back to show when ps misses preferred`);
        assert.equal(mgr.providers.get('ollama').config.contextWindow, 8192);
      }

      // LM Studio load models path
      {
        const writes = [];
        globalThis[runtimeKey] = makeRuntime(writes);
        globalThis.fetch = async (url) => {
          const u = String(url);
          if (u.includes('/api/v0/models')) {
            return jsonOk({
              data: [
                {
                  id: 'chat-a',
                  type: 'llm',
                  state: 'loaded',
                  loaded_context_length: 4096,
                  max_context_length: 32768,
                },
                {
                  id: 'chat-b',
                  type: 'llm',
                  state: 'loaded',
                  loaded_context_length: 8192,
                  max_context_length: 32768,
                },
              ],
            });
          }
          return new Response('missing', { status: 404 });
        };
        const mgr = new PM();
        const config = {
          ...mgr._defaultConfigs().lmstudio,
          model: 'chat-a',
          contextWindow: 16384,
        };
        mgr.providers.set('lmstudio', mgr._createProvider('lmstudio', config));
        const result = await mgr.listProviderModels('lmstudio');
        assert.equal(result.ok, true, `${label}: lmstudio list ok`);
        assert.equal(result.contextWindow, undefined, `${label}: lmstudio list does not persist previous-model context`);
        assert.equal(mgr.providers.get('lmstudio').config.contextWindow, 16384);
        const staleDetection = await mgr.detectProviderContextWindow('lmstudio', 'chat-b');
        assert.equal(staleDetection.ok, false, `${label}: lmstudio detection requires the selected model to be saved`);
        await mgr.updateProvider('lmstudio', { model: 'chat-b' });
        const detected = await mgr.detectProviderContextWindow('lmstudio', 'chat-b');
        assert.equal(detected.ok, true, `${label}: lmstudio selected-model detection ok`);
        assert.equal(detected.contextWindow, 8192, `${label}: lmstudio detects selected loaded context`);
        assert.equal(mgr.providers.get('lmstudio').config.contextWindow, 8192);
        assert.ok(
          writes.some((patch) =>
            patch.providers?.lmstudio?.model === 'chat-b' &&
            patch.providers?.lmstudio?.contextWindow === 8192
          ),
          `${label}: lmstudio selected-model persistence writes context window to storage`
        );
      }

      // vLLM /v1/models includes max_model_len on model cards.
      {
        const writes = [];
        globalThis[runtimeKey] = makeRuntime(writes);
        globalThis.fetch = async (url) => {
          const u = String(url);
          if (u.endsWith('/models')) {
            return jsonOk({
              data: [
                { id: 'other-model', max_model_len: 32768 },
                { id: 'served-model', max_model_len: 65536 },
              ],
            });
          }
          return new Response('missing', { status: 404 });
        };
        const mgr = new PM();
        const config = {
          ...mgr._defaultConfigs().vllm,
          model: 'served-model',
          contextWindow: 16384,
        };
        mgr.providers.set('vllm', mgr._createProvider('vllm', config));
        const result = await mgr.listProviderModels('vllm');
        assert.equal(result.ok, true, `${label}: vllm list ok`);
        assert.deepEqual(result.models, ['other-model', 'served-model']);
        assert.equal(result.contextWindow, 65536, `${label}: vllm detects matching max_model_len`);
        assert.equal(mgr.providers.get('vllm').config.contextWindow, 65536);
        assert.ok(
          writes.some((patch) => patch.providers?.vllm?.contextWindow === 65536),
          `${label}: vllm persistence writes detected window to storage`
        );
      }

      // SGLang model cards also expose max_model_len; treat it as runtime max.
      {
        const writes = [];
        globalThis[runtimeKey] = makeRuntime(writes);
        globalThis.fetch = async (url) => {
          if (String(url).endsWith('/models')) {
            return jsonOk({ data: [{ id: 'sglang-model', max_model_len: 8192 }] });
          }
          return new Response('missing', { status: 404 });
        };
        const mgr = new PM();
        const config = {
          ...mgr._defaultConfigs().sglang,
          model: 'sglang-model',
          contextWindow: 65536,
        };
        mgr.providers.set('sglang', mgr._createProvider('sglang', config));
        const result = await mgr.detectProviderContextWindow('sglang', 'sglang-model');
        assert.equal(result.ok, true, `${label}: sglang selected-model detection ok`);
        assert.equal(result.contextWindow, 8192, `${label}: sglang shrinks stale manual override`);
        assert.equal(mgr.providers.get('sglang').config.contextWindow, 8192);
        assert.ok(
          writes.some((patch) => patch.providers?.sglang?.contextWindow === 8192),
          `${label}: sglang persistence writes detected window to storage`
        );
      }

      // LocalAI exposes configured context_size through its model config API.
      {
        const writes = [];
        const calls = [];
        globalThis[runtimeKey] = makeRuntime(writes);
        globalThis.fetch = async (url, init = {}) => {
          calls.push({ url: String(url), headers: init.headers || {} });
          if (String(url).endsWith('/api/models/config-json/owner%2Flocal-model')) {
            return jsonOk({ context_size: 24576 });
          }
          return new Response('missing', { status: 404 });
        };
        const mgr = new PM();
        const config = {
          ...mgr._defaultConfigs().localai,
          model: 'owner/local-model',
          contextWindow: 16384,
          apiKey: 'localai-secret',
        };
        mgr.providers.set('localai', mgr._createProvider('localai', config));
        const result = await mgr.detectProviderContextWindow('localai', 'owner/local-model');
        assert.equal(result.ok, true, `${label}: localai selected-model detection ok`);
        assert.equal(result.contextWindow, 24576, `${label}: localai detects configured context_size`);
        assert.equal(mgr.providers.get('localai').config.contextWindow, 24576);
        assert.equal(calls[0].headers.Authorization, 'Bearer localai-secret');
        assert.ok(
          writes.some((patch) => patch.providers?.localai?.contextWindow === 24576),
          `${label}: localai persistence writes detected window to storage`
        );
      }

      // Model-pick detection must also fail closed if the base URL changes mid-flight.
      {
        const writes = [];
        globalThis[runtimeKey] = makeRuntime(writes);
        const mgr = new PM();
        const config = {
          ...mgr._defaultConfigs().lmstudio,
          baseUrl: 'http://localhost:1234/v1',
          model: 'chat-b',
          contextWindow: 16384,
        };
        mgr.providers.set('lmstudio', mgr._createProvider('lmstudio', config));

        let releaseDetection;
        mgr._detectLocalContextWindow = async () => {
          await new Promise((resolve) => { releaseDetection = resolve; });
          return { contextWindow: 8192, shrinkOverride: true };
        };

        const pending = mgr.detectProviderContextWindow('lmstudio', 'chat-b');
        await Promise.resolve();
        await mgr.updateProvider('lmstudio', { baseUrl: 'http://localhost:5678/v1' });
        releaseDetection();

        const result = await pending;
        assert.equal(result.ok, false, `${label}: stale selected-model detection fails closed`);
        assert.equal(result.contextWindow, undefined, `${label}: stale selected-model detection is not returned`);
        assert.equal(mgr.providers.get('lmstudio').config.baseUrl, 'http://localhost:5678/v1');
        assert.equal(mgr.providers.get('lmstudio').config.contextWindow, 16384);
        assert.equal(
          writes.some((patch) =>
            patch.providers?.lmstudio?.baseUrl === 'http://localhost:5678/v1' &&
            patch.providers?.lmstudio?.contextWindow === 8192
          ),
          false,
          `${label}: stale selected-model detection is not written after base URL changes`
        );
      }
    }
  } finally {
    globalThis.fetch = originalFetch;
    if (originalChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = originalChrome;
    if (originalBrowser === undefined) delete globalThis.browser;
    else globalThis.browser = originalBrowser;
  }
});

