test('WebBrain Compass 402 formatting and localized billing actions distinguish every quota tier', async () => {
  for (const [label, Provider, AgentClass] of [
    ['chrome', OpenAIProviderCh, AgentCh],
    ['firefox', OpenAIProviderFx, AgentFx],
  ]) {
    const provider = new Provider({
      providerName: 'webbrain-cloud',
      deviceGuid: 'device-guid',
    });
    const subscribe = provider._formatHttpError(402, JSON.stringify({
      error: { message: 'Free allowance used.', code: 'webbrain_cloud_free_tier_exceeded' },
      subscribe_url: 'https://buy.stripe.com/base?client_reference_id=device-guid',
    }));
    assert.match(subscribe, /Subscribe for more usage: https:\/\/buy\.stripe\.com\/base/, `${label}: free quota should offer subscription checkout`);

    const upgrade = provider._formatHttpError(402, JSON.stringify({
      error: { message: 'Paid allowance used.', code: 'webbrain_cloud_paid_tier_exceeded' },
      upgrade_url: 'https://api.webbrain.one/upgrade?client_reference_id=device-guid',
    }));
    assert.match(upgrade, /Upgrade to WebBrain Plus: https:\/\/api\.webbrain\.one\/upgrade/, `${label}: base paid quota should offer the Plus upgrade flow`);

    const plusBody = JSON.stringify({
      error: { message: 'Votre quota Plus quotidien est épuisé.', code: 'webbrain_cloud_plus_tier_exceeded' },
    });
    const plus = provider._formatHttpError(402, plusBody);
    assert.equal(plus, 'Votre quota Plus quotidien est épuisé.', `${label}: Plus exhaustion must not offer a duplicate subscription action`);
    const plusError = provider._httpError(402, plusBody, 'webbrain-cloud error 402');
    assert.equal(plusError.code, 'webbrain_cloud_plus_tier_exceeded', `${label}: provider error code should survive HTTP formatting`);
    assert.equal(new AgentClass({})._isCostAllowanceError(plusError), true, `${label}: localized Plus exhaustion should remain terminal by stable code`);
  }

  const localeCodes = [
    'ar', 'bn', 'de', 'en', 'es', 'fa', 'fr', 'he', 'hi', 'id', 'ja', 'ko',
    'ms', 'nl', 'pl', 'pt', 'ru', 'th', 'tl', 'tr', 'uk', 'vi', 'zh',
  ];
  const english = (await import(pathToFileURL(path.join(ROOT, 'src/chrome/src/ui/locales/en.js')).href)).default;
  for (const locale of localeCodes) {
    const chromeLocale = (await import(pathToFileURL(path.join(ROOT, `src/chrome/src/ui/locales/${locale}.js`)).href)).default;
    const firefoxLocale = (await import(pathToFileURL(path.join(ROOT, `src/firefox/src/ui/locales/${locale}.js`)).href)).default;
    for (const key of ['sp.subscribe.upgrade', 'sp.subscribe.resume_upgrade']) {
      assert.equal(chromeLocale[key], firefoxLocale[key], `${locale}: ${key} should match across browsers`);
      assert.ok(chromeLocale[key]?.trim(), `${locale}: ${key} should not be empty`);
      if (locale !== 'en') {
        assert.notEqual(chromeLocale[key], english[key], `${locale}: ${key} should not fall back to English`);
      }
    }
  }
});

test('WebBrain Compass quota errors stay terminal in the main streaming agent loop', async () => {
  for (const [index, AgentClass] of [AgentCh, AgentFx].entries()) {
    const quotaMessage = 'Votre quota Plus quotidien est épuisé.';
    const provider = {
      supportsTools: true,
      supportsVision: false,
      promptTier: 'full',
      contextWindow: 128000,
      model: 'webbrain-cloud 1.0',
      name: 'webbrain-cloud',
      calls: 0,
      async *chatStream() {
        this.calls += 1;
        const error = new Error(quotaMessage);
        error.code = 'webbrain_cloud_plus_tier_exceeded';
        throw error;
      },
    };
    const agent = new AgentClass({ getActive: () => provider, getVisionProvider: async () => null });
    const tabId = 5490 + index;
    configurePlanOnlyGuardAgent(agent, tabId);
    const updates = [];
    let traceStatus = null;
    agent._startTraceRun = async () => `quota_stream_${index}`;
    agent._endTraceRun = (_tabId, _runId, status) => { traceStatus = status; };

    const final = await agent.processMessageStream(
      tabId,
      'Continue the task.',
      (type, data) => updates.push({ type, data }),
      'act',
    );

    assert.equal(final, quotaMessage, `${AgentClass.name}: streaming quota should return the billing message`);
    assert.equal(traceStatus, 'cost_limit', `${AgentClass.name}: streaming quota should finish as cost_limit`);
    assert.equal(provider.calls, 1, `${AgentClass.name}: streaming quota should not retry`);
    assert.equal(updates.filter(update => update.type === 'warning' && update.data?.message === quotaMessage).length, 1, `${AgentClass.name}: streaming quota should emit one actionable warning`);
    assert.equal(updates.some(update => update.type === 'error'), false, `${AgentClass.name}: streaming quota should not emit generic error UI`);
    assert.equal(agent.getConversation(tabId, 'act').filter(message => message.role === 'assistant' && message.content === quotaMessage).length, 1, `${AgentClass.name}: streaming quota should persist one assistant billing message`);
  }
});

test('new provider auth, endpoint, protocol, and capability contracts are deterministic', () => {
  for (const [label, OpenAIProvider, VertexProvider, PM] of [
    ['chrome', OpenAIProviderCh, VertexAnthropicProviderCh, ProviderManagerCh],
    ['firefox', OpenAIProviderFx, VertexAnthropicProviderFx, ProviderManagerFx],
  ]) {
    const bearer = new OpenAIProvider({ providerName: 'deepinfra', apiKey: 'secret' });
    assert.equal(bearer._headers().Authorization, 'Bearer secret', `${label}: default auth should be bearer`);

    const vertex = new OpenAIProvider({
      providerName: 'google-vertex',
      baseUrl: 'https://{vertex_endpoint}/v1/projects/{project}/locations/{location}/endpoints/openapi',
      project: 'sample-project',
      location: 'us-central1',
      apiKey: 'google-key',
      apiKeyHeader: 'x-goog-api-key',
    });
    assert.equal(
      vertex.baseUrl,
      'https://us-central1-aiplatform.googleapis.com/v1/projects/sample-project/locations/us-central1/endpoints/openapi',
      `${label}: Vertex endpoint interpolation mismatch`,
    );
    assert.equal(vertex._headers()['x-goog-api-key'], 'google-key');
    assert.equal(vertex._headers().Authorization, undefined);

    const globalVertex = new OpenAIProvider({
      providerName: 'google-vertex',
      baseUrl: 'https://{vertex_endpoint}/v1/projects/{project}/locations/{location}/endpoints/openapi',
      project: 'sample-project',
      location: 'global',
      apiKey: 'google-key',
      apiKeyHeader: 'x-goog-api-key',
    });
    assert.equal(
      globalVertex.baseUrl,
      'https://aiplatform.googleapis.com/v1/projects/sample-project/locations/global/endpoints/openapi',
      `${label}: Vertex global location must use the global endpoint host`,
    );

    const azure = new OpenAIProvider({
      providerName: 'azure-cognitive-services',
      baseUrl: 'https://{resource}.openai.azure.com/openai/v1',
      resource: 'sample-resource',
      apiKey: 'azure-key',
      apiKeyHeader: 'api-key',
    });
    assert.equal(azure.baseUrl, 'https://sample-resource.openai.azure.com/openai/v1');
    assert.equal(azure._headers()['api-key'], 'azure-key');
    assert.equal(azure._headers().Authorization, undefined);

    const cloudflare = new OpenAIProvider({
      providerName: 'cloudflare',
      baseUrl: 'https://api.cloudflare.com/client/v4/accounts/{account_id}/ai/v1',
      accountId: '0123456789abcdef0123456789abcdef',
      gatewayId: 'my-gateway',
      apiKey: 'cf-token',
    });
    assert.match(cloudflare.baseUrl, /accounts\/0123456789abcdef0123456789abcdef\/ai\/v1$/);
    assert.equal(cloudflare._headers()['cf-aig-gateway-id'], 'my-gateway');

    const cloudflareDefaultGateway = new OpenAIProvider({
      providerName: 'cloudflare',
      model: '@cf/moonshotai/kimi-k2.6',
    });
    assert.equal(
      cloudflareDefaultGateway._headers()['cf-aig-gateway-id'],
      'default',
      `${label}: Workers AI models require a gateway header`,
    );
    const cloudflareThirdParty = new OpenAIProvider({
      providerName: 'cloudflare',
      model: 'anthropic/claude-sonnet-4',
    });
    assert.equal(
      cloudflareThirdParty._headers()['cf-aig-gateway-id'],
      undefined,
      `${label}: third-party models may use Cloudflare's implicit default gateway`,
    );

    const perplexityAgent = new OpenAIProvider({
      providerName: 'perplexity-agent',
      baseUrl: 'https://api.perplexity.ai/v1',
      apiFormat: 'responses',
      model: 'xai/grok-4-1-fast-non-reasoning',
    });
    assert.equal(perplexityAgent._usesResponsesApi(), true);
    assert.equal(perplexityAgent._responsesUrl(), 'https://api.perplexity.ai/v1/responses');

    const vertexAnthropic = new VertexProvider({
      project: 'sample-project',
      location: 'us-east5',
      apiKey: 'google-key',
      model: 'claude-haiku-4-5@20251001',
      extraBody: { thinking: { type: 'adaptive' } },
    });
    assert.match(vertexAnthropic._messagesUrl(false), /publishers\/anthropic\/models\/claude-haiku-4-5%4020251001:rawPredict$/);
    assert.match(vertexAnthropic._messagesUrl(true), /:streamRawPredict$/);
    assert.match(vertexAnthropic._messagesUrl(false), /^https:\/\/us-east5-aiplatform\.googleapis\.com\//);
    assert.equal(vertexAnthropic._headers()['x-goog-api-key'], 'google-key');
    const vertexBody = vertexAnthropic._prepareRequestBody(
      { model: 'ignored', messages: [], max_tokens: 16, temperature: 0.3 },
      {
        extraBody: {
          thinking: { display: 'summarized' },
          anthropic_version: 'must-not-win',
          model: 'override',
        },
      },
      false,
    );
    assert.equal(vertexBody.model, undefined);
    assert.equal(vertexBody.temperature, undefined);
    assert.equal(vertexBody.anthropic_version, 'vertex-2023-10-16');
    assert.deepEqual(vertexBody.thinking, { type: 'adaptive', display: 'summarized' });
    assert.match(
      new VertexProvider({
        project: 'sample-project',
        location: 'global',
        apiKey: 'google-key',
        model: 'claude-haiku-4-5@20251001',
      })._messagesUrl(false),
      /^https:\/\/aiplatform\.googleapis\.com\/v1\/projects\/sample-project\/locations\/global\//,
      `${label}: Vertex Anthropic global location must use the global endpoint`,
    );
    for (const location of ['us', 'eu']) {
      assert.match(
        new VertexProvider({
          project: 'sample-project',
          location,
          apiKey: 'google-key',
          model: 'claude-haiku-4-5@20251001',
        })._messagesUrl(false),
        new RegExp(`^https://aiplatform\\.${location}\\.rep\\.googleapis\\.com/v1/projects/sample-project/locations/${location}/`),
        `${label}: Vertex Anthropic ${location} must use its multi-region endpoint`,
      );
    }

    const defaults = new PM()._defaultConfigs();
    assert.equal(new PM()._createProvider('morph', defaults.morph).supportsTools, false);
    assert.equal(new PM()._createProvider('perplexity', defaults.perplexity).supportsTools, false);
    assert.equal(new PM()._createProvider('aws_bedrock', defaults.aws_bedrock).supportsAskStreaming, false);
  }
});

test('Chat Completions streaming rejects premature EOF and accepts terminal completion', async () => {
  const originalFetch = globalThis.fetch;
  try {
    for (const [label, Provider] of [
      ['chrome', OpenAIProviderCh],
      ['firefox', OpenAIProviderFx],
    ]) {
      globalThis.fetch = async () => new Response(
        'data: {"choices":[{"delta":{"content":"partial"}}]}\n\n',
        { status: 200, headers: { 'Content-Type': 'text/event-stream' } },
      );
      const truncated = new Provider({
        providerName: 'deepinfra',
        baseUrl: 'https://api.deepinfra.com/v1/openai',
        model: 'test-model',
        supportsAskStreaming: true,
      });
      await assert.rejects(
        async () => {
          for await (const _chunk of truncated.chatStream([{ role: 'user', content: 'hi' }])) {}
        },
        (error) => error?.isAskStreamFallbackSafe === true,
        `${label}: truncated stream should be fallback-safe`,
      );

      globalThis.fetch = async () => new Response(
        'data: {"choices":[{"delta":{"content":"done"},"finish_reason":"stop"}]}\n\n',
        { status: 200, headers: { 'Content-Type': 'text/event-stream' } },
      );
      const complete = [];
      for await (const chunk of truncated.chatStream([{ role: 'user', content: 'hi' }])) {
        complete.push(chunk);
      }
      assert.deepEqual(complete, [
        { type: 'text', content: 'done' },
        { type: 'done', content: '', finishReason: 'stop' },
      ], `${label}: terminal finish_reason should complete the stream`);
    }
  } finally {
    globalThis.fetch = originalFetch;
  }
});

test('OpenAI SSE parsers accept data fields without the optional space', async () => {
  const originalFetch = globalThis.fetch;
  try {
    for (const [label, Provider] of [
      ['chrome', OpenAIProviderCh],
      ['firefox', OpenAIProviderFx],
    ]) {
      globalThis.fetch = async () => new Response([
        `data:${JSON.stringify({ choices: [{ delta: { content: 'chat' } }] })}\n\n`,
        'data:[DONE]\n\n',
      ].join(''), { status: 200, headers: { 'Content-Type': 'text/event-stream' } });
      const chatProvider = new Provider({
        providerName: 'openai',
        baseUrl: 'https://api.openai.com/v1',
        model: 'gpt-5.5',
      });
      const chatChunks = [];
      for await (const chunk of chatProvider.chatStream([{ role: 'user', content: 'hello' }])) chatChunks.push(chunk);
      assert.deepEqual(chatChunks, [
        { type: 'text', content: 'chat' },
        { type: 'done', content: '' },
      ], `${label}: Chat Completions dropped a spec-valid data: line`);

      globalThis.fetch = async () => new Response([
        `data:${JSON.stringify({ type: 'response.output_text.delta', delta: 'responses' })}\n\n`,
        `data:${JSON.stringify({ type: 'response.completed', response: { output: [] } })}\n\n`,
      ].join(''), { status: 200, headers: { 'Content-Type': 'text/event-stream' } });
      const responsesProvider = new Provider({
        providerName: 'openai',
        baseUrl: 'https://api.openai.com/v1',
        model: 'gpt-5.6-terra',
      });
      const responseChunks = [];
      for await (const chunk of responsesProvider.chatStream([{ role: 'user', content: 'hello' }])) responseChunks.push(chunk);
      assert.deepEqual(responseChunks, [
        { type: 'text', content: 'responses' },
        { type: 'done', content: '', responseItems: [] },
      ], `${label}: Responses API dropped a spec-valid data: line`);
    }
  } finally {
    globalThis.fetch = originalFetch;
  }
});

test('_defaultConfigs: new cloud providers present and disabled by default', () => {
  // Don't enable cloud providers by default — they all require an API key.
  // Auto-enabling them would create dead entries in the UI.
  for (const PM of [ProviderManagerCh, ProviderManagerFx]) {
    const mgr = new PM();
    const defaults = mgr._defaultConfigs();
    for (const id of ['gemini', 'mistral', 'deepseek', 'xai', 'kimi']) {
      assert.ok(defaults[id], `${PM.name}: missing default config for ${id}`);
      assert.equal(defaults[id].category, 'cloud', `${PM.name}: ${id} should be cloud`);
      assert.equal(defaults[id].enabled, false, `${PM.name}: ${id} should default to disabled`);
      assert.ok(defaults[id].baseUrl, `${PM.name}: ${id} missing baseUrl`);
      assert.ok(defaults[id].model, `${PM.name}: ${id} missing default model`);
    }
    assert.equal(defaults.kimi.baseUrl, 'https://api.moonshot.ai/v1');
    assert.equal(defaults.kimi.model, 'kimi-k3');
    assert.equal(defaults.kimi.supportsStreamUsageOptions, true);
    assert.equal(defaults.kimi.omitTemperature, true);
    assert.equal(defaults.kimi.compat?.maxTokensField, 'max_completion_tokens');
    assert.equal(defaults.kimi.compat?.omitTemperature, undefined);
    const kimi = mgr._createProvider('kimi', defaults.kimi);
    assert.equal(kimi.contextWindow, 1000000);
    assert.equal(kimi.supportsVision, true);
    const messages = [{ role: 'user', content: 'hello' }];
    const body = kimi._buildChatCompletionsBody(messages, { maxTokens: 123 }, false);
    assert.equal(body.max_completion_tokens, 123);
    assert.equal(body.max_tokens, undefined);
    assert.equal(body.temperature, undefined);
    const streamBody = kimi._buildChatCompletionsBody(
      messages,
      { maxTokens: 123, temperature: 0.15 },
      true,
    );
    assert.equal(streamBody.temperature, undefined);
    assert.deepEqual(streamBody.stream_options, { include_usage: true });
  }
});

