test('Ask stream aggregation exposes text live but withholds tool calls until response.completed', async () => {
  for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
    let releaseCompleted;
    const completedGate = new Promise(resolve => { releaseCompleted = resolve; });
    const responseItems = [{ type: 'function_call', call_id: 'call_wait', name: 'read_page', arguments: '{}' }];
    const provider = {
      async *chatStream() {
        yield { type: 'text', content: 'Checking' };
        yield {
          type: 'tool_call',
          content: [{ index: 0, id: 'call_wait', type: 'function', function: { name: 'read_page', arguments: '{}' } }],
        };
        await completedGate;
        yield { type: 'usage', usage: { prompt_tokens: 5, completion_tokens: 2, total_tokens: 7 } };
        yield { type: 'done', responseItems, stop_reason: 'tool_calls' };
      },
    };
    const agent = new AgentClass({});
    agent._checkCostAllowance = async () => null;
    agent._recordCostUsage = async () => null;
    const deltas = [];
    let settled = false;
    const pending = agent._chatStreamWithCostAllowance(
      provider,
      [{ role: 'user', content: 'check' }],
      {},
      {},
      null,
      delta => deltas.push(delta),
    );
    pending.finally(() => { settled = true; });
    await new Promise(resolve => setImmediate(resolve));

    assert.deepEqual(deltas, ['Checking'], `${label}: text should be visible before completion`);
    assert.equal(settled, false, `${label}: tool-bearing result must remain unavailable before response.completed`);

    releaseCompleted();
    const result = await pending;
    assert.equal(result.content, 'Checking', `${label}: final text aggregation mismatch`);
    assert.equal(result.toolCalls?.[0]?.function?.name, 'read_page', `${label}: completed tool call missing`);
    assert.deepEqual(result.responseItems, responseItems, `${label}: completed replay items missing`);
    assert.equal(result.finishReason, 'tool_calls', `${label}: terminal stream reasons should reach aggregation`);
  }
});

test('Ask streaming estimates and records usage when a provider omits token metadata', async () => {
  for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
    const messages = [{ role: 'user', content: 'Summarize this page.' }];
    const streamOptions = {
      tools: [{
        type: 'function',
        function: {
          name: 'read_page',
          description: 'Read the current page.',
          parameters: { type: 'object', properties: {} },
        },
      }],
    };

    const successfulAgent = new AgentClass({});
    successfulAgent._checkCostAllowance = async () => null;
    let successfulRecordedUsage = null;
    successfulAgent._recordCostUsage = async (_provider, usage) => {
      successfulRecordedUsage = usage;
      return null;
    };
    const successfulProvider = {
      async *chatStream() {
        yield { type: 'text', content: 'Estimated answer.' };
        yield { type: 'done' };
      },
    };
    const result = await successfulAgent._chatStreamWithCostAllowance(
      successfulProvider,
      messages,
      streamOptions,
      {},
    );
    assert.equal(result.usage?.estimated, true, `${label}: missing stream usage should be marked estimated`);
    assert.ok(result.usage?.prompt_tokens > 0, `${label}: estimated prompt usage should include messages and tools`);
    assert.ok(result.usage?.completion_tokens > 0, `${label}: estimated completion usage should include streamed text`);
    assert.deepEqual(successfulRecordedUsage, result.usage, `${label}: estimated stream usage should reach cost accounting`);

    const interruptedAgent = new AgentClass({});
    interruptedAgent._checkCostAllowance = async () => null;
    let interruptedRecordedUsage = null;
    interruptedAgent._recordCostUsage = async (_provider, usage) => {
      interruptedRecordedUsage = usage;
      return null;
    };
    const interruptedProvider = {
      async *chatStream() {
        yield { type: 'text', content: 'Billable partial output.' };
        const error = new Error('stream ended early');
        error.isAskStreamFallbackSafe = true;
        throw error;
      },
    };
    await assert.rejects(
      interruptedAgent._chatStreamWithCostAllowance(
        interruptedProvider,
        messages,
        streamOptions,
        {},
      ),
      /stream ended early/,
    );
    assert.equal(interruptedRecordedUsage?.estimated, true, `${label}: interrupted billable output should be estimated`);
    assert.ok(interruptedRecordedUsage?.total_tokens > 0, `${label}: interrupted stream usage should reach cost accounting`);
  }
});

test('interactive Ask streaming preserves attachments and persists only the completed assistant turn', async () => {
  for (const [index, [label, AgentClass]] of [['chrome', AgentCh], ['firefox', AgentFx]].entries()) {
    let streamedMessages = null;
    let chatCalls = 0;
    const responseItems = [{ type: 'message', role: 'assistant', content: [{ type: 'output_text', text: 'Image received.' }] }];
    const provider = {
      supportsTools: false,
      supportsAskStreaming: true,
      supportsVision: true,
      promptTier: 'full',
      contextWindow: 128000,
      model: 'gpt-5.6-terra',
      name: 'openai',
      _supportsInteractiveAskStreaming: () => true,
      chat: async () => {
        chatCalls += 1;
        return { content: 'unexpected fallback', toolCalls: null };
      },
      async *chatStream(messages) {
        streamedMessages = messages;
        yield { type: 'text', content: 'Image ' };
        yield { type: 'text', content: 'received.' };
        yield { type: 'done', responseItems };
      },
    };
    const agent = new AgentClass({
      getActive: () => provider,
      getVisionProvider: async () => null,
    });
    const tabId = 9550 + index;
    configurePlanOnlyGuardAgent(agent, tabId);
    agent.conversationModes.set(tabId, 'ask');
    agent._maybeRunPlannerGate = async (_tabId, messages, enriched) => {
      messages.push(enriched);
      return { proceed: true, requestKind: 'execute', requiresStateChange: false };
    };
    agent._startTraceRun = async () => null;
    agent._endTraceRun = () => {};

    const updates = [];
    const imageUrl = 'data:image/png;base64,AA==';
    const final = await agent.processMessage(
      tabId,
      'What is in this image?',
      (type, data) => updates.push({ type, data }),
      'ask',
      [{ kind: 'image', dataUrl: imageUrl, name: 'sample.png' }],
      { interactiveChat: true, askStreamingEnabled: true },
    );

    assert.equal(final, 'Image received.', `${label}: streamed final mismatch`);
    assert.equal(chatCalls, 0, `${label}: successful stream should not call provider.chat()`);
    const userMessage = streamedMessages.find(message => message.role === 'user');
    assert.ok(Array.isArray(userMessage?.content), `${label}: attachment should reach the streamed request as content blocks`);
    assert.ok(userMessage.content.some(block => block.type === 'image_url' && block.image_url?.url === imageUrl), `${label}: image block missing from streamed request`);
    assert.deepEqual(updates.filter(update => update.type === 'text_delta').map(update => update.data.content), ['Image ', 'received.'], `${label}: visible deltas mismatch`);
    assert.equal(updates.filter(update => update.type === 'text').at(-1)?.data?.content, 'Image received.', `${label}: terminal formatting update missing`);
    const assistants = agent.conversations.get(tabId).filter(message => message.role === 'assistant');
    assert.equal(assistants.length, 1, `${label}: partial stream text must not be persisted as assistant history`);
    assert.equal(assistants[0].content, 'Image received.', `${label}: only completed assistant text should persist`);
    assert.deepEqual(assistants[0].response_items, responseItems, `${label}: terminal Responses items should persist`);
  }
});

test('Ask stream failure clears partial text and falls back once for the rest of the run', async () => {
  for (const [index, [label, AgentClass]] of [['chrome', AgentCh], ['firefox', AgentFx]].entries()) {
    let streamCalls = 0;
    let chatCalls = 0;
    const executed = [];
    const provider = {
      supportsTools: true,
      supportsAskStreaming: true,
      supportsVision: false,
      promptTier: 'full',
      contextWindow: 128000,
      model: 'gpt-5.6-terra',
      name: 'openai',
      _supportsInteractiveAskStreaming: () => true,
      async *chatStream() {
        streamCalls += 1;
        yield { type: 'text', content: 'Partial answer' };
        yield {
          type: 'tool_call',
          content: [{ index: 0, id: 'streamed_click', type: 'function', function: { name: 'click', arguments: '{"x":1,"y":1}' } }],
        };
        const error = new Error('connection reset before response.completed');
        error.isAskStreamError = true;
        error.isAskStreamFallbackSafe = true;
        throw error;
      },
      async chat() {
        chatCalls += 1;
        if (chatCalls === 1) {
          return {
            content: null,
            toolCalls: [{ id: 'fallback_read', type: 'function', function: { name: 'read_page', arguments: '{}' } }],
          };
        }
        return { content: 'Recovered answer.', toolCalls: null };
      },
    };
    const agent = new AgentClass({
      getActive: () => provider,
      getVisionProvider: async () => null,
    });
    const tabId = 9560 + index;
    configurePlanOnlyGuardAgent(agent, tabId);
    agent.conversationModes.set(tabId, 'ask');
    agent._maybeRunPlannerGate = async (_tabId, messages, enriched) => {
      messages.push(enriched);
      return { proceed: true, requestKind: 'execute', requiresStateChange: false };
    };
    agent._startTraceRun = async () => null;
    agent._endTraceRun = () => {};
    agent.executeTool = async (_tabId, name) => {
      executed.push(name);
      return { success: true, text: 'Fallback page result.' };
    };

    const updates = [];
    const final = await agent.processMessage(
      tabId,
      'Read the page.',
      (type, data) => updates.push({ type, data }),
      'ask',
      [],
      { interactiveChat: true, askStreamingEnabled: true },
    );

    assert.equal(final, 'Recovered answer.', `${label}: fallback final mismatch`);
    assert.equal(streamCalls, 1, `${label}: stream circuit breaker should stay open for later model turns in the run`);
    assert.equal(chatCalls, 2, `${label}: failed generation and its tool follow-up should use provider.chat()`);
    assert.deepEqual(executed, ['read_page'], `${label}: pre-completion streamed tool call must never execute`);
    assert.ok(updates.some(update => update.type === 'text' && update.data?.replace === true && update.data?.content === ''), `${label}: partial streamed text should be cleared`);
    assert.equal(
      updates.filter(update => update.type === 'warning' && update.data?.code === 'ask_stream_fallback').length,
      1,
      `${label}: localized fallback warning event should be emitted once`,
    );
    assert.equal(agent.conversations.get(tabId).some(message => message.role === 'assistant' && message.content === 'Partial answer'), false, `${label}: failed partial text must not persist`);
  }
});

test('Ask terminal stream errors clear partial text without retrying the generation', async () => {
  for (const [index, [label, AgentClass]] of [['chrome', AgentCh], ['firefox', AgentFx]].entries()) {
    let streamCalls = 0;
    let chatCalls = 0;
    const provider = {
      supportsTools: false,
      supportsVision: false,
      promptTier: 'full',
      contextWindow: 128000,
      model: 'gpt-5.6-terra',
      name: 'openai',
      _supportsInteractiveAskStreaming: () => true,
      async *chatStream() {
        streamCalls += 1;
        yield { type: 'text', content: 'Blocked partial' };
        const error = new Error('policy blocked');
        error.isAskStreamError = true;
        error.isAskStreamTerminalError = true;
        throw error;
      },
      async chat() {
        chatCalls += 1;
        return { content: 'Unexpected retry.', toolCalls: null };
      },
    };
    const agent = new AgentClass({
      getActive: () => provider,
      getVisionProvider: async () => null,
    });
    const tabId = 9570 + index;
    configurePlanOnlyGuardAgent(agent, tabId);
    agent.conversationModes.set(tabId, 'ask');
    agent._maybeRunPlannerGate = async (_tabId, messages, enriched) => {
      messages.push(enriched);
      return { proceed: true, requestKind: 'execute', requiresStateChange: false };
    };
    agent._startTraceRun = async () => null;
    agent._endTraceRun = () => {};

    const updates = [];
    const final = await agent.processMessage(
      tabId,
      'Explain the policy.',
      (type, data) => updates.push({ type, data }),
      'ask',
      [],
      { interactiveChat: true, askStreamingEnabled: true },
    );

    assert.equal(final, 'Error communicating with LLM: policy blocked', `${label}: terminal error should be surfaced`);
    assert.equal(streamCalls, 1, `${label}: terminal stream errors must not retry the generation`);
    assert.equal(chatCalls, 0, `${label}: terminal stream errors must not fall back to provider.chat()`);
    assert.ok(updates.some(update => update.type === 'text' && update.data?.replace === true && update.data?.content === ''), `${label}: partial streamed text should be cleared`);
    assert.equal(updates.filter(update => update.type === 'error').length, 1, `${label}: terminal error should be emitted once`);
    assert.equal(agent.conversations.get(tabId).some(message => message.role === 'assistant' && message.content === 'Blocked partial'), false, `${label}: failed partial text must not persist`);
  }
});

test('detached chat lifecycle owns the default-on Ask streaming kill switch', () => {
  assert.equal(ConfigTransferCh.DEFAULT_CONFIG_SETTINGS.openaiAskStreamingEnabled, true, 'Chrome config export should preserve the default-on streaming setting');
  assert.equal(ConfigTransferFx.DEFAULT_CONFIG_SETTINGS.openaiAskStreamingEnabled, true, 'Firefox config export should preserve the default-on streaming setting');
  for (const [label, prefix, storageName] of [
    ['chrome', 'src/chrome', 'chrome'],
    ['firefox', 'src/firefox', 'browser'],
  ]) {
    const background = fs.readFileSync(path.join(ROOT, prefix, 'src/background.js'), 'utf8');
    const panel = fs.readFileSync(path.join(ROOT, prefix, 'src/ui/sidepanel.js'), 'utf8');
    const settings = fs.readFileSync(path.join(ROOT, prefix, 'src/ui/settings.js'), 'utf8');
    const settingsHtml = fs.readFileSync(path.join(ROOT, prefix, 'src/ui/settings.html'), 'utf8');
    const chatBody = background.match(/case 'chat': \{([\s\S]*?)\n\s+case 'chat_stream':/)?.[1] || '';
    const continueBody = background.match(/case 'continue': \{([\s\S]*?)\n\s+case 'abort'/)?.[1] || '';

    assert.match(panel, /sendRunWithReconnect\('chat_start'/, `${label}: sidepanel must retain detached chat_start`);
    assert.match(background, /case 'chat_start':\s*\{[\s\S]*?launchDetachedRun\('chat'/, `${label}: background must retain detached launch/reconnect ownership`);
    assert.match(chatBody, new RegExp(`await ${storageName}\\.storage\\.local\\.get\\('openaiAskStreamingEnabled'\\)`), `${label}: each detached chat should read the current kill switch`);
    assert.match(chatBody, /interactiveChat: true/, `${label}: only interactive chat should receive streaming capability`);
    assert.match(chatBody, /askStreamingEnabled: askStreamingSettings\.openaiAskStreamingEnabled !== false/, `${label}: streaming should default on`);
    assert.doesNotMatch(continueBody, /interactiveChat|askStreamingEnabled|openaiAskStreamingEnabled/, `${label}: Continue must not inherit streaming capability`);
    assert.match(settingsHtml, /id="toggle-openai-ask-streaming" checked/, `${label}: Advanced kill switch should default on`);
    assert.match(settings, /openAIAskStreamingToggle\.checked = stored\.openaiAskStreamingEnabled !== false/, `${label}: unset storage should render the kill switch on`);
  }
});

test('Chat Completions scopes reasoning replay to providers that support it', () => {
  const reasoningMessage = (model, currentToolLoop = false, preserveAcrossTurns = false) => ({
    role: 'assistant',
    content: null,
    tool_calls: [{ id: 'call_1', type: 'function', function: { name: 'read_page', arguments: '{}' } }],
    response_items: [{ type: 'reasoning', encrypted_content: 'responses-only' }],
    reasoning_content: 'kimi-only reasoning',
    _reasoning_replay: {
      provider: 'kimi',
      model,
      ...(preserveAcrossTurns ? { preserveAcrossTurns: true } : {}),
      ...(currentToolLoop ? { currentToolLoop: true } : {}),
    },
  });
  const expectedWithoutReasoning = (message) => ({
    role: 'assistant',
    content: null,
    tool_calls: message.tool_calls,
  });
  const historicalK25 = reasoningMessage('kimi-k2.5');
  for (const [label, Provider] of [
    ['chrome OpenAI-compatible', OpenAIProviderCh],
    ['firefox OpenAI-compatible', OpenAIProviderFx],
    ['chrome Azure OpenAI', AzureOpenAIProviderCh],
    ['firefox Azure OpenAI', AzureOpenAIProviderFx],
    ['chrome llama.cpp', LlamaCppProviderCh],
    ['firefox llama.cpp', LlamaCppProviderFx],
  ]) {
    const generic = new Provider({ providerName: 'openai', model: 'generic-model' });
    assert.deepEqual(
      generic._chatMessages([historicalK25]),
      [expectedWithoutReasoning(historicalK25)],
      `${label}: provider switches must strip foreign replay fields`,
    );

    const kimiK25 = new Provider({
      providerName: 'kimi',
      model: 'kimi-k2.5',
    });
    assert.deepEqual(
      kimiK25._chatMessages([historicalK25]),
      [expectedWithoutReasoning(historicalK25)],
      `${label}: K2.5 must not receive unsupported preserved thinking`,
    );
  }

  for (const [label, Provider] of [
    ['chrome OpenAI-compatible', OpenAIProviderCh],
    ['firefox OpenAI-compatible', OpenAIProviderFx],
  ]) {
    const kimiK25 = new Provider({ providerName: 'kimi', model: 'kimi-k2.5' });
    const activeK25ToolLoop = reasoningMessage('kimi-k2.5', true);
    assert.deepEqual(
      kimiK25._chatMessages([activeK25ToolLoop]),
      [{
        ...expectedWithoutReasoning(activeK25ToolLoop),
        reasoning_content: 'kimi-only reasoning',
      }],
      `${label}: K2.5 must replay reasoning during the active tool loop`,
    );

    for (const model of ['kimi-k3', 'kimi-k2.7-code', 'kimi-k2.7-code-highspeed']) {
      const kimiPreserved = new Provider({ providerName: 'kimi', model });
      const historicalMessage = reasoningMessage(model, false, true);
      assert.deepEqual(
        kimiPreserved._chatMessages([historicalMessage]),
        [{
          ...expectedWithoutReasoning(historicalMessage),
          reasoning_content: 'kimi-only reasoning',
        }],
        `${label}: ${model} should retain required preserved thinking`,
      );
    }

    const kimiK26Default = new Provider({ providerName: 'kimi', model: 'kimi-k2.6' });
    const historicalK26 = reasoningMessage('kimi-k2.6');
    assert.deepEqual(
      kimiK26Default._chatMessages([historicalK26]),
      [expectedWithoutReasoning(historicalK26)],
      `${label}: K2.6 should not retain historical thinking by default`,
    );
    const activeK26ToolLoop = reasoningMessage('kimi-k2.6', true);
    assert.equal(
      kimiK26Default._chatMessages([activeK26ToolLoop])[0].reasoning_content,
      'kimi-only reasoning',
      `${label}: K2.6 should replay reasoning during the active tool loop`,
    );

    const kimiK26Preserved = new Provider({
      providerName: 'kimi',
      model: 'kimi-k2.6',
      extraBody: { thinking: { type: 'enabled', keep: 'all' } },
    });
    const preservedK26 = reasoningMessage('kimi-k2.6', false, true);
    assert.deepEqual(
      kimiK26Preserved._chatMessages([preservedK26]),
      [{
        ...expectedWithoutReasoning(preservedK26),
        reasoning_content: 'kimi-only reasoning',
      }],
      `${label}: explicitly preserved K2.6 calls should retain reasoning_content`,
    );

    const perRequestBody = kimiK26Default._buildChatCompletionsBody(
      [preservedK26],
      { extraBody: { thinking: { type: 'enabled', keep: 'all' } } },
    );
    assert.equal(
      perRequestBody.messages[0].reasoning_content,
      'kimi-only reasoning',
      `${label}: per-request K2.6 preserved thinking should retain reasoning_content`,
    );
    assert.deepEqual(perRequestBody.thinking, { type: 'enabled', keep: 'all' });

    const disabledBody = kimiK26Preserved._buildChatCompletionsBody(
      [preservedK26],
      { extraBody: { thinking: { type: 'disabled' } } },
    );
    assert.equal(
      disabledBody.messages[0].reasoning_content,
      undefined,
      `${label}: disabling K2.6 thinking should strip historical reasoning`,
    );

    const mismatchedModel = reasoningMessage('kimi-k3');
    assert.equal(
      kimiK25._chatMessages([mismatchedModel])[0].reasoning_content,
      undefined,
      `${label}: reasoning from a different Kimi model must not cross model switches`,
    );
    const unknownAlias = new Provider({ providerName: 'kimi', model: 'kimi-k2.5-preview' });
    assert.equal(
      unknownAlias._chatMessages([reasoningMessage('kimi-k2.5-preview', true)])[0].reasoning_content,
      undefined,
      `${label}: unknown Kimi aliases must not inherit reasoning replay support`,
    );
  }
});

test('GPT-5.6 Responses streaming preserves refusal text', async () => {
  const originalFetch = globalThis.fetch;
  const events = [
    { type: 'response.refusal.delta', delta: 'I cannot help with that.' },
    {
      type: 'response.completed',
      response: {
        output: [{
          type: 'message',
          role: 'assistant',
          content: [{ type: 'refusal', refusal: 'I cannot help with that.' }],
        }],
      },
    },
  ];
  const sse = events.map(event => `data: ${JSON.stringify(event)}\n\n`).join('');
  try {
    globalThis.fetch = async () => new Response(sse, {
      status: 200,
      headers: { 'Content-Type': 'text/event-stream' },
    });
    for (const Provider of [OpenAIProviderCh, OpenAIProviderFx]) {
      const provider = new Provider({
        providerName: 'openai',
        baseUrl: 'https://api.openai.com/v1',
        model: 'gpt-5.6-terra',
      });
      const chunks = [];
      for await (const chunk of provider.chatStream([{ role: 'user', content: 'hello' }])) {
        chunks.push(chunk);
      }
      assert.deepEqual(chunks[0], { type: 'text', content: 'I cannot help with that.' });
      assert.equal(chunks[1].type, 'done');
    }
  } finally {
    globalThis.fetch = originalFetch;
  }
});

test('Agent tool loops preserve provider reasoning state on both execution paths', () => {
  for (const [prefix, AgentClass, Provider] of [
    ['src/chrome', AgentCh, OpenAIProviderCh],
    ['src/firefox', AgentFx, OpenAIProviderFx],
  ]) {
    const source = fs.readFileSync(path.join(ROOT, prefix, 'src/agent/agent.js'), 'utf8');
    const agent = new AgentClass({});
    const kimiK25 = new Provider({ providerName: 'kimi', model: 'kimi-k2.5' });
    const kimiK3 = new Provider({ providerName: 'kimi', model: 'kimi-k3' });
    const assistant = {
      role: 'assistant',
      content: null,
      tool_calls: [{ id: 'call_1', function: { name: 'read_page', arguments: '{}' } }],
    };
    const activeK25ToolLoop = agent._withResponseItems(
      assistant,
      null,
      'required Kimi reasoning',
      kimiK25,
    );
    assert.deepEqual(activeK25ToolLoop, {
      ...assistant,
      reasoning_content: 'required Kimi reasoning',
      _reasoning_replay: {
        provider: 'kimi',
        model: 'kimi-k2.5',
        currentToolLoop: true,
      },
    }, `${prefix}: K2.5 reasoning should be replayable during the active tool loop`);
    assert.equal(
      kimiK25._chatMessages([activeK25ToolLoop])[0].reasoning_content,
      'required Kimi reasoning',
      `${prefix}: K2.5 immediate tool-result requests should retain reasoning`,
    );
    agent._expireCurrentToolReasoning([activeK25ToolLoop]);
    assert.equal(activeK25ToolLoop._reasoning_replay, undefined);
    assert.equal(activeK25ToolLoop.reasoning_content, undefined);
    assert.equal(
      kimiK25._chatMessages([activeK25ToolLoop])[0].reasoning_content,
      undefined,
      `${prefix}: K2.5 later turns should strip expired tool-loop reasoning`,
    );
    assert.deepEqual(
      agent._withResponseItems({ role: 'assistant', content: 'done' }, null, 'discarded final reasoning', kimiK25),
      { role: 'assistant', content: 'done' },
      `${prefix}: K2.5 final reasoning should not bloat persisted history`,
    );
    const preservedK3 = agent._withResponseItems(
      { role: 'assistant', content: 'done' },
      null,
      'preserved K3 reasoning',
      kimiK3,
    );
    assert.equal(
      kimiK3._chatMessages([preservedK3])[0].reasoning_content,
      'preserved K3 reasoning',
      `${prefix}: K3 reasoning should remain available across turns`,
    );
    const responseItems = [{ type: 'reasoning', encrypted_content: 'opaque' }];
    assert.deepEqual(
      agent._withResponseItems(assistant, responseItems, 'redundant summary'),
      { ...assistant, response_items: responseItems },
      `${prefix}: Responses replay items should remain authoritative`,
    );
    assert.ok(
      agent._estimateContextChars([{ role: 'assistant', content: '', reasoning_content: 'reasoning bytes' }])
        > agent._estimateContextChars([{ role: 'assistant', content: '' }]),
      `${prefix}: reasoning replay should count toward context budgeting`,
    );
    assert.match(source, /_withResponseItems\(message, responseItems, reasoningContent = '', provider = null\)[\s\S]*response_items: responseItems/, `${prefix}: assistant helper should retain Responses output Items`);
    assert.match(source, /_expireCurrentToolReasoning\(messages\)/, `${prefix}: new user turns should expire immediate-only reasoning replay`);
    assert.match(source, /reasoning_content: reasoningContent/, `${prefix}: assistant helper should retain Chat Completions reasoning content`);
    assert.match(source, /content: assistantToolContent,[\s\S]*tool_calls: result\.toolCalls,[\s\S]*}, result\.responseItems, result\.reasoningContent, provider\)/, `${prefix}: non-stream tool loop should retain provider reasoning state`);
    assert.match(source, /content: result\.content \}, result\.responseItems, result\.reasoningContent, provider\)[\s\S]*messages\.push\(this\._appOwnedUserMessage\(plainFinalBlocks\.join/, `${prefix}: non-stream progress continuations should scope provider reasoning state`);
    assert.match(source, /content: finalResponse \}, result\.responseItems, result\.reasoningContent, provider\)/, `${prefix}: non-stream final answers should scope provider reasoning state`);
    assert.match(source, /chunk\.type === 'reasoning'[\s\S]*content: fullText \|\| null,[\s\S]*tool_calls: toolCalls,[\s\S]*}, responseItems, reasoningContent, provider\)/, `${prefix}: stream tool loop should retain provider reasoning state`);
    assert.match(source, /content: fullText \}, responseItems, reasoningContent, provider\)[\s\S]*messages\.push\(this\._appOwnedUserMessage\(plainFinalBlocks\.join/, `${prefix}: stream progress continuations should scope provider reasoning state`);
    assert.match(source, /content: fullText \}, responseItems, reasoningContent, provider\)[\s\S]*return finish\(fullText\)/, `${prefix}: stream final answers should scope provider reasoning state`);
    assert.match(source, /if \(msg\.response_items\) totalChars \+= JSON\.stringify\(msg\.response_items\)\.length/, `${prefix}: context budgeting should include encrypted reasoning Items`);
    assert.match(source, /if \(typeof msg\.reasoning_content === 'string'\) totalChars \+= msg\.reasoning_content\.length/, `${prefix}: context budgeting should include Chat Completions reasoning content`);
  }
});

test('WebBrain Compass groups every generation in a stable conversation session without touching local or BYO calls', () => {
  for (const [label, AgentClass, Provider, prefix] of [
    ['chrome', AgentCh, OpenAIProviderCh, 'src/chrome'],
    ['firefox', AgentFx, OpenAIProviderFx, 'src/firefox'],
  ]) {
    const tabId = label === 'chrome' ? 731 : 732;
    const agent = new AgentClass({});
    agent.getConversation(tabId, 'ask');
    agent.screenshotRedaction = true;
    agent.strictSecretMode = true;
    agent.apiAllowedTabs.add(tabId);
    const firstConversationId = agent.conversationIds.get(tabId);
    assert.match(firstConversationId, /^conv_/, `${label}: new conversation should mint an id`);

    const cloud = { config: { providerName: 'webbrain-cloud' } };
    const main = agent._cloudGenerationOptions(cloud, { temperature: 0 }, { tabId, generationName: 'main' });
    const planner = agent._cloudGenerationOptions(cloud, {}, { tabId, generationName: 'planner' });
    assert.equal(main.webbrainSessionId, firstConversationId, `${label}: main call should carry the conversation id`);
    assert.equal(planner.webbrainSessionId, firstConversationId, `${label}: planner call should share the main session`);
    assert.equal(planner.webbrainGenerationName, 'planner', `${label}: planner call should be labeled`);
    assert.equal(main.webbrainRuntimeConfig?.schema_version, 1, `${label}: runtime trace schema missing`);
    assert.equal(main.webbrainRuntimeConfig?.browser_target, label, `${label}: browser target missing`);
    assert.equal(main.webbrainRuntimeConfig?.mode, 'ask', `${label}: effective mode missing`);
    assert.equal(main.webbrainRuntimeConfig?.screenshot_redaction, true, `${label}: screenshot redaction setting missing`);
    assert.equal(main.webbrainRuntimeConfig?.strict_secret_mode, true, `${label}: strict secret setting missing`);
    assert.equal(main.webbrainRuntimeConfig?.api_mutations_allowed, true, `${label}: per-tab API authorization missing`);
    assert.ok(!JSON.stringify(main.webbrainRuntimeConfig).includes('apiKey'), `${label}: runtime metadata must remain an allowlist`);
    assert.equal(main.webbrainRuntimeConfig?.max_agent_steps, agent.maxSteps, `${label}: step budget missing`);

    const scopedGrounding = label === 'chrome'
      ? SELECTION_CONTEXT_SOURCE_GROUNDING_CH
      : SELECTION_CONTEXT_SOURCE_GROUNDING_FX;
    agent.selectionGroundingScopes.set(tabId, {
      sourceGrounding: scopedGrounding,
      anchorFingerprint: 'opaque-anchor-fingerprint',
      excludedFingerprints: ['private-dialogue-fingerprint'],
    });
    const scopedTrace = agent._cloudGenerationOptions(cloud, {}, { tabId, generationName: 'main' });
    assert.equal(scopedTrace.webbrainRuntimeConfig?.selection_scope_policy, scopedGrounding, `${label}: trace should identify the active selection policy`);
    assert.equal(scopedTrace.webbrainRuntimeConfig?.selection_scope_anchor_present, true, `${label}: trace should expose only anchor presence`);
    assert.equal(scopedTrace.webbrainRuntimeConfig?.selection_scope_excluded_messages, 1, `${label}: trace should expose the excluded-message count`);
    assert.doesNotMatch(JSON.stringify(scopedTrace.webbrainRuntimeConfig), /opaque-anchor|private-dialogue/, `${label}: trace metadata leaked scope fingerprints`);
    agent.selectionGroundingScopes.delete(tabId);

    // "Unlimited" steps hydrate as Infinity; record the stored 0 sentinel so an
    // unlimited run is attributable instead of missing the field entirely.
    const previousMaxSteps = agent.maxSteps;
    agent.maxSteps = Infinity;
    const unlimited = agent._cloudGenerationOptions(cloud, {}, { tabId, generationName: 'main' });
    assert.equal(unlimited.webbrainRuntimeConfig?.max_agent_steps, 0, `${label}: unlimited step budget should record as 0`);
    agent.maxSteps = previousMaxSteps;

    // Without a tab there is no observable mode or per-tab authorization, so
    // those fields must be absent rather than asserted as ask/false.
    const untabbed = agent._runtimeTraceConfig(cloud);
    assert.equal('mode' in untabbed, false, `${label}: unknown mode should be omitted, not guessed`);
    assert.equal('api_mutations_allowed' in untabbed, false, `${label}: per-tab API authorization should be omitted without a tab`);
    assert.equal('selection_grounded' in untabbed, false, `${label}: selection grounding should be omitted without a tab`);
    assert.equal(untabbed.browser_target, label, `${label}: browser target should survive without a tab`);

    const byoOptions = agent._cloudGenerationOptions({ config: { providerName: 'openai' } }, { temperature: 0 }, { tabId, generationName: 'memory' });
    assert.deepEqual(byoOptions, { temperature: 0 }, `${label}: BYO provider received Cloud collection fields`);
    const localOptions = agent._cloudGenerationOptions({ config: { providerName: 'llama.cpp' } }, {}, { tabId, generationName: 'main' });
    assert.deepEqual(localOptions, {}, `${label}: local provider received Cloud collection fields`);

    agent.clearConversation(tabId);
    agent.getConversation(tabId, 'ask');
    const secondConversationId = agent.conversationIds.get(tabId);
    assert.notEqual(secondConversationId, firstConversationId, `${label}: starting a new conversation should rotate the session id`);

    const cloudProvider = new Provider({ providerName: 'webbrain-cloud' });
    const cloudBody = {};
    cloudProvider._addWebBrainCloudContext(cloudBody, {
      webbrainSessionId: firstConversationId,
      webbrainGenerationName: 'compaction',
      webbrainRuntimeConfig: {
        ...main.webbrainRuntimeConfig,
        api_key: 'must-not-leak',
        profile_text: 'must-not-leak',
      },
    });
    assert.equal(cloudBody.session_id, firstConversationId, `${label}: Cloud request body should include session_id`);
    assert.equal(cloudBody.trace?.generation_name, 'compaction', `${label}: Cloud request body should include the generation label`);
    assert.deepEqual(cloudBody.trace?.runtime_config, main.webbrainRuntimeConfig, `${label}: Cloud request body should include only allowlisted runtime settings`);
    assert.ok(!JSON.stringify(cloudBody).includes('must-not-leak'), `${label}: arbitrary settings leaked into Cloud trace context`);

    const byoProvider = new Provider({ providerName: 'openai', apiKey: 'test-key' });
    const byoBody = {};
    byoProvider._addWebBrainCloudContext(byoBody, {
      webbrainSessionId: firstConversationId,
      webbrainGenerationName: 'main',
    });
    assert.deepEqual(byoBody, {}, `${label}: BYO request body should not include Cloud session fields`);

    const agentSource = fs.readFileSync(path.join(ROOT, prefix, 'src/agent/agent.js'), 'utf8');
    const backgroundSource = fs.readFileSync(path.join(ROOT, prefix, 'src/background.js'), 'utf8');
    assert.match(
      agentSource,
      /conversationIds\.set\(tabId, `conv_\$\{tabId\}_\$\{Date\.now\(\)\}_\$\{secureRandomBase36Token\(12\)\}`\)/,
      `${label}: Cloud conversation IDs must use Web Crypto entropy`,
    );
    for (const generationName of ['main', 'planner', 'compaction', 'intent', 'vision']) {
      assert.match(agentSource, new RegExp(`generationName: '${generationName}'`), `${label}: ${generationName} calls should be labeled`);
    }
    assert.match(backgroundSource, /generationName: 'memory'/, `${label}: memory extraction calls should be labeled`);
    assert.match(backgroundSource, /userMemoryPayload\.conversationId = await agent\.getConversationId\(tabId\);/, `${label}: background memory jobs should retain the conversation id`);
  }
});

test('OpenAI-compatible streams request usage metadata only for supporting providers', () => {
  for (const Provider of [OpenAIProviderCh, OpenAIProviderFx]) {
    for (const config of [
      { category: 'cloud', providerName: 'gemini' },
      { category: 'cloud', providerName: 'deepseek' },
      { category: 'cloud', providerName: 'mistral', supportsStreamUsageOptions: false },
      { category: 'router', providerName: 'openrouter' },
      { providerName: 'openai' },
      { category: 'cloud', providerName: 'custom', supportsStreamUsageOptions: true },
    ]) {
      const provider = new Provider(config);
      const body = { stream: true, stream_options: { custom: 'keep' } };
      provider._addStreamUsageOptions(body);
      assert.deepEqual(body.stream_options, { custom: 'keep', include_usage: true });
    }

    for (const config of [
      { category: 'router', providerName: 'cloudflare' },
      { category: 'cloud', providerName: 'custom' },
      { category: 'router', providerName: 'custom-router' },
      { category: 'cloud', providerName: 'openai', supportsStreamUsageOptions: false },
    ]) {
      const provider = new Provider(config);
      const body = { stream: true };
      provider._addStreamUsageOptions(body);
      assert.equal(body.stream_options, undefined);
    }
  }
});

test('OpenAI-compatible streams emit only the final cumulative usage snapshot', async () => {
  const originalFetch = globalThis.fetch;
  const snapshots = [
    {
      prompt_tokens: 100,
      completion_tokens: 1,
      prompt_tokens_details: { cached_tokens: 80 },
    },
    {
      prompt_tokens: 100,
      completion_tokens: 5,
      prompt_tokens_details: { cached_tokens: 80 },
    },
  ];
  const sse = [
    `data: ${JSON.stringify({ choices: [{ delta: { content: 'ok' } }], usage: snapshots[0] })}\n\n`,
    `data: ${JSON.stringify({ choices: [], usage: snapshots[1] })}\n\n`,
    'data: [DONE]\n\n',
  ].join('');
  try {
    globalThis.fetch = async () => new Response(sse, {
      status: 200,
      headers: { 'Content-Type': 'text/event-stream' },
    });
    const cases = [
      [OpenAIProviderCh, { providerName: 'openai', baseUrl: 'https://api.openai.com/v1', model: 'gpt-4o' }],
      [OpenAIProviderFx, { providerName: 'openai', baseUrl: 'https://api.openai.com/v1', model: 'gpt-4o' }],
      [AzureOpenAIProviderCh, { baseUrl: 'https://x.openai.azure.com', model: 'deployment', apiVersion: '2024-10-21' }],
      [AzureOpenAIProviderFx, { baseUrl: 'https://x.openai.azure.com', model: 'deployment', apiVersion: '2024-10-21' }],
    ];
    for (const [Provider, config] of cases) {
      const chunks = [];
      for await (const chunk of new Provider(config).chatStream([{ role: 'user', content: 'hello' }])) {
        chunks.push(chunk);
      }
      const usageChunks = chunks.filter(chunk => chunk.type === 'usage');
      assert.equal(usageChunks.length, 1, `${Provider.name}: cumulative usage was counted more than once`);
      assert.deepEqual(usageChunks[0].usage, snapshots[1], `${Provider.name}: final usage snapshot was not retained`);
      assert.equal(chunks.at(-1)?.type, 'done');
    }
  } finally {
    globalThis.fetch = originalFetch;
  }
});

test('Groq streams preserve usage from the nested x_groq envelope', async () => {
  const originalFetch = globalThis.fetch;
  const usage = {
    prompt_tokens: 9,
    completion_tokens: 4,
    total_tokens: 13,
  };
  const sse = [
    `data: ${JSON.stringify({ choices: [{ delta: { content: 'Groq answer.' } }] })}\n\n`,
    `data: ${JSON.stringify({ choices: [], x_groq: { usage } })}\n\n`,
    'data: [DONE]\n\n',
  ].join('');
  try {
    globalThis.fetch = async () => new Response(sse, {
      status: 200,
      headers: { 'Content-Type': 'text/event-stream' },
    });
    for (const Provider of [OpenAIProviderCh, OpenAIProviderFx]) {
      const provider = new Provider({
        providerName: 'groq',
        baseUrl: 'https://api.groq.com/openai/v1',
        model: 'llama-3.3-70b-versatile',
        supportsAskStreaming: true,
      });
      const chunks = [];
      for await (const chunk of provider.chatStream([{ role: 'user', content: 'hello' }])) {
        chunks.push(chunk);
      }
      assert.deepEqual(chunks, [
        { type: 'text', content: 'Groq answer.' },
        { type: 'usage', usage },
        { type: 'done', content: '' },
      ]);
    }
  } finally {
    globalThis.fetch = originalFetch;
  }
});

