test('Anthropic and AWS Bedrock forward a required named tool choice', async () => {
  const tool = {
    type: 'function',
    function: {
      name: 'done',
      description: 'Finish the run.',
      parameters: { type: 'object', properties: {} },
    },
  };
  const toolChoice = { type: 'function', function: { name: 'done' } };
  const originalFetch = globalThis.fetch;
  try {
    for (const Provider of [AnthropicProviderCh, AnthropicProviderFx]) {
      let requestBody = null;
      globalThis.fetch = async (_url, init) => {
        requestBody = JSON.parse(init.body);
        return new Response(JSON.stringify({
          content: [{ type: 'tool_use', id: 'forced_done', name: 'done', input: {} }],
          usage: { input_tokens: 1, output_tokens: 1 },
        }), { status: 200, headers: { 'Content-Type': 'application/json' } });
      };
      const provider = new Provider({
        baseUrl: 'https://api.anthropic.com',
        model: 'claude-sonnet-4-6',
        apiKey: 'test-key',
      });
      const result = await provider.chat(
        [{ role: 'user', content: 'Deliver the partial result.' }],
        { tools: [tool], toolChoice },
      );
      assert.deepEqual(requestBody?.tool_choice, { type: 'tool', name: 'done' }, `${Provider.name}: required choice did not reach Anthropic request`);
      assert.equal(result.toolCalls?.[0]?.function?.name, 'done');
    }
  } finally {
    globalThis.fetch = originalFetch;
  }

  for (const Provider of [AwsBedrockProviderCh, AwsBedrockProviderFx]) {
    const provider = new Provider({
      region: 'us-east-1',
      accessKeyId: 'AKIA123',
      secretAccessKey: 'secret',
      model: 'anthropic.claude-3-sonnet-20240229-v1:0',
    });
    const payload = provider._toBedrockPayload(
      [{ role: 'user', content: 'Deliver the partial result.' }],
      { tools: [tool], toolChoice },
    );
    assert.deepEqual(payload.toolConfig?.toolChoice, { tool: { name: 'done' } }, `${Provider.name}: required choice did not reach Bedrock request`);
  }
});

test('AWS Bedrock provider normalizes usage and indexes parallel tool calls', () => {
  for (const Provider of [AwsBedrockProviderCh, AwsBedrockProviderFx]) {
    const provider = new Provider({
      region: 'us-east-1',
      accessKeyId: 'AKIA123',
      secretAccessKey: 'secret',
      model: 'anthropic.claude-3-sonnet-20240229-v1:0',
    });
    assert.equal(provider.model, 'anthropic.claude-3-sonnet-20240229-v1:0');

    const parsed = provider._fromBedrockResponse({
      output: {
        message: {
          content: [
            { text: 'hello' },
            { toolUse: { toolUseId: 'a', name: 'click', input: { x: 1 } } },
            { toolUse: { toolUseId: 'b', name: 'type_text', input: { text: 'hi' } } },
          ],
        },
      },
      usage: {
        inputTokens: 10,
        outputTokens: 5,
        totalTokens: 15,
        cacheReadInputTokens: 80,
        cacheWriteInputTokens: 30,
        cacheDetails: [
          { ttl: '1h', inputTokens: 20 },
          { ttl: '5m', inputTokens: 10 },
        ],
      },
    });
    assert.deepEqual(parsed.usage, {
      prompt_tokens: 10,
      completion_tokens: 5,
      total_tokens: 15,
      cacheReadInputTokens: 80,
      cacheWriteInputTokens: 30,
      cacheDetails: [
        { ttl: '1h', inputTokens: 20 },
        { ttl: '5m', inputTokens: 10 },
      ],
    });
    assert.equal(parsed.toolCalls.length, 2);
    assert.equal(parsed.toolCalls[0].index, 0);
    assert.equal(parsed.toolCalls[1].index, 1);
  }
});

test('OpenAI-compatible Cloudflare base URL substitutes and validates account IDs', async () => {
  const validAccountId = '0123456789abcdef0123456789abcdef';
  const templateUrl = 'https://api.cloudflare.com/client/v4/accounts/{account_id}/ai/v1';
  for (const Provider of [OpenAIProviderCh, OpenAIProviderFx]) {
    const provider = new Provider({
      providerName: 'cloudflare',
      baseUrl: templateUrl,
      accountId: validAccountId,
      model: '@cf/zai-org/glm-5.2',
    });
    assert.equal(
      provider.baseUrl,
      `https://api.cloudflare.com/client/v4/accounts/${validAccountId}/ai/v1`,
      `${Provider.name}: Cloudflare base URL should replace the account placeholder`,
    );
    assert.doesNotMatch(provider.baseUrl, /\{account_id\}/, `${Provider.name}: Cloudflare base URL should not retain the literal placeholder`);

    const explicitUrl = `https://api.cloudflare.com/client/v4/accounts/${validAccountId}/ai/v1`;
    assert.equal(
      new Provider({ providerName: 'cloudflare', baseUrl: explicitUrl, model: '@cf/zai-org/glm-5.2' }).baseUrl,
      explicitUrl,
      `${Provider.name}: manually expanded Cloudflare base URLs should keep working`,
    );

    for (const accountId of ['', 'abc/def', 'not-a-cloudflare-account-id']) {
      const result = await new Provider({
          providerName: 'cloudflare',
          baseUrl: templateUrl,
          accountId,
          model: '@cf/zai-org/glm-5.2',
        }).testConnection();
      assert.equal(result.ok, false, `${Provider.name}: invalid Cloudflare account IDs should fail before fetch`);
      assert.match(
        result.error,
        /Cloudflare Account ID is required and must be a 32-character hex string/,
        `${Provider.name}: invalid Cloudflare account IDs should fail before fetch`,
      );
    }
  }
});

