test('router-prefixed OpenAI reasoning ids use the advertised Chat Completions contract', () => {
  const messages = [{ role: 'user', content: 'hello' }];
  const newContractModels = ['openai/gpt-5.6-terra', 'openai/gpt-5.6-terra:batch', 'openai/gpt-5.6-terra:image'];
  const legacyContractModels = [
    'openai/o1',
    'openai/o3-mini',
    'openai/o4-mini:image',
    'openai/gpt-5-pro',
    'openai/gpt-5.2-pro',
    'openai/gpt-5.4-pro',
    'openai/gpt-5.5-pro',
    'openai/gpt-5.5-pro:batch',
    'openai/gpt-4o',
    'openai/gpt-4.1',
    'gpt-4.1',
    'openrouter/deepseek-v3',
    'openrouter/mistral-large',
    'o365-assistant',
  ];
  for (const compatibility of [ProviderCompatibilityCh, ProviderCompatibilityFx]) {
    for (const model of newContractModels) {
      assert.equal(compatibility.isNewOpenAIContractConfig({ providerName: 'openrouter', model }), true, `${model} should use the new contract`);
    }
    for (const model of legacyContractModels) {
      assert.equal(compatibility.isNewOpenAIContractConfig({ providerName: 'openrouter', model }), false, `${model} should keep the legacy contract`);
    }
  }

  for (const Provider of [OpenAIProviderCh, OpenAIProviderFx]) {
    for (const model of newContractModels) {
      const provider = new Provider({
        providerName: 'openrouter',
        baseUrl: 'https://openrouter.ai/api/v1',
        model,
      });
      assert.equal(provider._isNewOpenAIContract(), true, `${model} should use the new contract`);
      const body = provider._buildChatCompletionsBody(messages, { maxTokens: 123, temperature: 0.2 }, false);
      assert.equal(body.max_completion_tokens, 123, `${model} should use max_completion_tokens`);
      assert.equal(body.max_tokens, undefined, `${model} must not send max_tokens`);
      assert.equal(body.temperature, undefined, `${model} must omit temperature`);
    }

    for (const model of legacyContractModels) {
      const provider = new Provider({
        providerName: 'openrouter',
        baseUrl: 'https://openrouter.ai/api/v1',
        model,
      });
      assert.equal(provider._isNewOpenAIContract(), false, `${model} should keep the legacy contract`);
      const body = provider._buildChatCompletionsBody(messages, { maxTokens: 123 }, false);
      assert.equal(body.max_tokens, 123, `${model} should use max_tokens`);
      assert.equal(body.max_completion_tokens, undefined, `${model} must not send max_completion_tokens`);
      assert.equal(body.temperature, 0.7, `${model} should keep the default temperature`);
    }

    // gpt-4.1 accepts both parameter sets; it must stay legacy so explicit
    // temperatures (deterministic planner/compaction paths) are not dropped.
    const gpt41 = new Provider({
      providerName: 'openai',
      baseUrl: 'https://api.openai.com/v1',
      model: 'gpt-4.1',
    });
    assert.equal(gpt41._isNewOpenAIContract(), false, 'gpt-4.1 must keep the legacy contract');
    const gpt41Body = gpt41._buildChatCompletionsBody(messages, { maxTokens: 123, temperature: 0 }, false);
    assert.equal(gpt41Body.max_tokens, 123, 'gpt-4.1 should use max_tokens');
    assert.equal(gpt41Body.temperature, 0, 'gpt-4.1 must preserve an explicit temperature');

    const lmstudio = new Provider({
      providerName: 'lmstudio',
      category: 'local',
      baseUrl: 'http://localhost:1234/v1',
      model: 'openai/o1',
    });
    assert.equal(lmstudio._isNewOpenAIContract(), false, 'lmstudio must keep the legacy contract even for reasoning ids');
    const lmstudioBody = lmstudio._buildChatCompletionsBody(messages, { maxTokens: 123 }, false);
    assert.equal(lmstudioBody.max_tokens, 123, 'lmstudio should use max_tokens');
    assert.equal(lmstudioBody.temperature, 0.7, 'lmstudio should keep the default temperature');

    // The guard must be case-insensitive: a hand-built or duplicated config
    // with providerName 'LMStudio' still gets the legacy contract.
    const lmstudioMixedCase = new Provider({
      providerName: 'LMStudio',
      category: 'cloud',
      baseUrl: 'http://localhost:1234/v1',
      model: 'openai/o1',
    });
    assert.equal(lmstudioMixedCase._isNewOpenAIContract(), false, 'LM Studio guard must be case-insensitive');

    const official = new Provider({
      providerName: 'openai',
      baseUrl: 'https://api.openai.com/v1',
      model: 'gpt-5.6-terra',
    });
    assert.equal(official._isNewOpenAIContract(), true, 'unprefixed gpt-5.6-terra should still use the new contract');
    const officialBody = official._buildChatCompletionsBody(messages, { maxTokens: 123 }, false);
    assert.equal(officialBody.max_completion_tokens, 123, 'gpt-5.6-terra should use max_completion_tokens');
    assert.equal(officialBody.temperature, undefined, 'gpt-5.6-terra must omit temperature');
  }
});

test('OpenAI contract config keeps non-OpenRouter slash ids on legacy fields', () => {
  for (const [label, compatibility, settingsRel] of [
    ['chrome', ProviderCompatibilityCh, 'src/chrome/src/ui/settings.js'],
    ['firefox', ProviderCompatibilityFx, 'src/firefox/src/ui/settings.js'],
  ]) {
    assert.equal(
      compatibility.isNewOpenAIContractConfig({ providerName: 'openrouter', model: 'openai/gpt-5.6-terra' }),
      true,
      `${label}: OpenRouter GPT-5.6 Terra should use the new contract`,
    );
    for (const model of ['openai/o1', 'openai/o3-mini', 'openai/gpt-5.5-pro', 'openai/gpt-5.2-pro']) {
      assert.equal(
        compatibility.isNewOpenAIContractConfig({ providerName: 'openrouter', model }),
        false,
        `${label}: ${model} should keep OpenRouter's legacy contract`,
      );
    }
    assert.equal(
      compatibility.isNewOpenAIContractConfig({ providerName: 'custom-proxy', model: 'vendor/o3-mini' }),
      false,
      `${label}: unrelated slash-prefixed providers must keep legacy fields`,
    );
    assert.equal(
      compatibility.isNewOpenAIContractConfig({ providerName: 'lmstudio', category: 'local', model: 'openai/o3' }),
      false,
      `${label}: local providers must keep legacy fields`,
    );
    const settings = fs.readFileSync(path.join(ROOT, settingsRel), 'utf8');
    assert.match(settings, /function automaticTokenField\(config\)[\s\S]*isNewOpenAIContractConfig\(config\)/, `${label}: Settings must use the shared config predicate`);
  }
});

test('provider compatibility defaults preserve legacy chat request bodies', () => {
  const messages = [{ role: 'system', content: 'rules' }, { role: 'user', content: 'hello' }];
  for (const Provider of [OpenAIProviderCh, OpenAIProviderFx]) {
    const provider = new Provider({
      category: 'cloud',
      providerName: 'custom',
      baseUrl: 'https://example.test/v1',
      model: 'gpt-4o',
    });
    assert.deepEqual(provider._buildChatCompletionsBody(messages, { temperature: 0.2, maxTokens: 123 }, false), {
      model: 'gpt-4o',
      messages,
      stream: false,
      temperature: 0.2,
      max_tokens: 123,
    });
    assert.deepEqual(provider._buildChatCompletionsBody(messages, { temperature: 0.2, maxTokens: 123 }, true), {
      model: 'gpt-4o',
      messages,
      stream: true,
      temperature: 0.2,
      max_tokens: 123,
    });
    const internalMessages = [{
      role: 'assistant',
      content: 'What value should I use?',
      webbrainAppOwned: true,
      webbrainAppOwnedKind: 'planner_clarification',
      webbrainPlannerClarification: {
        requiresSubmission: true,
        pageUrl: 'https://example.test/application',
      },
    }];
    const internalBody = provider._buildChatCompletionsBody(internalMessages, {}, false);
    assert.deepEqual(
      internalBody.messages,
      [{ role: 'assistant', content: 'What value should I use?' }],
      'app-only planner clarification metadata must not reach Chat Completions providers',
    );
    assert.equal(
      internalMessages[0].webbrainPlannerClarification.requiresSubmission,
      true,
      'provider message sanitization must not mutate persisted conversation state',
    );
    assert.equal(internalMessages[0].webbrainAppOwned, true,
      'provider message sanitization must preserve app-owned metadata in persisted state');
  }
  for (const Provider of [LlamaCppProviderCh, LlamaCppProviderFx]) {
    const provider = new Provider({ baseUrl: 'http://localhost:8080' });
    assert.deepEqual(provider._buildRequestBody(messages, { temperature: 0.2, maxTokens: 123 }, false), {
      messages,
      temperature: 0.2,
      stream: false,
      max_tokens: 123,
    });
  }
  for (const Provider of [AzureOpenAIProviderCh, AzureOpenAIProviderFx]) {
    const provider = new Provider({
      baseUrl: 'https://x.openai.azure.com',
      model: 'deployment',
      apiVersion: '2024-10-21',
      supportsStreamUsageOptions: false,
    });
    assert.deepEqual(provider._buildRequestBody(messages, { temperature: 0.2, maxTokens: 123 }, false), {
      messages,
      stream: false,
      temperature: 0.2,
      max_tokens: 123,
    });
  }
});

test('provider compatibility maps reasoning, roles, token fields, and per-call overrides safely', () => {
  const originalMessages = [{ role: 'system', content: 'rules' }, { role: 'user', content: 'hello' }];
  for (const compat of [ProviderCompatibilityCh, ProviderCompatibilityFx]) {
    const qwenConfig = {
      providerName: 'vllm',
      model: 'Qwen/Qwen3.6-27B',
      compat: { reasoningEffort: 'high', systemPromptRole: 'developer', maxTokensField: 'max_completion_tokens' },
      extraBody: { chat_template_kwargs: { custom_flag: true }, repetition_penalty: 1.05 },
    };
    const mapped = compat.mapProviderMessages(originalMessages, qwenConfig);
    assert.equal(mapped[0].role, 'developer');
    assert.equal(originalMessages[0].role, 'system', 'role mapping must not mutate stored history');

    const body = { messages: mapped };
    compat.addConfiguredMaxTokens(body, 99, qwenConfig, 'max_tokens');
    const merged = compat.mergeProviderRequestBody(body, qwenConfig, {
      chat_template_kwargs: { enable_thinking: false },
    });
    assert.equal(merged.max_completion_tokens, 99);
    assert.equal(merged.max_tokens, undefined);
    assert.deepEqual(merged.chat_template_kwargs, { custom_flag: true, enable_thinking: false });
    assert.equal(merged.repetition_penalty, 1.05);
    assert.equal(qwenConfig.extraBody.chat_template_kwargs.custom_flag, true, 'request merging must not mutate saved config');

    assert.deepEqual(compat.compatibilityRequestBody({
      providerName: 'deepseek',
      model: 'deepseek-v4',
      compat: { reasoningEffort: 'off' },
    }), { thinking: { type: 'disabled' } });
    assert.deepEqual(compat.compatibilityRequestBody({
      providerName: 'openrouter',
      compat: { reasoningEffort: 'medium' },
    }), { reasoning: { effort: 'medium' } });
    assert.deepEqual(compat.compatibilityRequestBody({
      providerName: 'openrouter',
      compat: { reasoningEffort: 'max' },
    }), { reasoning: { effort: 'high' } }, 'OpenRouter clamps max to high');
    assert.deepEqual(compat.compatibilityRequestBody({
      providerName: 'openai',
      baseUrl: 'https://api.openai.com/v1',
      model: 'gpt-5.6-terra',
      compat: { reasoningEffort: 'max' },
    }), { reasoning: { effort: 'max' } }, 'OpenAI GPT-5.6 keeps max effort');
    assert.deepEqual(compat.compatibilityRequestBody({
      providerName: 'custom',
      baseUrl: 'https://proxy.example/v1',
      model: 'gpt-5.6-terra',
      compat: { preset: 'openai', reasoningEffort: 'off' },
    }), { reasoning_effort: 'none' });

    const plannerSchema = {
      type: 'object',
      additionalProperties: false,
      properties: { request_kind: { type: 'string' } },
      required: ['request_kind'],
    };
    assert.deepEqual(compat.plannerRequestBody({
      providerName: 'openrouter',
      model: 'deepseek/deepseek-v4',
    }, { schema: plannerSchema }), {
      reasoning: { enabled: false },
      response_format: {
        type: 'json_schema',
        json_schema: { name: 'webbrain_planner', strict: true, schema: plannerSchema },
      },
    }, 'OpenRouter planner controls are protocol-based, not model-based');
    assert.deepEqual(compat.plannerRequestBody({
      providerName: 'deepseek',
      baseUrl: 'https://api.deepseek.com/v1',
      model: 'deepseek-v4',
    }, { schema: plannerSchema }), {
      thinking: { type: 'disabled' },
      response_format: { type: 'json_object' },
    }, 'direct DeepSeek uses its native thinking and JSON Object controls');
    assert.deepEqual(compat.plannerRequestBody({
      providerName: 'openai',
      baseUrl: 'https://api.openai.com/v1',
      model: 'gpt-5.6-terra',
    }, { schema: plannerSchema }), {
      reasoning: { effort: 'minimal' },
      response_format: {
        type: 'json_schema',
        json_schema: { name: 'webbrain_planner', strict: true, schema: plannerSchema },
      },
    }, 'official OpenAI Responses planners receive low-budget reasoning and strict JSON schema');
    assert.equal(
      compat.plannerRequestBody({
        providerName: 'lmstudio',
        category: 'local',
        model: 'Qwen3.5-VL',
      }, { schema: plannerSchema }).chat_template_kwargs?.enable_thinking,
      false,
      'Qwen-family local servers receive the chat-template thinking control',
    );
    assert.equal(compat.plannerRequestBody({
      providerName: 'alibaba',
      category: 'cloud',
      model: 'qwen-plus',
    }, { schema: plannerSchema }).chat_template_kwargs, undefined, 'hosted Qwen APIs do not receive local chat-template fields');
    assert.deepEqual(compat.plannerRequestBody({
      providerName: 'custom',
      baseUrl: 'https://proxy.example/v1',
      model: 'deepseek-v4',
    }, { schema: plannerSchema }), {}, 'unknown compatible endpoints receive no speculative fields');

    // Partial nested extras must not clobber required nested fields.
    const nestedBase = {
      store: false,
      include: ['reasoning.encrypted_content'],
      reasoning: { effort: 'high' },
    };
    const nestedMerged = compat.mergeProviderRequestBody(nestedBase, {
      extraBody: { reasoning: { summary: 'auto' }, temperature: 0.2 },
    });
    assert.deepEqual(nestedMerged.reasoning, { effort: 'high', summary: 'auto' });
    assert.equal(nestedMerged.store, false);
    assert.deepEqual(nestedMerged.include, ['reasoning.encrypted_content']);
    assert.equal(nestedMerged.temperature, 0.2);

    assert.throws(
      () => compat.parseProviderExtraBodyJson('{"model":"blocked"}'),
      /reserved fields: model/,
    );
    assert.throws(() => compat.parseProviderExtraBodyJson('[]'), /must be a JSON object/);
    assert.throws(() => compat.parseProviderExtraBodyJson('{bad'), /not valid JSON/);
    assert.deepEqual(
      compat.mergeProviderRequestBody({ model: 'safe', stream: false }, {
        extraBody: { model: 'override', stream: true, temperature: 0.4 },
      }),
      { model: 'safe', stream: false, temperature: 0.4 },
    );
  }
});

test('DeepSeek Chat Completions uses native thinking, vision, streaming, and replay contracts', async () => {
  const originalFetch = globalThis.fetch;
  const tools = [{
    type: 'function',
    function: {
      name: 'read_page',
      description: 'Read the page',
      parameters: { type: 'object', properties: {}, additionalProperties: false },
    },
  }];
  try {
    for (const [label, compatibility] of [
      ['chrome', ProviderCompatibilityCh],
      ['firefox', ProviderCompatibilityFx],
    ]) {
      assert.equal(
        compatibility.normalizeOpenAICompatibleBaseUrl('https://api.deepseek.com'),
        'https://api.deepseek.com',
        `${label}: DeepSeek's root endpoint must not be rewritten to /v1`,
      );
      assert.equal(
        compatibility.normalizeOpenAICompatibleBaseUrl('https://api.deepseek.com/v1'),
        'https://api.deepseek.com/v1',
        `${label}: explicit DeepSeek-compatible paths must remain unchanged`,
      );
      assert.equal(
        compatibility.isDirectDeepSeekConfig({ providerName: 'proxy', baseUrl: 'https://api.deepseek.com' }),
        true,
        `${label}: the official DeepSeek host should select its native preset`,
      );
      for (const providerConfig of [
        { providerName: 'lmstudio', category: 'local', baseUrl: 'http://localhost:1234/v1' },
        { providerName: 'ollama', category: 'local', baseUrl: 'http://localhost:11434/v1' },
        { providerName: 'vllm', category: 'local', baseUrl: 'http://localhost:8000/v1' },
        { providerName: 'deepseek', category: 'local', baseUrl: 'http://localhost:9000/v1' },
      ]) {
        const localConfig = {
          ...providerConfig,
          model: 'deepseek-v4-flash',
          compat: { reasoningEffort: 'high' },
        };
        assert.equal(
          compatibility.isDirectDeepSeekConfig(localConfig),
          false,
          `${label}: ${providerConfig.providerName} must not be treated as the direct DeepSeek API`,
        );
        assert.deepEqual(
          compatibility.compatibilityRequestBody(localConfig),
          { chat_template_kwargs: { thinking: true } },
          `${label}: ${providerConfig.providerName} should keep local DeepSeek template controls`,
        );
      }
      for (const [effort, expected] of [
        ['minimal', { thinking: { type: 'enabled' }, reasoning_effort: 'low' }],
        ['low', { thinking: { type: 'enabled' }, reasoning_effort: 'low' }],
        ['medium', { thinking: { type: 'enabled' }, reasoning_effort: 'high' }],
        ['high', { thinking: { type: 'enabled' }, reasoning_effort: 'high' }],
        ['xhigh', { thinking: { type: 'enabled' }, reasoning_effort: 'high' }],
        ['max', { thinking: { type: 'enabled' }, reasoning_effort: 'max' }],
        ['off', { thinking: { type: 'disabled' } }],
      ]) {
        assert.deepEqual(
          compatibility.compatibilityRequestBody({
            providerName: 'deepseek',
            model: 'deepseek-v4-flash',
            compat: { reasoningEffort: effort },
          }),
          expected,
          `${label}: ${effort} should map to DeepSeek's documented wire fields`,
        );
      }
      assert.equal(
        compatibility.compatibilityRequestBody({
          providerName: 'deepseek',
          model: 'deepseek-v4-flash',
          compat: { reasoningEffort: 'off' },
        }).chat_template_kwargs,
        undefined,
        `${label}: DeepSeek must not receive Qwen chat-template thinking fields`,
      );
      const deepSeekVisionConfig = {
        providerName: 'deepseek',
        category: 'cloud',
        baseUrl: 'https://api.deepseek.com',
        compat: { reasoningEffort: 'high' },
      };
      const deepSeekVisionOptions = compatibility.visionGenerationOptions(160, {
        providerConfig: deepSeekVisionConfig,
      });
      assert.deepEqual(
        deepSeekVisionOptions,
        { maxTokens: 160, temperature: 0, extraBody: { thinking: { type: 'disabled' } } },
        `${label}: DeepSeek vision probes should disable thinking natively`,
      );
      assert.deepEqual(
        compatibility.mergeProviderRequestBody({}, deepSeekVisionConfig, deepSeekVisionOptions.extraBody),
        { thinking: { type: 'disabled' } },
        `${label}: disabling DeepSeek vision thinking must clear configured reasoning effort`,
      );
    }

    for (const PM of [ProviderManagerCh, ProviderManagerFx]) {
      const manager = new PM();
      const defaults = manager._defaultConfigs();
      assert.equal(defaults.deepseek.baseUrl, 'https://api.deepseek.com', `${PM.name}: official DeepSeek base URL`);
      assert.equal(defaults.deepseek.model, 'deepseek-v4-flash', `${PM.name}: current DeepSeek default model`);
      assert.equal(defaults.deepseek.contextWindow, 1000000, `${PM.name}: DeepSeek context window`);
      const migrated = manager._migrateStoredProviderConfigs({
        deepseek: {
          model: 'deepseek-v4-flash',
          baseUrl: 'https://api.deepseek.com/v1',
          inputCostPerMillionUsd: 0.27,
          outputCostPerMillionUsd: 1.1,
        },
      });
      assert.equal(migrated.deepseek.baseUrl, 'https://api.deepseek.com', `${PM.name}: untouched legacy DeepSeek defaults should migrate`);
    }

    for (const [label, Provider, AgentClass] of [
      ['chrome', OpenAIProviderCh, AgentCh],
      ['firefox', OpenAIProviderFx, AgentFx],
    ]) {
      const provider = new Provider({
        category: 'cloud',
        providerName: 'deepseek',
        baseUrl: 'https://api.deepseek.com',
        model: 'deepseek-v4-flash',
        compat: { reasoningEffort: 'high' },
        supportsStreamUsageOptions: true,
      });
      assert.equal(provider.supportsVision, false, `${label}: the text-only DeepSeek model must not advertise vision`);
      const vision = new Provider({ ...provider.config, model: 'deepseek-v4-flash-vision-exp' });
      assert.equal(vision.supportsVision, true, `${label}: the official DeepSeek vision model must advertise vision`);

      const body = provider._buildChatCompletionsBody(
        [{ role: 'user', content: 'Read the page' }],
        { tools, maxTokens: 321, temperature: 0.2 },
        true,
      );
      assert.equal(body.max_tokens, 321, `${label}: DeepSeek must use max_tokens`);
      assert.equal(body.max_completion_tokens, undefined, `${label}: DeepSeek must not use max_completion_tokens`);
      assert.deepEqual(body.thinking, { type: 'enabled' }, `${label}: thinking must be enabled natively`);
      assert.equal(body.reasoning_effort, 'high', `${label}: reasoning effort must use the DeepSeek field`);
      assert.equal(body.chat_template_kwargs, undefined, `${label}: legacy Qwen fields must be absent`);
      assert.deepEqual(body.stream_options, { include_usage: true }, `${label}: DeepSeek streaming should request usage`);
      assert.equal(body.tools.length, 1, `${label}: function tools must be sent`);

      const agent = new AgentClass({});
      const assistant = {
        role: 'assistant',
        content: null,
        tool_calls: [{ id: 'call-1', type: 'function', function: { name: 'read_page', arguments: '{}' } }],
      };
      const replayable = agent._withResponseItems(assistant, null, 'DeepSeek reasoning', provider);
      assert.equal(replayable.reasoning_content, 'DeepSeek reasoning', `${label}: reasoning content must be persisted`);
      assert.equal(replayable._reasoning_replay?.preserveAcrossTurns, true, `${label}: tool-loop reasoning must be marked persistent`);
      assert.equal(provider._chatMessages([replayable])[0].reasoning_content, 'DeepSeek reasoning', `${label}: reasoning content must be replayed`);
      agent._expireCurrentToolReasoning([replayable]);
      assert.equal(replayable.reasoning_content, 'DeepSeek reasoning', `${label}: DeepSeek reasoning must survive later turns`);

      let capturedUrl = '';
      let capturedBody = null;
      globalThis.fetch = async (url, options = {}) => {
        capturedUrl = String(url);
        capturedBody = JSON.parse(options.body);
        const events = [
          { choices: [{ delta: { reasoning_content: 'think' } }] },
          { choices: [{ delta: { content: 'answer' } }] },
          { choices: [{ delta: { tool_calls: [{ index: 0, id: 'call-1', type: 'function', function: { name: 'read_page', arguments: '{}' } }] } }] },
          { choices: [{ delta: {}, finish_reason: 'tool_calls' }], usage: { prompt_tokens: 12, completion_tokens: 8, total_tokens: 20 } },
        ];
        const sse = `${events.map(event => `data: ${JSON.stringify(event)}\n\n`).join('')}data: [DONE]\n\n`;
        return new Response(sse, { status: 200, headers: { 'Content-Type': 'text/event-stream' } });
      };
      const chunks = [];
      for await (const chunk of provider.chatStream([{ role: 'user', content: 'Read the page' }], { tools, maxTokens: 321 })) {
        chunks.push(chunk);
      }
      assert.equal(capturedUrl, 'https://api.deepseek.com/chat/completions', `${label}: requests must use the official Chat Completions path`);
      assert.deepEqual(capturedBody.thinking, { type: 'enabled' });
      assert.equal(capturedBody.reasoning_effort, 'high');
      assert.deepEqual(chunks.slice(0, 3), [
        { type: 'reasoning', content: 'think' },
        { type: 'text', content: 'answer' },
        { type: 'tool_call', content: [{ index: 0, id: 'call-1', type: 'function', function: { name: 'read_page', arguments: '{}' } }] },
      ], `${label}: DeepSeek reasoning, text, and tool deltas must be exposed`);
      assert.deepEqual(chunks[3], { type: 'usage', usage: { prompt_tokens: 12, completion_tokens: 8, total_tokens: 20 } });
      assert.deepEqual(chunks[4], { type: 'done', content: '', finishReason: 'tool_calls' });

      globalThis.fetch = async () => new Response(JSON.stringify({
        choices: [{
          message: {
            content: 'answer',
            reasoning_content: 'non-stream reasoning',
            tool_calls: [{ id: 'call-2', type: 'function', function: { name: 'read_page', arguments: '{}' } }],
          },
          finish_reason: 'tool_calls',
        }],
        usage: { prompt_tokens: 10, completion_tokens: 5, total_tokens: 15 },
      }), { status: 200, headers: { 'Content-Type': 'application/json' } });
      const result = await provider.chat([{ role: 'user', content: 'Read the page' }], { tools, maxTokens: 321 });
      assert.equal(result.reasoningContent, 'non-stream reasoning', `${label}: non-stream reasoning content must be returned`);
      assert.equal(result.toolCalls?.[0]?.id, 'call-2', `${label}: non-stream tool calls must be returned`);
      assert.deepEqual(result.usage, { prompt_tokens: 10, completion_tokens: 5, total_tokens: 15 });
    }
  } finally {
    globalThis.fetch = originalFetch;
  }
});

test('official GPT-5.6 uses Responses while older and custom OpenAI-compatible endpoints stay on Chat Completions', () => {
  const tools = [{
    type: 'function',
    function: {
      name: 'click',
      description: 'Click something',
      parameters: { type: 'object', properties: { ref: { type: 'string' } }, required: ['ref'] },
    },
  }];
  const messages = [
    { role: 'system', content: 'rules' },
    { role: 'user', content: 'go' },
    { role: 'assistant', content: null, tool_calls: [{ id: 'call_1', type: 'function', function: { name: 'click', arguments: '{"ref":"r1"}' } }] },
    { role: 'tool', tool_call_id: 'call_1', content: '{"ok":true}' },
  ];
  for (const Provider of [OpenAIProviderCh, OpenAIProviderFx]) {
    const provider = new Provider({
      category: 'cloud',
      providerName: 'openai',
      baseUrl: 'https://api.openai.com/v1',
      model: 'gpt-5.6-terra',
      compat: { reasoningEffort: 'high', systemPromptRole: 'developer' },
    });
    assert.equal(provider._usesResponsesApi(), true);
    const body = provider._buildResponsesBody(messages, { tools, maxTokens: 321 }, false);
    assert.equal(body.max_output_tokens, 321);
    assert.equal(body.max_completion_tokens, undefined);
    assert.equal(body.messages, undefined);
    assert.deepEqual(body.reasoning, { effort: 'high' });
    assert.equal(body.store, false);
    assert.deepEqual(body.include, ['reasoning.encrypted_content']);
    assert.equal(body.input[0].role, 'developer');
    assert.deepEqual(body.input[2], {
      type: 'function_call',
      call_id: 'call_1',
      name: 'click',
      arguments: '{"ref":"r1"}',
    });
    assert.deepEqual(body.input[3], {
      type: 'function_call_output',
      call_id: 'call_1',
      output: '{"ok":true}',
    });
    assert.deepEqual(body.tools[0], {
      type: 'function',
      name: 'click',
      description: 'Click something',
      parameters: tools[0].function.parameters,
      strict: false,
    });

    // Partial custom reasoning extras preserve effort; response_format is
    // converted to text.format and stripped from the Responses body.
    const maxProvider = new Provider({
      category: 'cloud',
      providerName: 'openai',
      baseUrl: 'https://api.openai.com/v1',
      model: 'gpt-5.6-terra',
      compat: { reasoningEffort: 'max' },
      extraBody: {
        reasoning: { summary: 'auto' },
        response_format: {
          type: 'json_schema',
          json_schema: {
            name: 'answer',
            schema: { type: 'object', properties: { ok: { type: 'boolean' } } },
            strict: true,
          },
        },
        store: true,
        include: [],
      },
    });
    const maxBody = maxProvider._buildResponsesBody([{ role: 'user', content: 'hi' }], {}, false);
    assert.equal(maxBody.reasoning.effort, 'max');
    assert.equal(maxBody.reasoning.summary, 'auto');
    assert.equal(maxBody.store, false, 'store must stay false for stateless Responses');
    assert.ok(maxBody.include.includes('reasoning.encrypted_content'));
    assert.equal(maxBody.response_format, undefined);
    assert.deepEqual(maxBody.text, {
      format: {
        type: 'json_schema',
        name: 'answer',
        schema: { type: 'object', properties: { ok: { type: 'boolean' } } },
        strict: true,
      },
    });

    const parsed = provider._parseResponsesData({
      output: [
        { type: 'reasoning', summary: [{ type: 'summary_text', text: 'Checked the page.' }] },
        { type: 'message', content: [{ type: 'output_text', text: 'Done' }] },
        { type: 'function_call', call_id: 'call_2', name: 'click', arguments: '{"ref":"r2"}' },
      ],
      usage: { input_tokens: 10, output_tokens: 4, total_tokens: 14 },
    });
    assert.equal(parsed.content, 'Done');
    assert.equal(parsed.reasoningContent, 'Checked the page.');
    assert.equal(parsed.toolCalls[0].id, 'call_2');
    assert.equal(parsed.usage.prompt_tokens, 10);
    assert.equal(parsed.usage.completion_tokens, 4);

    assert.equal(new Provider({
      providerName: 'openai',
      baseUrl: 'https://api.openai.com/v1',
      model: 'gpt-5.5',
    })._usesResponsesApi(), false);
    assert.equal(new Provider({
      providerName: 'openai',
      baseUrl: 'https://proxy.example/v1',
      model: 'gpt-5.6-terra',
    })._usesResponsesApi(), false);
  }
});

test('official GPT-5.6 streaming uses Responses events for text, tools, and usage', async () => {
  const originalFetch = globalThis.fetch;
  try {
    for (const Provider of [OpenAIProviderCh, OpenAIProviderFx]) {
      let capturedUrl = '';
      let capturedBody = null;
      globalThis.fetch = async (url, options = {}) => {
        capturedUrl = String(url);
        capturedBody = JSON.parse(options.body);
        // Match the production stream path: emit function_call on
        // output_item.done, then usage + responseItems on completed.
        const events = [
          { type: 'response.output_text.delta', delta: 'Hello' },
          {
            type: 'response.output_item.done',
            output_index: 1,
            item: { type: 'function_call', call_id: 'call_1', name: 'click', arguments: '{"ref":"r1"}' },
          },
          {
            type: 'response.completed',
            response: {
              stop_reason: 'stop',
              usage: { input_tokens: 8, output_tokens: 3, total_tokens: 11 },
              output: [
                { type: 'message', content: [{ type: 'output_text', text: 'Hello' }] },
                { type: 'function_call', call_id: 'call_1', name: 'click', arguments: '{"ref":"r1"}' },
              ],
            },
          },
        ].map((event) => `data: ${JSON.stringify(event)}\n\n`).join('');
        return new Response(events, { status: 200, headers: { 'Content-Type': 'text/event-stream' } });
      };
      const provider = new Provider({
        category: 'cloud',
        providerName: 'openai',
        baseUrl: 'https://api.openai.com/v1',
        model: 'gpt-5.6-terra',
        compat: { reasoningEffort: 'low' },
      });
      const chunks = [];
      for await (const chunk of provider.chatStream([{ role: 'user', content: 'hello' }], { maxTokens: 10 })) {
        chunks.push(chunk);
      }
      assert.equal(capturedUrl, 'https://api.openai.com/v1/responses');
      assert.equal(capturedBody.stream, true);
      assert.deepEqual(capturedBody.reasoning, { effort: 'low' });
      assert.equal(chunks[0].type, 'text');
      assert.equal(chunks[0].content, 'Hello');
      assert.equal(chunks[1].type, 'tool_call');
      assert.equal(chunks[1].content[0].id, 'call_1');
      assert.equal(chunks[1].content[0].function.arguments, '{"ref":"r1"}');
      assert.equal(chunks[2].type, 'usage');
      assert.equal(chunks[2].usage.prompt_tokens, 8);
      assert.equal(chunks.at(-1).type, 'done');
      assert.equal(chunks.at(-1).finishReason, 'stop');
      assert.equal(chunks.at(-1).responseItems.length, 2);
    }
  } finally {
    globalThis.fetch = originalFetch;
  }
});

test('official GPT-5.6 treats incomplete Responses as hard failures', async () => {
  const originalFetch = globalThis.fetch;
  try {
    for (const Provider of [OpenAIProviderCh, OpenAIProviderFx]) {
      const provider = new Provider({
        category: 'cloud',
        providerName: 'openai',
        baseUrl: 'https://api.openai.com/v1',
        model: 'gpt-5.6-terra',
      });

      assert.throws(
        () => provider._parseResponsesData({
          status: 'incomplete',
          incomplete_details: { reason: 'max_output_tokens' },
          output: [{ type: 'message', content: [{ type: 'output_text', text: 'truncated' }] }],
        }),
        /incomplete \(max_output_tokens\)/,
      );
      assert.throws(
        () => provider._parseResponsesData({
          status: 'failed',
          error: { message: 'provider refused the request' },
        }),
        /provider refused the request/,
      );

      globalThis.fetch = async () => {
        const events = [
          { type: 'response.output_text.delta', delta: 'partial' },
          {
            type: 'response.incomplete',
            response: {
              status: 'incomplete',
              incomplete_details: { reason: 'content_filter' },
              usage: { input_tokens: 3, output_tokens: 1, total_tokens: 4 },
              output: [{ type: 'message', content: [{ type: 'output_text', text: 'partial' }] }],
            },
          },
        ].map((event) => `data: ${JSON.stringify(event)}\n\n`).join('');
        return new Response(events, { status: 200, headers: { 'Content-Type': 'text/event-stream' } });
      };

      const chunks = [];
      let thrown = null;
      try {
        for await (const chunk of provider.chatStream([{ role: 'user', content: 'hello' }], { maxTokens: 10 })) {
          chunks.push(chunk);
        }
      } catch (error) {
        thrown = error;
      }
      assert.ok(thrown, 'incomplete streams must throw rather than yield done');
      assert.match(thrown.message, /incomplete \(content_filter\)/);
      assert.equal(thrown.incomplete, true);
      assert.equal(thrown.isResponsesStreamError, true);
      assert.equal(thrown.isResponsesStreamFallbackSafe, false, 'terminal response.incomplete must not trigger provider.chat() fallback');
      assert.equal(thrown.isAskStreamTerminalError, true, 'terminal response.incomplete must bypass the agent retry');
      assert.equal(chunks[0]?.type, 'text');
      assert.equal(chunks[0]?.content, 'partial');
      assert.equal(chunks[1]?.type, 'usage');
      assert.equal(chunks.some((chunk) => chunk.type === 'done'), false);

      globalThis.fetch = async () => new Response(
        `data: ${JSON.stringify({
          type: 'response.failed',
          response: { error: { message: 'provider refused the stream' } },
        })}\n\n`,
        { status: 200, headers: { 'Content-Type': 'text/event-stream' } },
      );
      let failed = null;
      try {
        for await (const _chunk of provider.chatStream([{ role: 'user', content: 'hello' }], { maxTokens: 10 })) {
          // No chunks are expected for response.failed.
        }
      } catch (error) {
        failed = error;
      }
      assert.match(failed?.message || '', /provider refused the stream/);
      assert.equal(failed?.isResponsesStreamError, true);
      assert.equal(failed?.isAskStreamTerminalError, true, 'response.failed must bypass the agent retry');
    }
  } finally {
    globalThis.fetch = originalFetch;
  }
});

test('official GPT-5.6 rejects premature Responses EOF and bare DONE sentinels', async () => {
  const originalFetch = globalThis.fetch;
  try {
    for (const Provider of [OpenAIProviderCh, OpenAIProviderFx]) {
      const provider = new Provider({
        category: 'cloud',
        providerName: 'openai',
        baseUrl: 'https://api.openai.com/v1',
        model: 'gpt-5.6-terra',
      });
      for (const sse of [
        'data: {"type":"response.output_text.delta","delta":"partial"}\n\n',
        'data: [DONE]\n\n',
      ]) {
        globalThis.fetch = async () => new Response(sse, {
          status: 200,
          headers: { 'Content-Type': 'text/event-stream' },
        });
        const chunks = [];
        let thrown = null;
        try {
          for await (const chunk of provider.chatStream([{ role: 'user', content: 'hello' }])) {
            chunks.push(chunk);
          }
        } catch (error) {
          thrown = error;
        }
        assert.ok(thrown, 'a Responses stream without response.completed must fail');
        assert.match(thrown.message, /incomplete \(missing_response_completed\)/);
        assert.equal(thrown.incomplete, true);
        assert.equal(thrown.isResponsesStreamError, true);
        assert.equal(thrown.isResponsesStreamFallbackSafe, true, 'missing response.completed should allow the non-streaming recovery path');
        assert.notEqual(thrown.isAskStreamTerminalError, true, 'recoverable missing completion must retain the non-streaming fallback');
        assert.equal(chunks.some((chunk) => chunk.type === 'done'), false);
      }
    }
  } finally {
    globalThis.fetch = originalFetch;
  }
});

test('official GPT-5.6 keeps HTTP stream errors terminal', async () => {
  const originalFetch = globalThis.fetch;
  try {
    globalThis.fetch = async () => new Response('{"error":{"message":"rate limited"}}', {
      status: 429,
      headers: { 'Content-Type': 'application/json' },
    });
    for (const Provider of [OpenAIProviderCh, OpenAIProviderFx]) {
      const provider = new Provider({
        category: 'cloud',
        providerName: 'openai',
        baseUrl: 'https://api.openai.com/v1',
        model: 'gpt-5.6-terra',
      });
      let thrown = null;
      try {
        for await (const _chunk of provider.chatStream([{ role: 'user', content: 'hello' }])) {
          // No chunks are expected for an HTTP failure.
        }
      } catch (error) {
        thrown = error;
      }
      assert.match(thrown?.message || '', /stream error 429/);
      assert.equal(thrown?.isResponsesStreamError, true);
      assert.notEqual(thrown?.isResponsesStreamFallbackSafe, true, 'HTTP/API failures must propagate without provider.chat() fallback');
    }
  } finally {
    globalThis.fetch = originalFetch;
  }
});

