test('set_field with submit:true requires CLICK, not the weaker TYPE', () => {
  assert.equal(capabilityFor('set_field', { ref_id: 'r', text: 'x' }), Capability.TYPE);
  assert.equal(capabilityFor('set_field', { ref_id: 'r', text: 'x', submit: true }), Capability.CLICK);
});

test('capabilitiesFor: set_field({submit}) requires BOTH type and click', () => {
  assert.deepEqual(capabilitiesFor('set_field', { text: 'x' }), [Capability.TYPE]);
  assert.deepEqual(capabilitiesFor('set_field', { text: 'x', submit: true }), [Capability.TYPE, Capability.CLICK]);
  // single-capability tools wrap to a 1-element array; read-only → []
  assert.deepEqual(capabilitiesFor('click', {}), [Capability.CLICK]);
  assert.deepEqual(capabilitiesFor('fetch_url', { url: 'https://x.com' }), [Capability.NETWORK]);
  assert.deepEqual(capabilitiesFor('read_page', {}), []);
});

test('press_keys: Enter and semicolon shortcuts require CLICK; Tab/Escape are benign', () => {
  for (const [label, capabilityFn, Capabilities] of [
    ['chrome', capabilityForCh, CapabilityCh],
    ['firefox', capabilityFor, Capability],
  ]) {
    assert.equal(capabilityFn('press_keys', { key: 'Enter' }), Capabilities.CLICK, `${label}: Enter`);
    assert.equal(capabilityFn('press_keys', { key: ';' }), Capabilities.CLICK, `${label}: semicolon`);
    assert.equal(capabilityFn('press_keys', { key: 'Escape' }), null, `${label}: Escape`);
    assert.equal(capabilityFn('press_keys', { key: 'Tab' }), null, `${label}: Tab`);
    assert.equal(capabilityFn('press_keys', {}), Capabilities.CLICK, `${label}: unknown key`); // fail safe
  }
});

test('submit controls bypass native select guards in click paths', () => {
  const chromeAgent = fs.readFileSync(path.join(ROOT, 'src/chrome/src/agent/agent.js'), 'utf8');
  assert.match(chromeAgent, /function findSubmitControl\(el\)[\s\S]*tag === 'INPUT' && \(type === 'submit' \|\| type === 'image'\)[\s\S]*tag === 'BUTTON' && \(type === 'submit' \|\| \(!type && !!\(control\.form \|\| control\.closest\?\.\('form'\)\)\)\)/, 'chrome agent: submit-control helper missing');
  const globalGuardStart = chromeAgent.indexOf("function findSubmitControl(el)");
  const submitBypass = chromeAgent.indexOf("if (findSubmitControl(e.target)) return;", globalGuardStart);
  const nearbySelectCall = chromeAgent.indexOf("const sel = findNearbySelect(e.target);", globalGuardStart);
  assert.ok(globalGuardStart !== -1 && submitBypass !== -1 && nearbySelectCall !== -1 && submitBypass < nearbySelectCall, 'chrome agent: submit bypass should run before nearby select guard');
  assert.match(chromeAgent, /isSubmitControl: isSubmitControl\(inp\)/, 'chrome agent: label-resolved controls should expose submit metadata');
  assert.match(chromeAgent, /isSubmitControl: isSubmitControl\(el\)/, 'chrome agent: text-resolved controls should expose submit metadata');
  assert.match(chromeAgent, /const coordSelCheck = info\.isSubmitControl \? null : await cdpClient\.evaluate/, 'chrome agent: submit text clicks should skip coordinate select guard');
  assert.match(chromeAgent, /const postClickSel1 = info\.isSubmitControl \? null : await cdpClient\.evaluate/, 'chrome agent: submit text clicks should skip post-click select false errors');
  assert.match(chromeAgent, /isEditableControl: isEditableControl\(el\)/, 'chrome agent: resolved click target should expose its own editability');
  assert.match(chromeAgent, /widgetFallback: true,[\s\S]*isEditableControl: el\.isContentEditable[\s\S]*role'\) === 'textbox'[\s\S]*role'\) === 'combobox'/, 'chrome agent: widened text-click fallback should preserve contenteditable/widget editability');
  assert.match(chromeAgent, /const isEditableTarget = info\.isEditableControl === true;/, 'chrome agent: stale-click exemption should use the clicked target, not post-submit focus');

  for (const [label, rel] of [
    ['chrome', 'src/chrome/src/content/content.js'],
    ['firefox', 'src/firefox/src/content/content.js'],
  ]) {
    const content = fs.readFileSync(path.join(ROOT, rel), 'utf8');
    assert.match(content, /function _isSubmitControl\(el\)[\s\S]*if \(tag === 'INPUT'\) return type === 'submit'[\s\S]*if \(tag === 'BUTTON'\) return type === 'submit' \|\| \(!type && !!\(control\.form \|\| control\.closest\?\.\('form'\)\)\)/, `${label}: content submit-control helper missing`);
    assert.match(content, /const targetIsSubmitControl = _isSubmitControl\(el\);/, `${label}: click path should classify submit target before select guards`);
    assert.ok(content.includes('if (!(el instanceof HTMLSelectElement) && !targetIsSubmitControl) {'), `${label}: nearby select guard should not block submit controls`);
    assert.ok(content.includes('if (!targetIsSubmitControl && postActive && postActive !== el && postActive instanceof HTMLSelectElement) {'), `${label}: post-click select false error should not block submit controls`);
    assert.match(content, /isSubmitControl: targetIsSubmitControl,/, `${label}: successful clicks should preserve submit classification for post-click validation`);
  }
  const chromeContent = fs.readFileSync(path.join(ROOT, 'src/chrome/src/content/content.js'), 'utf8');
  assert.match(chromeContent, /el\.tagName === 'INPUT' && !\['button', 'checkbox'[\s\S]*?'submit'\]\.includes\(inputType\)/, 'chrome: checkbox/radio focus must not receive the text-editable stale-click exemption');
});

test('native select rescue yields only to exact clickables and refuses ambiguous dropdowns', () => {
  const chromeAgent = fs.readFileSync(path.join(ROOT, 'src/chrome/src/agent/agent.js'), 'utf8');
  const autoSelectStart = chromeAgent.indexOf('async _autoSelectOption(');
  const autoSelectEnd = chromeAgent.indexOf('\n  async ', autoSelectStart + 10);
  const autoSelectBody = chromeAgent.slice(autoSelectStart, autoSelectEnd);
  assert.ok(autoSelectStart >= 0 && autoSelectEnd > autoSelectStart, 'chrome: auto-select helper should be independently inspectable');
  assert.match(autoSelectBody, /if \(txt && txt === lc\) return \{ found: false, suppressedByClickable: true \};/, 'chrome: only exact clickable text should suppress select rescue');
  assert.doesNotMatch(autoSelectBody, /txt\.includes\(lc\)[^\n]*suppressedByClickable/, 'chrome: substring clickables must not suppress select rescue');
  assert.match(autoSelectBody, /if \(matchingSelects\.length !== 1\)/, 'chrome: auto-select must not pick the first of several matching dropdowns');
  const scanStart = autoSelectBody.indexOf('const scanResult = await cdpClient.evaluate');
  const scanEnd = autoSelectBody.indexOf('const scan = scanResult?.result?.value;', scanStart);
  const scanBody = autoSelectBody.slice(scanStart, scanEnd);
  assert.doesNotMatch(scanBody, /sel\.focus\s*\(/, 'chrome: auto-select scan must remain observation-only before dispatch');
  assert.match(scanBody, /deadlineExpired\(\)/, 'chrome: auto-select scan must reject page work after the action deadline');
  assert.match(autoSelectBody, /const focusResult = await cdpClient\.evaluate[\s\S]*deadlineExpired\(\)[\s\S]*target\.focus\(\)/, 'chrome: auto-select refocus must enforce the page-side deadline');

  const firefoxContent = fs.readFileSync(path.join(ROOT, 'src/firefox/src/content/content.js'), 'utf8');
  const clickStart = firefoxContent.indexOf('function clickElement(params, actionDeadlineExpired = () => false) {');
  const clickEnd = firefoxContent.indexOf('\n  function ', clickStart + 10);
  const clickBody = firefoxContent.slice(clickStart, clickEnd);
  assert.ok(clickStart >= 0 && clickEnd > clickStart, 'firefox: click helper should be independently inspectable');
  assert.match(clickBody, /let textResolvedExact = false;/, 'firefox: click resolution should track the winning text tier');
  assert.match(clickBody, /textResolvedExact = \(usedMode === 'exact'\);/, 'firefox: direct matches should record exact-tier resolution');
  assert.match(clickBody, /!el \|\| el instanceof HTMLSelectElement \|\| !textResolvedExact/, 'firefox: prefix and contains matches should keep select rescue enabled');
  assert.match(clickBody, /matchingSelects\.length > 1/, 'firefox: select rescue must reject ambiguous dropdown matches');
  assert.match(clickBody, /method: 'select-already-set'/, 'firefox: an already-selected exact option must not fall through to an unrelated click');
});

test('accessibility ref lookup rejects disconnected elements', () => {
  for (const [label, rel] of [
    ['chrome', 'src/chrome/src/content/accessibility-tree.js'],
    ['firefox', 'src/firefox/src/content/accessibility-tree.js'],
  ]) {
    const source = fs.readFileSync(path.join(ROOT, rel), 'utf8');
    const start = source.indexOf('function lookup(refId) {');
    const end = source.indexOf('\n\n  // ── Public: suggest nearby refs', start);
    assert.ok(start >= 0 && end > start, `${label}: lookup helper should remain independently testable`);

    const scope = '123456789012';
    const liveRef = `ref_${scope}1`;
    const staleRef = `ref_${scope}2`;
    const collectedRef = `ref_${scope}3`;
    const connected = { isConnected: true };
    const elementMap = {
      [liveRef]: { deref: () => connected },
      [staleRef]: { deref: () => ({ isConnected: false }) },
      [collectedRef]: { deref: () => null },
    };
    const lookup = vm.runInNewContext(`(${source.slice(start, end)})`, {
      window: { __wbElementMap: elementMap },
      refOrdinal: refId => {
        const match = new RegExp(`^ref_${scope}(\\d+)$`).exec(String(refId || ''));
        return match ? Number(match[1]) : null;
      },
    });

    assert.equal(lookup(liveRef), connected, `${label}: connected refs should remain usable`);
    assert.equal(lookup(staleRef), null, `${label}: disconnected refs must be rejected`);
    assert.equal(elementMap[staleRef], undefined, `${label}: disconnected refs should be evicted`);
    assert.equal(lookup(collectedRef), null, `${label}: collected refs must be rejected`);
    assert.equal(elementMap[collectedRef], undefined, `${label}: collected refs should be evicted`);
    assert.equal(lookup('ref_unscoped'), null, `${label}: unscoped refs must remain invalid`);
  }
});

test('set_field waits for reconciliation and verifies the complete value', () => {
  for (const [label, rel] of [
    ['chrome', 'src/chrome/src/content/content.js'],
    ['firefox', 'src/firefox/src/content/content.js'],
  ]) {
    const source = fs.readFileSync(path.join(ROOT, rel), 'utf8');
    const helperStart = source.indexOf(label === 'chrome'
      ? 'function _contentEditableValueMatches('
      : 'function _setFieldValueMatches(');
    const helperEnd = source.indexOf('\n\n  function _editableTextValue', helperStart);
    assert.ok(helperStart >= 0 && helperEnd > helperStart, `${label}: exact-value helper should remain independently testable`);
    const matches = label === 'chrome'
      ? vm.runInNewContext(`(() => { ${source.slice(helperStart, helperEnd)}; return _setFieldValueMatches; })()`)
      : vm.runInNewContext(`(${source.slice(helperStart, helperEnd)})`);

    assert.equal(matches('Magnetic Locks', '', 'Magnetic Locks', true), true, `${label}: exact replacement should verify`);
    assert.equal(matches('Magnetic Locksg', '', 'Magnetic Locks', true), false, `${label}: trailing corruption must not verify`);
    assert.equal(matches('xMagnetic Locks', '', 'Magnetic Locks', true), false, `${label}: leading corruption must not verify`);
    assert.equal(matches('old-new', 'old-', 'new', false), true, `${label}: exact append should verify`);
    assert.equal(matches('new', 'old-', 'new', false), false, `${label}: append verification must preserve prior content`);
    assert.equal(matches('first\nsecond', '', 'first\r\nsecond', true, true), true, `${label}: rich-editor CRLF should match rendered newlines`);
    assert.equal(matches('first\n\n\nsecond', '', 'first\n\nsecond', true, true), label === 'chrome', `${label}: only Chromium should accept its empty-block readback expansion`);
    assert.equal(matches('first\n\n\n\n\nsecond', '', 'first\n\n\nsecond', true, true), label === 'chrome', `${label}: only Chromium should accept multiple empty-block expansions`);
    assert.equal(matches('\n\nfirst', '', '\nfirst', true, true), label === 'chrome', `${label}: only Chromium should accept a leading empty-block expansion`);
    assert.equal(matches('first\n\n', '', 'first\n', true, true), label === 'chrome', `${label}: only Chromium should accept a trailing empty-block expansion`);
    assert.equal(matches('firstsecond', '', 'first\nsecond', true, true), false, `${label}: missing rich-editor newlines must still fail`);
    assert.equal(matches('first\n\nsecond', '', 'first\nsecond', true, true), false, `${label}: an unexplained extra rich-editor newline must still fail`);
    assert.equal(matches('first\n\n\n\nsecond', '', 'first\n\nsecond', true, true), false, `${label}: non-Chromium newline expansion must still fail`);
    assert.equal(matches('first\nsecond!', '', 'first\nsecond', true, true), false, `${label}: rich-editor normalization must not accept other corruption`);
    assert.equal(
      matches('first\n\n\nbody\n\n\nclosing', 'first\n\n\nbody', '\n\nclosing', false, true),
      label === 'chrome',
      `${label}: only Chromium append verification should accept expansion inside the new suffix`,
    );
    assert.equal(
      matches('first\n\n\n\n\nbody\n\n\nclosing', 'first\n\n\nbody', '\n\nclosing', false, true),
      false,
      `${label}: append verification must reject expansion inside the preserved prefix`,
    );
    assert.equal(
      matches('\n\n\n\nclosing', '', '\n\nclosing', false, true),
      label === 'chrome',
      `${label}: only Chromium should accept leading block expansion when appending to an empty editor`,
    );
    assert.equal(
      matches('first\n\n\n\n\nclosing', 'first\n\n', '\n\nclosing', false, true),
      label === 'chrome',
      `${label}: only Chromium should accept suffix expansion after preserved trailing blocks`,
    );

    const branchStart = source.indexOf("'set_field': async () => {");
    const branchEnd = source.indexOf(label === 'chrome' ? "'ax_resolve_rect':" : "'hover':", branchStart);
    assert.ok(branchStart >= 0 && branchEnd > branchStart, `${label}: set_field handler should be bounded for regression checks`);
    const branch = source.slice(branchStart, branchEnd);
    const settleIndex = branch.indexOf('await new Promise(resolve => setTimeout(resolve, SET_FIELD_VERIFY_DELAY_MS))');
    const readbackIndex = branch.search(/(?:const|let) actual = el\.isContentEditable/);
    assert.ok(settleIndex >= 0 && readbackIndex > settleIndex, `${label}: verification must happen after controlled-input reconciliation`);
    assert.match(branch, /(?:const|let) actual = el\.isContentEditable \? _editableTextValue\(el\)/, `${label}: rich-editor verification must use rendered text`);
    assert.match(branch, /_setFieldValueMatches\(actual, prevValue, text, clear, el\.isContentEditable\)/, `${label}: newline normalization must remain contenteditable-only`);
    assert.match(branch, /await new Promise\(resolve => setTimeout\(resolve, SET_FIELD_VERIFY_DELAY_MS\)\);\s*if \(actionDeadlineExpired\(\)\) return deadlineFailure\(\);/, `${label}: set_field can continue after its verification wait expires`);
    assert.match(branch, /if \(usesNativeSubmit\)[\s\S]*if \(actionDeadlineExpired\(\)\) return deadlineFailure\(\);\s*submissionDispatched = true;\s*try \{\s*form\.requestSubmit\(\)/, `${label}: native set_field submission is not guarded at the mutation boundary`);
    assert.match(branch, /await new Promise\(r => setTimeout\(r, 80\)\);\s*if \(actionDeadlineExpired\(\)\) return deadlineFailure\(\);[\s\S]*await new Promise\(r => setTimeout\(r, 30\)\);\s*if \(actionDeadlineExpired\(\)\) return deadlineFailure\(\);[\s\S]*if \(actionDeadlineExpired\(\)\) return deadlineFailure\(\);\s*const enterResult = dispatchKeySequence\('Enter', 13, true\);\s*submissionDispatched = enterResult\.dispatched;\s*if \(!enterResult\.completedWithinDeadline\)/, `${label}: page-owned set_field submission can resume after its deadline`);
    assert.match(
      branch,
      /const dispatchKeySequence = \(key, keyCode, includeKeypress = false\) => \{[\s\S]*result\.dispatched = true;\s*el\.dispatchEvent\(new KeyboardEvent\('keydown'[\s\S]*const expiredAfterKeydown = actionDeadlineExpired\(\);[\s\S]*const expiredBeforeKeyup = expiredAfterKeydown \|\| actionDeadlineExpired\(\);[\s\S]*el\.dispatchEvent\(new KeyboardEvent\('keyup'[\s\S]*result\.completedWithinDeadline = !expiredBeforeKeyup && !actionDeadlineExpired\(\);/,
      `${label}: set_field can leave a synthetic key pressed when a listener crosses the deadline`,
    );
    assert.match(branch, /el\.focus\(\{ preventScroll: true \}\);\s*\} catch \{\}\s*if \(actionDeadlineExpired\(\)\) return deadlineFailure\(\);/, `${label}: set_field can mutate after focus handlers cross the deadline`);
    assert.match(branch, /if \(setter\) setter\.call\(el, newVal\); else el\.value = newVal;\s*if \(actionDeadlineExpired\(\)\) return deadlineFailure\(\);\s*el\.dispatchEvent\(new Event\('input'/, `${label}: set_field does not recheck its deadline before page events`);
    if (label === 'firefox') {
      assert.match(branch, /await _retryFieldWithExecCommand\([\s\S]*if \(actionDeadlineExpired\(\)\) return deadlineFailure\(\);/, 'firefox: set_field fallback can continue after its reconciliation wait expires');
      const hoverStart = source.indexOf("'hover': () => {");
      const hoverEnd = source.indexOf("'drag_drop': () => {", hoverStart);
      const hoverBranch = source.slice(hoverStart, hoverEnd);
      assert.match(hoverBranch, /el\.dispatchEvent\(new EventType\(type, eventInit\)\);\s*return !actionDeadlineExpired\(\);/, 'firefox: synthetic hover can report success after its last listener crosses the deadline');
      const dragStart = hoverEnd;
      const dragEnd = source.indexOf("'wait_for_stable':", dragStart);
      const dragBranch = source.slice(dragStart, dragEnd);
      assert.match(dragBranch, /const deadlineWithCleanup = \(\) => \{[\s\S]*dispatchCleanup\('dragend'[\s\S]*dispatchCleanup\('pointerup'[\s\S]*dispatchCleanup\('mouseup'/, 'firefox: expired synthetic drag can leave pointer or mouse state held');
      assert.match(dragBranch, /if \(!dispatch\('pointerdown'[\s\S]*pointerDown = true;[\s\S]*if \(!dispatch\('mousedown'[\s\S]*mouseDown = true;[\s\S]*if \(!dispatch\('dragstart'[\s\S]*dragStarted = true;/, 'firefox: synthetic drag cleanup does not track dispatched gesture state');
    }
    assert.match(branch, /!el\.isConnected \|\| !rect \|\| rect\.w < 1 \|\| rect\.h < 1/, `${label}: stale or zero-sized targets must fail before typing`);
     assert.match(branch, /if \(submit && verified\)/, `${label}: mismatched field values must not be submitted`);
     assert.match(branch, /addEventListener\('submit'/, `${label}: submit handling must observe actual submit events`);
     assert.match(branch, /outcomeUnknown: submissionOutcomeUnknown/, `${label}: unproven submissions must be surfaced as unknown`);
    assert.match(branch, /if \(!verified\) \{[\s\S]*return failure\(/, `${label}: mismatched field values must be explicit failed actions`);
    assert.match(branch, /dispatched\s*\?\s*\{ dispatched: true \}/, `${label}: post-dispatch verification failures must preserve action evidence`);
    assert.doesNotMatch(branch, /actual\.includes\(text\)/, `${label}: substring matches must not count as verified field values`);
  }
});

test('set_field submit chooses exactly one native or page-owned commit path', async () => {
  for (const [label, rel] of [
    ['chrome', 'src/chrome/src/content/content.js'],
    ['firefox', 'src/firefox/src/content/content.js'],
  ]) {
    const source = fs.readFileSync(path.join(ROOT, rel), 'utf8');

    // Pure boolean helper.
    const helperStart = source.indexOf('function _setFieldUsesNativeSubmit(');
    const helperEnd = source.indexOf('\n  }\n', helperStart) + 4;
    assert.ok(helperStart >= 0 && helperEnd > helperStart, `${label}: submit helper should remain independently testable`);
    const usesNativeSubmit = vm.runInNewContext(`(${source.slice(helperStart, helperEnd)})`);
    const formWithSubmit = { requestSubmit() {} };
    assert.equal(usesNativeSubmit(true, false, formWithSubmit), false, `${label}: combobox never uses native submit`);
    assert.equal(usesNativeSubmit(false, true, formWithSubmit), false, `${label}: contenteditable never uses native submit`);
    assert.equal(usesNativeSubmit(false, false, formWithSubmit), true, `${label}: plain field in a form uses native submit`);
    assert.equal(usesNativeSubmit(false, false, null), false, `${label}: form-less field does not use native submit`);
    assert.equal(usesNativeSubmit(false, false, {}), false, `${label}: form without requestSubmit does not use native submit`);

    // Behavioral slice of the submit block, run against stubs.
    const blockStart = source.indexOf('const dispatchKeySequence = (key, keyCode, includeKeypress = false) => {');
    const blockEnd = source.indexOf('\n            } catch {\n              submissionOutcomeUnknown = true;', blockStart);
    assert.ok(blockStart >= 0 && blockEnd > blockStart, `${label}: submit block not found`);
    const block = source.slice(blockStart, blockEnd);
    const runner = vm.runInNewContext(`async (stubs) => {
      const { el, msg, failure, isCombobox, _setFieldUsesNativeSubmit, _consumeMessageRecipientDispatchBinding, actionDeadlineExpired, deadlineFailure, ref_id, rect } = stubs;
      let nativeSubmitAttempted = false;
      let submissionOutcomeUnknown = true;
      let submissionDispatched = false;
      ${block}
      return { nativeSubmitAttempted, submissionOutcomeUnknown };
    }`, {
      setTimeout: callback => callback(),
      KeyboardEvent: class KeyboardEvent {
        constructor(type, init = {}) {
          this.type = type;
          Object.assign(this, init);
        }
      },
    });

    const exercise = async ({
      keydownCancelled = false,
      checkValidity = () => true,
      isCombobox = false,
      isContentEditable = false,
      hasForm = true,
      pageSubmitsOnKeydown = false,
      pageUsesDirectSubmitOnKeydown = false,
      submitCancelled = false,
      noValidate = false,
    } = {}) => {
      const calls = [];
      const submitListeners = [];
      const emitSubmit = () => {
        const event = { defaultPrevented: false };
        for (const listener of submitListeners) listener(event);
        if (submitCancelled) event.defaultPrevented = true;
      };
      const form = {
        requestSubmit: () => { calls.push('requestSubmit'); emitSubmit(); },
        checkValidity,
        noValidate,
        addEventListener: (type, listener) => { if (type === 'submit') submitListeners.push(listener); },
        removeEventListener: (type, listener) => {
          if (type === 'submit') {
            const index = submitListeners.indexOf(listener);
            if (index >= 0) submitListeners.splice(index, 1);
          }
        },
      };
      const el = {
        dispatchEvent: event => {
          calls.push(`${event.type}:${event.key}`);
          if (event.type === 'keydown' && event.key === 'Enter' && pageSubmitsOnKeydown) emitSubmit();
          if (event.type === 'keydown' && event.key === 'Enter' && pageUsesDirectSubmitOnKeydown) calls.push('form.submit');
          return !(keydownCancelled && event.type === 'keydown' && event.key === 'Enter');
        },
        form: hasForm ? form : null,
        closest: () => null,
        isContentEditable,
      };
      let failureResult = null;
      const failure = (msg, data) => { failureResult = data; return { success: false, ...data }; };
      const result = await runner({
        el,
        msg: { params: {} },
        failure,
        isCombobox,
        _setFieldUsesNativeSubmit: usesNativeSubmit,
        _consumeMessageRecipientDispatchBinding: () => ({ success: true }),
        actionDeadlineExpired: () => false,
        deadlineFailure: () => { throw new Error('unexpected deadline failure'); },
        ref_id: 'ref_1',
        rect: { x: 0, y: 0, w: 1, h: 1 },
      });
      return { calls, result, failureResult };
    };

    const plain = await exercise();
    assert.deepEqual(plain.calls, ['requestSubmit'], `${label}: plain form field must use only native submission`);
    assert.deepEqual({ ...plain.result }, { nativeSubmitAttempted: true, submissionOutcomeUnknown: false });
    assert.equal(plain.failureResult, null, `${label}: observed native submit must not fail`);

    const combobox = await exercise({ isCombobox: true, pageSubmitsOnKeydown: true });
    assert.deepEqual(combobox.calls, [
      'keydown:ArrowDown',
      'keyup:ArrowDown',
      'keydown:Enter',
      'keypress:Enter',
      'keyup:Enter',
    ], `${label}: combobox must use only its page-owned keyboard path`);
    assert.deepEqual({ ...combobox.result }, { nativeSubmitAttempted: true, submissionOutcomeUnknown: false });

    // form.submit() deliberately emits no submit event. The result remains
    // unknown, but the native fallback must still not repeat the action.
    const directSubmit = await exercise({ isCombobox: true, pageUsesDirectSubmitOnKeydown: true });
    assert.equal(directSubmit.calls.includes('form.submit'), true, `${label}: direct page submit was not exercised`);
    assert.equal(directSubmit.calls.includes('requestSubmit'), false, `${label}: unobserved page action must not trigger a second submit`);
    assert.deepEqual({ ...directSubmit.result }, { nativeSubmitAttempted: false, submissionOutcomeUnknown: true });

    const contenteditable = await exercise({ isContentEditable: true, keydownCancelled: true });
    assert.deepEqual(contenteditable.calls, ['keydown:Enter', 'keypress:Enter', 'keyup:Enter'], `${label}: contenteditable must stay on the keyboard path`);
    assert.deepEqual({ ...contenteditable.result }, { nativeSubmitAttempted: false, submissionOutcomeUnknown: true });

    // A page can cancel a submit event after observing it; that is not proof
    // that the consequential action reached the server.
    const cancelledSubmit = await exercise({ submitCancelled: true });
    assert.deepEqual(cancelledSubmit.calls, ['requestSubmit'], `${label}: cancelled native submit must not dispatch Enter`);
    assert.deepEqual({ ...cancelledSubmit.result }, { nativeSubmitAttempted: false, submissionOutcomeUnknown: true });

    const noValidate = await exercise({ noValidate: true, checkValidity: () => false });
    assert.deepEqual(noValidate.calls, ['requestSubmit'], `${label}: novalidate forms must still use native submission`);
    assert.deepEqual({ ...noValidate.result }, { nativeSubmitAttempted: true, submissionOutcomeUnknown: false });

    // Invalid form: surface the silent requestSubmit abort.
    const invalid = await exercise({ checkValidity: () => false });
    assert.deepEqual(invalid.calls, [], `${label}: invalid form must dispatch neither Enter nor requestSubmit`);
    assert.equal(invalid.failureResult?.submitted, false, `${label}: invalid form must fail with submitted:false`);
    assert.equal(invalid.failureResult?.invalid, true, `${label}: invalid form must flag invalid:true`);
  }
});

test('type_ax shares settled exact verification and explicit recovery contract', () => {
  for (const [label, rel] of [
    ['chrome', 'src/chrome/src/content/content.js'],
    ['firefox', 'src/firefox/src/content/content.js'],
  ]) {
    const source = fs.readFileSync(path.join(ROOT, rel), 'utf8');
    const branchStart = source.indexOf("'type_ax': async () => {");
    const branchEnd = source.indexOf("'set_field': async () => {", branchStart);
    assert.ok(branchStart >= 0 && branchEnd > branchStart, `${label}: type_ax handler should be bounded for regression checks`);
    const branch = source.slice(branchStart, branchEnd);
    const settleIndex = branch.indexOf('await new Promise(resolve => setTimeout(resolve, SET_FIELD_VERIFY_DELAY_MS))');
    const verifyIndex = branch.indexOf('_setFieldValueMatches(actual, previous, text');
    assert.ok(settleIndex >= 0 && verifyIndex > settleIndex, `${label}: type_ax must verify after page reconciliation`);
    const selectMutationIndex = branch.indexOf("method = 'type_ax_select'");
    const selectVerificationIndex = branch.indexOf('selectExpected !== null', settleIndex);
    assert.ok(selectMutationIndex >= 0 && selectMutationIndex < settleIndex, `${label}: select mutation should flow into the shared settle delay`);
    assert.ok(selectVerificationIndex > settleIndex, `${label}: select value must be compared exactly after reconciliation`);
    assert.doesNotMatch(
      branch.slice(selectMutationIndex, settleIndex),
      /return\s+\{\s*success:\s*true/,
      `${label}: select must not return verified success before settling`,
    );
    assert.match(branch, /verified: false[\s\S]*recoveryRequired: 'fresh_tree'/, `${label}: failed type_ax needs a fresh-tree recovery directive`);
    assert.match(branch, /success: true,[\s\S]*verified: true/, `${label}: successful type_ax must report verified:true`);
    assert.doesNotMatch(branch, /actual\.includes\(text\)/, `${label}: type_ax must not accept substring matches`);
    if (label === 'firefox') {
      assert.match(branch, /_retryFieldWithExecCommand/, 'firefox: type_ax should attempt the strongest in-page fallback');
    } else {
      assert.match(branch, /_expectedValue/, 'chrome: type_ax should preserve the exact expected value for its trusted background retry');
    }
  }
});

test('Chrome controlled-field fallback is ref-bound, trusted, verified, and submit-gated', () => {
  const agent = fs.readFileSync(path.join(ROOT, 'src/chrome/src/agent/agent.js'), 'utf8');
  const content = fs.readFileSync(path.join(ROOT, 'src/chrome/src/content/content.js'), 'utf8');
  const fallbackDeadlineStart = agent.indexOf('async _maybeFallbackFieldWithCdp(');
  const fallbackImplStart = agent.indexOf('async _maybeFallbackFieldWithCdpImpl(', fallbackDeadlineStart);
  assert.ok(fallbackDeadlineStart >= 0 && fallbackImplStart > fallbackDeadlineStart, 'chrome: trusted field retry deadline wrapper missing');
  const fallbackDeadlineSource = agent.slice(fallbackDeadlineStart, fallbackImplStart);
  assert.match(fallbackDeadlineSource, /this\._withContentActionDeadline\([\s\S]*this\._maybeFallbackFieldWithCdpImpl\([\s\S]*toolName/, 'chrome: trusted field retry pipeline bypasses the deadline');
  assert.match(fallbackDeadlineSource, /abortSignal =>[\s\S]*messageRecipientContext,[\s\S]*abortSignal/, 'chrome: trusted field retry deadline does not propagate cancellation');
  assert.match(fallbackDeadlineSource, /content_action_timeout[\s\S]*this\._contentActionTimeoutResult\(toolName, error\)/, 'chrome: trusted field retry timeout loses its unknown outcome');
  const fallbackImplEnd = agent.indexOf('async _resolveClickAxFallbackTarget(', fallbackImplStart);
  const fallbackImplSource = agent.slice(fallbackImplStart, fallbackImplEnd);
  assert.match(fallbackImplSource, /this\._throwIfAborted\(abortSignal\)[\s\S]*Input\.insertText[\s\S]*this\._throwIfAborted\(abortSignal\)[\s\S]*Input\.dispatchKeyEvent/, 'chrome: trusted field retry can continue mutating after cancellation');
  assert.match(agent, /_maybeFallbackFieldWithCdp[\s\S]*ax_prepare_field_for_trusted_type[\s\S]*Input\.insertText[\s\S]*ax_verify_field_value/, 'chrome: trusted field retry pipeline missing');
  assert.match(agent, /verification\.verified !== true[\s\S]*if \(toolName === 'set_field' && args\?\.submit === true\)/, 'chrome: submit must remain after trusted verification');
  assert.match(content, /'ax_prepare_field_for_trusted_type'[\s\S]*window\.__wb_ax_lookup\(ref_id\)[\s\S]*el\.select\(\)/, 'chrome: trusted retry must focus and select the ref-bound field');
  assert.match(content, /selectionMode === 'end'[\s\S]*range\.collapse\(false\)/, 'chrome: trusted contenteditable appends must preserve the existing DOM');
  assert.match(agent, /appendingContentEditable[\s\S]*args\?\.text[\s\S]*Input\.insertText/, 'chrome: trusted contenteditable appends must insert only the requested suffix');
  assert.match(content, /'ax_verify_field_value'[\s\S]*expectedPrefix[\s\S]*_setFieldValueMatches\(/, 'chrome: trusted retry must verify replacements and appends against their exact settled scope');
  for (const toolName of ['type_ax', 'set_field']) {
    const branchStart = content.indexOf(`'${toolName}': async () => {`);
    const branchEnd = toolName === 'type_ax'
      ? content.indexOf("'set_field': async () => {", branchStart)
      : content.indexOf("'ax_prepare_field_for_trusted_type':", branchStart);
    const branch = content.slice(branchStart, branchEnd);
    assert.match(branch, /el\.isContentEditable[\s\S]*trustedTypeRequired: true[\s\S]*_expectedValue/, `chrome: ${toolName} contenteditables must route through trusted typing`);
    assert.doesNotMatch(branch, /document\.execCommand\('insertText'/, `chrome: ${toolName} must not accept synthetic contenteditable DOM text as verified input`);
  }
});

test('Chrome controlled-field fallback timeout preserves an unknown mutation outcome', async () => {
  const originalChrome = globalThis.chrome;
  const originalAttach = cdpClientCh.attach;
  const originalSendCommand = cdpClientCh.sendCommand;
  try {
    let releasePreparation;
    let markPreparationStarted;
    const preparationStarted = new Promise(resolve => { markPreparationStarted = resolve; });
    const delayedPreparation = new Promise(resolve => { releasePreparation = resolve; });
    globalThis.chrome = {
      tabs: {
        async sendMessage(_tabId, message) {
          assert.equal(message.action, 'ax_prepare_field_for_trusted_type');
          markPreparationStarted();
          return delayedPreparation;
        },
      },
    };
    let cdpMutations = 0;
    cdpClientCh.attach = async () => {
      cdpMutations += 1;
      return { attached: true };
    };
    cdpClientCh.sendCommand = async () => {
      cdpMutations += 1;
      return {};
    };

    const agent = new AgentCh({});
    let deadlineTool = '';
    agent._withContentActionDeadline = async (operation, toolName) => {
      deadlineTool = toolName;
      const error = new Error(`${toolName} did not return a page response within 60 seconds.`);
      error.code = 'content_action_timeout';
      const controller = new AbortController();
      const started = Promise.resolve().then(() => operation(controller.signal));
      await preparationStarted;
      controller.abort(error);
      releasePreparation({
        success: true,
        fieldMeta: { type: 'text', contentEditable: false },
        contentEditable: false,
      });
      await assert.rejects(started, candidate => candidate === error);
      throw error;
    };

    const result = await agent._maybeFallbackFieldWithCdp(
      42,
      'set_field',
      { ref_id: 'ref_timeout', text: 'updated value' },
      {
        success: false,
        verified: false,
        _expectedValue: 'updated value',
        recoveryRequired: 'fresh_tree',
      },
    );

    assert.equal(deadlineTool, 'set_field');
    assert.equal(result.success, false);
    assert.equal(result.dispatched, true);
    assert.equal(result.outcomeUnknown, true);
    assert.equal(result.retryable, false);
    assert.equal(cdpMutations, 0, 'late field preparation reached trusted CDP mutation after timeout');
    assert.match(result.error, /may have reached the page.*inspect the current state/i);
  } finally {
    cdpClientCh.attach = originalAttach;
    cdpClientCh.sendCommand = originalSendCommand;
    if (originalChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = originalChrome;
  }
});

test('Chrome controlled-field fallback recovers exactly once and never submits a mismatch', async () => {
  const originalChrome = globalThis.chrome;
  const originals = {
    attach: cdpClientCh.attach,
    sendCommand: cdpClientCh.sendCommand,
  };
  try {
    const commands = [];
    let verified = true;
    let recipientValid = true;
    let contentEditable = false;
    let prepareCalls = 0;
    const prepareSelectionModes = [];
    globalThis.chrome = {
      tabs: {
        async sendMessage(_tabId, message) {
          if (message.action === 'ax_prepare_field_for_trusted_type') {
            prepareCalls += 1;
            prepareSelectionModes.push(message.params.selectionMode);
            return {
              success: true,
              fieldMeta: { type: contentEditable ? 'div' : 'text', contentEditable },
              isCombobox: false,
              contentEditable,
              ...(contentEditable ? { rect: { x: 10, y: 20, w: 300, h: 80 } } : {}),
            };
          }
          if (message.action === 'ax_verify_field_value') {
            return {
              success: true,
              verified,
              actual: verified ? message.params.expected : '',
              fieldMeta: { type: 'text' },
            };
          }
          if (message.action === 'consume_message_recipient_dispatch_binding') {
            return recipientValid
              ? { success: true, matched: true }
              : {
                  success: false,
                  reasonCode: 'active_recipient_changed_before_dispatch',
                  error: 'active conversation changed',
                };
          }
          throw new Error(`unexpected action ${message.action}`);
        },
      },
    };
    cdpClientCh.attach = async () => ({ attached: true });
    cdpClientCh.sendCommand = async (_tabId, method, params) => {
      commands.push({ method, params });
      return {};
    };

    const agent = new AgentCh({});
    const recovered = await agent._maybeFallbackFieldWithCdp(
      42,
      'set_field',
      { ref_id: 'ref_search', text: 'gary flake', submit: true },
      {
        success: false,
        verified: false,
        error: 'controlled input reset',
        _expectedValue: 'gary flake',
        recoveryRequired: 'fresh_tree',
      },
    );
    assert.equal(recovered.success, true);
    assert.equal(recovered.verified, true);
    assert.equal(recovered.trustedFallback, true);
    assert.equal(recovered.submitted, true);
    assert.deepEqual(
      commands.map(command => [command.method, command.params?.text || command.params?.key]),
      [
        ['Input.insertText', 'gary flake'],
        ['Input.dispatchKeyEvent', 'Enter'],
        ['Input.dispatchKeyEvent', 'Enter'],
      ],
      'trusted text must settle before Enter is dispatched',
    );

    commands.length = 0;
    recipientValid = false;
    const recipientRace = await agent._maybeFallbackFieldWithCdp(
      42,
      'set_field',
      { ref_id: 'ref_search', text: 'gary flake', submit: true },
      {
        success: false,
        verified: false,
        error: 'controlled input reset',
        _expectedValue: 'gary flake',
        recoveryRequired: 'fresh_tree',
      },
      {
        messageRecipientGuardRequired: true,
        messageRecipientDispatchBinding: { token: 'recipient-race' },
      },
    );
    assert.equal(recipientRace.success, false);
    assert.equal(recipientRace.messageDispatched, false);
    assert.equal(recipientRace.reasonCode, 'active_recipient_changed_before_dispatch');
    assert.equal(commands.some(command => command.method === 'Input.insertText'), true, 'field typing should remain visible');
    assert.equal(commands.some(command => command.params?.key === 'Enter'), false, 'recipient race must stop before Enter');
    recipientValid = true;

    commands.length = 0;
    contentEditable = true;
    prepareCalls = 0;
    prepareSelectionModes.length = 0;
    const recoveredEditor = await agent._maybeFallbackFieldWithCdp(
      42,
      'set_field',
      { ref_id: 'ref_editor', text: 'exact post', submit: false },
      {
        success: false,
        verified: false,
        dispatched: false,
        noDispatch: true,
        trustedTypeRequired: true,
        error: 'contenteditable requires trusted typing',
        _expectedValue: 'exact post',
      },
    );
    assert.equal(recoveredEditor.success, true);
    assert.equal(recoveredEditor.trusted, true);
    assert.equal(recoveredEditor.dispatched, true);
    assert.equal(recoveredEditor.noDispatch, undefined);
    assert.equal(recoveredEditor.trustedTypeRequired, undefined);
    assert.equal(prepareCalls, 2, 'contenteditable trusted focus must be followed by ref-bound reselection');
    assert.deepEqual(prepareSelectionModes, ['all', 'all'], 'contenteditable replacement must select all on both preparations');
    assert.deepEqual(
      commands.map(command => command.method),
      [
        'Input.dispatchMouseEvent',
        'Input.dispatchMouseEvent',
        'Input.dispatchMouseEvent',
        'Input.insertText',
      ],
      'contenteditable recovery must use trusted focus followed by trusted text insertion',
    );

    commands.length = 0;
    prepareCalls = 0;
    prepareSelectionModes.length = 0;
    const recoveredAppend = await agent._maybeFallbackFieldWithCdp(
      42,
      'type_ax',
      { ref_id: 'ref_editor', text: '\n\nclosing', clear: false },
      {
        success: false,
        verified: false,
        dispatched: false,
        noDispatch: true,
        trustedTypeRequired: true,
        error: 'contenteditable requires trusted typing',
        _expectedValue: 'existing\n\nclosing',
      },
    );
    assert.equal(recoveredAppend.success, true);
    assert.equal(recoveredAppend.verified, true);
    assert.equal(prepareCalls, 2);
    assert.deepEqual(prepareSelectionModes, ['end', 'end'], 'contenteditable append must collapse at the end on both preparations');
    assert.deepEqual(
      commands.filter(command => command.method === 'Input.insertText').map(command => command.params.text),
      ['\n\nclosing'],
      'contenteditable append must not retype the existing editor value',
    );

    commands.length = 0;
    verified = false;
    const failedEditor = await agent._maybeFallbackFieldWithCdp(
      42,
      'set_field',
      { ref_id: 'ref_editor', text: 'exact post', submit: false },
      {
        success: false,
        verified: false,
        dispatched: false,
        noDispatch: true,
        trustedTypeRequired: true,
        error: 'contenteditable requires trusted typing',
        _expectedValue: 'exact post',
      },
    );
    assert.equal(failedEditor.success, false);
    assert.equal(failedEditor.verified, false);
    assert.equal(failedEditor.dispatched, true, 'a failed readback must preserve the trusted input dispatch');
    assert.equal(failedEditor.noDispatch, false, 'trusted contenteditable input must not remain retry-safe');
    assert.equal(failedEditor.recoveryRequired, 'fresh_tree');
    assert.equal(commands.filter(command => command.method === 'Input.insertText').length, 1, 'only one trusted editor retry is allowed');

    commands.length = 0;
    contentEditable = false;
    const failed = await agent._maybeFallbackFieldWithCdp(
      42,
      'set_field',
      { ref_id: 'ref_search', text: 'gary flake', submit: true },
      {
        success: false,
        verified: false,
        error: 'controlled input reset',
        _expectedValue: 'gary flake',
        recoveryRequired: 'fresh_tree',
      },
    );
    assert.equal(failed.success, false);
    assert.equal(failed.verified, false);
    assert.equal(failed.recoveryRequired, 'fresh_tree');
    assert.equal(commands.filter(command => command.method === 'Input.insertText').length, 1, 'only one trusted retry is allowed');
    assert.equal(commands.some(command => command.params?.key === 'Enter'), false, 'a mismatched field must never submit');
  } finally {
    cdpClientCh.attach = originals.attach;
    cdpClientCh.sendCommand = originals.sendCommand;
    if (originalChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = originalChrome;
  }
});

test('click_ax rejects stale zero-sized targets before activation', () => {
  for (const [label, rel] of [
    ['chrome', 'src/chrome/src/content/content.js'],
    ['firefox', 'src/firefox/src/content/content.js'],
  ]) {
    const source = fs.readFileSync(path.join(ROOT, rel), 'utf8');
    const branchStart = source.search(/'click_ax': (?:async )?\(\) => \{/);
    const branchEnd = source.indexOf("'type_ax':", branchStart);
    assert.ok(branchStart >= 0 && branchEnd > branchStart, `${label}: click_ax handler should be bounded for regression checks`);
    const branch = source.slice(branchStart, branchEnd);
    const staleGuard = branch.indexOf('!el.isConnected || rect.width < 1 || rect.height < 1');
    const activation = branch.indexOf('el.click()');
    assert.ok(staleGuard >= 0 && activation > staleGuard, `${label}: zero-sized AX targets must be rejected before click activation`);
    assert.match(branch, /return failure\([\s\S]*stale or not visibly rendered[\s\S]*Re-read the accessibility tree/, `${label}: stale click errors should direct the agent to refresh refs`);
    assert.match(branch, /dispatched: false, noDispatch: true, fallbackAttempted: false/, `${label}: pre-click stale failures must remain safe for agent fallback`);
  }
});

test('submit detector source covers submit controls, Enter, set_field, iframes, and execute_js', () => {
  for (const [label, rel] of [
    ['chrome', 'src/chrome/src/agent/agent.js'],
    ['firefox', 'src/firefox/src/agent/agent.js'],
  ]) {
    const agent = fs.readFileSync(path.join(ROOT, rel), 'utf8');
    assert.match(agent, /static _submitActionProbe/, `${label}: submit probe missing`);
    assert.match(agent, /static _submitActionProbe = function _submitActionProbe/, `${label}: submit probe should serialize as a standalone function expression`);
    assert.match(agent, /input\[type="submit"\]/, `${label}: click target resolver should include input[type=submit]`);
    assert.match(agent, /tag === 'input'[\s\S]*type === 'submit'/, `${label}: submit detector should catch input[type=submit]`);
    assert.match(agent, /tag === 'button'[\s\S]*!type \|\| type === 'submit'/, `${label}: submit detector should catch default form buttons`);
    assert.match(agent, /tag === 'input'[\s\S]*type === 'button'/, `${label}: JS-driven input buttons inside forms should fail closed as submit candidates`);
    assert.match(agent, /tag === 'button'[\s\S]*type === 'button'/, `${label}: JS-driven form buttons should fail closed as submit candidates`);
    assert.match(agent, /\[role="button"\],\[onclick\],\[data-action\]/, `${label}: non-native form controls should be considered submit candidates`);
    assert.match(agent, /const hasActivationHandler = candidate\.hasAttribute\?\.\('onclick'\) \|\| candidate\.hasAttribute\?\.\('data-action'\)/, `${label}: handler-backed form controls should fail closed`);
    assert.match(agent, /role === 'button' \|\| hasActivationHandler/, `${label}: role button and handler-backed form controls should fail closed`);
    assert.match(agent, /name === 'set_field' && !args\?\.submit/, `${label}: set_field({submit:true}) precheck missing`);
    assert.match(agent, /set_field\(\{submit:true\}\)/, `${label}: set_field submit reason missing`);
    assert.match(agent, /Enter key in a form field/, `${label}: Enter-in-form-field detection missing`);
    assert.match(agent, /Enter key on a submit button\/control/, `${label}: Enter-on-focused-submit detection missing`);
    assert.match(agent, /toolName === 'press_keys'[\s\S]*isSubmitControl\(target\)[\s\S]*Enter key on a submit button\/control[\s\S]*isFormField\(target\)/, `${label}: focused submit controls should be checked before form fields for Enter`);
    assert.match(agent, /name === 'iframe_click' \|\| name === 'press_keys'/, `${label}: iframe/all-frame probing missing`);
    assert.match(agent, /allFrames/, `${label}: iframe equivalent submit checks should use allFrames`);
    assert.doesNotMatch(agent, /name === 'execute_js' && !this\._executeJsLooksLikeFormSubmit/, `${label}: execute_js should not depend on incomplete static submit regexes`);
    assert.match(agent, /if \(name === 'execute_js'\) \{[\s\S]*execute_js can run page JavaScript/, `${label}: execute_js should fail closed before generic execute_js grants`);
    assert.match(agent, /JavaScript execution can trigger form submission through dynamic code/, `${label}: execute_js submit confirmation summary missing`);
    assert.match(agent, /__wb_resolve_click_target_for_submit_probe/, `${label}: submit probe should reuse content click-index resolver when available`);
    assert.match(agent, /const deepQuerySelector = \(root, selector\)/, `${label}: selector submit probing should pierce open shadow roots`);
    assert.match(agent, /return deepQuerySelector\(doc, args\.selector\)/, `${label}: selector submit probing should use the deep selector resolver`);
    assert.match(agent, /const safeQuerySelector = \(root, selector\)/, `${label}: selector submit probing should use the safe selector fallback`);
    assert.match(agent, /selector\.startsWith\('#'\)[\s\S]*const rawId = selector\.slice\(1\)\.replace[\s\S]*root\.getElementById\(rawId\)/, `${label}: safe selector fallback should handle bare ID selectors`);
    assert.match(agent, /rawId\.replace\([\s\S]*\/"\/g[\s\S]*\)/, `${label}: safe selector fallback should escape quotes and backslashes`);
    assert.match(agent, /root\.querySelector\(`(?:#\$\{CSS\.escape\(rawId\)\}|\[id="\$\{(?:rawId\.replace|escapedRawId))/, `${label}: safe selector fallback should retry ID selectors`);
    assert.match(agent, /const escaped = selector\.replace[\s\S]*return root\.querySelector\(escaped\)/, `${label}: safe selector fallback should retry escaped colons`);
    assert.match(agent, /const labelControlFor = \(el\) => \{[\s\S]*String\(el\.tagName \|\| ''\)\.toUpperCase\(\) !== 'LABEL'[\s\S]*el\.htmlFor[\s\S]*doc\.getElementById\(el\.htmlFor\)[\s\S]*button,input,textarea,select/, `${label}: submit probe should resolve labels to associated controls`);
    assert.match(agent, /const target = labelControlFor\(el\) \|\| el;[\s\S]*const candidate = target\.closest\?\.\('button,input,\[role="button"\],\[onclick\],\[data-action\]'\)/, `${label}: submit-control detection should inspect label-backed controls`);
    assert.match(agent, /const submitControlEvidence = \(el\) => \{/, `${label}: custom submit controls should classify preflight evidence strength`);
    assert.match(agent, /const submitInfo = \(form, reason, pendingEl = null, pendingValue = null, validationSubmitEvidence = 'strong'\)/, `${label}: submit summaries should carry preflight evidence strength`);
    assert.match(agent, /evidence\.strong \? 'strong' : 'heuristic'/, `${label}: custom submit probes should label strong and heuristic evidence`);
    assert.match(agent, /detected\.validationSubmitEvidence === 'strong' \? 'strong' : 'heuristic'/, `${label}: submit evidence strength should survive page-probe normalization`);
    assert.match(agent, /const findTopmostModal = \(\) => \{[\s\S]*dialog\[open\][\s\S]*\[role="dialog"\]\[aria-modal="true"\][\s\S]*\[class\*="DialogOverlay"\]/, `${label}: text submit probing should mirror modal scoping`);
    assert.match(agent, /Array\.from\(\(findTopmostModal\(\) \|\| doc\)\.querySelectorAll/, `${label}: text submit probing should search inside the topmost modal when present`);
  }
});

test('submit detector redacts pending password values before summaries', () => {
  for (const [label, rel] of [
    ['chrome', 'src/chrome/src/agent/agent.js'],
    ['firefox', 'src/firefox/src/agent/agent.js'],
  ]) {
    const agent = fs.readFileSync(path.join(ROOT, rel), 'utf8');
    const fieldValueStart = agent.indexOf('const fieldValue = (el, pendingEl = null, pendingValue = null) => {');
    assert.notEqual(fieldValueStart, -1, `${label}: fieldValue helper missing`);
    const fieldValueEnd = agent.indexOf('const defaultValue = (el) => {', fieldValueStart);
    const fieldValueBody = agent.slice(fieldValueStart, fieldValueEnd);
    const passwordIdx = fieldValueBody.indexOf("if (type === 'password') return '[password redacted]'");
    const pendingIdx = fieldValueBody.indexOf('if (pendingEl && el === pendingEl)');
    assert.ok(passwordIdx !== -1, `${label}: password redaction missing`);
    assert.ok(pendingIdx !== -1, `${label}: pending value handling missing`);
    assert.ok(passwordIdx < pendingIdx, `${label}: password fields must redact before pending set_field text is substituted`);
  }
});

