test('plan before act: try is default while explicit off is preserved', () => {
  for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
    const agent = new AgentClass({});
    assert.equal(agent.planBeforeActMode, 'try', `${label} default mode`);
    assert.equal(agent.planBeforeAct, true, `${label} legacy mirror default`);
    assert.equal(agent._plannerMode(), 'try', `${label} effective default mode`);
    assert.equal(agent.planReviewMode, 'confidence', `${label} default plan review mode`);
    assert.equal(agent.planReviewConfidenceThreshold, 0.75, `${label} default plan review threshold`);
    assert.equal(agent._shouldReviewPlan({ confidence: 0.74 }), true, `${label} default below-threshold plans should review`);
    assert.equal(agent._shouldReviewPlan({ confidence: 0.75 }), false, `${label} default at-threshold plans should auto-approve`);
    agent.setPlanReviewSettings({ mode: 'always', confidenceThreshold: 95 });
    assert.equal(agent.planReviewMode, 'always', `${label} review mode setter`);
    assert.equal(agent.planReviewConfidenceThreshold, 0.95, `${label} review threshold percent setter`);
    assert.equal(agent._shouldReviewPlan({ confidence: 1 }), true, `${label} always mode should review high-confidence plans`);
    agent.setPlanReviewSettings({ mode: 'never', confidenceThreshold: 0.9 });
    assert.equal(agent._shouldReviewPlan({ confidence: 0.1 }), false, `${label} never mode should auto-approve low-confidence plans`);
    agent.setPlanReviewSettings({ mode: 'confidence', confidenceThreshold: 0.9 });
    assert.equal(agent._shouldReviewPlan({ confidence: 0.89 }), true, `${label} below-threshold plans should review`);
    assert.equal(agent._shouldReviewPlan({ confidence: 0.9 }), false, `${label} at-threshold plans should auto-approve`);
    agent.setPlanReviewSettings({ confidenceThreshold: 0 });
    assert.equal(agent.planReviewConfidenceThreshold, 0.5, `${label} out-of-band low threshold clamps to the slider floor`);
    agent.setPlanReviewSettings({ confidenceThreshold: 1 });
    assert.equal(agent.planReviewConfidenceThreshold, 0.99, `${label} out-of-band high threshold clamps to the slider ceiling`);
    agent.setPlanReviewSettings({ confidenceThreshold: 0.9 });
    agent.setPlanBeforeActMode('try');
    assert.equal(agent.planBeforeAct, true, `${label} try enables legacy mirror`);
    assert.equal(agent._plannerMode(), 'try', `${label} try mode`);
    agent.setPlanBeforeActMode('strict');
    assert.equal(agent.planBeforeAct, true, `${label} strict enables legacy mirror`);
    assert.equal(agent._plannerMode(), 'strict', `${label} strict mode`);
    agent.setPlanBeforeActMode('off');
    assert.equal(agent.planBeforeAct, false, `${label} off disables legacy mirror`);
    assert.equal(agent._plannerMode(), 'off', `${label} off mode`);
  }
  for (const file of [
    'src/chrome/src/background.js',
    'src/firefox/src/background.js',
    'src/chrome/src/ui/settings.js',
    'src/firefox/src/ui/settings.js',
  ]) {
    const source = fs.readFileSync(path.join(ROOT, file), 'utf8');
    assert.match(source, /planBeforeActMode/, `${file} should use the planner mode setting`);
    assert.match(source, /return 'try'/, `${file} should treat unset storage as planning try`);
    assert.match(source, /planBeforeAct(?:Mode)?[^]*?=== false[^]*?return 'off'/, `${file} should preserve explicit legacy off storage`);
    assert.match(source, /planBeforeAct(?:Mode)?[^]*?=== true[^]*?return 'strict'/, `${file} should migrate legacy enabled storage to strict`);
  }
  for (const file of [
    'src/chrome/src/background.js',
    'src/firefox/src/background.js',
    'src/chrome/src/ui/settings.js',
    'src/firefox/src/ui/settings.js',
  ]) {
    const source = fs.readFileSync(path.join(ROOT, file), 'utf8');
    assert.match(source, /planReviewMode/, `${file} should persist the plan review mode setting`);
    assert.match(source, /planReviewConfidenceThreshold/, `${file} should persist the plan review confidence threshold`);
  }
  for (const file of [
    'src/chrome/src/ui/settings.html',
    'src/firefox/src/ui/settings.html',
  ]) {
    const html = fs.readFileSync(path.join(ROOT, file), 'utf8');
    assert.match(html, /<select id="select-plan-before-act-mode">\s*<option value="try"/, `${file} should render try as the first/default option`);
    assert.match(html, /<select id="select-plan-review-mode">\s*<option value="confidence"/, `${file} should render confidence review as the first/default option`);
    assert.match(html, /id="range-plan-review-confidence"/, `${file} should expose the confidence threshold slider`);
    assert.match(html, /id="range-plan-review-confidence"[^>]*value="75"/, `${file} should render the 75% default threshold`);
  }
  for (const file of [
    'src/chrome/src/ui/locales/en.js',
    'src/firefox/src/ui/locales/en.js',
  ]) {
    const locale = fs.readFileSync(path.join(ROOT, file), 'utf8');
    assert.match(locale, /Try \(default\).*may reuse a recently approved plan for a short follow-up/, `${file} should describe try planning as the default with short-follow-up reuse`);
    assert.match(locale, /Try retries once, then continues in Act with a warning if intent or planning is still invalid; Strict stops before tools/, `${file} should describe the two-attempt Act continuation`);
    assert.match(locale, /'st\.display\.plan_before_act\.try': 'Try planning \(default\)'/, `${file} should label try planning as default`);
    assert.match(locale, /'st\.display\.plan_before_act\.off': 'Off'/, `${file} should not label off as default`);
    assert.doesNotMatch(locale, /plan_before_act\.desc[^\n]*Off by default/, `${file} should not describe plan-before-act as off by default`);
    assert.doesNotMatch(locale, /plan_before_act\.off': 'Off \(default\)'/, `${file} should not mark off as default`);
  }
});

test('Chrome Web Store release uses an always-on protected-page guard and opt-in trusted skill tools', async () => {
  const dashboard = 'https://chrome.google.com/webstore/devconsole/f4a5b26f-27fe-4bc4-ad37-203b236e337c';
  const reviews = 'https://chromewebstore.google.com/detail/webbrain/ljhijonmfahplgbbacgcfnaihbjljhhb/reviews';
  assert.equal(chromeProtectedPageForUrl(dashboard), 'chrome-web-store-developer');
  assert.equal(chromeProtectedPageForUrl('https://chrome.google.com/webstore/devconsole?hl=en'), 'chrome-web-store-developer');
  assert.equal(chromeProtectedPageForUrl('https://chrome.google.com/webstore/devconsole#published'), 'chrome-web-store-developer');
  assert.equal(chromeProtectedPageForUrl(reviews), 'chrome-web-store-gallery');
  assert.equal(chromeProtectedPageForUrl('https://chromewebstore.google.com/'), 'chrome-web-store-gallery');
  assert.equal(chromeProtectedPageForUrl('http://chromewebstore.google.com/detail/example'), '');
  assert.equal(chromeProtectedPageForUrl('https://chromewebstore.google.com.evil.example/detail/example'), '');
  assert.equal(chromeProtectedPageForUrl('https://example.com/?next=https://chrome.google.com/webstore/devconsole'), '');
  const failure = chromeProtectedPageFailure(dashboard, 'get_accessibility_tree');
  assert.equal(failure.errorCode, 'chrome_protected_page');
  assert.equal(failure.nonRetryable, true);
  assert.equal(failure.dispatched, false);
  assert.equal(failure.recoverySkill, undefined);
  assert.match(failure.error, /Do not retry/i);
  assert.match(failure.error, /Continue manually/i);
  assert.doesNotMatch(failure.error, /enable.*Chrome Web Store release|Settings → Skills/i);
  const galleryFailure = chromeProtectedPageFailure(reviews, 'get_accessibility_tree');
  assert.equal(galleryFailure.errorCode, 'chrome_protected_page');
  assert.equal(galleryFailure.nonRetryableScope, 'chrome-protected-page:chrome-web-store-gallery');
  assert.equal(galleryFailure.recoveryTool, 'inspect_viewport');
  assert.match(galleryFailure.error, /vision-enabled screenshot may be used once/i);
  const chromeAgentRoutingSource = fs.readFileSync(path.join(ROOT, 'src/chrome/src/agent/agent.js'), 'utf8');
  assert.doesNotMatch(chromeAgentRoutingSource, /ask the user to enable\/configure that packaged skill/i, 'chrome: runtime warning must not route users to a removed packaged skill');
  for (const file of ['src/chrome/src/agent/adapters.js', 'src/firefox/src/agent/adapters.js']) {
    const adapterSource = fs.readFileSync(path.join(ROOT, file), 'utf8');
    assert.doesNotMatch(adapterSource, /ask the user to enable "Chrome Web Store release"/i, `${file}: adapter must not route users to a removed packaged skill`);
    assert.match(adapterSource, /Continue manually in the dashboard; no packaged release skill is available/i, `${file}: adapter should provide an available fallback`);
  }
  for (const toolName of ['wait_for_stable', 'get_accessibility_tree', 'read_page', 'click_ax', 'upload_file', 'download_resource_from_page', 'execute_js', 'get_frames']) {
    assert.equal(isChromeProtectedPageDomTool(toolName), true, `chrome: ${toolName} should be stopped before protected-page dispatch`);
  }
  assert.equal(isChromeProtectedPageDomTool('download_files'), false, 'chrome: direct URL downloads should remain available without page DOM');
  assert.equal(isChromeProtectedPageDomTool('screenshot'), false, 'chrome: screenshots remain an optional read-only fallback');
  assert.equal(isChromeProtectedPageDomTool('chrome_web_store_status'), false, 'chrome: trusted release tools must bypass the DOM guard');

  for (const [label, prefix, normalize, buildDefinitions, buildRegistry, runtime] of [
    ['chrome', 'src/chrome', normalizeCustomSkillsCh, buildSkillToolDefinitionsCh, buildSkillToolRegistryCh, ChromeWebStoreReleaseCh],
    ['firefox', 'src/firefox', normalizeCustomSkillsFx, buildSkillToolDefinitionsFx, buildSkillToolRegistryFx, ChromeWebStoreReleaseFx],
  ]) {
    const record = packagedChromeWebStoreRecord(prefix);
    const normalized = normalize([record]);
    assert.equal(normalized.length, 1, `${label}: packaged release skill should normalize`);
    assert.deepEqual(normalized[0].tools.map((tool) => tool.name), [
      'chrome_web_store_status',
      'chrome_web_store_upload',
      'chrome_web_store_publish',
    ], `${label}: exact built-in release skill should receive all trusted tools`);
    assert.equal(normalized[0].tools.every((tool) => tool.kind === 'chromeWebStore'), true, `${label}: release tools should use the trusted built-in kind`);

    const rawSpoof = normalize([{ ...record, sourceType: 'text', sourceUrl: '' }]);
    assert.equal(rawSpoof[0].tools.length, 0, `${label}: raw/imported text must not acquire privileged release handlers`);
    const normalizedRecordSpoof = normalize([{ ...normalized[0], sourceType: 'text', sourceUrl: '' }]);
    assert.equal(normalizedRecordSpoof[0].tools.length, 0, `${label}: persisted privileged tool objects must not survive without exact built-in provenance`);

    const askNames = buildDefinitions(normalized, { mode: 'ask', tier: 'full' }).map((tool) => tool.function.name);
    const actNames = buildDefinitions(normalized, { mode: 'act', tier: 'full' }).map((tool) => tool.function.name);
    assert.deepEqual(askNames, ['chrome_web_store_status'], `${label}: Ask should expose only the read-only status tool`);
    assert.deepEqual(actNames, ['chrome_web_store_status', 'chrome_web_store_upload', 'chrome_web_store_publish'], `${label}: Act should expose the full release workflow`);

    const registry = buildRegistry(normalized);
    const statusTool = registry.get('chrome_web_store_status');
    const uploadTool = registry.get('chrome_web_store_upload');
    const publishTool = registry.get('chrome_web_store_publish');
    assert.equal(runtime.isTrustedChromeWebStoreSkillTool(statusTool), true, `${label}: registry should retain the trusted skill provenance`);

    const storageData = {
      [runtime.CHROME_WEB_STORE_CONFIG_KEY]: {
        publisherId: 'f4a5b26f-27fe-4bc4-ad37-203b236e337c',
        itemId: 'abcdefghijklmnopabcdefghijklmnop',
      },
      [runtime.CHROME_WEB_STORE_PACKAGE_KEY]: {
        name: 'webbrain-25.4.2.zip',
        size: 3,
        sha256: 'abc123',
        base64: btoa('zip'),
      },
    };
    const storage = { get: async () => structuredClone(storageData) };
    const calls = [];
    const fetchImpl = async (url, init) => {
      calls.push({ url, init });
      const result = url.endsWith(':fetchStatus')
        ? { itemId: storageData[runtime.CHROME_WEB_STORE_CONFIG_KEY].itemId, publishedItemRevisionStatus: { state: 'OK' } }
        : url.endsWith(':upload')
          ? { uploadState: 'SUCCEEDED', crxVersion: '25.4.2' }
          : { state: 'PENDING_REVIEW' };
      return { ok: true, status: 200, text: async () => JSON.stringify(result) };
    };
    const opts = { storage, fetchImpl, accessToken: 'test-token' };
    const status = await runtime.executeChromeWebStoreSkillTool(statusTool, {}, opts);
    const upload = await runtime.executeChromeWebStoreSkillTool(uploadTool, {}, opts);
    const publish = await runtime.executeChromeWebStoreSkillTool(publishTool, { publish_type: 'staged', deploy_percentage: 25 }, opts);
    const invalidPublish = await runtime.executeChromeWebStoreSkillTool(publishTool, { publish_type: 'stage' }, opts);
    assert.equal(status.success, true, `${label}: status should execute`);
    assert.equal(status.dispatched, false, `${label}: status is read-only`);
    assert.equal(upload.success, true, `${label}: upload should execute`);
    assert.equal(upload.package.name, 'webbrain-25.4.2.zip', `${label}: upload should return metadata only`);
    assert.equal(JSON.stringify(upload).includes('emlw'), false, `${label}: upload result must not contain ZIP base64`);
    assert.equal(publish.success, true, `${label}: publish should execute`);
    assert.equal(invalidPublish.success, false, `${label}: an unknown publish type must fail closed`);
    assert.equal(invalidPublish.noDispatch, true, `${label}: an unknown publish type must not dispatch`);
    assert.match(invalidPublish.error, /publish_type/, `${label}: invalid publish type should identify the bad argument`);
    assert.equal(calls.length, 3, `${label}: invalid publish type must not send an API request`);
    assert.equal(calls[0].url.endsWith(':fetchStatus'), true, `${label}: status endpoint mismatch`);
    assert.equal(calls[1].url.includes('/upload/v2/publishers/'), true, `${label}: upload endpoint mismatch`);
    assert.equal(calls[1].init.body instanceof Uint8Array, true, `${label}: upload should send binary bytes`);
    assert.deepEqual(JSON.parse(calls[2].init.body), {
      publishType: 'STAGED_PUBLISH',
      blockOnWarnings: true,
      deployInfos: [{ deployPercentage: 25 }],
    }, `${label}: publish body should be warning-blocking and preserve explicit rollout`);

    const preDispatchFailure = await runtime.executeChromeWebStoreSkillTool(uploadTool, {}, {
      storage,
      fetchImpl: {},
      accessToken: 'test-token',
    });
    assert.equal(preDispatchFailure.success, false, `${label}: unavailable fetch should fail`);
    assert.equal(preDispatchFailure.dispatched, false, `${label}: pre-dispatch setup failure was marked dispatched`);
    assert.equal(preDispatchFailure.noDispatch, true, `${label}: pre-dispatch setup failure should avoid completion debt`);
    assert.notEqual(preDispatchFailure.outcomeUnknown, true, `${label}: pre-dispatch setup failure should not be ambiguous`);

    let ambiguousAttempts = 0;
    const ambiguousFailure = await runtime.executeChromeWebStoreSkillTool(uploadTool, {}, {
      storage,
      fetchImpl: async () => {
        ambiguousAttempts += 1;
        throw new Error('connection reset');
      },
      accessToken: 'test-token',
    });
    assert.equal(ambiguousAttempts, 1, `${label}: ambiguous upload should attempt fetch once`);
    assert.equal(ambiguousFailure.success, false, `${label}: rejected upload fetch should fail`);
    assert.equal(ambiguousFailure.dispatched, true, `${label}: post-dispatch failure lost its dispatch marker`);
    assert.equal(ambiguousFailure.outcomeUnknown, true, `${label}: post-dispatch failure should remain ambiguous`);
    assert.notEqual(ambiguousFailure.noDispatch, true, `${label}: ambiguous upload must retain completion debt`);

    const warningSecret = 'opaque_validation_token_abcdefghijklmnopqrstuvwxyz0123456789';
    const warningFailure = await runtime.executeChromeWebStoreSkillTool(publishTool, {}, {
      storage,
      fetchImpl: async () => ({
        ok: false,
        status: 400,
        text: async () => JSON.stringify({
          error: {
            message: 'Publish blocked by validation warnings.',
            details: [{
              reason: 'MISSING_PRIVACY_DISCLOSURE',
              message: 'Add the required privacy disclosure before publishing.',
              opaqueToken: warningSecret,
            }],
          },
        }),
      }),
      accessToken: 'test-token',
    });
    assert.equal(warningFailure.success, false, `${label}: warning-blocked publish should fail`);
    assert.match(warningFailure.error, /Publish blocked by validation warnings/, `${label}: warning failure lost its summary`);
    assert.match(warningFailure.error, /MISSING_PRIVACY_DISCLOSURE/, `${label}: warning failure lost its detail code`);
    assert.match(warningFailure.error, /required privacy disclosure/, `${label}: warning failure lost its remediation detail`);
    assert.equal(warningFailure.error.includes(warningSecret), false, `${label}: warning failure leaked an opaque token`);
    assert.ok(warningFailure.error.length <= 1000, `${label}: warning detail summary exceeded its bound`);
  }

  const originalChrome = globalThis.chrome;
  try {
    const tabId = 6023;
    globalThis.chrome = {
      tabs: {
        get: async () => ({ id: tabId, url: dashboard }),
      },
    };
    const agent = new AgentCh({ getVisionProvider: async () => null });
    const messages = [];
    let webMcpPreparationCalls = 0;
    let submitProbeCalls = 0;
    let permissionPromptCalls = 0;
    let toolDispatchCalls = 0;
    agent.conversationModes.set(tabId, 'act');
    agent.providerManager = { ...(agent.providerManager || {}), getVisionProvider: async () => null };
    agent._ensureGateSetting = async () => false;
    agent._prepareWebMCPToolCall = async () => {
      webMcpPreparationCalls += 1;
      throw new Error('protected-page WebMCP preparation must not run');
    };
    agent._detectLikelySubmitAction = async () => {
      submitProbeCalls += 1;
      throw new Error('protected-page submit probing must not run');
    };
    agent._promptPermission = async () => {
      permissionPromptCalls += 1;
      return 'once';
    };
    agent.executeTool = async () => {
      toolDispatchCalls += 1;
      throw new Error('protected-page tool dispatch must not run');
    };
    agent._rememberMastodonObservation = async () => null;
    agent._recordProgressObservation = async () => null;
    agent._autoRecordProgressAction = () => null;
    agent._persist = () => {};

    const batchResult = await agent._executeToolBatch(
      tabId,
      [{
        id: 'cws_protected_webmcp',
        function: { name: 'execute_webmcp_tool', arguments: '{"tool_id":"page-tool","input":{}}' },
      }],
      messages,
      () => {},
      { supportsVision: false },
      '',
      new Set(['execute_webmcp_tool']),
      1,
    );

    assert.equal(batchResult.action, 'continue', 'chrome: protected failure should return through the normal tool-result pipeline');
    assert.equal(webMcpPreparationCalls, 0, 'chrome: protected guard must run before WebMCP/CDP preparation');
    assert.equal(submitProbeCalls, 0, 'chrome: protected guard must run before submit DOM probes');
    assert.equal(permissionPromptCalls, 0, 'chrome: blocked protected-page tools must not ask for a permission they cannot use');
    assert.equal(toolDispatchCalls, 0, 'chrome: protected-page tools must not reach executeTool');
    assert.equal(messages.length, 1, 'chrome: protected failure should produce one ordinary tool result');
    assert.match(messages[0].content, /"errorCode":"chrome_protected_page"/);
    assert.match(messages[0].content, /TRUSTED RUNTIME ROUTING/);
  } finally {
    if (originalChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = originalChrome;
  }

  assert.equal(capabilityForCh('chrome_web_store_upload', {}), CapabilityCh.UPLOAD);
  assert.equal(capabilityForCh('chrome_web_store_publish', {}), CapabilityCh.NETWORK);
  assert.equal(
    hostForCapabilityCh(CapabilityCh.UPLOAD, { _trustedPermissionUrl: 'https://chromewebstore.googleapis.com/' }, 'https://example.com/', 'chrome_web_store_upload'),
    'chromewebstore.googleapis.com',
  );
  assert.equal(
    hostForCapabilityCh(CapabilityCh.UPLOAD, { url: 'https://attacker.example/' }, 'https://dashboard.example/', 'upload_file'),
    'dashboard.example',
    'ordinary page uploads must remain charged to the current page even if raw args contain a URL',
  );
  for (const invariant of [CompletionInvariantCh, CompletionInvariantFx]) {
    assert.equal(invariant.isCompletionActionTool('chrome_web_store_upload'), true);
    assert.equal(invariant.isCompletionActionTool('chrome_web_store_publish'), true);
    assert.equal(invariant.isCompletionObservationTool('chrome_web_store_status', {}, { success: true }), true);
  }
  for (const [label, AgentClass, invariant] of [
    ['chrome', AgentCh, CompletionInvariantCh],
    ['firefox', AgentFx, CompletionInvariantFx],
  ]) {
    const agent = new AgentClass({});
    const tabId = label === 'chrome' ? 6021 : 6022;
    agent.completionInvariants.set(tabId, invariant.createCompletionInvariantState(`${label}-cws`));
    const recorded = agent._recordCompletionSubmitAttempt(
      tabId,
      { isSubmit: true },
      'chrome_web_store_publish',
      {},
      '',
      '',
      { success: true, dispatched: true },
    );
    assert.equal(recorded, null, `${label}: API publishing should not create unverifiable dashboard DOM-submit state`);
    assert.equal(agent._completionSubmitStates.has(tabId), false, `${label}: API publishing should verify through chrome_web_store_status`);
  }

  const adapter = getActiveAdapter(dashboard);
  assert.equal(adapter?.name, 'chrome-web-store-developer');
  assert.doesNotMatch(adapter?.notes || '', /chrome_web_store_status|Settings → Skills/);
  assert.match(adapter?.notes || '', /Continue manually in the dashboard/);
  assert.equal(getActiveAdapter('https://chrome.google.com/webstore/devconsole?authuser=1')?.name, 'chrome-web-store-developer');
  assert.equal(getActiveAdapterFx(dashboard)?.name, 'chrome-web-store-developer');
  assert.equal(getActiveAdapterFx('https://chrome.google.com/webstore/devconsole#drafts')?.name, 'chrome-web-store-developer');
  assert.doesNotMatch(getActiveAdapterFx(dashboard)?.notes || '', /chrome_web_store_status|Settings → Skills/);
  assert.match(getActiveAdapterFx(dashboard)?.notes || '', /Continue manually in the dashboard/);

  const chromeAgentSource = fs.readFileSync(path.join(ROOT, 'src/chrome/src/agent/agent.js'), 'utf8');
  const guardIndex = chromeAgentSource.indexOf('const protectedPageFailure = await this._chromeProtectedPageFailure(tabId, fnName);');
  const webMcpPreparationIndex = chromeAgentSource.indexOf('const webMcpPreparation = protectedPageFailure', guardIndex);
  const toolbarPreflightIndex = chromeAgentSource.indexOf('const pipelineToolbarPreflight = await this._preflightRichTextToolbarTarget(', webMcpPreparationIndex);
  const toolDispatchIndex = chromeAgentSource.indexOf('const pipelineRawToolResult = pipelineToolbarPreflight.block || await this.executeTool(', toolbarPreflightIndex);
  assert.ok(
    guardIndex >= 0
      && webMcpPreparationIndex > guardIndex
      && toolbarPreflightIndex > webMcpPreparationIndex
      && toolDispatchIndex > toolbarPreflightIndex,
    'chrome: protected-page guard must run before WebMCP preparation, toolbar preflight, and tool dispatch',
  );
  assert.match(chromeAgentSource, /TRUSTED RUNTIME ROUTING: Chrome blocks extension DOM\/debugger access/, 'chrome: protected-page recovery should remain outside the untrusted page-content wrapper');
  assert.doesNotMatch(chromeAgentSource, /ask the user to enable\/configure that packaged skill/i, 'chrome: protected-page recovery must not route users to a removed packaged skill');
});

test('Chrome Web Store upload forces a fresh status turn before any batched publish', async () => {
  for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
    const agent = new AgentClass({
      getActive: () => ({ promptTier: 'full', supportsVision: false }),
      getVisionProvider: async () => null,
    });
    const tabId = label === 'chrome' ? 6024 : 6025;
    const messages = [];
    const executed = [];
    agent._ensureGateSetting = async () => false;
    agent._skipPermissionGate = true;
    agent._rememberMastodonObservation = async () => null;
    agent._recordProgressObservation = async () => null;
    agent._autoRecordProgressAction = () => null;
    agent._persist = () => {};
    agent.executeTool = async (_tabId, name) => {
      executed.push(name);
      return { success: true, dispatched: name !== 'chrome_web_store_status' };
    };

    const result = await agent._executeToolBatch(
      tabId,
      [
        { id: 'release_upload', function: { name: 'chrome_web_store_upload', arguments: '{}' } },
        { id: 'release_status', function: { name: 'chrome_web_store_status', arguments: '{}' } },
        { id: 'release_publish', function: { name: 'chrome_web_store_publish', arguments: '{"publish_type":"default"}' } },
      ],
      messages,
      () => {},
      { supportsVision: false },
      null,
      new Set(['chrome_web_store_upload', 'chrome_web_store_status', 'chrome_web_store_publish']),
      1,
    );

    assert.equal(result.action, 'continue', `${label}: upload boundary should start a fresh turn`);
    assert.deepEqual(executed, ['chrome_web_store_upload'], `${label}: status or publish ran in the upload batch`);
    for (const id of ['release_status', 'release_publish']) {
      const skipped = JSON.parse(messages.find(message => message.tool_call_id === id).content);
      assert.equal(skipped.skipped, true, `${label}/${id}: queued release call was not skipped`);
      assert.equal(skipped.skippedBecause, 'fresh_turn_required', `${label}/${id}: fresh-turn marker missing`);
      assert.equal(skipped.triggeringTool, 'chrome_web_store_upload', `${label}/${id}: upload trigger missing`);
      assert.equal(skipped.reason, 'chrome_web_store_upload_requires_status', `${label}/${id}: status requirement missing`);
    }
  }
});

test('Chrome Web Store gallery access promotes after bounded failures and uses at most one vision fallback', async () => {
  const previousChrome = globalThis.chrome;
  const reviews = 'https://chromewebstore.google.com/detail/webbrain/ljhijonmfahplgbbacgcfnaihbjljhhb/reviews';
  const tabId = 934;
  let tabUrl = reviews;
  try {
    globalThis.chrome = {
      ...(previousChrome || {}),
      tabs: {
        ...(previousChrome?.tabs || {}),
        get: async id => ({ id, active: true, status: 'complete', url: tabUrl }),
      },
    };

    const textOnlyAgent = new AgentCh({
      getActive: () => ({ supportsVision: false }),
      getVisionProvider: async () => null,
    });
    textOnlyAgent.currentRunId.set(tabId, 'gallery-text-only');
    assert.equal(
      await textOnlyAgent._chromeProtectedPageFailure(tabId, 'get_accessibility_tree'),
      null,
      'public gallery pages should get one ordinary recovery before promotion',
    );
    const missingTree = {
      success: false,
      errorCode: 'missing_tool_response',
      missingToolResponse: true,
      error: 'get_accessibility_tree returned no result.',
    };
    const first = await textOnlyAgent._maybePromoteChromeProtectedGalleryResult(
      tabId,
      'get_accessibility_tree',
      { filter: 'visible' },
      missingTree,
    );
    assert.equal(first.errorCode, 'missing_tool_response');
    assert.equal(first.protectedPageCandidate, 'chrome-web-store-gallery');
    assert.equal(first.protectedPageAttempt, 1);

    const frames = await textOnlyAgent._maybePromoteChromeProtectedGalleryResult(
      tabId,
      'get_frames',
      {},
      { success: true, frames: [{ id: '0', url: reviews }] },
    );
    assert.equal(frames.success, true, 'browser frame metadata remains usable');

    const promoted = await textOnlyAgent._maybePromoteChromeProtectedGalleryResult(
      tabId,
      'wait_for_stable',
      {},
      { ...missingTree, error: 'wait_for_stable returned no result.' },
    );
    assert.equal(promoted.errorCode, 'chrome_protected_page');
    assert.equal(promoted.nonRetryable, true);
    assert.equal(promoted.protectedPageConfirmed, true);
    assert.equal(promoted.protectedPageEvidence, 'repeated_missing_page_access');
    assert.equal(promoted.protectedPageAttempts, 2);
    assert.equal(promoted.manualRequired, true);
    assert.equal(promoted.screenshotAttempted, false, 'text-only runs should not capture an unusable screenshot');
    assert.match(promoted.hint, /no vision-capable model/i);

    const resetAgent = new AgentCh({
      getActive: () => ({ supportsVision: false }),
      getVisionProvider: async () => null,
    });
    resetAgent.currentRunId.set(tabId, 'gallery-reset');
    await resetAgent._maybePromoteChromeProtectedGalleryResult(
      tabId,
      'read_page',
      {},
      missingTree,
    );
    await resetAgent._maybePromoteChromeProtectedGalleryResult(
      tabId,
      'read_page',
      {},
      { success: true, text: 'Readable page content' },
    );
    const afterHealthyRead = await resetAgent._maybePromoteChromeProtectedGalleryResult(
      tabId,
      'read_page',
      {},
      missingTree,
    );
    assert.equal(afterHealthyRead.protectedPageAttempt, 1, 'a healthy DOM read should reset the candidate counter');

    for (const urlReadTool of ['fetch_url', 'research_url', 'read_page_source']) {
      const urlResetAgent = new AgentCh({
        getActive: () => ({ supportsVision: false }),
        getVisionProvider: async () => null,
      });
      urlResetAgent.currentRunId.set(tabId, `gallery-url-reset-${urlReadTool}`);
      const failedUrlRead = await urlResetAgent._maybePromoteChromeProtectedGalleryResult(
        tabId,
        urlReadTool,
        { url: reviews },
        { success: false, url: reviews, error: `${urlReadTool} failed: Failed to fetch` },
      );
      assert.equal(failedUrlRead.protectedPageAttempt, 1, `${urlReadTool}: failed URL read should start suspicion`);
      const healthyUrlRead = await urlResetAgent._maybePromoteChromeProtectedGalleryResult(
        tabId,
        urlReadTool,
        { url: reviews },
        { success: true, url: reviews, text: 'Readable page content' },
      );
      assert.equal(healthyUrlRead.success, true, `${urlReadTool}: successful URL read should remain usable`);
      const afterHealthyUrlRead = await urlResetAgent._maybePromoteChromeProtectedGalleryResult(
        tabId,
        'read_page',
        {},
        missingTree,
      );
      assert.equal(
        afterHealthyUrlRead.protectedPageAttempt,
        1,
        `${urlReadTool}: successful URL read should reset the candidate counter`,
      );
    }

    tabUrl = 'https://example.com/';
    await resetAgent._maybePromoteChromeProtectedGalleryResult(
      tabId,
      'read_page',
      {},
      { success: true, text: 'Different page' },
    );
    assert.equal(resetAgent._chromeProtectedGalleryStates.has(tabId), false, 'navigation away should clear gallery suspicion');

    tabUrl = reviews;
    let screenshotCalls = 0;
    const visionAgent = new AgentCh({
      getActive: () => ({ supportsVision: true }),
      getVisionProvider: async () => null,
    });
    visionAgent.currentRunId.set(tabId, 'gallery-vision');
    visionAgent.executeTool = async (_tabId, name) => {
      assert.equal(name, 'inspect_viewport');
      screenshotCalls++;
      return {
        success: true,
        method: 'image_attach',
        description: 'One protected-page viewport',
        _attachImage: 'data:image/png;base64,AA==',
      };
    };
    const explicitDenial = await visionAgent._maybePromoteChromeProtectedGalleryResult(
      tabId,
      'research_url',
      { url: reviews },
      { success: false, error: 'research_url failed: The extensions gallery cannot be scripted.' },
    );
    assert.equal(explicitDenial.errorCode, 'chrome_protected_page');
    assert.equal(explicitDenial.protectedPageEvidence, 'explicit_chrome_gallery_denial');
    assert.equal(explicitDenial.visualFallbackSucceeded, true);
    assert.equal(explicitDenial.screenshotAttempted, true);
    assert.equal(explicitDenial._attachImage, 'data:image/png;base64,AA==');
    assert.equal(screenshotCalls, 1, 'a definitive gallery denial should trigger one visual fallback');

    const repeated = await visionAgent._maybePromoteChromeProtectedGalleryResult(
      tabId,
      'get_shadow_dom',
      {},
      { success: false, error: 'The extensions gallery cannot be scripted.' },
    );
    assert.equal(repeated.manualRequired, true);
    assert.equal(repeated.screenshotAttempted, true);
    assert.equal(screenshotCalls, 1, 'confirmed gallery protection must not capture a second screenshot');
  } finally {
    if (previousChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = previousChrome;
  }
});

test('Chrome Web Store gallery retry state is scoped to process-message runs without tracing', async () => {
  for (const method of ['processMessage', 'processMessageStream']) {
    const agent = new AgentCh({});
    const tabId = method === 'processMessage' ? 936 : 937;
    let enteredInner = false;
    agent._claimRunEntry = async () => {};
    agent._hydrate = async () => {};
    agent._resetActiveSkillsForRun = () => {};
    agent._clearRunLoopState = () => {};
    agent._resetRichTextToolbarAudit = () => {};
    agent._beginCompletionInvariant = () => null;
    agent._beginReadCompleteness = async () => null;
    agent._clearCompletionInvariant = () => {};
    agent._clearReadCompleteness = () => {};
    agent._configureCapturePolicyForRun = () => null;
    agent._restoreCapturePolicyAfterRun = async () => {};
    agent._discardProvisionalSelectionGroundingScope = () => {};
    agent._storeContinuationExecutionEvidence = () => {};
    agent._chromeProtectedGalleryStates.set(tabId, {
      key: 'stale-run',
      failures: 2,
      confirmed: true,
      screenshotAttempted: true,
    });
    const innerName = method === 'processMessage'
      ? '_processMessageInner'
      : '_processMessageStreamInner';
    agent[innerName] = async () => {
      enteredInner = true;
      assert.equal(
        agent._chromeProtectedGalleryStates.has(tabId),
        false,
        `${method}: a previous run must not suppress this run's retry or vision fallback`,
      );
      agent._chromeProtectedGalleryStates.set(tabId, {
        key: 'current-run',
        failures: 2,
        confirmed: true,
        screenshotAttempted: true,
      });
      return 'done';
    };

    const result = method === 'processMessage'
      ? await agent.processMessage(tabId, 'review this page')
      : await agent.processMessageStream(tabId, 'review this page');
    assert.equal(result, 'done');
    assert.equal(enteredInner, true, `${method}: test did not enter the run`);
    assert.equal(
      agent._chromeProtectedGalleryStates.has(tabId),
      false,
      `${method}: protected-page state must be discarded when the run finishes`,
    );
  }
});

test('Chrome Web Store gallery promotion terminates queued browser work after visual or manual fallback', async () => {
  const previousChrome = globalThis.chrome;
  const reviews = 'https://chromewebstore.google.com/detail/webbrain/ljhijonmfahplgbbacgcfnaihbjljhhb/reviews';
  const tabId = 935;
  try {
    globalThis.chrome = {
      ...(previousChrome || {}),
      tabs: {
        ...(previousChrome?.tabs || {}),
        get: async id => ({ id, active: true, status: 'complete', url: reviews }),
      },
    };

    for (const supportsVision of [false, true]) {
      const agent = new AgentCh({
        getActive: () => ({ contextWindow: 128000, supportsVision }),
        getVisionProvider: async () => null,
      });
      const messages = [];
      const executed = [];
      let screenshotCalls = 0;
      agent.currentRunId.set(tabId, `gallery-batch-${supportsVision ? 'vision' : 'manual'}`);
      agent._currentUrl = async () => reviews;
      agent._persist = () => {};
      agent.executeTool = async (_tabId, name) => {
        executed.push(name);
        if (name === 'inspect_viewport') {
          screenshotCalls++;
          return {
            success: true,
            method: 'image_attach',
            description: 'Protected Chrome Web Store viewport',
            _attachImage: 'data:image/png;base64,AA==',
          };
        }
        return undefined;
      };

      const first = await agent._executeToolBatch(
        tabId,
        [{ id: `gallery_first_${supportsVision}`, function: { name: 'get_accessibility_tree', arguments: '{"filter":"visible"}' } }],
        messages,
        () => {},
        { supportsVision },
        null,
        new Set(['get_accessibility_tree']),
        1,
      );
      assert.equal(first.action, 'continue');

      const updates = [];
      const secondCallId = `gallery_second_${supportsVision}`;
      const queuedCallId = `gallery_queued_${supportsVision}`;
      const second = await agent._executeToolBatch(
        tabId,
        [
          { id: secondCallId, function: { name: 'wait_for_stable', arguments: '{}' } },
          { id: queuedCallId, function: { name: 'click_ax', arguments: '{"ref_id":"ref_1"}' } },
        ],
        messages,
        (type, data) => updates.push({ type, data }),
        { supportsVision },
        null,
        new Set(['wait_for_stable', 'click_ax', 'done']),
        2,
      );

      assert.equal(second.action, supportsVision ? 'deliver' : 'return');
      assert.equal(
        second.status,
        supportsVision ? 'chrome_protected_page_visual_fallback' : 'chrome_protected_page_manual_required',
      );
      assert.deepEqual(
        executed,
        supportsVision
          ? ['get_accessibility_tree', 'wait_for_stable', 'inspect_viewport']
          : ['get_accessibility_tree', 'wait_for_stable'],
        'queued actions must not dispatch after gallery protection is confirmed',
      );
      assert.equal(screenshotCalls, supportsVision ? 1 : 0);
      if (supportsVision) {
        assert.deepEqual(second.recovery, {
          phase: 'protected_page_recovery',
          status: 'chrome_protected_page_visual_fallback',
        });
      } else {
        assert.equal(second.recovery, undefined);
      }
      const protectedUpdate = updates.find(update => update.type === 'tool_result' && update.data?.name === 'wait_for_stable');
      assert.equal(protectedUpdate?.data?.result?.errorCode, 'chrome_protected_page');
      assert.equal(protectedUpdate?.data?.result?.nonRetryable, true);
      const skipped = messages.find(message => message.tool_call_id === queuedCallId);
      assert.match(skipped?.content || '', /bounded visual\/manual fallback is terminal/i);
      const imageTurn = messages.find(message => Array.isArray(message.content)
        && message.content.some(block => block?.type === 'image_url'));
      assert.equal(!!imageTurn, supportsVision, 'only the vision path should attach one screenshot');
    }
  } finally {
    if (previousChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = previousChrome;
  }
});

test('Chrome Web Store visual fallback uses protected-page terminal recovery and preserves status', async () => {
  const agent = new AgentCh({});
  const tabId = 938;
  const messages = [
    { role: 'system', content: 'ordinary agent prompt' },
    { role: 'user', content: 'Summarize the visible reviews.' },
    {
      role: 'tool',
      tool_call_id: 'protected_read',
      content: JSON.stringify({
        success: false,
        errorCode: 'chrome_protected_page',
        protectedPage: 'chrome-web-store-gallery',
        visualFallback: { description: 'The screenshot shows two visible review cards.' },
      }),
    },
  ];
  const updates = [];
  let request = null;
  agent._persist = () => {};
  agent._chatWithCostAllowance = async (_provider, sentMessages, options) => {
    request = { sentMessages, options };
    return {
      content: '',
      toolCalls: [{
        id: 'protected_done',
        function: {
          name: 'done',
          arguments: JSON.stringify({
            summary: 'The screenshot exposed two review cards. Chrome protected the page, so further review and interaction must continue manually.',
            outcome: 'partial',
          }),
        },
      }],
    };
  };

  const recovery = await agent._recoverDeliveryCheckpointTurn(
    tabId,
    messages,
    (type, data) => updates.push({ type, data }),
    { model: 'test-model', supportsVision: true },
    {},
    null,
    2,
    'protected fallback should not be used',
    {},
    null,
    null,
    {
      phase: 'protected_page_recovery',
      status: 'chrome_protected_page_visual_fallback',
    },
  );

  assert.equal(recovery.status, 'chrome_protected_page_visual_fallback');
  assert.match(recovery.content, /Chrome protected the page/i);
  assert.match(request?.sentMessages?.[0]?.content || '', /protected-page delivery turn/i);
  assert.doesNotMatch(request?.sentMessages?.[0]?.content || '', /two delivery checkpoints|observation limit/i);
  assert.match(request?.options?.tools?.[0]?.function?.description || '', /Chrome protected/i);
  assert.doesNotMatch(request?.options?.tools?.[0]?.function?.description || '', /observation limit/i);
  assert.equal(
    updates.some(update => update.type === 'run_status'
      && update.data?.status === 'chrome_protected_page_visual_fallback'),
    true,
  );
  assert.equal(
    updates.some(update => /observation limit/i.test(update.data?.message || '')),
    false,
    'protected-page recovery must not claim that delivery checkpoints were exhausted',
  );
  const persistedResult = JSON.parse(messages.at(-1)?.content || '{}');
  assert.equal(persistedResult.protectedPageRecovery, true);
});

test('Chrome Web Store status forces a fresh inspection turn before publish', async () => {
  for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
    const agent = new AgentClass({
      getActive: () => ({ promptTier: 'full', supportsVision: false }),
      getVisionProvider: async () => null,
    });
    const tabId = label === 'chrome' ? 6026 : 6027;
    const messages = [];
    const executed = [];
    agent._ensureGateSetting = async () => false;
    agent._skipPermissionGate = true;
    agent._rememberMastodonObservation = async () => null;
    agent._recordProgressObservation = async () => null;
    agent._autoRecordProgressAction = () => null;
    agent._persist = () => {};
    agent.executeTool = async (_tabId, name) => {
      executed.push(name);
      return { success: true, dispatched: name === 'chrome_web_store_publish' };
    };

    const result = await agent._executeToolBatch(
      tabId,
      [
        { id: 'release_status', function: { name: 'chrome_web_store_status', arguments: '{}' } },
        { id: 'release_publish', function: { name: 'chrome_web_store_publish', arguments: '{"publish_type":"default"}' } },
      ],
      messages,
      () => {},
      { supportsVision: false },
      null,
      new Set(['chrome_web_store_status', 'chrome_web_store_publish']),
      1,
    );

    assert.equal(result.action, 'continue', `${label}: status boundary should start a fresh turn`);
    assert.deepEqual(executed, ['chrome_web_store_status'], `${label}: publish ran before status inspection`);
    const skipped = JSON.parse(messages.find(message => message.tool_call_id === 'release_publish').content);
    assert.equal(skipped.skipped, true, `${label}: queued publish was not skipped`);
    assert.equal(skipped.skippedBecause, 'fresh_turn_required', `${label}: fresh-turn marker missing`);
    assert.equal(skipped.triggeringTool, 'chrome_web_store_status', `${label}: status trigger missing`);
    assert.equal(skipped.reason, 'chrome_web_store_status_requires_inspection', `${label}: inspection requirement missing`);
  }
});

