test('planner gate: clearing scratchpad or conversation clears short-follow-up allowance', async () => {
  await withPlannerBrowserGlobals(async () => {
    for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
      const tabId = label === 'chrome' ? 9250 : 9251;
      const agent = new AgentClass({ getActive: () => ({}) });
      const seedMessages = () => [
        { role: 'system', content: 'system' },
        agent._buildScratchpadMessage('[Approved plan — pinned by planner]\n\n### Summary\nOriginal plan.'),
      ];

      agent.conversations.set(tabId, seedMessages());
      agent.plannerFollowUpSkipTabs.add(tabId);
      const clearedScratchpad = agent.clearScratchpad(tabId);
      assert.equal(clearedScratchpad.existed, true, `${label} should clear the seeded scratchpad`);
      assert.equal(agent.plannerFollowUpSkipTabs.has(tabId), false, `${label} scratchpad clear should clear the skip allowance`);

      agent.plannerFollowUpSkipTabs.add(tabId);
      const clearedMissingScratchpad = agent.clearScratchpad(tabId);
      assert.equal(clearedMissingScratchpad.existed, false, `${label} second scratchpad clear should be a no-op`);
      assert.equal(agent.plannerFollowUpSkipTabs.has(tabId), false, `${label} no-op scratchpad clear should still clear the skip allowance`);

      agent.conversations.set(tabId, seedMessages());
      agent.plannerFollowUpSkipTabs.add(tabId);
      agent.clearConversation(tabId);
      assert.equal(agent.plannerFollowUpSkipTabs.has(tabId), false, `${label} conversation clear should clear the skip allowance`);
    }
  });
});

test('planner gate: review exposes compact markdown plus verbose markdown', async () => {
  await withPlannerBrowserGlobals(async () => {
    for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
      const tabId = label === 'chrome' ? 9211 : 9212;
      const agent = new AgentClass({ getActive: () => ({}) });
      agent.setPlanReviewSettings({ confidenceThreshold: 0.9 });
      agent.conversations.set(tabId, [{ role: 'system', content: 'system' }]);
      agent._chatWithCostAllowance = async () => ({ content: plannerFixtureJson() });
      agent._waitForPlanReview = async (_tabId, _planId, _plan, markdown, _onUpdate, verboseMarkdown) => {
        assert.match(markdown, /Open the page and collect visible account links/, `${label} compact plan should keep the summary`);
        assert.match(markdown, /1\. Read the current page/, `${label} compact plan should include steps`);
        assert.doesNotMatch(markdown, /read_page|Scratchpad|Progress ledger/, `${label} compact plan should hide tools and memory internals`);
        assert.match(verboseMarkdown, /Confidence: 75%/, `${label} verbose plan should include confidence`);
        assert.match(verboseMarkdown, /read_page/, `${label} verbose plan should include tool names`);
        assert.match(verboseMarkdown, /Scratchpad: yes/, `${label} verbose plan should include memory strategy`);
        return {
          action: 'approve',
          editedText: '**Edited compact plan**\n\n### Steps\n1. Read the page and collect account links carefully',
          markdownMode: 'compact',
        };
      };

      const gate = await agent._runPlannerGate(
        tabId,
        { role: 'user', content: 'collect account links' },
        () => {},
        null,
      );
      assert.equal(gate.proceed, true, `${label} should proceed after approval`);
      assert.doesNotMatch(gate.approvedScratchpadText, /read_page/, `${label} compact edits should not re-pin stale hidden tool detail`);
      assert.match(gate.approvedScratchpadText, /Edited compact plan/, `${label} scratchpad handoff should preserve compact edits`);
      assert.doesNotMatch(gate.approvedScratchpadText, /Scratchpad: yes|Planner execution metadata/, `${label} edited scope must not inherit stale execution metadata`);
    }
  });
});

test('planner gate: 75% confidence plans auto-approve by default', async () => {
  await withPlannerBrowserGlobals(async () => {
    for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
      const tabId = label === 'chrome' ? 9215 : 9216;
      const agent = new AgentClass({ getActive: () => ({}) });
      agent.conversations.set(tabId, [{ role: 'system', content: 'system' }]);
      agent._chatWithCostAllowance = async () => ({ content: plannerFixtureJson({ confidence: 0.75 }) });
      agent._waitForPlanReview = async () => {
        throw new Error('75% default should not wait for side panel plan approval');
      };

      const autoApprovedEvents = [];
      const gate = await agent._runPlannerGate(
        tabId,
        { role: 'user', content: 'collect account links' },
        (type, data) => {
          assert.notEqual(type, 'plan_review', `${label} should not emit a plan review prompt`);
          if (type === 'plan_auto_approved') autoApprovedEvents.push(data);
        },
        null,
      );

      assert.equal(gate.proceed, true, `${label} should proceed`);
      assert.equal(autoApprovedEvents.length, 1, `${label} should emit a visible auto-approve trace`);
      assert.equal(autoApprovedEvents[0].confidence, 0.75, `${label} auto-approve trace should carry the plan confidence`);
      assert.match(gate.approvedScratchpadText, /\[Approved plan — pinned by planner\]/, `${label} should pin the auto-approved plan`);
      assert.match(gate.approvedScratchpadText, /Confidence: 75%/, `${label} auto-approved handoff should keep confidence`);
      assert.match(gate.approvedScratchpadText, /read_page/, `${label} auto-approved handoff should keep verbose tool detail`);
    }
  });
});

