test('run UI journal: streamed deltas coalesce durable snapshots without delaying live events', async () => {
  for (const [label, Journal, PersistenceScheduler, backgroundRel] of [
    ['chrome', RunUiJournalCh, RunUiPersistenceSchedulerCh, 'src/chrome/src/background.js'],
    ['firefox', RunUiJournalFx, RunUiPersistenceSchedulerFx, 'src/firefox/src/background.js'],
  ]) {
    let nextTimerId = 0;
    const timers = new Map();
    const persisted = [];
    const persistence = new PersistenceScheduler({
      persist: (_tabId, snapshot) => persisted.push(structuredClone(snapshot)),
      setTimeoutFn: function (callback) {
        assert.equal(this, globalThis, `${label}: setTimeout must retain its browser-global receiver`);
        const timerId = ++nextTimerId;
        timers.set(timerId, () => {
          timers.delete(timerId);
          callback();
        });
        return timerId;
      },
      clearTimeoutFn: function (timerId) {
        assert.equal(this, globalThis, `${label}: clearTimeout must retain its browser-global receiver`);
        timers.delete(timerId);
      },
    });
    const journal = new Journal({
      onChange(tabId, snapshot, change) {
        if (change?.eventType === 'text_delta') persistence.defer(tabId, snapshot);
        else void persistence.persistNow(tabId, snapshot);
      },
    });

    journal.begin(40, `${label}-stream`);
    journal.record(40, `${label}-stream`, 'text_delta', { content: 'one' });
    journal.record(40, `${label}-stream`, 'text_delta', { content: 'two' });
    assert.equal(persisted.length, 1, `${label}: deltas should not clone/write a durable snapshot immediately`);
    assert.equal(timers.size, 1, `${label}: consecutive deltas should share one trailing timer`);
    assert.equal(journal.get(40).streamedText, 'onetwo', `${label}: the journal should retain exact raw Markdown across panel remounts`);
    assert.equal(journal.get(40).streamedTextStartSeq, 1, `${label}: the raw stream snapshot should retain its first represented sequence`);
    assert.equal(journal.get(40).streamedTextSeq, 2, `${label}: the raw stream snapshot should retain its latest represented sequence`);

    timers.values().next().value();
    await Promise.resolve();
    assert.equal(persisted.at(-1).seq, 2, `${label}: the trailing write should capture the latest delta sequence`);

    journal.record(40, `${label}-stream`, 'text_delta', { content: 'three' });
    journal.record(40, `${label}-stream`, 'thinking', { content: 'done streaming' });
    assert.equal(timers.size, 0, `${label}: a non-delta update should cancel the trailing timer`);
    assert.equal(persisted.at(-1).seq, 4, `${label}: a non-delta update should persist all prior deltas immediately`);
    journal.acknowledge(40, `${label}-stream`, 4);
    assert.equal(journal.get(40).events.length, 0, `${label}: acknowledged events should still be released`);
    assert.equal(journal.get(40).streamedText, 'onetwothree', `${label}: acknowledgement must retain the cumulative raw stream for later remounts`);

    journal.record(40, `${label}-stream`, 'text_delta', { content: 'cancelled' });
    persistence.cancel(40);
    assert.equal(timers.size, 0, `${label}: clearing a run should discard its deferred persistence timer`);
    journal.record(40, `${label}-stream`, 'tool_call', { name: 'click', args: {} });
    assert.equal(journal.get(40).streamedText, '', `${label}: a tool transition should clear the preceding streamed prose snapshot`);
    assert.equal(journal.get(40).streamedTextSeq, 0, `${label}: a tool transition should clear the represented stream sequence`);

    const background = fs.readFileSync(path.join(ROOT, backgroundRel), 'utf8');
    assert.match(background, /change\?\.eventType === 'text_delta'[\s\S]*?runUiSnapshotPersistence\.defer\(tabId, snapshot\)/, `${label}: background should defer only text deltas`);
    assert.match(background, /runUiSnapshotPersistence\.flush\(tabId\) \|\| runUiPersistenceQueues\.get\(tabId\)/, `${label}: durability checkpoints should flush deferred deltas`);
    assert.match(background, /function clearRunUiSnapshot\(tabId\) \{\s*runUiSnapshotPersistence\.cancel\(tabId\)/, `${label}: clearing a run should cancel deferred persistence`);
    assert.match(background, /function sendAgentUpdate\([\s\S]{0,700}?runtime\.sendMessage\(/, `${label}: live event broadcast should remain immediate`);
  }
});

test('run UI journal: mocked tab switching keeps plans and progress scoped to their origin tab', () => {
  for (const [label, Journal] of [['chrome', RunUiJournalCh], ['firefox', RunUiJournalFx]]) {
    const journal = new Journal();
    const gmailTab = 41;
    const githubTab = 42;
    const gmailRequest = 'gmail-request';
    const githubRequest = 'github-request';
    const mounted = [];
    let currentTabId = githubTab;

    const deliver = (tabId, requestId, type, data, runId) => {
      const event = journal.record(tabId, requestId, type, data, runId);
      const message = { tabId, requestId, runId, type, data, seq: event?.seq };
      // This is the side-panel runtime routing contract: live events from a
      // hidden tab are journaled but never mounted in the visible tab.
      if (message.tabId === currentTabId) mounted.push(message);
    };

    journal.begin(gmailTab, gmailRequest);
    deliver(gmailTab, gmailRequest, 'plan_review', { planId: 'gmail-plan', markdown: 'Gmail plan' }, 'gmail-run');
    journal.begin(githubTab, githubRequest);
    deliver(githubTab, githubRequest, 'thinking', { content: 'Reading GitHub' }, 'github-run');

    assert.deepEqual(mounted.map(event => event.data?.content), ['Reading GitHub'], `${label}: GitHub must not mount Gmail's plan`);
    assert.equal(journal.get(gmailTab).status, 'awaiting_plan', `${label}: hidden Gmail plan should remain pending`);
    assert.equal(journal.get(githubTab).status, 'running', `${label}: GitHub should keep its own run state`);

    currentTabId = gmailTab;
    const lastRenderedSeq = 0;
    const replay = journal.get(gmailTab).events.filter(event => event.seq > lastRenderedSeq);
    assert.deepEqual(replay.map(event => event.data.planId), ['gmail-plan'], `${label}: returning to Gmail should replay its plan exactly once`);

    deliver(gmailTab, gmailRequest, 'plan_resolved', { planId: 'gmail-plan', decision: 'approve' }, 'gmail-run');
    assert.equal(journal.get(gmailTab).status, 'running', `${label}: resolving the plan should make restored copies non-pending`);
    assert.equal(journal.get(gmailTab).events.at(-1).type, 'plan_resolved', `${label}: plan resolution should be journaled for every mounted copy`);
    assert.deepEqual(
      journal.get(gmailTab).lastPlanResolution,
      { planId: 'gmail-plan', decision: 'approve' },
      `${label}: plan resolution proof should survive event acknowledgement`,
    );
    journal.acknowledge(gmailTab, gmailRequest, journal.get(gmailTab).seq);
    assert.deepEqual(
      journal.get(gmailTab).lastPlanResolution,
      { planId: 'gmail-plan', decision: 'approve' },
      `${label}: reconnect should still prove an approval after replay events are released`,
    );
  }
});

test('run UI journal: concurrent tabs, bounded replay, terminal snapshots, and stale requests are isolated', () => {
  for (const [label, Journal] of [['chrome', RunUiJournalCh], ['firefox', RunUiJournalFx]]) {
    const persisted = new Map();
    const journal = new Journal({ eventLimit: 3, onChange: (tabId, snapshot) => persisted.set(tabId, structuredClone(snapshot)) });
    journal.begin(1, 'request-a');
    journal.begin(2, 'request-b');
    journal.record(1, 'request-a', 'thinking', { content: 'a1' }, 'run-a');
    journal.record(2, 'request-b', 'thinking', { content: 'b1' }, 'run-b');
    journal.record(1, 'request-a', 'thinking', { content: 'a2' }, 'run-a');
    journal.record(1, 'request-a', 'thinking', { content: 'a3' }, 'run-a');
    journal.record(1, 'request-a', 'thinking', { content: 'a4' }, 'run-a');

    assert.equal(journal.get(1).events.length, 3, `${label}: replay journal should remain bounded`);
    assert.equal(journal.get(1).discardedBeforeSeq, 1, `${label}: eviction should expose the genuine replay-gap boundary`);
    assert.equal(journal.get(1).truncatedBeforeSeq, 1, `${label}: compaction should expose the missing sequence boundary`);
    assert.deepEqual(journal.get(2).events.map(event => event.data.content), ['b1'], `${label}: tab B events must remain independent`);
    assert.equal(journal.record(1, 'stale-request', 'plan_review', { planId: 'stale' }, 'run-stale'), null, `${label}: stale request events must be rejected`);

    journal.finish(1, 'request-a', 'completed', 'A finished', 'run-a');
    assert.equal(journal.get(1).status, 'completed', `${label}: hidden completion should persist a terminal state`);
    assert.equal(journal.get(1).finalContent, 'A finished', `${label}: hidden completion should persist final content`);
    assert.equal(journal.get(1).events.at(-1).type, 'run_complete', `${label}: terminal completion should receive the next ordered sequence`);
    assert.equal(journal.get(2).status, 'running', `${label}: completing tab A must not stop tab B`);

    const terminalSeq = journal.get(1).seq;
    assert.ok(journal.acknowledge(1, 'request-a', terminalSeq), `${label}: the rendered tab should acknowledge replay`);
    assert.equal(journal.get(1).events.length, 0, `${label}: acknowledged replay events should be released`);
    assert.equal(journal.get(1).discardedBeforeSeq, 2, `${label}: acknowledgement must not turn rendered events into replay loss`);
    assert.equal(journal.get(1).finalContent, 'A finished', `${label}: acknowledgement must retain the terminal snapshot`);

    const remounted = new Journal();
    remounted.restore(1, persisted.get(1));
    assert.equal(remounted.get(1).finalContent, 'A finished', `${label}: service-worker/panel remount should restore the terminal snapshot`);
  }
});

test('run UI journal: attachment delivery state survives terminal acknowledgement and remount', () => {
  for (const [label, Journal] of [['chrome', RunUiJournalCh], ['firefox', RunUiJournalFx]]) {
    const persisted = new Map();
    const journal = new Journal({
      onChange: (tabId, snapshot) => persisted.set(tabId, structuredClone(snapshot)),
    });
    journal.begin(51, `${label}-attachment`, { attachmentCount: 2 });
    assert.equal(journal.get(51).attachmentDeliveryState, 'sending', `${label}: attachment runs should begin in sending state`);
    journal.finish(51, `${label}-attachment`, 'completed', 'done');
    journal.setAttachmentDeliveryState(51, `${label}-attachment`, 'included');
    assert.equal(journal.get(51).attachmentDeliveryState, 'included', `${label}: terminal delivery state should be durable`);
    assert.equal(
      journal.get(51).events.at(-1).data.attachmentDeliveryState,
      'included',
      `${label}: the terminal replay event should carry the same delivery state`,
    );
    journal.acknowledge(51, `${label}-attachment`, journal.get(51).seq);
    assert.equal(journal.get(51).events.length, 0, `${label}: terminal replay may be acknowledged`);
    assert.equal(journal.get(51).attachmentDeliveryState, 'included', `${label}: acknowledgement must retain attachment proof`);

    const remounted = new Journal();
    remounted.restore(51, persisted.get(51));
    assert.equal(remounted.get(51).attachmentDeliveryState, 'included', `${label}: a reopened panel should recover the terminal state`);

    const rejected = new Journal();
    rejected.begin(52, `${label}-rejected`, { attachmentCount: 1 });
    rejected.record(52, `${label}-rejected`, 'attachment_rejected', { error: 'unsupported' });
    assert.equal(rejected.get(52).attachmentDeliveryState, 'not-sent', `${label}: structured rejection should be durable as not sent`);
  }
});

test('run UI journal: resumed requests preserve sequence and replay boundaries', () => {
  for (const [label, Journal] of [['chrome', RunUiJournalCh], ['firefox', RunUiJournalFx]]) {
    const journal = new Journal();
    journal.begin(7, 'resume-request', { foreground: true });
    journal.record(7, 'resume-request', 'thinking', { content: 'Before restart' }, 'run-before');
    journal.record(7, 'resume-request', 'plan_review', { planId: 'plan-before' }, 'run-before');
    journal.acknowledge(7, 'resume-request', 1);

    const before = journal.get(7);
    assert.equal(before.foreground, true, `${label}: foreground mode should be part of the durable run snapshot`);
    assert.equal(before.seq, 2, `${label}: fixture should start above sequence zero`);
    assert.equal(before.ackedSeq, 1, `${label}: fixture should retain an acknowledged replay boundary`);

    const restarted = new Journal();
    restarted.restore(7, structuredClone(before));
    const resumed = restarted.resume(7, 'resume-request');
    assert.ok(resumed, `${label}: matching request should resume its existing journal`);
    assert.equal(resumed.foreground, true, `${label}: restored continuations should retain foreground mode`);
    assert.equal(resumed.seq, 2, `${label}: resume must preserve the prior sequence`);
    assert.equal(resumed.ackedSeq, 1, `${label}: resume must preserve the acknowledged replay boundary`);
    assert.equal(resumed.discardedBeforeSeq, 0, `${label}: acknowledged events must not become replay gaps`);
    assert.equal(resumed.truncatedBeforeSeq, 0, `${label}: legacy truncation state should represent eviction only`);
    assert.equal(resumed.status, 'running', `${label}: resumed journal should return to running`);
    assert.equal(resumed.pendingPlanId, null, `${label}: stale pre-restart plan ownership should be cleared`);
    assert.deepEqual(
      resumed.events.map(event => event.seq),
      [2],
      `${label}: unacknowledged pre-restart events should remain replayable`,
    );

    const next = restarted.record(7, 'resume-request', 'thinking', { content: 'After restart' }, 'run-after');
    assert.equal(next.seq, 3, `${label}: first resumed event should advance beyond the old sequence`);

    const backgroundRun = new Journal().begin(8, 'background-request');
    assert.equal(backgroundRun.foreground, false, `${label}: ordinary runs should remain background by default`);
    assert.deepEqual(
      restarted.get(7).events.map(event => event.seq),
      [2, 3],
      `${label}: resumed events should not collide with prior replay sequence numbers`,
    );
    assert.equal(restarted.resume(7, 'different-request'), null, `${label}: a manual continuation must not reuse another request journal`);
  }
});

test('run UI journal: replay gaps distinguish acknowledgements and dedupe repeated polls', () => {
  for (const [label, Journal, discardedBeforeSeq, unavailableBeforeSeq] of [
    ['chrome', RunUiJournalCh, runUiDiscardedBeforeSeqCh, runUiUnavailableBeforeSeqCh],
    ['firefox', RunUiJournalFx, runUiDiscardedBeforeSeqFx, runUiUnavailableBeforeSeqFx],
  ]) {
    const acknowledged = new Journal();
    acknowledged.begin(9, `${label}-ack-only`);
    acknowledged.record(9, `${label}-ack-only`, 'thinking', { step: 1 });
    acknowledged.acknowledge(9, `${label}-ack-only`, 1);
    assert.equal(discardedBeforeSeq(acknowledged.get(9)), 0, `${label}: normal acknowledgement must not report replay loss`);
    assert.equal(unavailableBeforeSeq(acknowledged.get(9)), 1, `${label}: another panel should still know acknowledged events are unavailable for replay`);

    const evicted = new Journal({ eventLimit: 1 });
    evicted.begin(10, `${label}-evicted`);
    evicted.record(10, `${label}-evicted`, 'thinking', { step: 1 });
    evicted.record(10, `${label}-evicted`, 'thinking', { step: 2 });
    const snapshot = evicted.get(10);
    let lastRenderedSeq = 0;
    let replayGapNoted = false;
    let notices = 0;
    for (let poll = 0; poll < 6; poll++) {
      const boundary = unavailableBeforeSeq(snapshot);
      if (boundary > lastRenderedSeq && !replayGapNoted) {
        notices += 1;
        replayGapNoted = true;
      }
    }
    assert.equal(notices, 1, `${label}: repeated state polls should render one replay-gap notice`);
    assert.equal(lastRenderedSeq, 0, `${label}: a replay-gap notice must not claim that unavailable events were rendered`);

    assert.equal(
      discardedBeforeSeq({ ackedSeq: 4, truncatedBeforeSeq: 4 }),
      0,
      `${label}: legacy ack-only snapshots should migrate without a false replay gap`,
    );
    assert.equal(
      discardedBeforeSeq({ ackedSeq: 1, truncatedBeforeSeq: 3 }),
      3,
      `${label}: legacy snapshots should preserve a genuine unacknowledged eviction boundary`,
    );

    lastRenderedSeq = 0;
    replayGapNoted = false;
    notices = 0;
    for (let poll = 0; poll < 6; poll++) {
      const boundary = unavailableBeforeSeq(acknowledged.get(9));
      if (boundary > lastRenderedSeq && !replayGapNoted) {
        notices += 1;
        replayGapNoted = true;
      }
    }
    assert.equal(notices, 1, `${label}: acknowledged events from another panel should produce one replay-gap notice, not one per poll`);

    const advancing = new Journal();
    advancing.begin(12, `${label}-advancing-boundary`);
    lastRenderedSeq = 0;
    replayGapNoted = false;
    notices = 0;
    for (let step = 1; step <= 3; step++) {
      const event = advancing.record(12, `${label}-advancing-boundary`, 'thinking', { step });
      advancing.acknowledge(12, `${label}-advancing-boundary`, event.seq);
      const boundary = unavailableBeforeSeq(advancing.get(12));
      if (boundary > lastRenderedSeq && !replayGapNoted) {
        notices += 1;
        replayGapNoted = true;
      }
    }
    assert.equal(notices, 1, `${label}: an advancing replay boundary should still render only one notice for the run`);
    assert.equal(lastRenderedSeq, 0, `${label}: advancing replay loss must not move the rendered-event cursor`);

    const completed = new Journal();
    completed.begin(11, `${label}-acknowledged-terminal`);
    completed.record(11, `${label}-acknowledged-terminal`, 'thinking', { step: 1 });
    const terminal = completed.finish(
      11,
      `${label}-acknowledged-terminal`,
      'completed',
      'Recovered terminal answer',
    );
    completed.acknowledge(11, `${label}-acknowledged-terminal`, terminal.seq);
    const terminalSnapshot = completed.get(11);
    lastRenderedSeq = 0;
    replayGapNoted = false;
    notices = 0;
    let terminalRenders = 0;
    let renderedTerminalContent = '';
    for (let poll = 0; poll < 6; poll++) {
      const boundary = unavailableBeforeSeq(terminalSnapshot);
      if (boundary > lastRenderedSeq && !replayGapNoted) {
        notices += 1;
        replayGapNoted = true;
      }
      if (lastRenderedSeq < terminalSnapshot.seq) {
        terminalRenders += 1;
        renderedTerminalContent = terminalSnapshot.finalContent;
        lastRenderedSeq = terminalSnapshot.seq;
      }
    }
    assert.equal(notices, 1, `${label}: acknowledged terminal replay loss should still render one gap notice`);
    assert.equal(terminalRenders, 1, `${label}: gap deduplication must leave the acknowledged terminal snapshot renderable`);
    assert.equal(renderedTerminalContent, 'Recovered terminal answer', `${label}: terminal fallback content should survive acknowledgement`);
  }
});

test('all locales translate the run-progress replay-gap notice', async () => {
  for (const [label, panelRel, localeDir] of [
    ['chrome', 'src/chrome/src/ui/sidepanel.js', 'src/chrome/src/ui/locales'],
    ['firefox', 'src/firefox/src/ui/sidepanel.js', 'src/firefox/src/ui/locales'],
  ]) {
    const panel = fs.readFileSync(path.join(ROOT, panelRel), 'utf8');
    assert.match(
      panel,
      /function addRunProgressReplayGapNote\(\) \{[\s\S]*?note\.textContent = t\('sp\.run_progress_replay_gap'\)/,
      `${label}: replay-gap notice should render through the locale layer`,
    );
    for (const filename of fs.readdirSync(path.join(ROOT, localeDir)).filter((name) => name.endsWith('.js'))) {
      const locale = (await import('file://' + path.join(ROOT, localeDir, filename).replace(/\\/g, '/'))).default;
      const message = locale['sp.run_progress_replay_gap'];
      assert.equal(typeof message, 'string', `${label}/${filename}: missing translated run-progress replay-gap notice`);
      assert.ok(message.trim().length > 0, `${label}/${filename}: replay-gap notice must not be empty`);
      // The whole point of the separate notice: replay loss is UI history loss,
      // so no locale may reuse its context-compaction copy for it.
      assert.notEqual(message, locale['sp.context_compacted'], `${label}/${filename}: replay loss needs copy distinct from context compaction`);
      assert.notEqual(message, locale['sp.context_compacted_manual'], `${label}/${filename}: replay loss needs copy distinct from manual context compaction`);
    }
  }
});

test('run UI journal: consequential tool checkpoints stay pending until conversation durability is confirmed', () => {
  for (const [label, Journal] of [['chrome', RunUiJournalCh], ['firefox', RunUiJournalFx]]) {
    const journal = new Journal();
    const snapshot = journal.begin(8, `${label}-tool-checkpoint`, { mode: 'act', kind: 'chat' });
    assert.equal(snapshot.mode, 'act', `${label}: recovery metadata should retain the originating mode`);
    assert.equal(snapshot.kind, 'chat', `${label}: recovery metadata should identify fresh chat runs`);

    const call = journal.record(8, snapshot.requestId, 'tool_call', {
      name: 'click',
      args: { text: 'Publish' },
      outcomeUnknown: true,
    });
    assert.deepEqual(
      journal.get(8).pendingToolCall,
      { name: 'click', seq: call.seq },
      `${label}: a consequential call must remain visibly pending before execution`,
    );

    journal.record(8, snapshot.requestId, 'tool_result', {
      name: 'click',
      result: { success: true },
    });
    assert.ok(
      journal.get(8).pendingToolCall,
      `${label}: receiving a tool result alone must not clear the restart guard before conversation persistence`,
    );
    journal.settleToolCall(8, snapshot.requestId, 'click');
    assert.equal(
      journal.get(8).pendingToolCall,
      null,
      `${label}: the guard should clear only after the durable conversation checkpoint`,
    );
  }
});

test('submitted chat durability marker is persisted atomically with the user turn', async () => {
  for (const [label, AgentClass, apiName] of [
    ['chrome', AgentCh, 'chrome'],
    ['firefox', AgentFx, 'browser'],
  ]) {
    const previousApi = globalThis[apiName];
    const session = {};
    const writes = [];
    globalThis[apiName] = {
      storage: {
        session: {
          get: async key => ({ [key]: session[key] }),
          set: async values => {
            const cloned = structuredClone(values);
            writes.push(cloned);
            Object.assign(session, cloned);
          },
          remove: async key => { delete session[key]; },
        },
      },
    };
    try {
      const tabId = label === 'chrome' ? 61 : 62;
      const requestId = `${label}-durable-user-turn`;
      const first = new AgentClass({});
      first.conversations.set(tabId, [
        { role: 'system', content: 'System prompt' },
        { role: 'user', content: 'Original submitted prompt' },
      ]);
      first.conversationModes.set(tabId, 'act');
      first.conversationIds.set(tabId, `${label}-conversation`);

      await first._persistSubmittedTurn(tabId, requestId);

      assert.equal(writes.length, 1, `${label}: the user turn and durability marker should share one storage write`);
      const stored = session[`agentConv:${tabId}`];
      assert.equal(stored.submittedRunRequestId, requestId, `${label}: storage should bind the durable turn to its run request`);
      assert.equal(stored.messages.at(-1)?.content, 'Original submitted prompt', `${label}: the same write should contain the submitted user turn`);

      const restarted = new AgentClass({});
      assert.equal(
        await restarted.hasDurableSubmittedTurn(tabId, requestId),
        true,
        `${label}: a restarted background should recognize the persisted submitted turn`,
      );
      assert.equal(
        await restarted.hasDurableSubmittedTurn(tabId, `${requestId}-other`),
        false,
        `${label}: durability proof must stay request-scoped`,
      );

      globalThis[apiName].storage.session.set = async () => {
        throw new Error('QUOTA_BYTES exceeded');
      };
      const quotaLimited = new AgentClass({});
      quotaLimited.conversations.set(tabId, [
        { role: 'system', content: 'System prompt' },
        { role: 'user', content: 'A large but otherwise valid submitted prompt' },
      ]);
      assert.equal(
        await quotaLimited._persistSubmittedTurn(tabId, `${requestId}-quota`),
        false,
        `${label}: a session-storage quota failure should only disable recovery durability`,
      );
      assert.equal(
        await quotaLimited.hasDurableSubmittedTurn(tabId, `${requestId}-quota`),
        false,
        `${label}: a failed storage write must not be advertised as durable`,
      );
    } finally {
      if (previousApi === undefined) delete globalThis[apiName];
      else globalThis[apiName] = previousApi;
    }
  }
});

test('detached runs reconnect to a live request without starting it twice', async () => {
  for (const [label, runDetachedWithReconnect] of [
    ['chrome', runDetachedWithReconnectCh],
    ['firefox', runDetachedWithReconnectFx],
  ]) {
    const requestId = `${label}-live-reconnect`;
    const starts = [];
    const statuses = [];
    const replayedStates = [];
    const states = [
      {
        running: true,
        starting: false,
        runUi: { requestId, status: 'running', events: [] },
      },
      {
        running: false,
        starting: false,
        submittedTurnDurable: true,
        runUi: {
          requestId,
          status: 'completed',
          finalContent: 'Recovered answer',
          successfulDone: true,
          events: [{
            type: 'tool_result',
            data: { name: 'done', result: { done: true, outcome: 'success' } },
          }],
        },
      },
    ];
    let firstStart = true;
    const response = await runDetachedWithReconnect({
      initialAction: 'chat_start',
      payload: { tabId: 41, requestId, mode: 'act', text: 'inspect the page' },
      start: async (action) => {
        starts.push(action);
        if (firstStart) {
          firstStart = false;
          throw new Error('WebBrain extension connection was lost while sending "chat_start".');
        }
        return { accepted: true, requestId };
      },
      probe: async () => states.shift(),
      isConnectionError: error => /connection was lost/i.test(error.message),
      onStatus: status => statuses.push(status.phase),
      onState: state => replayedStates.push(state?.runUi?.status),
      wait: async () => {},
    });

    assert.deepEqual(starts, ['chat_start'], `${label}: uncertain delivery should not duplicate a live run`);
    assert.equal(response.content, 'Recovered answer', `${label}: terminal content should come from the run journal`);
    assert.equal(response.reconnected, true, `${label}: response should report reconnection`);
    assert.equal(response.resumed, false, `${label}: a still-live run should not be resumed`);
    assert.equal(response.successfulDone, true, `${label}: successful done state should survive journal replay`);
    assert.equal(response.submittedTurnDurable, true, `${label}: terminal responses should preserve durable-turn proof for safe UI resume routing`);
    assert.ok(statuses.includes('reconnecting'), `${label}: reconnecting status should be visible`);
    assert.ok(statuses.includes('reconnected'), `${label}: reconnected status should be visible`);
    assert.deepEqual(replayedStates, ['running', 'completed'], `${label}: missed UI journal states should be replayable after reconnect`);
  }
});

test('detached run followers honor local cancellation before their next state probe', async () => {
  for (const [label, runDetachedWithReconnect] of [
    ['chrome', runDetachedWithReconnectCh],
    ['firefox', runDetachedWithReconnectFx],
  ]) {
    const requestId = `${label}-locally-cancelled-follower`;
    let shouldContinue = true;
    let starts = 0;
    let probes = 0;
    let waits = 0;
    await assert.rejects(
      runDetachedWithReconnect({
        initialAction: 'chat_start',
        payload: { tabId: 42, requestId, mode: 'act', text: 'stop this run' },
        start: async () => {
          starts += 1;
          return { accepted: true, requestId };
        },
        probe: async () => {
          probes += 1;
          return { running: true, runUi: { requestId, status: 'running', events: [] } };
        },
        shouldContinue: () => shouldContinue,
        isConnectionError: () => false,
        wait: async () => {
          waits += 1;
          shouldContinue = false;
        },
      }),
      /Run recovery was cancelled/,
      `${label}: aborting the local follower should not wait for a terminal journal that clear may remove`,
    );
    assert.equal(starts, 1, `${label}: cancellation should not restart the request`);
    assert.equal(waits, 1, `${label}: cancellation should be observed at the first poll boundary`);
    assert.equal(probes, 0, `${label}: a cancelled follower should not race conversation clear with another probe`);

    const probeRequestId = `${label}-cancelled-during-probe`;
    let probeShouldContinue = true;
    let appliedStates = 0;
    await assert.rejects(
      runDetachedWithReconnect({
        initialAction: 'chat_start',
        payload: { tabId: 43, requestId: probeRequestId, mode: 'act', text: 'clear during probe' },
        start: async () => ({ accepted: true, requestId: probeRequestId }),
        probe: async () => {
          probeShouldContinue = false;
          return { running: true, runUi: { requestId: probeRequestId, status: 'running', events: [] } };
        },
        shouldContinue: () => probeShouldContinue,
        onState: () => { appliedStates += 1; },
        isConnectionError: () => false,
        wait: async () => {},
      }),
      /Run recovery was cancelled/,
      `${label}: cancellation during a probe should reject before applying stale state`,
    );
    assert.equal(appliedStates, 0, `${label}: a probe completed after clear must not replay old conversation state`);

    const applyRequestId = `${label}-cancelled-during-state-apply`;
    let applyShouldContinue = true;
    let completedStateApplications = 0;
    await assert.rejects(
      runDetachedWithReconnect({
        initialAction: 'chat_start',
        payload: { tabId: 44, requestId: applyRequestId, mode: 'act', text: 'clear during state apply' },
        start: async () => ({ accepted: true, requestId: applyRequestId }),
        probe: async () => ({
          running: false,
          starting: false,
          submittedTurnDurable: true,
          runUi: { requestId: applyRequestId, status: 'completed', finalContent: 'stale result', events: [] },
        }),
        shouldContinue: () => applyShouldContinue,
        onState: async () => {
          await Promise.resolve();
          applyShouldContinue = false;
          completedStateApplications += 1;
          return false;
        },
        isConnectionError: () => false,
        wait: async () => {},
      }),
      /Run recovery was cancelled/,
      `${label}: cancellation while applying state should reject before consuming a terminal snapshot`,
    );
    assert.equal(completedStateApplications, 1, `${label}: cancellation should be observed immediately after the awaited state application`);
  }
});

