test('profile sync keeps Chromium-only WebGPU provider state out of portable vaults', async () => {
  const chromeSync = await import(
    'file://' + path.join(ROOT, 'src/chrome/src/profile-sync.js').replace(/\\/g, '/')
  );
  const firefoxSync = await import(
    'file://' + path.join(ROOT, 'src/firefox/src/profile-sync.js').replace(/\\/g, '/')
  );
  const portableBase = {
    version: 1,
    providers: { openai: { type: 'openai', apiKey: 'portable-secret' } },
    activeProvider: 'openai',
    auxiliaryProviders: {},
    profile: { enabled: false, text: '' },
    memory: { records: [] },
    tombstones: {},
    meta: { providersAt: 5, providerItemsAt: { openai: 5 }, activeProviderAt: 5 },
  };
  const pollutedRemote = {
    ...portableBase,
    providers: {
      ...portableBase.providers,
      webgpu: { type: 'webgpu', model: WEBGPU_LFM25_MODEL_ID, configured: true },
    },
    activeProvider: 'webgpu',
    meta: { providersAt: 20, providerItemsAt: { openai: 5, webgpu: 20 }, activeProviderAt: 20 },
  };

  for (const runtime of [chromeSync, firefoxSync]) {
    const { vault } = runtime.mergeProfileVaults(portableBase, pollutedRemote);
    assert.equal(vault.providers.webgpu, undefined);
    assert.equal(vault.activeProvider, 'openai', 'a polluted WebGPU selection should retain the local portable selection');
    assert.equal(vault.meta.providerItemsAt.webgpu, undefined);
  }

  const localState = {
    providers: structuredClone(pollutedRemote.providers),
    activeProvider: 'webgpu',
    profileSyncPortableActiveProvider: 'openai',
    profileSyncMetadataV1: structuredClone(pollutedRemote.meta),
  };
  const chromeWrites = [];
  const chromeStorage = {
    get: async () => structuredClone(localState),
    set: async values => {
      chromeWrites.push(structuredClone(values));
      Object.assign(localState, structuredClone(values));
    },
  };
  const chromeManager = new chromeSync.ProfileSyncManager(chromeStorage);
  const localVault = await chromeManager.localVault();
  assert.equal(localVault.providers.webgpu, undefined);
  assert.equal(localVault.activeProvider, 'openai');
  assert.equal(localVault.meta.providerItemsAt.webgpu, undefined);

  await chromeManager.apply({
    ...portableBase,
    providers: { anthropic: { type: 'anthropic', apiKey: 'remote-secret' } },
    activeProvider: 'anthropic',
  }, []);
  const chromeApplied = chromeWrites.at(-1);
  assert.equal(chromeApplied.providers.webgpu.configured, true, 'Chrome should retain its local-only provider config');
  assert.equal(chromeApplied.providers.anthropic.apiKey, 'remote-secret');
  assert.equal(chromeApplied.activeProvider, 'webgpu', 'remote sync should not deactivate the local WebGPU provider');
  assert.equal(chromeApplied.profileSyncPortableActiveProvider, 'anthropic');

  let scheduled = 0;
  chromeManager.schedule = () => { scheduled++; };
  await chromeManager.noteChanges({
    activeProvider: { oldValue: 'anthropic', newValue: 'webgpu' },
    providers: {
      oldValue: chromeApplied.providers,
      newValue: { ...chromeApplied.providers, webgpu: { ...chromeApplied.providers.webgpu, contextWindow: 8192 } },
    },
  });
  assert.equal(localState.profileSyncPortableActiveProvider, 'anthropic');
  assert.equal(scheduled, 0, 'local-only WebGPU edits should not schedule a portable vault upload');

  let firefoxApplied;
  const firefoxManager = new firefoxSync.ProfileSyncManager({
    set: async values => { firefoxApplied = structuredClone(values); },
  });
  await firefoxManager.apply(pollutedRemote, []);
  assert.equal(firefoxApplied.providers.webgpu, undefined);
  assert.equal(firefoxApplied.activeProvider, 'webbrain_cloud');
  assert.equal(firefoxApplied.profileSyncMetadataV1.providerItemsAt.webgpu, undefined);
});

test('profile sync password change uploads a vault encrypted with the new password', async () => {
  const { ProfileSyncManager, decryptProfileVault } = await import(
    'file://' + path.join(ROOT, 'src/chrome/src/profile-sync.js').replace(/\\/g, '/')
  );
  const payload = { providers: { openai: { apiKey: 'secret' } }, profile: { text: 'private' }, memory: { records: [] } };
  let uploaded = null;
  const manager = new ProfileSyncManager({
    get: async () => ({ profileSyncEnabled: true, profileSyncToken: 'token' }),
  });
  manager.unlock = async password => {
    assert.equal(password, 'old password');
    manager.password = password;
    manager.envelope = { vaultId: 'vault-1' };
    manager.revision = 7;
  };
  manager.localVault = async () => payload;
  manager.request = async (_path, options) => {
    uploaded = JSON.parse(options.body).envelope;
    assert.equal(options.headers['If-Match'], '7');
    return { body: { revision: 8 } };
  };
  await manager.changePassword('old password', 'new password long enough');
  assert.deepEqual((await decryptProfileVault(uploaded, 'new password long enough')).payload, payload);
  await assert.rejects(() => decryptProfileVault(uploaded, 'old password'), /Incorrect sync password/);
});

test('profile sync serializes metadata updates and re-reads local state before apply', async () => {
  const { ProfileSyncManager, encryptProfileVault, decryptProfileVault } = await import(
    'file://' + path.join(ROOT, 'src/chrome/src/profile-sync.js').replace(/\\/g, '/')
  );
  let metadata = {};
  const storage = {
    get: async () => ({ profileSyncEnabled: true, profileSyncMetadataV1: structuredClone(metadata) }),
    set: async values => { if (values.profileSyncMetadataV1) metadata = structuredClone(values.profileSyncMetadataV1); },
  };
  const manager = new ProfileSyncManager(storage);
  manager.schedule = () => {};
  await Promise.all([
    manager.noteChanges({ providers: { newValue: {} } }),
    manager.noteChanges({ profileText: { newValue: 'updated' } }),
  ]);
  assert.ok(metadata.providersAt);
  assert.ok(metadata.profileAt);

  const password = 'correct horse battery staple';
  const remotePayload = { providers: { openai: { apiKey: 'remote' } }, activeProvider: 'openai', auxiliaryProviders: {}, profile: {}, memory: { records: [] }, tombstones: {}, meta: { providersAt: 5 } };
  const { envelope } = await encryptProfileVault(remotePayload, password);
  const initial = { ...remotePayload, providers: { openai: { apiKey: 'stale-local' } }, meta: { providersAt: 1 } };
  const latest = { ...remotePayload, providers: { openai: { apiKey: 'new-local' } }, meta: { providersAt: 10 } };
  let reads = 0;
  let applied;
  let uploaded;
  manager.password = password;
  manager.localVault = async () => structuredClone(reads++ === 0 ? initial : latest);
  manager.apply = async vault => { applied = structuredClone(vault); };
  manager.request = async (_path, options = {}) => {
    if (!options.method) return { body: { envelope, revision: 1 } };
    uploaded = JSON.parse(options.body).envelope;
    return { body: { revision: 2 } };
  };
  await manager.sync();
  assert.equal(applied.providers.openai.apiKey, 'new-local');
  assert.equal((await decryptProfileVault(uploaded, password)).payload.providers.openai.apiKey, 'new-local');
});

test('profile sync runs a follow-up pass when another sync joins an upload', async () => {
  const { ProfileSyncManager } = await import(
    'file://' + path.join(ROOT, 'src/chrome/src/profile-sync.js').replace(/\\/g, '/')
  );
  const manager = new ProfileSyncManager({ get: async () => ({ profileSyncEnabled: true, profileSyncToken: 'token' }) });
  let release;
  let runs = 0;
  manager.runSync = async () => { runs++; if (runs === 1) await new Promise(resolve => { release = resolve; }); return { runs }; };
  const first = manager.sync();
  await new Promise(resolve => setTimeout(resolve, 0));
  const joined = manager.sync();
  release();
  await Promise.all([first, joined]);
  assert.equal(runs, 2);
});

test('profile sync aborts an upload when the session locks in flight', async () => {
  const { ProfileSyncManager } = await import(
    'file://' + path.join(ROOT, 'src/chrome/src/profile-sync.js').replace(/\\/g, '/')
  );
  const manager = new ProfileSyncManager({});
  manager.password = 'correct horse battery staple';
  manager.localVault = async () => ({ providers: {}, auxiliaryProviders: {}, profile: {}, memory: { records: [] }, tombstones: {}, meta: {} });
  let release;
  let uploads = 0;
  manager.request = async (_path, options = {}) => {
    if (options.method === 'PUT') { uploads++; return { body: { revision: 1 } }; }
    await new Promise(resolve => { release = resolve; });
    const error = new Error('missing'); error.status = 404; throw error;
  };
  const syncing = manager.sync({ create: true });
  await new Promise(resolve => setTimeout(resolve, 0));
  manager.lock();
  release();
  await assert.rejects(syncing, /locked/);
  assert.equal(uploads, 0);
});

