test('captcha website URL uses the selected HTTP frame or nearest HTTP ancestor', async () => {
  for (const build of ['chrome', 'firefox']) {
    const mod = await import(pathToFileURL(path.join(ROOT, `src/${build}/src/agent/captcha-solver.js`)).href);
    const runtime = await import(pathToFileURL(path.join(ROOT, `src/${build}/src/agent/captcha-frame-runtime.js`)).href);
    const topLevelUrl = 'https://example.test/form';
    assert.equal(
      mod.captchaWebsiteUrl('https://example.test/checkpoint/captcha', topLevelUrl),
      'https://example.test/checkpoint/captcha',
      `${build}: HTTP frame URL was not used`,
    );
    assert.equal(
      mod.captchaWebsiteUrl('about:blank', topLevelUrl),
      topLevelUrl,
      `${build}: about:blank replaced the usable website URL`,
    );
    assert.equal(
      mod.captchaWebsiteUrl('about:srcdoc', topLevelUrl),
      topLevelUrl,
      `${build}: about:srcdoc replaced the usable website URL`,
    );
    const challengeUrl = 'https://captcha.vendor.test/challenge';
    const opaqueCandidate = {
      frameId: 12,
      frameUrl: 'about:srcdoc',
      type: 'recaptcha_v2',
      websiteKey: 'KEY_OPAQUE_NESTED',
      visible: true,
      normalCheckbox: true,
    };
    const opaqueAdjusted = runtime.applyCaptchaFrameVisibility(
      [opaqueCandidate],
      [
        {
          frameId: 0,
          frameUrl: topLevelUrl,
          childFrames: [{
            url: challengeUrl,
            loadedUrl: challengeUrl,
            name: 'challenge',
            visible: true,
          }],
        },
        {
          frameId: 7,
          frameUrl: challengeUrl,
          frameName: 'challenge',
          childFrames: [{
            url: 'about:srcdoc',
            loadedUrl: 'about:srcdoc',
            name: 'opaque',
            visible: true,
          }],
        },
        {
          frameId: 12,
          frameUrl: 'about:srcdoc',
          frameName: 'opaque',
          childFrames: [],
        },
      ],
      [
        { frameId: 0, parentFrameId: -1, url: topLevelUrl },
        { frameId: 7, parentFrameId: 0, url: challengeUrl },
        { frameId: 12, parentFrameId: 7, url: 'about:srcdoc' },
      ],
    );
    assert.equal(
      opaqueAdjusted[0].websiteURL,
      challengeUrl,
      `${build}: opaque frame did not inherit its nearest HTTP ancestor URL`,
    );
  }
});

test('captcha token injection revalidates the selected frame and calls one matched callback', async () => {
  const previous = {
    document: globalThis.document,
    location: globalThis.location,
    window: globalThis.window,
    Event: globalThis.Event,
    HTMLTextAreaElement: globalThis.HTMLTextAreaElement,
    HTMLInputElement: globalThis.HTMLInputElement,
  };
  try {
    for (const build of ['chrome', 'firefox']) {
      const runtime = await import(pathToFileURL(path.join(ROOT, `src/${build}/src/agent/captcha-frame-runtime.js`)).href);
      let callbackToken = null;
      const response = {
        tagName: 'TEXTAREA',
        id: 'g-recaptcha-response-only',
        value: '',
        textContent: '',
        style: {},
        getAttribute: (name) => name === 'id' ? 'g-recaptcha-response-only' : null,
        dispatchEvent: () => true,
      };
      const host = {
        getAttribute: (name) => ({
          'data-sitekey': 'KEY_ACTIVE',
          'data-callback': 'onCaptchaSolved',
        })[name] || null,
      };
      let declaredCallbackEnabled = true;
      let turnstileChallengeMarkerEnabled = false;
      let captchaUrlElements = [];
      let responseFields = [response];
      let captchaHosts = [host];
      const document = {
        querySelector: (selector) => {
          if (selector.includes('g-recaptcha-response')) return responseFields[0] || null;
          if (turnstileChallengeMarkerEnabled
              && selector === 'script[src*="challenges.cloudflare.com/turnstile"]') {
            return {};
          }
          return null;
        },
        querySelectorAll: (selector) => {
          if (selector.includes('textarea[name=') || selector.includes('input[name=')) {
            return responseFields;
          }
          if (selector.includes('[data-callback]')) return declaredCallbackEnabled ? captchaHosts : [];
          if (selector.includes('[data-sitekey]')) return captchaHosts;
          if (selector === 'iframe[src], script[src]') return captchaUrlElements;
          return [];
        },
        createElement: () => response,
        body: { appendChild: () => {} },
        documentElement: { appendChild: () => {} },
      };
      globalThis.document = document;
      globalThis.location = { href: 'https://example.test/checkpoint/captcha' };
      globalThis.window = {
        onCaptchaSolved: (token) => { callbackToken = token; },
        performance: { timeOrigin: 123456789 },
      };
      globalThis.Event = class {
        constructor(type, options) { this.type = type; this.bubbles = options?.bubbles; }
      };
      globalThis.HTMLTextAreaElement = class {};
      globalThis.HTMLInputElement = class {};

      const missingTarget = runtime.injectCaptchaTokenInPage({
        fieldName: 'g-recaptcha-response',
        token: 'TOKEN_UNTARGETED',
        target: {},
      });
      assert.equal(missingTarget.success, false, `${build}: targetless page injection succeeded`);
      assert.equal(missingTarget.targetRequired, true, `${build}: targetless page injection diagnostic missing`);
      assert.equal(response.value, '', `${build}: targetless page injection touched the field`);

      const injected = runtime.injectCaptchaTokenInPage({
        fieldName: 'g-recaptcha-response',
        token: 'TOKEN_123',
        target: {
          frameId: 9,
          frameUrl: globalThis.location.href,
          websiteKey: 'KEY_ACTIVE',
        },
      });
      assert.equal(injected.success, true, `${build}: targeted injection failed`);
      assert.equal(injected.siteKeyMatched, true, `${build}: key revalidation missing`);
      assert.equal(injected.fieldUpdated, true, `${build}: response-field status missing`);
      assert.deepEqual(injected.fieldsUpdated, ['g-recaptcha-response'], `${build}: updated-field diagnostic`);
      assert.equal(injected.calledCallback, true, `${build}: unique callback was not invoked`);
      assert.equal(callbackToken, 'TOKEN_123', `${build}: callback received wrong token`);
      assert.equal(response.value, 'TOKEN_123', `${build}: response field was not set`);

      let hiddenCallbackToken = null;
      let modalCallbackToken = null;
      const makeResponse = id => ({
        tagName: 'TEXTAREA',
        id,
        value: '',
        textContent: '',
        style: {},
        getAttribute: (name) => name === 'id' ? id : null,
        dispatchEvent: () => true,
      });
      const hiddenResponse = makeResponse('g-recaptcha-response-hidden');
      const modalResponse = makeResponse('g-recaptcha-response-modal');
      const makeHost = (callbackName) => ({
        getAttribute: (name) => ({
          'data-sitekey': 'KEY_SHARED_WIDGET',
          'data-callback': callbackName,
        })[name] || null,
      });
      responseFields = [hiddenResponse, modalResponse];
      captchaHosts = [makeHost('onHiddenCaptcha'), makeHost('onModalCaptcha')];
      globalThis.window.onHiddenCaptcha = token => { hiddenCallbackToken = token; };
      globalThis.window.onModalCaptcha = token => { modalCallbackToken = token; };

      const ambiguousField = runtime.injectCaptchaTokenInPage({
        fieldName: 'g-recaptcha-response',
        token: 'TOKEN_AMBIGUOUS_FIELD',
        target: {
          frameId: 9,
          frameUrl: globalThis.location.href,
          websiteKey: 'KEY_SHARED_WIDGET',
        },
      });
      assert.equal(ambiguousField.success, false, `${build}: ambiguous response field was updated`);
      assert.equal(
        ambiguousField.ambiguousResponseField,
        true,
        `${build}: ambiguous response field diagnostic missing`,
      );
      assert.equal(hiddenResponse.value, '', `${build}: ambiguous solve touched the hidden response field`);
      assert.equal(modalResponse.value, '', `${build}: ambiguous solve touched the modal response field`);

      const targetedField = runtime.injectCaptchaTokenInPage({
        fieldName: 'g-recaptcha-response',
        token: 'TOKEN_MODAL_WIDGET',
        callbackHint: 'onModalCaptcha',
        target: {
          frameId: 9,
          frameUrl: globalThis.location.href,
          websiteKey: 'KEY_SHARED_WIDGET',
          responseFieldId: 'g-recaptcha-response-modal',
          responseFieldIndex: 1,
        },
      });
      assert.equal(targetedField.success, true, `${build}: selected response field injection failed`);
      assert.equal(hiddenResponse.value, '', `${build}: hidden widget received the selected token`);
      assert.equal(modalResponse.value, 'TOKEN_MODAL_WIDGET', `${build}: modal widget did not receive its token`);
      assert.equal(hiddenCallbackToken, null, `${build}: hidden widget callback was invoked`);
      assert.equal(modalCallbackToken, 'TOKEN_MODAL_WIDGET', `${build}: selected callback was not invoked`);

      hiddenResponse.value = '';
      modalResponse.value = '';
      const staleFieldId = runtime.injectCaptchaTokenInPage({
        fieldName: 'g-recaptcha-response',
        token: 'TOKEN_STALE_FIELD_ID',
        target: {
          frameId: 9,
          frameUrl: globalThis.location.href,
          websiteKey: 'KEY_SHARED_WIDGET',
          responseFieldId: 'g-recaptcha-response-removed',
          responseFieldIndex: 1,
        },
      });
      assert.equal(staleFieldId.success, false, `${build}: missing selected field ID fell back to an index`);
      assert.equal(staleFieldId.staleTarget, true, `${build}: missing selected field ID was not marked stale`);
      assert.equal(hiddenResponse.value, '', `${build}: stale field ID touched the first response field`);
      assert.equal(modalResponse.value, '', `${build}: stale field ID touched the old indexed response field`);

      const canonicalHcaptchaResponse = makeResponse('h-captcha-response-only');
      let createdCompatibilityResponse = null;
      let hcaptchaCompatibilityResponses = [];
      const hcaptchaHost = {
        getAttribute: (name) => name === 'data-sitekey' ? 'HKEY_CANONICAL_ONLY' : null,
      };
      const hcaptchaDocument = {
        querySelector: () => null,
        querySelectorAll: (selector) => {
          if (selector.includes('h-captcha-response')) return [canonicalHcaptchaResponse];
          if (selector.includes('g-recaptcha-response')) return hcaptchaCompatibilityResponses;
          if (selector.includes('[data-sitekey]')) return [hcaptchaHost];
          return [];
        },
        createElement: () => makeResponse(''),
        body: {
          appendChild: (element) => {
            createdCompatibilityResponse = element;
          },
        },
        documentElement: { appendChild: () => {} },
      };
      const hcaptchaWindow = {
        location: { href: 'https://example.test/hcaptcha' },
        performance: { timeOrigin: 123456789 },
        Event: globalThis.Event,
        HTMLTextAreaElement: globalThis.HTMLTextAreaElement,
        HTMLInputElement: globalThis.HTMLInputElement,
      };
      const canonicalOnlyHcaptcha = runtime.injectCaptchaTokenInPage({
        fieldName: 'h-captcha-response',
        alsoSet: 'g-recaptcha-response',
        token: 'TOKEN_HCAPTCHA_CANONICAL_ONLY',
        target: {
          frameId: 9,
          frameUrl: hcaptchaWindow.location.href,
          websiteKey: 'HKEY_CANONICAL_ONLY',
          responseFieldId: 'h-captcha-response-only',
          responseFieldIndex: 0,
          documentTimeOrigin: 123456789,
        },
      }, {
        document: hcaptchaDocument,
        window: hcaptchaWindow,
      });
      assert.equal(
        canonicalOnlyHcaptcha.success,
        true,
        `${build}: missing hCaptcha compatibility field aborted injection`,
      );
      assert.equal(
        canonicalHcaptchaResponse.value,
        'TOKEN_HCAPTCHA_CANONICAL_ONLY',
        `${build}: canonical hCaptcha field was not updated`,
      );
      assert.equal(
        createdCompatibilityResponse?.value,
        'TOKEN_HCAPTCHA_CANONICAL_ONLY',
        `${build}: missing hCaptcha compatibility field was not created`,
      );

      const firstCompatibilityResponse = makeResponse('g-recaptcha-response-first');
      const secondCompatibilityResponse = makeResponse('g-recaptcha-response-second');
      hcaptchaCompatibilityResponses = [firstCompatibilityResponse, secondCompatibilityResponse];
      canonicalHcaptchaResponse.value = '';
      createdCompatibilityResponse = null;
      const ambiguousCompatibilityHcaptcha = runtime.injectCaptchaTokenInPage({
        fieldName: 'h-captcha-response',
        alsoSet: 'g-recaptcha-response',
        token: 'TOKEN_HCAPTCHA_AMBIGUOUS_COMPATIBILITY',
        target: {
          frameId: 9,
          frameUrl: hcaptchaWindow.location.href,
          websiteKey: 'HKEY_CANONICAL_ONLY',
          responseFieldId: 'h-captcha-response-only',
          responseFieldIndex: 0,
          documentTimeOrigin: 123456789,
        },
      }, {
        document: hcaptchaDocument,
        window: hcaptchaWindow,
      });
      assert.equal(
        ambiguousCompatibilityHcaptcha.success,
        true,
        `${build}: ambiguous hCaptcha compatibility fields aborted canonical injection`,
      );
      assert.deepEqual(
        ambiguousCompatibilityHcaptcha.fieldsUpdated,
        ['h-captcha-response'],
        `${build}: skipped compatibility field was reported as updated`,
      );
      assert.equal(
        ambiguousCompatibilityHcaptcha.compatibilityFieldSkipped,
        true,
        `${build}: compatibility-field skip was not reported`,
      );
      assert.match(
        ambiguousCompatibilityHcaptcha.compatibilityFieldError,
        /Multiple CAPTCHA response fields/,
        `${build}: compatibility-field ambiguity diagnostic missing`,
      );
      assert.equal(
        canonicalHcaptchaResponse.value,
        'TOKEN_HCAPTCHA_AMBIGUOUS_COMPATIBILITY',
        `${build}: canonical hCaptcha field was not updated after compatibility ambiguity`,
      );
      assert.equal(firstCompatibilityResponse.value, '', `${build}: first ambiguous compatibility field was updated`);
      assert.equal(secondCompatibilityResponse.value, '', `${build}: second ambiguous compatibility field was updated`);
      assert.equal(createdCompatibilityResponse, null, `${build}: ambiguous compatibility field was recreated`);

      responseFields = [response];
      captchaHosts = [host];
      const selectedFrameUrl = globalThis.location.href;
      globalThis.location.href = `${selectedFrameUrl}?step=verify#captcha`;
      response.value = '';
      const sameDocumentUrlChange = runtime.injectCaptchaTokenInPage({
        fieldName: 'g-recaptcha-response',
        token: 'TOKEN_SPA_URL',
        target: {
          frameId: 9,
          frameUrl: selectedFrameUrl,
          websiteKey: 'KEY_ACTIVE',
          documentTimeOrigin: 123456789,
        },
      });
      assert.equal(
        sameDocumentUrlChange.success,
        true,
        `${build}: same-document query/hash change blocked injection`,
      );
      assert.equal(response.value, 'TOKEN_SPA_URL', `${build}: SPA token was not injected`);

      response.value = '';
      globalThis.window.performance.timeOrigin = 987654321;
      const replacedDocument = runtime.injectCaptchaTokenInPage({
        fieldName: 'g-recaptcha-response',
        token: 'TOKEN_REPLACED_DOCUMENT',
        target: {
          frameId: 9,
          frameUrl: globalThis.location.href,
          websiteKey: 'KEY_ACTIVE',
          documentTimeOrigin: 123456789,
        },
      });
      assert.equal(replacedDocument.success, false, `${build}: replacement document accepted a stale token`);
      assert.equal(replacedDocument.staleTarget, true, `${build}: replacement document was not marked stale`);
      assert.equal(response.value, '', `${build}: stale document token touched the field`);
      globalThis.window.performance.timeOrigin = 123456789;

      declaredCallbackEnabled = false;
      callbackToken = null;
      response.value = '';
      globalThis.window.___grecaptcha_cfg = {
        clients: {
          0: {
            widget: {
              sitekey: 'KEY_ACTIVE',
              callback: (token) => { callbackToken = token; },
            },
          },
        },
      };
      const internalCallback = runtime.injectCaptchaTokenInPage({
        fieldName: 'g-recaptcha-response',
        token: 'TOKEN_INTERNAL',
        target: {
          frameId: 9,
          frameUrl: globalThis.location.href,
          websiteKey: 'KEY_ACTIVE',
        },
      });
      assert.equal(internalCallback.calledCallback, true, `${build}: unique Google client callback was not invoked`);
      assert.equal(internalCallback.callbackSource, 'grecaptcha-client', `${build}: Google callback source missing`);
      assert.equal(callbackToken, 'TOKEN_INTERNAL', `${build}: Google client callback received wrong token`);

      response.value = '';
      const stale = runtime.injectCaptchaTokenInPage({
        fieldName: 'g-recaptcha-response',
        token: 'TOKEN_STALE',
        target: {
          frameId: 9,
          frameUrl: globalThis.location.href,
          websiteKey: 'KEY_GONE',
        },
      });
      assert.equal(stale.success, false, `${build}: stale site key was injected`);
      assert.equal(stale.fieldUpdated, false, `${build}: stale field status was inaccurate`);
      assert.equal(stale.staleTarget, true, `${build}: stale target marker missing`);
      assert.equal(response.value, '', `${build}: stale token touched the field`);

      captchaUrlElements = [{
        src: 'https://newassets.hcaptcha.com/captcha/v1/hcaptcha.html#frame=checkbox&sitekey=KEY_FRAGMENT',
      }];
      const fragmentKey = runtime.injectCaptchaTokenInPage({
        fieldName: 'h-captcha-response',
        token: 'TOKEN_FRAGMENT_KEY',
        target: {
          frameId: 9,
          frameUrl: globalThis.location.href,
          websiteKey: 'KEY_FRAGMENT',
          type: 'hcaptcha',
        },
      });
      assert.equal(fragmentKey.success, true, `${build}: fragment site key injection failed`);
      assert.equal(fragmentKey.siteKeyMatched, true, `${build}: fragment site key was not revalidated`);
      assert.equal(response.value, 'TOKEN_FRAGMENT_KEY', `${build}: fragment-key token was not injected`);
      captchaUrlElements = [];
      response.value = '';

      turnstileChallengeMarkerEnabled = true;
      const explicitTurnstile = runtime.injectCaptchaTokenInPage({
        fieldName: 'cf-turnstile-response',
        token: 'TOKEN_TURNSTILE',
        target: {
          frameId: 9,
          frameUrl: globalThis.location.href,
          websiteKey: 'TURNSTILE_EXPLICIT_KEY',
          type: 'turnstile',
          explicitWebsiteKey: true,
        },
      });
      assert.equal(explicitTurnstile.success, true, `${build}: explicit-key Turnstile injection failed`);
      assert.equal(explicitTurnstile.siteKeyMatched, false, `${build}: absent explicit key was reported as matched`);
      assert.equal(
        explicitTurnstile.challengeMarkerMatched,
        true,
        `${build}: keyless Turnstile marker was not revalidated`,
      );
      assert.equal(response.value, 'TOKEN_TURNSTILE', `${build}: Turnstile token was not injected`);
      turnstileChallengeMarkerEnabled = false;
      response.value = '';
      const staleExplicitTurnstile = runtime.injectCaptchaTokenInPage({
        fieldName: 'cf-turnstile-response',
        token: 'TOKEN_TURNSTILE_STALE',
        target: {
          frameId: 9,
          frameUrl: globalThis.location.href,
          websiteKey: 'TURNSTILE_EXPLICIT_KEY',
          type: 'turnstile',
          explicitWebsiteKey: true,
        },
      });
      assert.equal(staleExplicitTurnstile.success, false, `${build}: stale keyless Turnstile target was injected`);
      assert.equal(staleExplicitTurnstile.staleTarget, true, `${build}: stale Turnstile marker missing`);
      assert.equal(response.value, '', `${build}: stale Turnstile token touched the field`);

      const wrongFrame = runtime.injectCaptchaTokenInPage({
        fieldName: 'g-recaptcha-response',
        token: 'TOKEN_WRONG_FRAME',
        target: {
          frameId: 9,
          frameUrl: 'https://example.test/other-frame',
          websiteKey: 'KEY_ACTIVE',
        },
      });
      assert.equal(wrongFrame.skipped, true, `${build}: wrong frame was not skipped`);
      assert.equal(response.value, '', `${build}: wrong-frame token touched the field`);
    }
  } finally {
    globalThis.document = previous.document;
    globalThis.location = previous.location;
    globalThis.window = previous.window;
    globalThis.Event = previous.Event;
    globalThis.HTMLTextAreaElement = previous.HTMLTextAreaElement;
    globalThis.HTMLInputElement = previous.HTMLInputElement;
  }
});

test('captcha injection wrappers target the selected frame in both builds', async () => {
  const previous = { chrome: globalThis.chrome, browser: globalThis.browser };
  try {
    const chromeMod = await import(pathToFileURL(path.join(ROOT, 'src/chrome/src/agent/captcha-solver.js')).href);
    let chromeCall = null;
    globalThis.chrome = {
      scripting: {
        executeScript: async (details) => {
          chromeCall = details;
          return [{ frameId: 9, result: { success: true, frameUrl: 'https://example.test/captcha' } }];
        },
      },
    };
    const chromeResult = await chromeMod.injectToken(1, {
      fieldName: 'g-recaptcha-response',
      token: 'TOKEN',
      target: { frameId: 9, frameUrl: 'https://example.test/captcha', websiteKey: 'KEY' },
    });
    assert.deepEqual(chromeCall.target.frameIds, [9], 'Chrome injection did not target selected frameId');
    assert.equal(chromeCall.world, 'MAIN', 'Chrome callback injection did not use the page main world');
    assert.equal(chromeResult.frameId, 9, 'Chrome injection result lost frameId');
    chromeCall = null;
    const chromeUntargeted = await chromeMod.injectToken(1, {
      fieldName: 'g-recaptcha-response',
      token: 'TOKEN',
      target: null,
    });
    assert.equal(chromeUntargeted.success, false, 'Chrome targetless injection succeeded');
    assert.equal(chromeUntargeted.targetRequired, true, 'Chrome targetless injection diagnostic missing');
    assert.equal(chromeCall, null, 'Chrome targetless injection reached the page');

    const firefoxMod = await import(pathToFileURL(path.join(ROOT, 'src/firefox/src/agent/captcha-solver.js')).href);
    let firefoxCall = null;
    globalThis.browser = {
      tabs: {
        executeScript: async (_tabId, details) => {
          firefoxCall = details;
          return [{ success: true, frameUrl: 'https://example.test/captcha' }];
        },
      },
    };
    const firefoxResult = await firefoxMod.injectToken(2, {
      fieldName: 'g-recaptcha-response',
      token: 'TOKEN',
      target: { frameId: 11, frameUrl: 'https://example.test/captcha', websiteKey: 'KEY' },
    });
    assert.equal(firefoxCall.frameId, 11, 'Firefox injection did not target selected frameId');
    assert.equal(firefoxCall.matchAboutBlank, true, 'Firefox injection did not enable inherited-origin matching');
    assert.equal(firefoxResult.frameId, 11, 'Firefox injection result lost frameId');
    firefoxCall = null;
    const firefoxUntargeted = await firefoxMod.injectToken(2, {
      fieldName: 'g-recaptcha-response',
      token: 'TOKEN',
      target: null,
    });
    assert.equal(firefoxUntargeted.success, false, 'Firefox targetless injection succeeded');
    assert.equal(firefoxUntargeted.targetRequired, true, 'Firefox targetless injection diagnostic missing');
    assert.equal(firefoxCall, null, 'Firefox targetless injection reached the page');
  } finally {
    globalThis.chrome = previous.chrome;
    globalThis.browser = previous.browser;
  }
});

test('solve_captcha runtime always detects missing fields and rejects type conflicts before dispatch', () => {
  for (const build of ['chrome', 'firefox']) {
    const agent = fs.readFileSync(path.join(ROOT, `src/${build}/src/agent/agent.js`), 'utf8');
    assert.match(
      agent,
      /if \(type !== 'image_to_text'\) \{[\s\S]*?detectCaptcha\(tabId, \{\s*type,\s*frameUrl,\s*frameId,\s*framePath,\s*websiteKey,/,
      `${build}: solve_captcha does not run frame-aware detection when type is supplied`,
    );
    assert.match(
      agent,
      /type && !captchaTypesMatch\(type, detected\.type, isEnterprise, detected\.isEnterprise\)[\s\S]*?conflicts with the active detected candidate/,
      `${build}: explicit type conflicts are not rejected locally`,
    );
    assert.match(
      agent,
      /pageAction && detected\.pageAction && String\(pageAction\) !== String\(detected\.pageAction\)[\s\S]*?requested pageAction[\s\S]*?conflicts with the active detected candidate action/,
      `${build}: explicit pageAction conflicts are not rejected locally`,
    );
    assert.match(
      agent,
      /if \(!websiteKey\) websiteKey = detected\.websiteKey/,
      `${build}: detected site key does not fill a missing explicit argument`,
    );
    assert.match(
      agent,
      /target: detected \? \{[\s\S]*?frameId: detected\.frameId,[\s\S]*?frameUrl: detected\.frameUrl/,
      `${build}: selected frame is not carried into token injection`,
    );
    assert.match(
      agent,
      /explicitWebsiteKey: detected\.explicitWebsiteKey === true/,
      `${build}: explicit Turnstile key marker is not carried into token injection`,
    );
    assert.match(
      agent,
      /const wantInject = args\?\.inject !== false && type !== 'image_to_text';[\s\S]*?if \(wantInject && !detected\) \{[\s\S]*?no safe injection target could be verified[\s\S]*?\}[\s\S]*?dispatched = true;/,
      `${build}: targetless default injection is not rejected before paid dispatch`,
    );
    assert.match(
      agent,
      /documentTimeOrigin: detected\.documentTimeOrigin/,
      `${build}: selected document identity is not carried into token injection`,
    );
    assert.match(
      agent,
      /const explicitTokenOnlyFallback = args\?\.inject === false[\s\S]*?candidate\?\.websiteKey === websiteKey[\s\S]*?if \(!explicitTokenOnlyFallback/,
      `${build}: unrelated candidates still block an explicit token-only solve`,
    );
    assert.match(
      agent,
      /try \{\s*detection = await detectCaptcha\(tabId, \{[\s\S]*?frameId,[\s\S]*?framePath,[\s\S]*?websiteKey,[\s\S]*?\}\);[\s\S]*?catch \(detectionError\) \{[\s\S]*?args\?\.inject === false && !!type && !!websiteKey[\s\S]*?CAPTCHA frame detection failed before dispatch/,
      `${build}: a detection exception still blocks a fully explicit token-only solve`,
    );
    assert.match(
      agent,
      /websiteURL = detected\.websiteURL \|\| captchaWebsiteUrl\(detected\.frameUrl, websiteURL\)/,
      `${build}: nearest HTTP ancestor URL is not used for opaque selected frames`,
    );
    assert.match(
      agent,
      /callbackHint: detected\.callbackName \|\| null,[\s\S]*?responseFieldId: detected\.responseFieldId,[\s\S]*?responseFieldIndex: detected\.responseFieldIndex/,
      `${build}: selected widget identity is not carried into token injection`,
    );
    assert.match(
      agent,
      /visibilityModeApplies[\s\S]*?isInvisible != null[\s\S]*?Boolean\(isInvisible\) !== Boolean\(detected\.isInvisible\)[\s\S]*?requested isInvisible=/,
      `${build}: explicit visibility conflicts are not rejected locally`,
    );
    assert.match(
      agent,
      /isEnterprise != null[\s\S]*?Boolean\(isEnterprise\) !== Boolean\(detected\.isEnterprise\)[\s\S]*?requested isEnterprise=/,
      `${build}: explicit Enterprise conflicts are not rejected locally`,
    );
    assert.match(
      agent,
      /alsoResponseFieldId: detected\.alsoResponseFieldId,[\s\S]*?alsoResponseFieldIndex: detected\.alsoResponseFieldIndex/,
      `${build}: hCaptcha compatibility field identity is not carried into injection`,
    );
  }
});

test('capsolver errors: demo-key refusals and task-config errors get different remedies', async () => {
  const cases = [
    {
      label: 'demo key refusal',
      body: { errorId: 1, errorCode: 'ERROR_INVALID_TASK_DATA', errorDescription: "We don't support this service." },
      expect: /public TEST\/DEMO key/,
    },
    {
      label: 'wrong task type for the widget',
      // Exactly what an Enterprise sitekey returns for a plain V2 task. This
      // must NOT be blamed on a demo key: the fix is to correct the task
      // type, not to give up and move to another site.
      body: { errorId: 1, errorCode: 'ERROR_INVALID_TASK_DATA', errorDescription: 'Invalid input: check captcha type or parameters' },
      expect: /rejected the task configuration/,
    },
    {
      label: 'ordinary parameter error containing the substring "test"',
      // A bare /test/ match here treats "latest" as a test key.
      body: { errorId: 1, errorCode: 'ERROR_INVALID_TASK_DATA', errorDescription: 'websiteKey is required for the latest task version' },
      expect: /^CapSolver: websiteKey is required for the latest task version$/,
    },
    {
      label: 'unrelated failure passes through untouched',
      body: { errorId: 1, errorCode: 'ERROR_ZERO_BALANCE', errorDescription: 'Your balance is zero' },
      expect: /^CapSolver: Your balance is zero$/,
    },
  ];

  const previousFetch = globalThis.fetch;
  try {
    for (const build of ['chrome', 'firefox']) {
      const mod = await import(pathToFileURL(path.join(ROOT, `src/${build}/src/agent/captcha-solver.js`)).href);
      for (const { label, body, expect } of cases) {
        globalThis.fetch = async () => ({ ok: true, json: async () => body });
        await assert.rejects(
          () => mod.getBalance('test-key'),
          (err) => {
            assert.match(err.message, expect, `${build}: ${label}`);
            return true;
          },
          `${build}: ${label} should reject`,
        );
      }
    }
  } finally {
    globalThis.fetch = previousFetch;
  }
});

test('built-in tool schemas are closed and invalid arguments never dispatch', async () => {
  for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
    const toolsModule = await import(pathToFileURL(path.join(ROOT, `src/${label}/src/agent/tools.js`)).href);
    const argumentModule = await import(pathToFileURL(path.join(ROOT, `src/${label}/src/agent/tool-arguments.js`)).href);
    const advertised = toolsModule.getToolsForMode('act');
    assert.ok(advertised.length > 0, `${label}: Act tool catalog is empty`);
    assert.ok(
      advertised.every(tool => tool.function?.parameters?.additionalProperties === false),
      `${label}: an advertised object schema remains open`,
    );

    const setField = toolsModule.AGENT_TOOLS.find(tool => tool.function?.name === 'set_field');
    const rejectedLang = argumentModule.validateToolArguments(
      'set_field',
      { ref_id: 'ref_1', text: 'miras.global', clear: true, submit: false, lang: 'tr-deasciify' },
      setField.function.parameters,
    );
    assert.equal(rejectedLang.ok, false, `${label}: undeclared lang argument was accepted`);
    assert.equal(rejectedLang.result.noDispatch, true, `${label}: rejected lang argument did not fail closed`);
    assert.equal(rejectedLang.result.errorCode, 'invalid_tool_arguments', `${label}: unstable invalid-argument code`);

    const carouselNavigate = toolsModule.AGENT_TOOLS.find(tool => tool.function?.name === 'carousel_navigate');
    const rejectedStringIndex = argumentModule.validateToolArguments(
      'carousel_navigate',
      { index: '1' },
      carouselNavigate.function.parameters,
    );
    assert.equal(rejectedStringIndex.ok, false, `${label}: string carousel index bypassed integer validation`);
    assert.equal(rejectedStringIndex.result.noDispatch, true, `${label}: invalid carousel index did not fail closed`);

    const fetchUrl = toolsModule.AGENT_TOOLS.find(tool => tool.function?.name === 'fetch_url');
    const acceptedHeaders = argumentModule.validateToolArguments(
      'fetch_url',
      {
        url: 'https://api.example.com/items',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: 'Bearer test-token',
          'X-Custom-Header': 'custom-value',
        },
        body: '{}',
      },
      fetchUrl.function.parameters,
    );
    assert.equal(acceptedHeaders.ok, true, `${label}: string-valued fetch_url headers were rejected`);

    for (const invalidValue of [42, true, null, ['application/json'], { value: 'application/json' }]) {
      const rejectedHeaders = argumentModule.validateToolArguments(
        'fetch_url',
        { url: 'https://api.example.com/items', headers: { 'Content-Type': invalidValue } },
        fetchUrl.function.parameters,
      );
      assert.equal(rejectedHeaders.ok, false, `${label}: non-string fetch_url header value was accepted`);
      assert.ok(rejectedHeaders.result.invalidArgumentNames.includes('$.headers.Content-Type'), `${label}: invalid header path was not reported`);
    }

    const rejectedFetchTopLevel = argumentModule.validateToolArguments(
      'fetch_url',
      { url: 'https://api.example.com/items', timeout: 5000 },
      fetchUrl.function.parameters,
    );
    assert.equal(rejectedFetchTopLevel.ok, false, `${label}: undeclared fetch_url top-level argument was accepted`);
    assert.ok(rejectedFetchTopLevel.result.invalidArgumentNames.includes('$.timeout'), `${label}: undeclared fetch_url argument path was not reported`);

    const click = toolsModule.AGENT_TOOLS.find(tool => tool.function?.name === 'click');
    for (const args of [
      { text: 'Save', selector: '#save' },
      { x: 10 },
    ]) {
      const rejectedClick = argumentModule.validateToolArguments('click', args, click.function.parameters);
      assert.equal(rejectedClick.ok, false, `${label}: mixed/incomplete click target was accepted`);
      assert.equal(rejectedClick.result.noDispatch, true, `${label}: invalid click target did not fail closed`);
    }
    const normalizedInertClick = argumentModule.validateToolArguments(
      'click',
      { index: 3, x: 0, y: 0, text: '', selector: '' },
      click.function.parameters,
    );
    assert.equal(normalizedInertClick.ok, true, `${label}: inert provider click defaults conflicted with the real index target`);
    assert.deepEqual(normalizedInertClick.args, { index: 3 }, `${label}: inert provider click defaults were not removed`);
    assert.equal(
      argumentModule.validateToolArguments('click', { index: 3 }, click.function.parameters).ok,
      true,
      `${label}: one valid click strategy was rejected`,
    );

    const agent = new AgentClass({
      getActive: () => ({ contextWindow: 128000, supportsVision: false }),
      getVisionProvider: async () => null,
    });
    const tabId = label === 'chrome' ? 9901 : 9902;
    agent.conversationModes.set(tabId, 'act');
    agent._persist = () => {};
    let dispatches = 0;
    agent.executeTool = async () => {
      dispatches++;
      return { success: true };
    };
    const messages = [];
    const updates = [];
    await agent._executeToolBatch(
      tabId,
      [{ id: 'bad_lang', function: { name: 'set_field', arguments: JSON.stringify({ ref_id: 'ref_1', text: 'miras.global', lang: 'tr-deasciify' }) } }],
      messages,
      (type, data) => updates.push({ type, data }),
      { supportsVision: false },
      null,
      new Set(['set_field']),
      1,
    );
    assert.equal(dispatches, 0, `${label}: invalid set_field arguments reached executeTool`);
    const result = JSON.parse(messages.find(message => message.role === 'tool')?.content || '{}');
    assert.equal(result.invalidArguments, true, `${label}: structured invalidArguments marker missing`);
    assert.equal(result.noDispatch, true, `${label}: structured noDispatch marker missing`);
    assert.ok(updates.some(update => update.type === 'tool_result' && update.data?.result?.noDispatch === true), `${label}: UI did not receive the rejected tool result`);

    const headerMessages = [];
    await agent._executeToolBatch(
      tabId,
      [{ id: 'bad_headers', function: { name: 'fetch_url', arguments: JSON.stringify({ url: 'https://api.example.com/items', headers: { Authorization: 123 } }) } }],
      headerMessages,
      () => {},
      { supportsVision: false },
      null,
      new Set(['fetch_url']),
      2,
    );
    assert.equal(dispatches, 0, `${label}: invalid fetch_url headers reached executeTool`);
    const headerResult = JSON.parse(headerMessages.find(message => message.role === 'tool')?.content || '{}');
    assert.equal(headerResult.invalidArguments, true, `${label}: invalid header result marker missing`);
    assert.equal(headerResult.noDispatch, true, `${label}: invalid header noDispatch marker missing`);
  }
});

test('execute protocol suppresses planner payloads, rejects false Ask claims, and ends with friendly failure', async () => {
  const plannerPayload = JSON.stringify({
    request_kind: 'execute',
    requires_state_change: true,
    summary: 'Fill the form.',
    steps: [{ id: '1', action: 'Type the value.' }],
    localized: { locale: 'tr', summary: 'Formu doldur.', steps: [] },
  });
  for (const AgentClass of [AgentCh, AgentFx]) {
    const agent = new AgentClass({ getActive: () => ({ contextWindow: 128000, supportsVision: false }) });
    const tabId = AgentClass === AgentCh ? 9911 : 9912;
    assert.equal(agent._isPlannerShapedJson(plannerPayload), true, `${AgentClass.name}: planner JSON was not detected`);
    agent._startPlanExecutionGuard(tabId, 'act', { requestKind: 'execute', requiresStateChange: false });
    assert.equal(
      agent._looksLikePlanOnlyTerminal('You are currently in Ask mode. Switch to Act mode to continue.', agent._planExecutionGuards.get(tabId)),
      true,
      `${AgentClass.name}: false runtime-mode claim was accepted`,
    );
    const first = agent._planOnlyTerminalDecision(tabId, plannerPayload);
    assert.equal(first?.retry, true, `${AgentClass.name}: first planner terminal did not receive one recovery`);
    const second = agent._planOnlyTerminalDecision(tabId, plannerPayload);
    assert.match(second?.failure || '', /could not verify any requested page action/i, `${AgentClass.name}: terminal failure is not user-facing`);
    assert.doesNotMatch(second?.failure || '', /execute protocol|recovery nudge|model returned/i, `${AgentClass.name}: raw protocol detail leaked to terminal`);
  }
});

test('both planner variants share Act advice follow-up routing rules', () => {
  assert.equal(PLANNER_RESPONSE_ONLY_RULES, PLANNER_RESPONSE_ONLY_RULES_FX, 'Chrome/Firefox response-only rules diverged');
  for (const [build, fullPrompt, intentPrompt] of [
    ['chrome', PLANNER_SYSTEM_PROMPT, PLANNER_INTENT_SYSTEM_PROMPT],
    ['firefox', PLANNER_SYSTEM_PROMPT_FX, PLANNER_INTENT_SYSTEM_PROMPT_FX],
  ]) {
    assert.ok(fullPrompt.includes(PLANNER_RESPONSE_ONLY_RULES), `${build}: full planner is missing shared advice-follow-up rules`);
    assert.ok(intentPrompt.includes(PLANNER_RESPONSE_ONLY_RULES), `${build}: compact intent planner is missing shared advice-follow-up rules`);
    assert.match(fullPrompt, /corrects, qualifies, or revises an answer or draft/, `${build}: full planner lacks correction-follow-up guidance`);
    assert.match(intentPrompt, /corrects, qualifies, or revises an answer or draft/, `${build}: intent planner lacks correction-follow-up guidance`);
    assert.match(fullPrompt, /required form value remains unavailable after relevant inspection[\s\S]*?leave the field untouched/, `${build}: full planner missing form-value guard`);
    assert.match(intentPrompt, /required form value remains unavailable after relevant inspection[\s\S]*?leave the field untouched/, `${build}: intent planner missing form-value guard`);
  }
});

test('error formatting is bounded and never exposes object coercion text', async () => {
  for (const build of ['chrome', 'firefox']) {
    const { formatErrorMessage } = await import(pathToFileURL(path.join(ROOT, `src/${build}/src/error-format.js`)).href);
    assert.equal(formatErrorMessage({ error: { detail: { message: 'Provider rejected the request.' } } }), 'Provider rejected the request.', `${build}: nested provider message missing`);
    assert.equal(formatErrorMessage(new Error('Network unavailable.')), 'Network unavailable.', `${build}: Error instance message missing`);
    assert.equal(formatErrorMessage({ error: { cause: new Error('Nested provider failure.') } }), 'Nested provider failure.', `${build}: nested Error cause message missing`);
    const arbitrary = formatErrorMessage({ status: 503, payload: { retry: false } });
    assert.doesNotMatch(arbitrary, /\[object Object\]/, `${build}: arbitrary object leaked coercion text`);
    assert.match(arbitrary, /"status":503/, `${build}: arbitrary object did not receive a useful stable representation`);
    const circular = { code: 'E_LOOP' };
    circular.self = circular;
    assert.doesNotMatch(formatErrorMessage(circular), /\[object Object\]/, `${build}: circular error leaked coercion text`);
    assert.ok(formatErrorMessage({ message: 'x'.repeat(5000) }, { maxLength: 200 }).length <= 200, `${build}: formatter ignored its bound`);

    const panel = fs.readFileSync(path.join(ROOT, `src/${build}/src/ui/sidepanel.js`), 'utf8');
    assert.match(panel, /function renderAgentErrorUpdate[\s\S]*?formatErrorMessage\(data\?\.message \?\? data\?\.error \?\? data\)/, `${build}: UI error ingress is not normalized`);
    assert.match(panel, /const existing = content\.querySelector\('\.msg-copy-btn:not\(\.scratchpad-copy-btn\)'\)/, `${build}: message Copy insertion is not idempotent`);
    assert.match(panel, /btn\.title = t\('sp\.copy\.message\.title'\)/, `${build}: message Copy still reuses the code tooltip`);
    assert.match(panel, /data-rejected-completion[\s\S]*?rejectedCompletion = 'pending'/, `${build}: rejected done retries are not collapsed`);
    assert.match(panel, /sp\.tool\.done\.rejected[\s\S]*?sp\.tool\.done\.failed/, `${build}: rejected and failed completion attempts are still labelled as successful done calls`);
  }
});

test('session conversation snapshots strip binary payloads and cap large tool results', async () => {
  const imagePayload = 'A'.repeat(3 * 1024 * 1024);
  for (const build of ['chrome', 'firefox']) {
    const persistence = await import(pathToFileURL(path.join(ROOT, `src/${build}/src/agent/conversation-persistence.js`)).href);
    const messages = [
      { role: 'system', content: 'system' },
      {
        role: 'user',
        attachmentHandles: [{ attachmentId: 'attachment_safe_1', kind: 'image', name: 'fixture.png' }],
        content: [
          { type: 'text', text: 'Use this attachment.' },
          { type: 'image_url', image_url: { url: `data:image/png;base64,${imagePayload}` } },
        ],
      },
      { role: 'tool', tool_call_id: 'shot', content: JSON.stringify({ image: `data:image/png;base64,${imagePayload}`, tree: 'x'.repeat(200_000) }) },
      { role: 'user', transientCompletionVerification: true, content: [{ type: 'image_url', image_url: { url: `data:image/png;base64,${imagePayload}` } }] },
    ];
    const serialized = persistence.serializeConversationForSession(messages);
    const json = JSON.stringify(serialized.messages);
    assert.equal(serialized.compacted, true, `${build}: binary snapshot was not marked compacted`);
    assert.ok(serialized.bytes <= persistence.SESSION_CONVERSATION_BUDGET_BYTES, `${build}: serialized conversation exceeded its bound`);
    assert.doesNotMatch(json, /data:image\//, `${build}: inline image survived session serialization`);
    assert.doesNotMatch(json, new RegExp(`A{${1024 * 1024}}`), `${build}: multi-megabyte payload survived session serialization`);
    assert.match(json, /attachment_safe_1/, `${build}: user attachment durable handle was lost`);
    assert.match(json, /Completion verification screenshot omitted/, `${build}: completion screenshot placeholder missing`);
  }
});

test('session conversation snapshots drop tool results orphaned by assistant compaction', async () => {
  for (const build of ['chrome', 'firefox']) {
    const persistence = await import(pathToFileURL(path.join(ROOT, `src/${build}/src/agent/conversation-persistence.js`)).href);
    const messages = [];
    for (let i = 0; i < 40; i++) {
      messages.push({
        role: 'assistant',
        content: null,
        tool_calls: [{ id: `tc${i}`, type: 'function', function: { name: 'x', arguments: '{"big":"' + 'a'.repeat(5000) + '"}' } }],
      });
      messages.push({ role: 'tool', tool_call_id: `tc${i}`, content: 'result '.repeat(2000) });
    }
    const serialized = persistence.serializeConversationForSession(messages, { maxBytes: 100_000 });
    assert.equal(serialized.compacted, true, `${build}: oversized conversation was not compacted`);
    assert.ok(serialized.bytes <= 100_000, `${build}: serialized conversation exceeded its requested bound`);
    const toolCallIds = new Set(
      serialized.messages
        .filter(m => m.role === 'assistant')
        .flatMap(m => Array.isArray(m.tool_calls) ? m.tool_calls.map(c => c.id) : []),
    );
    const orphaned = serialized.messages.filter(
      m => m.role === 'tool' && !toolCallIds.has(m.tool_call_id),
    );
    assert.equal(orphaned.length, 0,
      `${build}: snapshot left tool results with no matching assistant tool_calls`);

    // A conversation that fits the budget is returned verbatim.
    const small = [
      { role: 'system', content: 'system' },
      { role: 'assistant', content: null, tool_calls: [{ id: 'keep', type: 'function', function: { name: 'f', arguments: '{}' } }] },
      { role: 'tool', tool_call_id: 'keep', content: 'ok' },
    ];
    const untouched = persistence.serializeConversationForSession(small);
    assert.equal(untouched.compacted, false, `${build}: in-budget conversation was modified`);
    assert.equal(untouched.messages.length, 3, `${build}: in-budget conversation lost messages`);
  }
});

test('quota exhaustion degrades recovery once, continues live, and disables automatic replay', async () => {
  const previousChrome = globalThis.chrome;
  const previousBrowser = globalThis.browser;
  try {
    for (const [label, AgentClass, apiName, tabId] of [
      ['chrome', AgentCh, 'chrome', 9931],
      ['firefox', AgentFx, 'browser', 9932],
    ]) {
      let writes = 0;
      globalThis[apiName] = {
        storage: {
          session: {
            get: async () => ({}),
            set: async () => {
              writes++;
              throw new Error('QUOTA_BYTES exceeded');
            },
          },
        },
      };
      const agent = new AgentClass({});
      agent.conversations.set(tabId, [{ role: 'system', content: 'system' }, { role: 'user', content: 'continue live' }]);
      agent.submittedRunRequestIds.set(tabId, `${label}-request`);
      agent.currentRunId.set(tabId, `${label}-run`);
      const updates = [];
      agent._runUpdateCallbacks.set(tabId, (type, data) => updates.push({ type, data }));

      const first = await agent._persistNow(tabId);
      const second = await agent._persistNow(tabId);
      assert.deepEqual(
        { ok: first.ok, degraded: first.degraded, reason: first.reason },
        { ok: false, degraded: true, reason: 'quota' },
        `${label}: quota failure did not return structured degradation`,
      );
      assert.equal(second.ok, false, `${label}: repeated quota write unexpectedly became durable`);
      assert.equal(writes, 4, `${label}: each write should make one compact retry and stop`);
      assert.equal(updates.filter(update => update.data?.code === 'persistence_degraded').length, 1, `${label}: degradation warning was not deduped per run`);
      assert.equal(agent.activeRunState(tabId).persistenceDegraded, true, `${label}: active run state omitted degradation`);
      assert.equal(await agent.hasDurableSubmittedTurn(tabId, `${label}-request`), false, `${label}: non-durable run remained replayable`);
      assert.equal(agent.conversations.get(tabId).at(-1).content, 'continue live', `${label}: live conversation was discarded`);

      let retryWrites = 0;
      let compactStored = null;
      globalThis[apiName].storage.session.set = async patch => {
        retryWrites++;
        if (retryWrites === 1) throw new Error('QUOTA_BYTES exceeded');
        compactStored = patch;
      };
      const recovered = new AgentClass({});
      recovered.conversations.set(tabId, [{ role: 'system', content: 'system' }, { role: 'tool', content: 'x'.repeat(600_000) }]);
      const persisted = await recovered._persistNow(tabId);
      assert.equal(persisted.ok, true, `${label}: compact retry did not recover`);
      assert.equal(persisted.reason, 'quota_compacted', `${label}: compact retry reason missing`);
      assert.ok(JSON.stringify(compactStored).length < 500_000, `${label}: retry snapshot was not tightly bounded`);
    }
  } finally {
    if (previousChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = previousChrome;
    if (previousBrowser === undefined) delete globalThis.browser;
    else globalThis.browser = previousBrowser;
  }
});

test('run UI persistence compaction preserves acknowledged versus discarded boundaries', async () => {
  for (const build of ['chrome', 'firefox']) {
    const journal = await import(pathToFileURL(path.join(ROOT, `src/${build}/src/run-ui-journal.js`)).href);
    const events = Array.from({ length: 120 }, (_, index) => ({
      seq: index + 1,
      type: 'text_delta',
      data: { content: 'x'.repeat(10_000) },
      ts: index + 1,
    }));
    const snapshot = { requestId: 'bounded-run', seq: 120, ackedSeq: 10, discardedBeforeSeq: 0, events, streamedText: 'x'.repeat(100_000), finalContent: '' };
    const compact = journal.compactRunUiSnapshotForPersist(snapshot, { tight: true });
    assert.ok(JSON.stringify(compact).length <= journal.RUN_UI_PERSIST_RETRY_BUDGET, `${build}: run UI retry snapshot exceeded budget`);
    assert.equal(compact.ackedSeq, 10, `${build}: compaction rewrote acknowledged boundary`);
    assert.ok(compact.discardedBeforeSeq > compact.ackedSeq, `${build}: genuine persisted eviction did not create a replay-gap boundary`);
    const acknowledgedOnly = { ackedSeq: 42, discardedBeforeSeq: 0, truncatedBeforeSeq: 42 };
    assert.equal(journal.runUiDiscardedBeforeSeq(acknowledgedOnly), 0, `${build}: acknowledged events became a false replay gap`);
  }
});

test('run UI tool-result compaction keeps accessibility tree previews', async () => {
  for (const build of ['chrome', 'firefox']) {
    const journal = await import(pathToFileURL(path.join(ROOT, `src/${build}/src/run-ui-journal.js`)).href);
    const tree = journal.compactRunUiData('tool_result', {
      name: 'get_accessibility_tree',
      result: {
        pageContent: 'Role: combobox, name: Adults, value: 1 Adult',
        viewport: { width: 1280, height: 800 },
        treeRevision: 4,
      },
    });
    assert.equal(tree.name, 'get_accessibility_tree', `${build}: compacted tree result dropped the tool name`);
    assert.match(tree.result?.pageContent || '', /1 Adult/, `${build}: compacted tree result dropped pageContent`);
    assert.notEqual(JSON.stringify(tree.result), '{}', `${build}: compacted tree result collapsed to empty JSON`);

    const longText = 'x'.repeat(800);
    const truncated = journal.compactRunUiData('tool_result', {
      name: 'get_accessibility_tree',
      result: { pageContent: longText },
    });
    assert.equal(truncated.result.pageContent.length, 500, `${build}: long tree pageContent should be truncated`);
    assert.equal(truncated.result.pageContentTruncated, true, `${build}: truncated tree pageContent should be marked`);
    const persistedTree = journal.compactRunUiSnapshotForPersist({
      events: [{ seq: 1, type: 'tool_result', data: truncated }],
    });
    assert.equal(persistedTree.events[0].data.result.pageContentTruncated, true, `${build}: persisted tree preview lost its truncation marker on a second compaction pass`);

    const truncatedText = journal.compactRunUiData('tool_result', {
      name: 'read_page',
      result: { text: longText },
    });
    assert.equal(truncatedText.result.text.length, 500, `${build}: long text preview should be truncated`);
    assert.equal(truncatedText.result.textTruncated, true, `${build}: truncated text preview should be marked`);
    const persistedText = journal.compactRunUiSnapshotForPersist({
      events: [{ seq: 1, type: 'tool_result', data: truncatedText }],
    });
    assert.equal(persistedText.events[0].data.result.textTruncated, true, `${build}: persisted text preview lost its truncation marker on a second compaction pass`);

    const empty = journal.compactRunUiData('tool_result', {
      name: 'get_accessibility_tree',
      result: { viewport: { width: 1 } },
    });
    assert.ok(empty.result?.preview, `${build}: metadata-only results should keep a JSON preview`);
    assert.notEqual(JSON.stringify(empty.result), '{}', `${build}: metadata-only results collapsed to empty JSON`);
  }
});

