test('dedicated vision deadlines are enforced in Chrome and Firefox', async () => {
  const originalSetTimeout = globalThis.setTimeout;
  const originalClearTimeout = globalThis.clearTimeout;
  const scheduled = new Set();
  try {
    globalThis.setTimeout = (callback, delay, ...args) => {
      if (delay !== 90_000) return originalSetTimeout(callback, delay, ...args);
      const token = { cancelled: false };
      scheduled.add(token);
      queueMicrotask(() => {
        if (!token.cancelled) callback(...args);
      });
      return token;
    };
    globalThis.clearTimeout = token => {
      if (scheduled.has(token)) token.cancelled = true;
      else originalClearTimeout(token);
    };
    for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
      const agent = new AgentClass({});
      await assert.rejects(
        agent._withVisionDeadline(new Promise(() => {})),
        error => error?.code === 'vision_timeout' && /90000ms/.test(error.message),
        `${label}: hung vision request did not reach the shared deadline`,
      );
    }
  } finally {
    globalThis.setTimeout = originalSetTimeout;
    globalThis.clearTimeout = originalClearTimeout;
  }
});

test('dedicated vision deadline aborts the in-flight provider request', async () => {
  const originalSetTimeout = globalThis.setTimeout;
  const originalClearTimeout = globalThis.clearTimeout;
  const scheduled = new Set();
  try {
    globalThis.setTimeout = (callback, delay, ...args) => {
      if (delay !== 90_000) return originalSetTimeout(callback, delay, ...args);
      const token = {
        cancelled: false,
        fire() {
          if (!this.cancelled) callback(...args);
        },
      };
      scheduled.add(token);
      return token;
    };
    globalThis.clearTimeout = token => {
      if (scheduled.has(token)) token.cancelled = true;
      else originalClearTimeout(token);
    };
    for (const [label, AgentClass] of [['chrome', AgentCh], ['firefox', AgentFx]]) {
      let seenSignal = null;
      let recordedUsage = false;
      scheduled.clear();
      const vision = {
        config: { model: 'remote-vision', baseUrl: 'https://vision.example/v1', category: 'cloud' },
        async chat(_messages, options) {
          seenSignal = options.signal;
          await new Promise(resolve => {
            options.signal.addEventListener('abort', resolve, { once: true });
          });
          return { content: 'late caption', usage: { total_tokens: 12 } };
        },
      };
      const agent = new AgentClass({});
      agent._recordCostUsage = async () => {
        recordedUsage = true;
        return null;
      };
      const pending = agent._describeScreenshot(
        label === 'chrome' ? 2991 : 2992,
        'data:image/png;base64,AA==',
        'timeout_abort',
        null,
        { provider: vision, route: 'explicit_override', rawImage: false },
      );
      for (let i = 0; i < 30 && !seenSignal; i++) await Promise.resolve();
      assert.ok(seenSignal, `${label}: vision chat did not receive a deadline signal`);
      assert.equal(seenSignal.aborted, false, `${label}: vision request was aborted before its deadline`);
      for (const token of scheduled) token.fire();
      const described = await pending;
      for (let i = 0; i < 8; i++) await Promise.resolve();
      assert.equal(described, null, `${label}: timed-out vision should not return a description`);
      assert.equal(seenSignal.aborted, true, `${label}: provider chat did not receive an aborted signal`);
      assert.equal(recordedUsage, false, `${label}: timed-out vision still recorded cost`);
    }
  } finally {
    globalThis.setTimeout = originalSetTimeout;
    globalThis.clearTimeout = originalClearTimeout;
  }
});

test('multimodal connection tests exercise image and audio routes instead of only model listing', async () => {
  const originalChrome = globalThis.chrome;
  const originalBrowser = globalThis.browser;
  const originalFetch = globalThis.fetch;
  try {
    for (const [label, ProviderManager] of [
      ['chrome', ProviderManagerCh],
      ['firefox', ProviderManagerFx],
    ]) {
      const storageApi = {
        runtime: {
          getURL: relativePath => `https://${label}.extension.test/${relativePath}`,
        },
        storage: {
          local: {
            get: async () => ({
              transcriptionModel: {
                baseUrl: 'http://127.0.0.1:1234',
                model: 'whisper-local',
                apiKey: '',
              },
            }),
          },
          onChanged: { addListener() {} },
        },
      };
      globalThis.chrome = storageApi;
      globalThis.browser = storageApi;
      let endpointResponse = null;
      let request = null;
      globalThis.fetch = async (url, options) => {
        const requestedUrl = String(url);
        const assetPrefix = `https://${label}.extension.test/`;
        if (requestedUrl.startsWith(assetPrefix)) {
          const relativePath = requestedUrl.slice(assetPrefix.length);
          return new Response(fs.readFileSync(path.join(ROOT, `src/${label}`, relativePath)), {
            status: 200,
          });
        }
        request = { url: requestedUrl, options };
        return endpointResponse();
      };

      const visionCalls = [];
      const visionManager = new ProviderManager();
      visionManager.getVisionOverrideProvider = async () => ({
        model: 'qwen/qwen3.5-9b',
        baseUrl: 'http://127.0.0.1:1234/v1',
        chat: async (messages, options) => {
          visionCalls.push({ messages, options });
          return { content: 'WB7' };
        },
      });
      const visionResult = await visionManager.testVisionProvider();
      assert.equal(visionResult.ok, true, `${label}: real vision probe should pass`);
      assert.equal(visionCalls.length, 1);
      assert.match(visionCalls[0].messages[0].content[0].image_url.url, /^data:image\/png;base64,/);
      assert.equal(visionCalls[0].options.extraBody.reasoning_tokens, 0);
      assert.equal(visionCalls[0].options.webbrainVisionProbe, true);

      if (label === 'chrome') {
        visionManager.getVisionOverrideProvider = async () => null;
        visionManager.getLocalVisionFallbackProvider = async () => ({
          name: 'webgpu-vision',
          model: WEBGPU_VISION_MODEL_ID,
          baseUrl: 'local://webgpu',
          chat: async (messages, options) => {
            assert.match(messages[0].content[1].text, /three solid vertical color panels/i);
            assert.equal(options.webbrainVisionProbe, true);
            return { content: 'yellow, blue, red' };
          },
        });
        const localVisionResult = await visionManager.testVisionProvider();
        assert.equal(localVisionResult.ok, true, 'chrome: local color-panel vision probe should pass');
      }

      visionManager.getVisionOverrideProvider = async () => ({
        model: 'text-only-model',
        baseUrl: 'http://127.0.0.1:1234/v1',
        chat: async () => ({ content: 'I can respond without reading the image.' }),
      });
      const textOnlyResult = await visionManager.testVisionProvider();
      assert.equal(textOnlyResult.ok, false, `${label}: a text-only response must not pass the vision probe`);
      assert.match(textOnlyResult.error, /did not read the image probe correctly/);

      endpointResponse = () => new Response(JSON.stringify({ text: '' }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });

      const result = await new ProviderManager().testTranscriptionProvider();
      assert.equal(result.ok, true, `${label}: valid silent audio probe should pass`);
      assert.equal(request.url, 'http://127.0.0.1:1234/v1/audio/transcriptions');
      assert.equal(request.options.method, 'POST');
      assert.ok(request.options.body instanceof FormData);
      assert.equal(request.options.body.get('model'), 'whisper-local');
      assert.ok(request.options.body.get('file') instanceof Blob);
      assert.equal(
        createHash('sha256')
          .update(Buffer.from(await request.options.body.get('file').arrayBuffer()))
          .digest('hex'),
        '56d4af65701c26df20bd4021eda95b6e830348ce3a746086079fe89285548dc9',
        `${label}: transcription request changed the silent WAV payload`,
      );

      endpointResponse = () => new Response(JSON.stringify({
        error: 'Unexpected endpoint or method.',
      }), { status: 200, headers: { 'Content-Type': 'application/json' } });
      const rejected = await new ProviderManager().testTranscriptionProvider();
      assert.equal(rejected.ok, false, `${label}: HTTP-200 endpoint errors must fail the connection test`);
      assert.match(rejected.error, /Unexpected endpoint or method/);
    }
  } finally {
    if (originalChrome === undefined) delete globalThis.chrome;
    else globalThis.chrome = originalChrome;
    if (originalBrowser === undefined) delete globalThis.browser;
    else globalThis.browser = originalBrowser;
    globalThis.fetch = originalFetch;
  }
});

